      AND substr(uuid, 9, 1) = '-' AND substr(uuid, 14, 1) = '-'
      AND substr(uuid, 19, 1) = '-' AND substr(uuid, 24, 1) = '-'
      AND length(replace(uuid, '-', '')) = 32
      AND replace(uuid, '-', '') NOT GLOB '*[^0-9a-f]*'
      AND uuid != '00000000-0000-0000-0000-000000000000'),
  namespace TEXT NOT NULL CHECK (length(namespace) BETWEEN 1 AND 128),
  label TEXT NOT NULL DEFAULT '',
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
, canonical_uuid TEXT REFERENCES source_accounts(uuid));

CREATE TABLE source_account_identifier_evidence (
  identifier_uuid TEXT NOT NULL REFERENCES source_account_identifiers(uuid) ON UPDATE CASCADE,
  evidence_key TEXT NOT NULL CHECK (length(evidence_key) BETWEEN 1 AND 512),
  basis TEXT NOT NULL CHECK (length(basis) BETWEEN 1 AND 128),
  origin TEXT NOT NULL CHECK (length(origin) BETWEEN 1 AND 128),
  details TEXT NOT NULL CHECK (json_valid(details) AND json_type(details) = 'object'),
  first_observed DATETIME NOT NULL,
  last_observed DATETIME NOT NULL,
  PRIMARY KEY (identifier_uuid, evidence_key),
  CHECK (first_observed <= last_observed)
) WITHOUT ROWID;

CREATE TABLE account_performer_decisions (
  uuid TEXT NOT NULL PRIMARY KEY,
  account_uuid TEXT NOT NULL REFERENCES source_accounts(uuid) ON UPDATE CASCADE,
  revision INTEGER NOT NULL CHECK (revision > 0),
  state TEXT NOT NULL CHECK (state IN ('linked', 'unlinked', 'undecided')),
  performer_uuid TEXT REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  origin TEXT NOT NULL CHECK (origin IN ('review', 'profile-url', 'migration')),
  reason TEXT NOT NULL DEFAULT '',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (account_uuid, revision),
  UNIQUE (account_uuid, uuid),
  CHECK ((state = 'linked' AND performer_uuid IS NOT NULL) OR
    (state IN ('unlinked', 'undecided') AND performer_uuid IS NULL))
);

CREATE TABLE account_performer_links (
  account_uuid TEXT NOT NULL PRIMARY KEY REFERENCES source_accounts(uuid) ON UPDATE CASCADE,
  decision_uuid TEXT NOT NULL,
  FOREIGN KEY (account_uuid, decision_uuid) REFERENCES account_performer_decisions(account_uuid, uuid) ON UPDATE CASCADE
);

CREATE TABLE source_posts (
  uuid TEXT NOT NULL PRIMARY KEY
    CHECK (length(uuid) = 36 AND uuid = lower(uuid)
      AND substr(uuid, 9, 1) = '-' AND substr(uuid, 14, 1) = '-'
      AND substr(uuid, 19, 1) = '-' AND substr(uuid, 24, 1) = '-'
      AND length(replace(uuid, '-', '')) = 32
      AND replace(uuid, '-', '') NOT GLOB '*[^0-9a-f]*'
      AND uuid != '00000000-0000-0000-0000-000000000000'),
  state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('active', 'forgotten')),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE source_post_identifiers (
  namespace TEXT NOT NULL CHECK (length(namespace) BETWEEN 1 AND 128),
  value TEXT NOT NULL CHECK (length(value) BETWEEN 1 AND 2048),
  post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
  PRIMARY KEY (namespace, value)
) WITHOUT ROWID;

CREATE TABLE source_payloads (
  digest TEXT NOT NULL PRIMARY KEY CHECK (length(digest) = 64 AND digest NOT GLOB '*[^0-9a-f]*'),
  encoding TEXT NOT NULL CHECK (encoding IN ('json', 'gzip')),
  byte_length INTEGER NOT NULL CHECK (byte_length BETWEEN 2 AND 4194304),
  data BLOB NOT NULL CHECK (length(data) BETWEEN 2 AND 4194304)
) WITHOUT ROWID;

CREATE TABLE source_profile_bodies (
  hash TEXT NOT NULL PRIMARY KEY CHECK (length(hash) = 64 AND hash NOT GLOB '*[^0-9a-f]*'),
  namespace TEXT NOT NULL CHECK (length(namespace) BETWEEN 1 AND 128),
  payload_digest TEXT NOT NULL REFERENCES source_payloads(digest)
) WITHOUT ROWID;

CREATE TABLE source_post_revisions (
  uuid TEXT NOT NULL PRIMARY KEY
    CHECK (length(uuid) = 36 AND uuid = lower(uuid)
      AND substr(uuid, 9, 1) = '-' AND substr(uuid, 14, 1) = '-'
      AND substr(uuid, 19, 1) = '-' AND substr(uuid, 24, 1) = '-'
      AND length(replace(uuid, '-', '')) = 32
      AND replace(uuid, '-', '') NOT GLOB '*[^0-9a-f]*'
      AND uuid != '00000000-0000-0000-0000-000000000000'),
  post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
  signature TEXT NOT NULL CHECK (length(signature) = 64 AND signature NOT GLOB '*[^0-9a-f]*'),
  body_digest TEXT NOT NULL REFERENCES source_payloads(digest),
  metadata TEXT NOT NULL CHECK (length(metadata) <= 262144 AND json_valid(metadata) AND json_type(metadata) = 'object'),
  structure_version TEXT NOT NULL,
  UNIQUE (post_uuid, signature),
  UNIQUE (post_uuid, uuid)
);

CREATE TABLE source_capture_profiles (
  capture_uuid TEXT NOT NULL REFERENCES source_captures(uuid),
  part TEXT NOT NULL CHECK (part IN ('shared', 'patch')),
  path TEXT NOT NULL CHECK (length(path) BETWEEN 1 AND 8192 AND substr(path, 1, 1) = '/'),
  profile_hash TEXT NOT NULL REFERENCES source_profile_bodies(hash),
  PRIMARY KEY (capture_uuid, part, path)
) WITHOUT ROWID;

CREATE TABLE source_attachments (
  uuid TEXT NOT NULL PRIMARY KEY
    CHECK (length(uuid) = 36 AND uuid = lower(uuid)
      AND substr(uuid, 9, 1) = '-' AND substr(uuid, 14, 1) = '-'
      AND substr(uuid, 19, 1) = '-' AND substr(uuid, 24, 1) = '-'
      AND length(replace(uuid, '-', '')) = 32
      AND replace(uuid, '-', '') NOT GLOB '*[^0-9a-f]*'
      AND uuid != '00000000-0000-0000-0000-000000000000'),
  post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
  namespace TEXT NOT NULL CHECK (length(namespace) BETWEEN 1 AND 128),
  value TEXT NOT NULL CHECK (length(value) BETWEEN 1 AND 2048),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),
  UNIQUE (post_uuid, namespace, value),
  UNIQUE (post_uuid, uuid)
);

CREATE TABLE source_attachment_manifests (
  uuid TEXT NOT NULL PRIMARY KEY
    CHECK (length(uuid) = 36 AND uuid = lower(uuid)
      AND substr(uuid, 9, 1) = '-' AND substr(uuid, 14, 1) = '-'
      AND substr(uuid, 19, 1) = '-' AND substr(uuid, 24, 1) = '-'
      AND length(replace(uuid, '-', '')) = 32
      AND replace(uuid, '-', '') NOT GLOB '*[^0-9a-f]*'
      AND uuid != '00000000-0000-0000-0000-000000000000'),
  post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
  version TEXT NOT NULL,
  signature TEXT NOT NULL CHECK (length(signature) = 64 AND signature NOT GLOB '*[^0-9a-f]*'),
  complete INTEGER NOT NULL CHECK (complete IN (0, 1)),
  declared_album INTEGER NOT NULL CHECK (declared_album IN (0, 1)),
  expected_count INTEGER CHECK (expected_count BETWEEN 0 AND 1000000),
  entry_count INTEGER NOT NULL CHECK (entry_count BETWEEN 0 AND 4096),
  CHECK (expected_count IS NULL OR entry_count <= expected_count),
  CHECK (complete = 0 OR (expected_count IS NOT NULL AND expected_count = entry_count)),
  UNIQUE (post_uuid, signature),
  UNIQUE (post_uuid, uuid)
);

CREATE TABLE source_attachment_entries (
  manifest_uuid TEXT NOT NULL,
  post_uuid TEXT NOT NULL,
  position INTEGER NOT NULL CHECK (position BETWEEN 0 AND 999999),
  attachment_uuid TEXT NOT NULL,
  media_kind TEXT NOT NULL CHECK (media_kind IN ('image', 'video', 'unknown')),
  PRIMARY KEY (manifest_uuid, position),
  UNIQUE (manifest_uuid, position, attachment_uuid),
  FOREIGN KEY (post_uuid, manifest_uuid) REFERENCES source_attachment_manifests(post_uuid, uuid),
  FOREIGN KEY (post_uuid, attachment_uuid) REFERENCES source_attachments(post_uuid, uuid)
) WITHOUT ROWID;

CREATE TABLE source_capture_attachment_manifests (
  capture_uuid TEXT NOT NULL PRIMARY KEY,
  post_uuid TEXT NOT NULL,
  manifest_uuid TEXT NOT NULL,
  UNIQUE (capture_uuid, manifest_uuid),
  FOREIGN KEY (post_uuid, capture_uuid) REFERENCES source_captures(post_uuid, uuid),
  FOREIGN KEY (post_uuid, manifest_uuid) REFERENCES source_attachment_manifests(post_uuid, uuid)
) WITHOUT ROWID;

CREATE TABLE attachment_media_decisions (
  uuid TEXT NOT NULL PRIMARY KEY
    CHECK (length(uuid) = 36 AND uuid = lower(uuid)
      AND substr(uuid, 9, 1) = '-' AND substr(uuid, 14, 1) = '-'
      AND substr(uuid, 19, 1) = '-' AND substr(uuid, 24, 1) = '-'
      AND length(replace(uuid, '-', '')) = 32
      AND replace(uuid, '-', '') NOT GLOB '*[^0-9a-f]*'
      AND uuid != '00000000-0000-0000-0000-000000000000'),
  attachment_uuid TEXT NOT NULL REFERENCES source_attachments(uuid),
  revision INTEGER NOT NULL CHECK (revision > 0),
  state TEXT NOT NULL CHECK (state IN ('linked', 'unlinked', 'undecided')),
  media_uuid TEXT REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  origin TEXT NOT NULL CHECK (origin IN ('review', 'ingest', 'migration')),
  reason TEXT NOT NULL DEFAULT '' CHECK (length(reason) <= 4096),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (attachment_uuid, revision),
  UNIQUE (attachment_uuid, uuid),
  CHECK ((state = 'linked' AND media_uuid IS NOT NULL) OR (state IN ('unlinked', 'undecided') AND media_uuid IS NULL))
);

CREATE TABLE attachment_media_links (
  attachment_uuid TEXT NOT NULL PRIMARY KEY REFERENCES source_attachments(uuid),
  decision_uuid TEXT NOT NULL,
  FOREIGN KEY (attachment_uuid, decision_uuid) REFERENCES attachment_media_decisions(attachment_uuid, uuid)
) WITHOUT ROWID;

CREATE TABLE post_attachment_selections (
  post_uuid TEXT NOT NULL PRIMARY KEY REFERENCES source_posts(uuid),
  decision_uuid TEXT NOT NULL,
  FOREIGN KEY (post_uuid, decision_uuid) REFERENCES post_attachment_decisions(post_uuid, uuid)
) WITHOUT ROWID;

CREATE TABLE post_gallery_decisions (
  uuid TEXT NOT NULL PRIMARY KEY
    CHECK (length(uuid) = 36 AND uuid = lower(uuid)
      AND substr(uuid, 9, 1) = '-' AND substr(uuid, 14, 1) = '-'
      AND substr(uuid, 19, 1) = '-' AND substr(uuid, 24, 1) = '-'
      AND length(replace(uuid, '-', '')) = 32
      AND replace(uuid, '-', '') NOT GLOB '*[^0-9a-f]*'
      AND uuid != '00000000-0000-0000-0000-000000000000'),
  post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
  revision INTEGER NOT NULL CHECK (revision > 0),
  state TEXT NOT NULL CHECK (state IN ('linked', 'disabled')),
  gallery_uuid TEXT REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  selection_uuid TEXT,
  origin TEXT NOT NULL CHECK (origin IN ('source', 'review', 'migration')),
  reason TEXT NOT NULL DEFAULT '' CHECK (length(reason) <= 4096),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (post_uuid, revision),
  UNIQUE (post_uuid, uuid),
  UNIQUE (post_uuid, uuid, gallery_uuid),
  FOREIGN KEY (post_uuid, selection_uuid) REFERENCES post_attachment_decisions(post_uuid, uuid),
  CHECK (origin != 'source' OR (state = 'linked' AND selection_uuid IS NOT NULL)),
  CHECK ((state = 'linked' AND gallery_uuid IS NOT NULL) OR (state = 'disabled' AND gallery_uuid IS NULL))
);

CREATE TABLE post_gallery_links (
  post_uuid TEXT NOT NULL PRIMARY KEY REFERENCES source_posts(uuid),
  decision_uuid TEXT NOT NULL,
  gallery_uuid TEXT,
  UNIQUE (post_uuid, gallery_uuid),
  FOREIGN KEY (post_uuid, decision_uuid) REFERENCES post_gallery_decisions(post_uuid, uuid),
  FOREIGN KEY (post_uuid, decision_uuid, gallery_uuid) REFERENCES post_gallery_decisions(post_uuid, uuid, gallery_uuid) ON UPDATE CASCADE
) WITHOUT ROWID;

CREATE TABLE source_gallery_write_context (
  gallery_uuid TEXT NOT NULL PRIMARY KEY,
  post_uuid TEXT NOT NULL,
  selection_uuid TEXT NOT NULL,
  FOREIGN KEY (post_uuid, selection_uuid) REFERENCES post_attachment_decisions(post_uuid, uuid),
  FOREIGN KEY (post_uuid, gallery_uuid) REFERENCES post_gallery_links(post_uuid, gallery_uuid) ON UPDATE CASCADE
) WITHOUT ROWID;

CREATE TABLE gallery_membership_events (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  uuid TEXT NOT NULL UNIQUE
    CHECK (length(uuid) = 36 AND uuid = lower(uuid)
      AND substr(uuid, 9, 1) = '-' AND substr(uuid, 14, 1) = '-'
      AND substr(uuid, 19, 1) = '-' AND substr(uuid, 24, 1) = '-'
      AND length(replace(uuid, '-', '')) = 32
      AND replace(uuid, '-', '') NOT GLOB '*[^0-9a-f]*'
      AND uuid != '00000000-0000-0000-0000-000000000000'),
  gallery_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  media_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  state TEXT NOT NULL CHECK (state IN ('included', 'excluded')),
  origin TEXT NOT NULL CHECK (origin IN ('source', 'library', 'migration')),
  post_uuid TEXT REFERENCES source_posts(uuid),
  selection_uuid TEXT,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (gallery_uuid, media_uuid, uuid),
  FOREIGN KEY (post_uuid, selection_uuid) REFERENCES post_attachment_decisions(post_uuid, uuid),
  CHECK ((origin = 'source' AND post_uuid IS NOT NULL AND selection_uuid IS NOT NULL) OR (origin != 'source' AND post_uuid IS NULL AND selection_uuid IS NULL))
);

CREATE TABLE gallery_membership_heads (
  gallery_uuid TEXT NOT NULL,
  media_uuid TEXT NOT NULL,
  event_uuid TEXT NOT NULL,
  PRIMARY KEY (gallery_uuid, media_uuid),
  FOREIGN KEY (gallery_uuid, media_uuid, event_uuid) REFERENCES gallery_membership_events(gallery_uuid, media_uuid, uuid) ON UPDATE CASCADE
) WITHOUT ROWID;

CREATE TABLE metadata_field_baselines (
  entity_uuid TEXT NOT NULL PRIMARY KEY REFERENCES archive_entities(uuid) ON UPDATE CASCADE
) WITHOUT ROWID;

CREATE TABLE metadata_field_heads (
  entity_uuid TEXT NOT NULL,
  field TEXT NOT NULL,
  decision_uuid TEXT NOT NULL,
  PRIMARY KEY (entity_uuid, field),
  FOREIGN KEY (entity_uuid, field, decision_uuid) REFERENCES metadata_field_decisions(entity_uuid, field, uuid) ON UPDATE CASCADE
) WITHOUT ROWID;

CREATE TABLE metadata_field_decisions (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  uuid TEXT NOT NULL UNIQUE DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', (random() & 3) + 1, 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6))))
    CHECK (length(uuid)=36 AND uuid=lower(uuid)
      AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
      AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
      AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
      AND uuid!='00000000-0000-0000-0000-000000000000'),
  entity_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  field TEXT NOT NULL CHECK (field IN ('title','code','details','date','rating100','organized','director','production_date','photographer','urls','custom_fields','studio','performers','tags','groups')),
  mode TEXT NOT NULL CHECK (mode IN ('set','clear','inherit','preserved')),
  origin TEXT NOT NULL CHECK (origin IN ('library','review','migration','legacy','unattributed','source','policy','filename')),
  value_json TEXT NOT NULL CHECK (length(CAST(value_json AS BLOB)) <= 4194304 AND json_valid(value_json)),
  capture_uuid TEXT REFERENCES source_captures(uuid),
  reason TEXT NOT NULL DEFAULT '' CHECK (length(reason) <= 4096),
  sealed BOOLEAN NOT NULL DEFAULT 1 CHECK (sealed IN (0,1)),
  reference_count INTEGER NOT NULL DEFAULT 0 CHECK (reference_count BETWEEN 0 AND 4096),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (entity_uuid, field, uuid),
  CHECK (mode!='preserved' OR origin IN ('legacy','unattributed','migration')),
  CHECK (origin NOT IN ('legacy','unattributed') OR mode='preserved'),
  CHECK (origin NOT IN ('source','policy','filename') OR mode='inherit'),
  CHECK (origin!='library' OR mode IN ('set','clear')),
  CHECK (origin!='source' OR capture_uuid IS NOT NULL),
  CHECK (origin!='filename' OR (field='title' AND capture_uuid IS NULL)),
  CHECK (field IN ('studio','performers','tags','groups') OR (sealed=1 AND reference_count=0)),
  CHECK (sealed=1 OR reference_count=0),
  CHECK (CASE
    WHEN field IN ('studio','performers','tags','groups') THEN json_type(value_json)='null'
    WHEN field='urls' THEN json_type(value_json)='array'
    WHEN field='custom_fields' THEN json_type(value_json)='object'
    WHEN field IN ('date','production_date') THEN json_type(value_json) IN ('null','text')
    WHEN field='rating100' THEN json_type(value_json) IN ('null','integer')
    WHEN field='organized' THEN json_type(value_json) IN ('true','false')
    ELSE json_type(value_json)='text' END),
  CHECK (mode!='clear' OR CASE
    WHEN field IN ('studio','performers','tags','groups') THEN json_type(value_json)='null'
    WHEN field='urls' THEN json_array_length(value_json)=0
    WHEN field='custom_fields' THEN value_json='{}'
    WHEN field IN ('date','production_date','rating100') THEN json_type(value_json)='null'
    WHEN field='organized' THEN json_type(value_json)='false'
    ELSE json_extract(value_json,'$')='' END)
);

CREATE TABLE metadata_field_write_context (
  entity_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  field TEXT NOT NULL CHECK (field IN ('title','code','details','date','rating100','organized','director','production_date','photographer','urls','custom_fields','studio','performers','tags','groups')),
  PRIMARY KEY (entity_uuid, field)
) WITHOUT ROWID;

CREATE TABLE metadata_field_references (
  decision_uuid TEXT NOT NULL REFERENCES metadata_field_decisions(uuid),
  position INTEGER NOT NULL CHECK(position BETWEEN 0 AND 4095),
  target_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  scene_index INTEGER CHECK(scene_index IS NULL OR typeof(scene_index)='integer'),
  PRIMARY KEY(decision_uuid,position),
  UNIQUE(decision_uuid,target_uuid)
) WITHOUT ROWID;

CREATE TABLE metadata_field_pending (
  entity_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  field TEXT NOT NULL CHECK(field IN ('urls','custom_fields','studio','performers','tags','groups')),
  previous_json TEXT NOT NULL CHECK(json_valid(previous_json) AND length(CAST(previous_json AS BLOB))<=4194304),
  PRIMARY KEY(entity_uuid,field)
) WITHOUT ROWID;

CREATE TABLE source_account_identifiers (
  uuid TEXT NOT NULL PRIMARY KEY,
  account_uuid TEXT NOT NULL REFERENCES source_accounts(uuid),
  canonical_uuid TEXT NOT NULL,
  namespace TEXT NOT NULL CHECK(length(namespace) BETWEEN 1 AND 128),
  kind TEXT NOT NULL CHECK(length(kind) BETWEEN 1 AND 32),
  value TEXT NOT NULL CHECK(length(value) BETWEEN 1 AND 2048),
  UNIQUE(account_uuid,namespace,kind,value),
  FOREIGN KEY(account_uuid,canonical_uuid) REFERENCES source_accounts(uuid,canonical_uuid) ON UPDATE CASCADE
);

CREATE TABLE source_account_consolidations (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  uuid TEXT NOT NULL UNIQUE CHECK(length(uuid)=36 AND uuid=lower(uuid)
    AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
    AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
    AND uuid!='00000000-0000-0000-0000-000000000000'),
  source_uuid TEXT NOT NULL UNIQUE REFERENCES source_accounts(uuid),
  destination_uuid TEXT NOT NULL REFERENCES source_accounts(uuid),
  source_revision INTEGER NOT NULL CHECK(source_revision>0),
  destination_revision INTEGER NOT NULL CHECK(destination_revision>0),
  ownership_decision_uuid TEXT NOT NULL,
  signature TEXT NOT NULL CHECK(length(signature)=64 AND signature NOT GLOB '*[^0-9a-f]*'),
  request_digest TEXT NOT NULL CHECK(length(request_digest)=64 AND request_digest NOT GLOB '*[^0-9a-f]*'),
  origin TEXT NOT NULL CHECK(origin IN ('review','migration')),
  reason TEXT NOT NULL CHECK(length(reason)<=4096),
  accepted_identifier_conflicts BOOLEAN NOT NULL CHECK(accepted_identifier_conflicts IN (0,1)),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK(source_uuid!=destination_uuid),
  UNIQUE(destination_uuid,destination_revision),
  FOREIGN KEY(destination_uuid,ownership_decision_uuid) REFERENCES account_performer_decisions(account_uuid,uuid)
);

CREATE TABLE source_account_consolidation_context (
  source_uuid TEXT NOT NULL PRIMARY KEY REFERENCES source_accounts(uuid),
  destination_uuid TEXT NOT NULL REFERENCES source_accounts(uuid),
  CHECK(source_uuid!=destination_uuid)
);

CREATE TABLE media_roots (
  uuid TEXT NOT NULL PRIMARY KEY
    CHECK(length(uuid)=36 AND uuid=lower(uuid)
      AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
      AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
      AND length(replace(uuid,'-',''))=32
      AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
      AND uuid!='00000000-0000-0000-0000-000000000000'),
  revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, scan_enabled INTEGER NOT NULL DEFAULT 0 CHECK(scan_enabled IN (0,1)), exclude_video INTEGER NOT NULL DEFAULT 0 CHECK(exclude_video IN (0,1)), exclude_image INTEGER NOT NULL DEFAULT 0 CHECK(exclude_image IN (0,1)), scan_revision INTEGER NOT NULL DEFAULT 0 CHECK(scan_revision>=0),
  FOREIGN KEY(uuid,revision) REFERENCES media_root_revisions(root_uuid,revision) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE media_root_revisions (
  root_uuid TEXT NOT NULL REFERENCES media_roots(uuid),
  revision INTEGER NOT NULL CHECK(revision>0),
  label TEXT NOT NULL CHECK(length(label) BETWEEN 1 AND 1024),
  state TEXT NOT NULL CHECK(state IN ('active','disabled','retired')),
  server_path TEXT,
  directory_identity TEXT,
  origin TEXT NOT NULL CHECK(origin IN ('review','migration')),
  reason TEXT NOT NULL CHECK(length(reason)<=4096),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, unbound_path TEXT NOT NULL DEFAULT ''
  CHECK(length(unbound_path)<=4096 AND (unbound_path='' OR server_path IS NULL)),
  PRIMARY KEY(root_uuid,revision),
  CHECK((server_path IS NULL AND directory_identity IS NULL) OR
    (server_path IS NOT NULL AND directory_identity IS NOT NULL AND length(server_path) BETWEEN 1 AND 4096 AND length(directory_identity) BETWEEN 1 AND 128))
);

CREATE TABLE source_collections (
  uuid TEXT NOT NULL PRIMARY KEY
    CHECK(length(uuid)=36 AND uuid=lower(uuid)
      AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
      AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
      AND length(replace(uuid,'-',''))=32
      AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
      AND uuid!='00000000-0000-0000-0000-000000000000'),
  revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(uuid,revision) REFERENCES source_collection_revisions(collection_uuid,revision) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE source_collection_revisions (
  collection_uuid TEXT NOT NULL REFERENCES source_collections(uuid),
  revision INTEGER NOT NULL CHECK(revision>0),
  label TEXT NOT NULL CHECK(length(label) BETWEEN 1 AND 1024),
  kind TEXT NOT NULL CHECK(kind IN ('account','feed','subreddit','search','manual_batch','directory','legacy_catalog','collection')),
  namespace TEXT NOT NULL CHECK(length(namespace)<=128),
  state TEXT NOT NULL CHECK(state IN ('active','disabled','retired')),
  target_url TEXT NOT NULL CHECK(length(target_url)<=8192),
  account_uuid TEXT,
  root_uuid TEXT REFERENCES media_roots(uuid),
  path_prefix TEXT NOT NULL CHECK(length(path_prefix)<=4096),
  origin TEXT NOT NULL CHECK(origin IN ('review','migration','ingest')),
  reason TEXT NOT NULL CHECK(length(reason)<=4096),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(collection_uuid,revision),
  FOREIGN KEY(account_uuid,namespace) REFERENCES source_accounts(uuid,namespace),
  CHECK((root_uuid IS NULL AND path_prefix='') OR (root_uuid IS NOT NULL AND length(path_prefix)>0))
);

CREATE TABLE source_collection_captures (
  collection_uuid TEXT NOT NULL,
  collection_revision INTEGER NOT NULL,
  capture_uuid TEXT NOT NULL REFERENCES source_captures(uuid),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(collection_uuid,capture_uuid,collection_revision),
  FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision)
);

CREATE TABLE source_collection_media_intake (
  uuid TEXT NOT NULL PRIMARY KEY
    CHECK(length(uuid)=36 AND uuid=lower(uuid)
      AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
      AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
      AND length(replace(uuid,'-',''))=32
      AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
      AND uuid!='00000000-0000-0000-0000-000000000000'),
  collection_uuid TEXT NOT NULL,
  collection_revision INTEGER NOT NULL,
  media_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  submitted_media_uuid TEXT NOT NULL,
  origin TEXT NOT NULL CHECK(origin IN ('scan','ingest','review','migration')),
  reason TEXT NOT NULL CHECK(length(reason)<=4096),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision)
);

CREATE TABLE capture_publisher_decisions (
  uuid TEXT NOT NULL PRIMARY KEY
    CHECK(length(uuid)=36 AND uuid=lower(uuid)
      AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
      AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
      AND length(replace(uuid,'-',''))=32
      AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
      AND uuid!='00000000-0000-0000-0000-000000000000'),
  capture_uuid TEXT NOT NULL REFERENCES source_captures(uuid),
  revision INTEGER NOT NULL CHECK(revision>0),
  state TEXT NOT NULL CHECK(state IN ('linked','unlinked','undecided')),
  account_uuid TEXT REFERENCES source_accounts(uuid),
  origin TEXT NOT NULL CHECK(origin IN ('capture','review','migration')),
  policy TEXT NOT NULL CHECK(length(policy) BETWEEN 1 AND 128),
  reason TEXT NOT NULL CHECK(length(reason)<=4096),
  request_digest TEXT NOT NULL CHECK(length(request_digest)=64 AND request_digest NOT GLOB '*[^0-9a-f]*'),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK((state='linked' AND account_uuid IS NOT NULL) OR (state!='linked' AND account_uuid IS NULL)),
  UNIQUE(capture_uuid,revision),
  UNIQUE(capture_uuid,uuid),
  FOREIGN KEY(capture_uuid) REFERENCES capture_publisher_heads(capture_uuid) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE capture_publisher_heads (
  capture_uuid TEXT NOT NULL PRIMARY KEY REFERENCES source_captures(uuid),
  decision_uuid TEXT NOT NULL,
  FOREIGN KEY(capture_uuid,decision_uuid) REFERENCES capture_publisher_decisions(capture_uuid,uuid)
);

CREATE TABLE capture_publisher_claims (
  decision_uuid TEXT NOT NULL REFERENCES capture_publisher_decisions(uuid),
  identifier_uuid TEXT NOT NULL,
  evidence_key TEXT NOT NULL,
  PRIMARY KEY(decision_uuid,identifier_uuid,evidence_key),
  FOREIGN KEY(identifier_uuid,evidence_key) REFERENCES source_account_identifier_evidence(identifier_uuid,evidence_key)
);

CREATE TABLE capture_publisher_write_context (
  request_uuid TEXT NOT NULL PRIMARY KEY,
  capture_uuid TEXT NOT NULL REFERENCES source_captures(uuid)
);

CREATE TABLE ingest_producers (
  uuid TEXT NOT NULL PRIMARY KEY CHECK(length(uuid)=36 AND uuid=lower(uuid)
    AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
    AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
    AND uuid!='00000000-0000-0000-0000-000000000000'),
  label TEXT NOT NULL CHECK(length(label) BETWEEN 1 AND 256),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE ingest_credentials (
  uuid TEXT NOT NULL PRIMARY KEY CHECK(length(uuid)=36 AND uuid=lower(uuid)
    AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
    AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
    AND uuid!='00000000-0000-0000-0000-000000000000'),
  producer_uuid TEXT NOT NULL REFERENCES ingest_producers(uuid),
  secret_hash TEXT NOT NULL CHECK(length(secret_hash)=64 AND secret_hash NOT GLOB '*[^0-9a-f]*'),
  expires_at DATETIME,
  revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN (0,1)),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(producer_uuid,uuid)
);

CREATE TABLE ingest_credential_scopes (
  credential_uuid TEXT NOT NULL REFERENCES ingest_credentials(uuid),
  collection_uuid TEXT NOT NULL REFERENCES source_collections(uuid),
  root_uuid TEXT REFERENCES media_roots(uuid),
  PRIMARY KEY(credential_uuid,collection_uuid)
);

CREATE TABLE media_contents (
 uuid TEXT NOT NULL PRIMARY KEY
 CHECK(length(uuid)=36 AND uuid=lower(uuid) AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
 AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-' AND length(replace(uuid,'-',''))=32
 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*' AND uuid!='00000000-0000-0000-0000-000000000000'),
 sha256 TEXT NOT NULL UNIQUE CHECK(length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*'),
 size INTEGER NOT NULL CHECK(typeof(size)='integer' AND size>=0),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE file_content_versions (
 file_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
 generation INTEGER NOT NULL CHECK(typeof(generation)='integer' AND generation>0),
 content_uuid TEXT NOT NULL REFERENCES media_contents(uuid),
 root_uuid TEXT NOT NULL REFERENCES media_roots(uuid),
 root_revision INTEGER NOT NULL CHECK(typeof(root_revision)='integer' AND root_revision>0),
 relative_path TEXT NOT NULL CHECK(length(relative_path)>0 AND length(relative_path)<=4096),
 filesystem_identity TEXT NOT NULL CHECK(length(filesystem_identity)>0 AND length(filesystem_identity)<=256),
 mod_time_text TEXT NOT NULL CHECK(length(mod_time_text)>0 AND length(mod_time_text)<=64),
 change_token TEXT NOT NULL CHECK(length(change_token)<=256),
 verified_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(file_uuid,generation),
 FOREIGN KEY(root_uuid,root_revision) REFERENCES media_root_revisions(root_uuid,revision)
);

CREATE TABLE archive_job_submissions (
 request_uuid TEXT NOT NULL PRIMARY KEY CHECK(length(request_uuid)=36 AND request_uuid=lower(request_uuid)
   AND substr(request_uuid,9,1)='-' AND substr(request_uuid,14,1)='-' AND substr(request_uuid,19,1)='-' AND substr(request_uuid,24,1)='-'
   AND length(replace(request_uuid,'-',''))=32 AND replace(request_uuid,'-','') NOT GLOB '*[^0-9a-f]*'
   AND request_uuid!='00000000-0000-0000-0000-000000000000'),
 digest TEXT NOT NULL CHECK(length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*'),
 job_uuid TEXT NOT NULL REFERENCES archive_jobs(uuid),
 created_at_ms INTEGER NOT NULL CHECK(typeof(created_at_ms)='integer' AND created_at_ms>0)
);

CREATE TABLE archive_job_attempts (
 job_uuid TEXT NOT NULL REFERENCES archive_jobs(uuid),
 fence INTEGER NOT NULL CHECK(typeof(fence)='integer' AND fence>0),
 owner_uuid TEXT NOT NULL CHECK(length(owner_uuid)=36 AND owner_uuid=lower(owner_uuid)
   AND substr(owner_uuid,9,1)='-' AND substr(owner_uuid,14,1)='-' AND substr(owner_uuid,19,1)='-' AND substr(owner_uuid,24,1)='-'
   AND length(replace(owner_uuid,'-',''))=32 AND replace(owner_uuid,'-','') NOT GLOB '*[^0-9a-f]*'
   AND owner_uuid!='00000000-0000-0000-0000-000000000000'),
 started_at_ms INTEGER NOT NULL CHECK(typeof(started_at_ms)='integer' AND started_at_ms>0),
 ended_at_ms INTEGER,
 outcome TEXT NOT NULL DEFAULT 'running' CHECK(outcome IN ('running','succeeded','retry','failed','cancelled','expired')),
 result TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(result) AND json_type(result)='object' AND length(CAST(result AS BLOB))<=16384),
 error_code TEXT NOT NULL DEFAULT '' CHECK(length(error_code)<=128),
 PRIMARY KEY(job_uuid,fence),
 CHECK((outcome='running' AND ended_at_ms IS NULL) OR (outcome!='running' AND typeof(ended_at_ms)='integer' AND ended_at_ms>=started_at_ms))
);

CREATE TABLE file_path_fences (
 folder_path TEXT NOT NULL,
 basename TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>0),
 PRIMARY KEY(folder_path,basename)
);

CREATE TABLE metadata_policies (
  collection_uuid TEXT NOT NULL PRIMARY KEY REFERENCES source_collections(uuid),
  revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
  FOREIGN KEY(collection_uuid,revision) REFERENCES metadata_policy_revisions(collection_uuid,revision) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE metadata_policy_revisions (
  collection_uuid TEXT NOT NULL REFERENCES metadata_policies(collection_uuid),
  revision INTEGER NOT NULL CHECK(revision>0),
  collection_revision INTEGER NOT NULL CHECK(collection_revision>0),
  definition TEXT NOT NULL CHECK(json_valid(definition) AND json_type(definition)='object' AND length(CAST(definition AS BLOB))<=131072),
  origin TEXT NOT NULL CHECK(origin IN ('review','migration')),
  reason TEXT NOT NULL CHECK(length(reason)<=4096),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(collection_uuid,revision),
  FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision)
);

CREATE TABLE metadata_decision_policies (
  decision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES metadata_field_decisions(uuid),
  collection_uuid TEXT NOT NULL,
  revision INTEGER NOT NULL,
  FOREIGN KEY(collection_uuid,revision) REFERENCES metadata_policy_revisions(collection_uuid,revision)
);

CREATE TABLE source_run_requests (
  producer_uuid TEXT NOT NULL REFERENCES ingest_producers(uuid),
  request_uuid TEXT NOT NULL CHECK(length(request_uuid)=36 AND request_uuid=lower(request_uuid)
    AND substr(request_uuid,9,1)='-' AND substr(request_uuid,14,1)='-' AND substr(request_uuid,19,1)='-' AND substr(request_uuid,24,1)='-'
    AND length(replace(request_uuid,'-',''))=32 AND replace(request_uuid,'-','') NOT GLOB '*[^0-9a-f]*'
    AND request_uuid!='00000000-0000-0000-0000-000000000000'),
  digest TEXT NOT NULL CHECK(length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*'),
  run_uuid TEXT NOT NULL REFERENCES source_runs(uuid),
  created_at_ms INTEGER NOT NULL,
  PRIMARY KEY(producer_uuid,request_uuid)
);

CREATE TABLE source_run_attempts (
  run_uuid TEXT NOT NULL REFERENCES source_runs(uuid),
  fence INTEGER NOT NULL CHECK(fence>0),
  producer_uuid TEXT NOT NULL REFERENCES ingest_producers(uuid),
  owner_uuid TEXT NOT NULL,
  window TEXT NOT NULL CHECK(json_valid(window) AND json_type(window)='object' AND length(window)<=512),
  progress TEXT NOT NULL CHECK(json_valid(progress) AND json_type(progress)='object' AND length(progress)<=4096),
  started_at_ms INTEGER NOT NULL,
  ended_at_ms INTEGER,
  outcome TEXT NOT NULL DEFAULT 'running' CHECK(outcome IN ('running','succeeded','retry','deferred','cancelled','expired')),
  error_code TEXT NOT NULL DEFAULT '' CHECK(length(error_code)<=128),
  PRIMARY KEY(run_uuid,fence),
  CHECK((outcome='running' AND ended_at_ms IS NULL) OR (outcome!='running' AND ended_at_ms>=started_at_ms))
);

CREATE TABLE source_run_cooldowns (
  target_key TEXT NOT NULL PRIMARY KEY CHECK(length(target_key)=64 AND target_key NOT GLOB '*[^0-9a-f]*'),
  available_at_ms INTEGER NOT NULL CHECK(available_at_ms>0)
);

CREATE TABLE source_run_reviews (
  run_uuid TEXT NOT NULL REFERENCES source_runs(uuid),
  revision INTEGER NOT NULL,
  action TEXT NOT NULL CHECK(action IN ('retry','cancel')),
  created_at_ms INTEGER NOT NULL,
  PRIMARY KEY(run_uuid,revision)
);

CREATE TABLE ingest_credential_roots (
 credential_uuid TEXT NOT NULL REFERENCES ingest_credentials(uuid),
 root_uuid TEXT NOT NULL REFERENCES media_roots(uuid),
 PRIMARY KEY(credential_uuid,root_uuid)
);

CREATE TABLE source_backfill_decisions (
  id INTEGER PRIMARY KEY,
  uuid TEXT NOT NULL UNIQUE CHECK(length(uuid)=36 AND uuid=lower(uuid)
    AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
    AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
    AND uuid!='00000000-0000-0000-0000-000000000000'),
  root_uuid TEXT NOT NULL REFERENCES media_roots(uuid),
  platform TEXT NOT NULL CHECK(platform IN ('reddit','twitter')),
  account TEXT NOT NULL CHECK(length(account) BETWEEN 1 AND 32),
  component TEXT NOT NULL CHECK(length(component) BETWEEN 1 AND 64),
  outcome TEXT NOT NULL CHECK(outcome IN ('completed','skipped')),
  basis TEXT NOT NULL CHECK(basis IN ('source_runs','legacy_completion','legacy_skip')),
  decided_at TEXT NOT NULL,
  producer_uuid TEXT REFERENCES ingest_producers(uuid),
  source_uuid TEXT,
  source_table TEXT,
  source_key TEXT,
  evidence TEXT NOT NULL CHECK(json_valid(evidence) AND json_type(evidence)='object' AND length(CAST(evidence AS BLOB))<=1048576),
  input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64 AND input_sha256 NOT GLOB '*[^0-9a-f]*'),
  created_at TEXT NOT NULL,
  UNIQUE(source_uuid,source_table,source_key),
  CHECK((platform='reddit' AND account=lower(account) AND account NOT GLOB '*[^a-z0-9_-]*' AND account!='me')
     OR (platform='twitter' AND length(account)<=30 AND account NOT GLOB '*[^0-9]*' AND (account='0' OR substr(account,1,1)!='0'))),
  CHECK((basis='source_runs' AND outcome='completed' AND component!='*' AND producer_uuid IS NOT NULL AND source_uuid IS NULL AND source_table IS NULL AND source_key IS NULL)
     OR (basis='legacy_completion' AND outcome='completed' AND component!='*' AND producer_uuid IS NULL AND source_uuid IS NOT NULL AND source_table='backfill_completion' AND source_key IS NOT NULL)
     OR (basis='legacy_skip' AND outcome='skipped' AND component='*' AND producer_uuid IS NULL AND source_uuid IS NOT NULL AND source_table='legacy_backfill_skip' AND source_key IS NOT NULL))
);

CREATE TABLE source_backfill_requests (
  decision_uuid TEXT NOT NULL REFERENCES source_backfill_decisions(uuid),
  producer_uuid TEXT NOT NULL,
  request_uuid TEXT NOT NULL,
  PRIMARY KEY(decision_uuid,producer_uuid,request_uuid),
  FOREIGN KEY(producer_uuid,request_uuid) REFERENCES source_run_requests(producer_uuid,request_uuid)
);

CREATE TABLE scan_journals (
  uuid TEXT PRIMARY KEY CHECK(length(uuid)=36),
  root_uuid TEXT NOT NULL REFERENCES media_roots(uuid),
  source_uuid TEXT NOT NULL CHECK(length(source_uuid)=36),
  input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64 AND input_sha256 NOT GLOB '*[^0-9a-f]*'),
  captured_at TEXT NOT NULL,
  record_count INTEGER NOT NULL CHECK(record_count BETWEEN 0 AND 10000),
  inventory TEXT NOT NULL CHECK(json_valid(inventory) AND json_type(inventory)='object' AND length(inventory)<=4096),
  created_at TEXT NOT NULL
);

CREATE TABLE scan_journal_records (
  id INTEGER PRIMARY KEY,
  uuid TEXT NOT NULL UNIQUE CHECK(length(uuid)=36),
  journal_uuid TEXT NOT NULL REFERENCES scan_journals(uuid),
  source_table TEXT NOT NULL CHECK(source_table IN ('scan_jobs','extractor_jobs','scan_deferrals',
    'backfill_scan_completion','collection_backfill_completion','backfill_policy_migrations','legacy_handoffs')),
  source_key TEXT NOT NULL CHECK(json_valid(source_key) AND json_type(source_key)='array' AND length(source_key)<=8192),
  context TEXT NOT NULL DEFAULT '' CHECK(context IN ('','host','n8n')),
  target_url TEXT NOT NULL DEFAULT '' CHECK(length(target_url)<=8192),
  disposition TEXT NOT NULL CHECK(disposition IN ('pending_binding','historical','review')),
  summary TEXT NOT NULL CHECK(json_valid(summary) AND json_type(summary)='object' AND length(CAST(summary AS BLOB))<=16384),
  evidence TEXT NOT NULL CHECK(json_valid(evidence) AND json_type(evidence)='object' AND length(CAST(evidence AS BLOB))<=1048576),
  UNIQUE(journal_uuid,source_table,source_key)
);

CREATE TABLE scan_journal_activations (
  uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36 AND uuid=lower(uuid)),
  journal_uuid TEXT NOT NULL REFERENCES scan_journals(uuid),
  run_uuid TEXT NOT NULL UNIQUE REFERENCES source_runs(uuid),
  plan TEXT NOT NULL CHECK(json_valid(plan) AND json_type(plan)='object' AND length(plan)<=1048576),
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0)
);

CREATE TABLE scan_journal_activation_jobs (
  source_uuid TEXT NOT NULL,
  source_key TEXT NOT NULL,
  record_uuid TEXT NOT NULL UNIQUE REFERENCES scan_journal_records(uuid),
  activation_uuid TEXT NOT NULL REFERENCES scan_journal_activations(uuid),
  PRIMARY KEY(source_uuid,source_key)
);

CREATE TABLE catalog_identity_imports (
  uuid TEXT PRIMARY KEY CHECK(length(uuid)=36),
  source_uuid TEXT NOT NULL CHECK(length(source_uuid)=36),
  namespace TEXT NOT NULL CHECK(length(namespace) BETWEEN 1 AND 128),
  input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64 AND input_sha256 NOT GLOB '*[^0-9a-f]*'),
  plan_sha256 TEXT NOT NULL CHECK(length(plan_sha256)=64 AND plan_sha256 NOT GLOB '*[^0-9a-f]*'),
  record_count INTEGER NOT NULL CHECK(record_count BETWEEN 0 AND 10000),
  plan TEXT NOT NULL CHECK(json_valid(plan) AND json_type(plan)='object' AND length(CAST(plan AS BLOB))<=8388608),
  created_at TEXT NOT NULL,
  UNIQUE(source_uuid,namespace)
);

CREATE TABLE catalog_identity_import_records (
  id INTEGER PRIMARY KEY,
  import_uuid TEXT NOT NULL REFERENCES catalog_identity_imports(uuid),
  source_table TEXT NOT NULL CHECK(source_table IN ('performer_identities','performer_identity_bindings',
    'performer_account_associations','performer_identity_events','performer_identity_migrations',
    'catalog_metadata_performers','catalog_metadata_accounts')),
  source_key TEXT NOT NULL CHECK(json_valid(source_key) AND json_type(source_key)='array' AND length(source_key)<=8192),
  outcome TEXT NOT NULL CHECK(outcome IN ('copied','mapped','review','superseded')),
  reason TEXT NOT NULL,
  archive_uuid TEXT REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  account_uuid TEXT REFERENCES source_accounts(uuid) ON UPDATE CASCADE,
  evidence TEXT NOT NULL CHECK(json_valid(evidence) AND json_type(evidence)='object' AND length(CAST(evidence AS BLOB))<=1048576),
  UNIQUE(import_uuid,source_table,source_key)
);

CREATE TABLE catalog_registry_imports (
 uuid TEXT PRIMARY KEY CHECK(length(uuid)=36),
 source_uuid TEXT NOT NULL UNIQUE CHECK(length(source_uuid)=36),
 identity_import_uuid TEXT NOT NULL REFERENCES catalog_identity_imports(uuid),
 input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64 AND input_sha256 NOT GLOB '*[^0-9a-f]*'),
 plan_sha256 TEXT NOT NULL CHECK(length(plan_sha256)=64 AND plan_sha256 NOT GLOB '*[^0-9a-f]*'),
 record_count INTEGER NOT NULL CHECK(record_count BETWEEN 0 AND 25000),
 plan TEXT NOT NULL CHECK(json_valid(plan) AND json_type(plan)='object' AND length(CAST(plan AS BLOB))<=33554432),
 created_at TEXT NOT NULL
);

CREATE TABLE catalog_registry_import_records (
 id INTEGER PRIMARY KEY,
 import_uuid TEXT NOT NULL REFERENCES catalog_registry_imports(uuid),
 source_table TEXT NOT NULL CHECK(source_table IN ('catalogs','routes','links','account_identifiers','account_identifier_checkpoints','account_profile_urls')),
 source_key TEXT NOT NULL CHECK(json_valid(source_key) AND json_type(source_key)='array' AND length(CAST(source_key AS BLOB))<=32768),
 outcome TEXT NOT NULL CHECK(outcome IN ('copied','mapped','review')),
 reason TEXT NOT NULL,
 account_uuid TEXT REFERENCES source_accounts(uuid) ON UPDATE CASCADE,
 collection_uuid TEXT REFERENCES source_collections(uuid) ON UPDATE CASCADE,
 evidence TEXT NOT NULL CHECK(json_valid(evidence) AND json_type(evidence)='object' AND length(CAST(evidence AS BLOB))<=1048576),
 UNIQUE(import_uuid,source_table,source_key)
);

CREATE TABLE catalog_account_mappings (
 source_uuid TEXT NOT NULL,
 account_key TEXT NOT NULL,
 account_uuid TEXT NOT NULL REFERENCES source_accounts(uuid) ON UPDATE CASCADE,
 import_uuid TEXT NOT NULL REFERENCES catalog_registry_imports(uuid),
 PRIMARY KEY(source_uuid,account_key)
);

CREATE TABLE catalog_collection_mappings (
 source_uuid TEXT NOT NULL,
 catalog_id TEXT NOT NULL,
 collection_uuid TEXT NOT NULL REFERENCES source_collections(uuid) ON UPDATE CASCADE,
 import_uuid TEXT NOT NULL REFERENCES catalog_registry_imports(uuid),
 PRIMARY KEY(source_uuid,catalog_id)
);

CREATE TABLE catalog_snapshots (
 uuid TEXT PRIMARY KEY CHECK(length(uuid)=36),
 source_uuid TEXT NOT NULL CHECK(length(source_uuid)=36),
 registry_import_uuid TEXT NOT NULL REFERENCES catalog_registry_imports(uuid),
 catalog_id TEXT NOT NULL,
 collection_uuid TEXT NOT NULL REFERENCES source_collections(uuid) ON UPDATE CASCADE,
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64 AND manifest_sha256 NOT GLOB '*[^0-9a-f]*'),
 manifest BLOB NOT NULL CHECK(typeof(manifest)='blob' AND length(manifest)<=8388608),
 captured_at TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('receiving','received')),
 chunk_count INTEGER NOT NULL CHECK(chunk_count BETWEEN 1 AND 100000),
 record_count INTEGER NOT NULL CHECK(record_count BETWEEN 1 AND 10000000),
 byte_count INTEGER NOT NULL CHECK(byte_count>0),
 next_chunk INTEGER NOT NULL DEFAULT 0 CHECK(next_chunk BETWEEN 0 AND chunk_count),
 received_records INTEGER NOT NULL DEFAULT 0 CHECK(received_records BETWEEN 0 AND record_count),
 received_bytes INTEGER NOT NULL DEFAULT 0 CHECK(received_bytes BETWEEN 0 AND byte_count),
 last_table TEXT NOT NULL DEFAULT '',
 last_key TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(last_key) AND json_type(last_key)='array' AND length(CAST(last_key AS BLOB))<=32768),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL, nfo_compacted INTEGER NOT NULL DEFAULT 0
 CHECK(nfo_compacted IN (0,1)), memberships_compacted INTEGER NOT NULL DEFAULT 0
 CHECK(memberships_compacted IN (0,1)),
 UNIQUE(source_uuid,catalog_id),
 CHECK((state='received')=(next_chunk=chunk_count)),
 CHECK(state!='received' OR (received_records=record_count AND received_bytes=byte_count))
);

CREATE TABLE catalog_snapshot_tables (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_snapshots(uuid),
 source_table TEXT NOT NULL,
 received_records INTEGER NOT NULL DEFAULT 0 CHECK(received_records>=0),
 received_bytes INTEGER NOT NULL DEFAULT 0 CHECK(received_bytes>=0),
 received_sha256 TEXT NOT NULL CHECK(length(received_sha256)=64),
 hash_state BLOB NOT NULL CHECK(typeof(hash_state)='blob' AND length(hash_state)<=256),
 PRIMARY KEY(snapshot_uuid,source_table)
);

CREATE TABLE catalog_snapshot_chunks (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_snapshots(uuid),
 chunk_index INTEGER NOT NULL CHECK(chunk_index BETWEEN 0 AND 99999),
 sha256 TEXT NOT NULL CHECK(length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*'),
 record_count INTEGER NOT NULL CHECK(record_count BETWEEN 1 AND 1000),
 byte_count INTEGER NOT NULL CHECK(byte_count BETWEEN 1 AND 16777216),
 created_at TEXT NOT NULL,
 PRIMARY KEY(snapshot_uuid,chunk_index)
);

CREATE TABLE catalog_snapshot_records (
 snapshot_uuid TEXT NOT NULL,
 ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 1 AND 10000000),
 chunk_index INTEGER NOT NULL,
 source_table TEXT NOT NULL,
 source_key TEXT NOT NULL CHECK(json_valid(source_key) AND json_type(source_key)='array' AND length(CAST(source_key AS BLOB))<=32768),
 data TEXT NOT NULL CHECK(json_valid(data) AND json_type(data)='object'),
 byte_count INTEGER NOT NULL CHECK(byte_count=length(CAST(data AS BLOB)) AND byte_count BETWEEN 1 AND 16777216),
 data_sha256 TEXT NOT NULL CHECK(length(data_sha256)=64 AND data_sha256 NOT GLOB '*[^0-9a-f]*'),
 PRIMARY KEY(snapshot_uuid,ordinal),
 UNIQUE(snapshot_uuid,source_table,source_key),
 FOREIGN KEY(snapshot_uuid,chunk_index) REFERENCES catalog_snapshot_chunks(snapshot_uuid,chunk_index),
 FOREIGN KEY(snapshot_uuid,source_table) REFERENCES catalog_snapshot_tables(snapshot_uuid,source_table)
);

CREATE TABLE catalog_evidence_imports (
 snapshot_uuid TEXT PRIMARY KEY REFERENCES catalog_snapshots(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records BETWEEN 0 AND processed_records),
 capture_mappings INTEGER NOT NULL DEFAULT 0 CHECK(capture_mappings BETWEEN 0 AND processed_records),
 profile_mappings INTEGER NOT NULL DEFAULT 0 CHECK(profile_mappings BETWEEN 0 AND processed_records),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 CHECK(state='running' OR processed_records=source_records)
);

CREATE TABLE catalog_evidence_posts (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_evidence_imports(snapshot_uuid),
 source_key TEXT NOT NULL CHECK(json_valid(source_key) AND json_type(source_key)='array'),
 source_ordinal INTEGER NOT NULL CHECK(source_ordinal>0),
 data_sha256 TEXT NOT NULL CHECK(length(data_sha256)=64),
 post_uuid TEXT REFERENCES source_posts(uuid),
 basis TEXT NOT NULL,
 reason TEXT NOT NULL,
 PRIMARY KEY(snapshot_uuid,source_key)
);

CREATE TABLE catalog_evidence_records (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_evidence_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 source_table TEXT NOT NULL CHECK(source_table IN ('account_snapshots','posts','observations','observation_details')),
 source_key TEXT NOT NULL CHECK(json_valid(source_key) AND json_type(source_key)='array'),
 data_sha256 TEXT NOT NULL CHECK(length(data_sha256)=64),
 outcome TEXT NOT NULL CHECK(outcome IN ('mapped','shared','review')),
 reason TEXT NOT NULL,
 post_uuid TEXT REFERENCES source_posts(uuid),
 capture_uuid TEXT REFERENCES source_captures(uuid),
 profile_hash TEXT REFERENCES source_profile_bodies(hash),
 header_sha256 TEXT CHECK(header_sha256 IS NULL OR length(header_sha256)=64),
 PRIMARY KEY(snapshot_uuid,ordinal)
);

CREATE TABLE source_post_urls (
 uuid TEXT NOT NULL PRIMARY KEY CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 url TEXT NOT NULL CHECK(length(CAST(url AS BLOB)) BETWEEN 1 AND 8192),
 UNIQUE(post_uuid,url)
);

CREATE TABLE source_post_url_evidence (
 uuid TEXT NOT NULL PRIMARY KEY CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 url_uuid TEXT NOT NULL REFERENCES source_post_urls(uuid),
 origin TEXT NOT NULL CHECK(origin IN ('capture','review','migration')),
 basis TEXT NOT NULL CHECK(length(basis) BETWEEN 1 AND 128),
 observed_at DATETIME NOT NULL CHECK(length(observed_at)=30 AND substr(observed_at,11,1)='T' AND substr(observed_at,20,1)='.' AND substr(observed_at,30,1)='Z' AND julianday(observed_at) IS NOT NULL),
 details TEXT NOT NULL CHECK(json_valid(details) AND json_type(details)='object' AND length(CAST(details AS BLOB))<=65536),
 request_digest TEXT NOT NULL CHECK(length(request_digest)=64 AND request_digest NOT GLOB '*[^0-9a-f]*')
);

CREATE TABLE source_post_identifier_evidence (
 uuid TEXT NOT NULL PRIMARY KEY CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 namespace TEXT NOT NULL,
 value TEXT NOT NULL,
 origin TEXT NOT NULL CHECK(origin IN ('capture','review','migration')),
 basis TEXT NOT NULL CHECK(length(basis) BETWEEN 1 AND 128),
 observed_at DATETIME NOT NULL CHECK(length(observed_at)=30 AND substr(observed_at,11,1)='T' AND substr(observed_at,20,1)='.' AND substr(observed_at,30,1)='Z' AND julianday(observed_at) IS NOT NULL),
 details TEXT NOT NULL CHECK(json_valid(details) AND json_type(details)='object' AND length(CAST(details AS BLOB))<=65536),
 request_digest TEXT NOT NULL CHECK(length(request_digest)=64 AND request_digest NOT GLOB '*[^0-9a-f]*'),
 FOREIGN KEY(namespace,value) REFERENCES source_post_identifiers(namespace,value)
);

CREATE TABLE source_post_account_claims (
 uuid TEXT NOT NULL PRIMARY KEY CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 account_uuid TEXT NOT NULL REFERENCES source_accounts(uuid),
 origin TEXT NOT NULL CHECK(origin IN ('capture','review','migration')),
 basis TEXT NOT NULL CHECK(length(basis) BETWEEN 1 AND 128),
 observed_at DATETIME NOT NULL CHECK(length(observed_at)=30 AND substr(observed_at,11,1)='T' AND substr(observed_at,20,1)='.' AND substr(observed_at,30,1)='Z' AND julianday(observed_at) IS NOT NULL),
 details TEXT NOT NULL CHECK(json_valid(details) AND json_type(details)='object' AND length(CAST(details AS BLOB))<=65536),
 request_digest TEXT NOT NULL CHECK(length(request_digest)=64 AND request_digest NOT GLOB '*[^0-9a-f]*')
);

CREATE TABLE catalog_relations_imports (
 snapshot_uuid TEXT PRIMARY KEY REFERENCES catalog_snapshots(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 mapped_records INTEGER NOT NULL DEFAULT 0 CHECK(mapped_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 unassigned_records INTEGER NOT NULL DEFAULT 0 CHECK(unassigned_records>=0),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 CHECK(mapped_records+review_records+unassigned_records=processed_records),
 CHECK(state='running' OR processed_records=source_records)
);

CREATE TABLE catalog_relation_records (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_relations_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 source_table TEXT NOT NULL CHECK(source_table IN ('accounts','handles','posts','post_urls','post_aliases')),
 source_key TEXT NOT NULL CHECK(json_valid(source_key) AND json_type(source_key)='array'),
 data_sha256 TEXT NOT NULL CHECK(length(data_sha256)=64),
 source_values TEXT NOT NULL CHECK(length(CAST(source_values AS BLOB))<=16777216 AND json_valid(source_values) AND json_type(source_values)='object'),
 outcome TEXT NOT NULL CHECK(outcome IN ('mapped','review','unassigned')),
 reason TEXT NOT NULL,
 account_uuid TEXT REFERENCES source_accounts(uuid),
 identifier_uuid TEXT REFERENCES source_account_identifiers(uuid),
 identifier_evidence_key TEXT,
 post_uuid TEXT REFERENCES source_posts(uuid),
 url_evidence_uuid TEXT REFERENCES source_post_url_evidence(uuid),
 post_identifier_evidence_uuid TEXT REFERENCES source_post_identifier_evidence(uuid),
 account_claim_uuid TEXT REFERENCES source_post_account_claims(uuid),
 PRIMARY KEY(snapshot_uuid,ordinal),
 UNIQUE(snapshot_uuid,source_table,source_key),
 FOREIGN KEY(identifier_uuid,identifier_evidence_key) REFERENCES source_account_identifier_evidence(identifier_uuid,evidence_key),
 CHECK((identifier_uuid IS NULL)=(identifier_evidence_key IS NULL)),
 CHECK((outcome='mapped' AND reason='') OR (outcome!='mapped' AND reason!='')),
 CHECK(outcome='mapped' OR (identifier_uuid IS NULL AND url_evidence_uuid IS NULL AND post_identifier_evidence_uuid IS NULL AND account_claim_uuid IS NULL)),
 CHECK(outcome!='unassigned' OR source_table='posts'),
 CHECK(identifier_uuid IS NULL OR (source_table IN ('accounts','handles') AND account_uuid IS NOT NULL)),
 CHECK(url_evidence_uuid IS NULL OR (source_table='post_urls' AND post_uuid IS NOT NULL)),
 CHECK(post_identifier_evidence_uuid IS NULL OR (source_table='post_aliases' AND post_uuid IS NOT NULL)),
 CHECK(account_claim_uuid IS NULL OR (source_table='posts' AND post_uuid IS NOT NULL AND account_uuid IS NOT NULL)),
 CHECK(outcome!='mapped' OR identifier_uuid IS NOT NULL OR url_evidence_uuid IS NOT NULL OR post_identifier_evidence_uuid IS NOT NULL OR account_claim_uuid IS NOT NULL)
);

CREATE TABLE catalog_publisher_imports (
 snapshot_uuid TEXT PRIMARY KEY REFERENCES catalog_snapshots(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64),
 policy TEXT NOT NULL CHECK(length(policy) BETWEEN 1 AND 128),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 linked_records INTEGER NOT NULL DEFAULT 0 CHECK(linked_records>=0),
 preserved_records INTEGER NOT NULL DEFAULT 0 CHECK(preserved_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 unavailable_records INTEGER NOT NULL DEFAULT 0 CHECK(unavailable_records>=0),
 created_accounts INTEGER NOT NULL DEFAULT 0 CHECK(created_accounts BETWEEN 0 AND linked_records),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 CHECK(linked_records+preserved_records+review_records+unavailable_records=processed_records),
 CHECK(state='running' OR processed_records=source_records)
);

CREATE TABLE catalog_publisher_records (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_publisher_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 capture_uuid TEXT REFERENCES source_captures(uuid),
 decision_uuid TEXT,
 outcome TEXT NOT NULL CHECK(outcome IN ('linked','preserved','review','unavailable')),
 reason TEXT NOT NULL CHECK(length(reason)<=128),
 created_account INTEGER NOT NULL DEFAULT 0 CHECK(created_account IN (0,1)),
 context_json TEXT NOT NULL CHECK(json_valid(context_json) AND json_type(context_json)='object' AND length(CAST(context_json AS BLOB))<=65536),
 PRIMARY KEY(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES catalog_evidence_records(snapshot_uuid,ordinal),
 FOREIGN KEY(capture_uuid,decision_uuid) REFERENCES capture_publisher_decisions(capture_uuid,uuid),
 CHECK(capture_uuid IS NOT NULL OR (outcome='review' AND decision_uuid IS NULL)),
 CHECK(outcome NOT IN ('linked','preserved') OR decision_uuid IS NOT NULL),
 CHECK((outcome='linked' AND reason='') OR (outcome!='linked' AND reason!='')),
 CHECK(created_account=0 OR outcome='linked')
);

CREATE TABLE catalog_attachment_imports (
 snapshot_uuid TEXT PRIMARY KEY REFERENCES catalog_snapshots(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64),
 policy TEXT NOT NULL CHECK(length(policy) BETWEEN 1 AND 128),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 mapped_records INTEGER NOT NULL DEFAULT 0 CHECK(mapped_records>=0),
 preserved_records INTEGER NOT NULL DEFAULT 0 CHECK(preserved_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 unavailable_records INTEGER NOT NULL DEFAULT 0 CHECK(unavailable_records>=0),
 changed_selections INTEGER NOT NULL DEFAULT 0 CHECK(changed_selections BETWEEN 0 AND mapped_records),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 CHECK(mapped_records+preserved_records+review_records+unavailable_records=processed_records),
 CHECK(state='running' OR processed_records=source_records)
);

CREATE TABLE catalog_attachment_records (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_attachment_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 post_uuid TEXT REFERENCES source_posts(uuid),
 capture_uuid TEXT REFERENCES source_captures(uuid),
 manifest_uuid TEXT,
 selection_uuid TEXT,
 outcome TEXT NOT NULL CHECK(outcome IN ('mapped','preserved','review','unavailable')),
 reason TEXT NOT NULL CHECK(length(reason)<=128),
 selection_changed INTEGER NOT NULL DEFAULT 0 CHECK(selection_changed IN (0,1)),
 context_json TEXT NOT NULL CHECK(json_valid(context_json) AND json_type(context_json)='object' AND length(CAST(context_json AS BLOB))<=65536),
 PRIMARY KEY(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES catalog_evidence_records(snapshot_uuid,ordinal),
 FOREIGN KEY(post_uuid,capture_uuid) REFERENCES source_captures(post_uuid,uuid),
 FOREIGN KEY(capture_uuid,manifest_uuid) REFERENCES source_capture_attachment_manifests(capture_uuid,manifest_uuid),
 FOREIGN KEY(post_uuid,selection_uuid) REFERENCES post_attachment_decisions(post_uuid,uuid),
 CHECK(capture_uuid IS NULL OR post_uuid IS NOT NULL),
 CHECK(capture_uuid IS NOT NULL OR (outcome='review' AND manifest_uuid IS NULL AND selection_uuid IS NULL)),
 CHECK(outcome NOT IN ('mapped','preserved') OR (manifest_uuid IS NOT NULL AND selection_uuid IS NOT NULL)),
 CHECK((outcome='mapped' AND reason='') OR (outcome!='mapped' AND reason!='')),
 CHECK(selection_changed=0 OR outcome='mapped')
);

CREATE TABLE "source_media_evidence" (
  uuid TEXT NOT NULL PRIMARY KEY
    CHECK (length(uuid) = 36 AND uuid = lower(uuid)
      AND substr(uuid, 9, 1) = '-' AND substr(uuid, 14, 1) = '-'
      AND substr(uuid, 19, 1) = '-' AND substr(uuid, 24, 1) = '-'
      AND length(replace(uuid, '-', '')) = 32
      AND replace(uuid, '-', '') NOT GLOB '*[^0-9a-f]*'
      AND uuid != '00000000-0000-0000-0000-000000000000'),
  post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
  attachment_uuid TEXT,
  capture_uuid TEXT,
  manifest_uuid TEXT,
  position INTEGER,
  media_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  file_uuid TEXT REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  basis TEXT NOT NULL CHECK (basis IN ('observed-file', 'verified-bytes', 'review', 'legacy')),
  details TEXT NOT NULL CHECK (length(details) <= 65536 AND json_valid(details) AND json_type(details) = 'object'),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK ((manifest_uuid IS NULL) = (position IS NULL)),
  CHECK ((manifest_uuid IS NOT NULL) = (attachment_uuid IS NOT NULL AND capture_uuid IS NOT NULL)),
  CHECK (basis NOT IN ('observed-file','verified-bytes')
    OR (attachment_uuid IS NOT NULL AND capture_uuid IS NOT NULL AND file_uuid IS NOT NULL)),
  FOREIGN KEY (post_uuid, attachment_uuid) REFERENCES source_attachments(post_uuid, uuid),
  FOREIGN KEY (post_uuid, capture_uuid) REFERENCES source_captures(post_uuid, uuid),
  FOREIGN KEY (capture_uuid, manifest_uuid) REFERENCES source_capture_attachment_manifests(capture_uuid, manifest_uuid),
  FOREIGN KEY (manifest_uuid, position, attachment_uuid) REFERENCES source_attachment_entries(manifest_uuid, position, attachment_uuid)
);

CREATE TABLE source_content_claims (
 uuid TEXT NOT NULL PRIMARY KEY
 CHECK(length(uuid)=36 AND uuid=lower(uuid) AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
 AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-' AND length(replace(uuid,'-',''))=32
 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*' AND uuid!='00000000-0000-0000-0000-000000000000'),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL,
 reference_namespace TEXT NOT NULL CHECK(length(reference_namespace) BETWEEN 1 AND 128),
 reference_value TEXT NOT NULL CHECK(length(reference_value) BETWEEN 1 AND 4096),
 digest_algorithm TEXT CHECK(digest_algorithm IS NULL OR length(digest_algorithm) BETWEEN 1 AND 128),
 digest TEXT CHECK(digest IS NULL OR length(digest) BETWEEN 1 AND 4096),
 size INTEGER CHECK(size IS NULL OR (typeof(size)='integer' AND size>=0)),
 source_created_at TEXT NOT NULL CHECK(length(source_created_at)<=64),
 origin TEXT NOT NULL CHECK(origin IN ('migration','ingest','review','scan')),
 observed_at DATETIME NOT NULL,
 details TEXT NOT NULL CHECK(length(CAST(details AS BLOB))<=65536 AND json_valid(details) AND json_type(details)='object'),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK((digest_algorithm IS NULL)=(digest IS NULL)),
 UNIQUE(uuid,collection_uuid),
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision)
);

CREATE TABLE source_file_observations (
 uuid TEXT NOT NULL PRIMARY KEY
 CHECK(length(uuid)=36 AND uuid=lower(uuid) AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
 AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-' AND length(replace(uuid,'-',''))=32
 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*' AND uuid!='00000000-0000-0000-0000-000000000000'),
 content_claim_uuid TEXT,
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL,
 root_uuid TEXT NOT NULL,
 root_revision INTEGER NOT NULL,
 relative_path TEXT NOT NULL CHECK(length(relative_path) BETWEEN 1 AND 4096),
 archive_path TEXT CHECK(archive_path IS NULL OR length(archive_path) BETWEEN 1 AND 4096),
 state TEXT NOT NULL CHECK(state IN ('present','missing','pending','deduplicated')),
 role TEXT NOT NULL CHECK(role IN ('local','converted-source','source-media-reference')),
 size INTEGER CHECK(size IS NULL OR (typeof(size)='integer' AND size>=0)),
 modified_at_ns INTEGER CHECK(modified_at_ns IS NULL OR typeof(modified_at_ns)='integer'),
 source_first_observed TEXT NOT NULL CHECK(length(source_first_observed)<=64),
 survivor_path TEXT CHECK(survivor_path IS NULL OR length(survivor_path) BETWEEN 1 AND 4096),
 origin TEXT NOT NULL CHECK(origin IN ('migration','ingest','review','scan')),
 observed_at DATETIME NOT NULL,
 details TEXT NOT NULL CHECK(length(CAST(details AS BLOB))<=65536 AND json_valid(details) AND json_type(details)='object'),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(content_claim_uuid,collection_uuid) REFERENCES source_content_claims(uuid,collection_uuid),
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 FOREIGN KEY(root_uuid,root_revision) REFERENCES media_root_revisions(root_uuid,revision)
);

CREATE TABLE source_file_matches (
 uuid TEXT NOT NULL PRIMARY KEY
 CHECK(length(uuid)=36 AND uuid=lower(uuid) AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
 AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-' AND length(replace(uuid,'-',''))=32
 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*' AND uuid!='00000000-0000-0000-0000-000000000000'),
 observation_uuid TEXT NOT NULL REFERENCES source_file_observations(uuid),
 file_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
 generation INTEGER NOT NULL CHECK(typeof(generation)='integer' AND generation>0),
 archive_file_uuid TEXT REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
 archive_generation INTEGER CHECK(archive_generation IS NULL OR (typeof(archive_generation)='integer' AND archive_generation>0)),
 library_root_path TEXT NOT NULL CHECK(length(library_root_path)<=4096),
 basis TEXT NOT NULL CHECK(basis IN ('exact-path','survivor-path','verified-content','review')),
 origin TEXT NOT NULL CHECK(origin IN ('migration','ingest','review','scan')),
 details TEXT NOT NULL CHECK(length(CAST(details AS BLOB))<=65536 AND json_valid(details) AND json_type(details)='object'),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK((archive_file_uuid IS NULL)=(archive_generation IS NULL)),
 CHECK((basis IN ('exact-path','survivor-path'))=(library_root_path!=''))
);

CREATE TABLE source_post_file_evidence (
 uuid TEXT NOT NULL PRIMARY KEY
 CHECK(length(uuid)=36 AND uuid=lower(uuid) AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
 AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-' AND length(replace(uuid,'-',''))=32
 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*' AND uuid!='00000000-0000-0000-0000-000000000000'),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 observation_uuid TEXT NOT NULL REFERENCES source_file_observations(uuid),
 origin TEXT NOT NULL CHECK(origin IN ('capture','migration','review')),
 basis TEXT NOT NULL CHECK(length(basis) BETWEEN 1 AND 128),
 observed_at DATETIME NOT NULL,
 details TEXT NOT NULL CHECK(length(CAST(details AS BLOB))<=65536 AND json_valid(details) AND json_type(details)='object')
);

CREATE TABLE catalog_media_imports (
 snapshot_uuid TEXT PRIMARY KEY REFERENCES catalog_snapshots(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64),
 root_uuid TEXT NOT NULL,
 root_revision INTEGER NOT NULL,
 collection_revision INTEGER NOT NULL CHECK(collection_revision>0),
 library_root_path TEXT NOT NULL CHECK(length(library_root_path) BETWEEN 1 AND 4096),
 policy TEXT NOT NULL CHECK(policy='catalog-media-v1'),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 phase TEXT NOT NULL CHECK(phase IN ('assets','files','appearances','complete')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 mapped_records INTEGER NOT NULL DEFAULT 0 CHECK(mapped_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 unavailable_records INTEGER NOT NULL DEFAULT 0 CHECK(unavailable_records>=0),
 matched_files INTEGER NOT NULL DEFAULT 0 CHECK(matched_files BETWEEN 0 AND processed_records),
 media_associations INTEGER NOT NULL DEFAULT 0 CHECK(media_associations BETWEEN 0 AND processed_records),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 FOREIGN KEY(root_uuid,root_revision) REFERENCES media_root_revisions(root_uuid,revision),
 CHECK(mapped_records+review_records+unavailable_records=processed_records),
 CHECK((state='running')=(phase!='complete')),
 CHECK(state='running' OR processed_records=source_records)
);

CREATE TABLE catalog_media_records (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_media_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 claim_uuid TEXT REFERENCES source_content_claims(uuid),
 observation_uuid TEXT REFERENCES source_file_observations(uuid),
 match_uuid TEXT REFERENCES source_file_matches(uuid),
 post_uuid TEXT REFERENCES source_posts(uuid),
 post_file_uuid TEXT REFERENCES source_post_file_evidence(uuid),
 media_evidence_uuid TEXT REFERENCES source_media_evidence(uuid),
 outcome TEXT NOT NULL CHECK(outcome IN ('mapped','review','unavailable')),
 reason TEXT NOT NULL CHECK(length(reason)<=128),
 context_json TEXT NOT NULL CHECK(json_valid(context_json) AND json_type(context_json)='object' AND length(CAST(context_json AS BLOB))<=65536),
 PRIMARY KEY(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES catalog_snapshot_records(snapshot_uuid,ordinal),
 CHECK(match_uuid IS NULL OR observation_uuid IS NOT NULL),
 CHECK(post_file_uuid IS NULL OR (post_uuid IS NOT NULL AND observation_uuid IS NOT NULL)),
 CHECK(media_evidence_uuid IS NULL OR (post_uuid IS NOT NULL AND match_uuid IS NOT NULL)),
 CHECK((outcome='mapped' AND reason='') OR (outcome!='mapped' AND reason!=''))
);

CREATE TABLE source_collection_post_evidence (
 uuid TEXT NOT NULL PRIMARY KEY
 CHECK(length(uuid)=36 AND uuid=lower(uuid) AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
 AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-' AND length(replace(uuid,'-',''))=32
 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*' AND uuid!='00000000-0000-0000-0000-000000000000'),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL,
 origin TEXT NOT NULL CHECK(origin IN ('capture','migration','review')),
 basis TEXT NOT NULL CHECK(length(basis) BETWEEN 1 AND 128),
 observed_at DATETIME NOT NULL,
 details TEXT NOT NULL CHECK(length(CAST(details AS BLOB))<=65536 AND json_valid(details) AND json_type(details)='object'),
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision)
);

CREATE TABLE catalog_membership_groups (
 source_uuid TEXT NOT NULL REFERENCES catalog_registry_imports(source_uuid),
 source_key TEXT NOT NULL CHECK(length(CAST(source_key AS BLOB)) BETWEEN 1 AND 4096),
 source_kind TEXT NOT NULL CHECK(length(source_kind) BETWEEN 1 AND 128),
 source_label TEXT NOT NULL CHECK(length(CAST(source_label AS BLOB)) BETWEEN 1 AND 1024),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL,
 first_snapshot_uuid TEXT NOT NULL REFERENCES catalog_snapshots(uuid),
 PRIMARY KEY(source_uuid,source_key),
 UNIQUE(collection_uuid),
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision)
);

CREATE TABLE catalog_membership_imports (
 snapshot_uuid TEXT PRIMARY KEY REFERENCES catalog_snapshots(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64),
 policy TEXT NOT NULL CHECK(policy='catalog-membership-v1'),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 mapped_records INTEGER NOT NULL DEFAULT 0 CHECK(mapped_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 CHECK(mapped_records+review_records=processed_records),
 CHECK(state='running' OR processed_records=source_records)
);

CREATE TABLE catalog_membership_records (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_membership_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 post_uuid TEXT REFERENCES source_posts(uuid),
 collection_uuid TEXT REFERENCES source_collections(uuid),
 membership_uuid TEXT REFERENCES source_collection_post_evidence(uuid),
 outcome TEXT NOT NULL CHECK(outcome IN ('mapped','review')),
 reason TEXT NOT NULL,
 PRIMARY KEY(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES catalog_snapshot_records(snapshot_uuid,ordinal),
 CHECK((outcome='mapped')=(reason='')),
 CHECK((outcome='mapped')=(membership_uuid IS NOT NULL)),
 CHECK(membership_uuid IS NULL OR (post_uuid IS NOT NULL AND collection_uuid IS NOT NULL))
);

CREATE TABLE source_document_contents (
 content_sha256 TEXT PRIMARY KEY NOT NULL
 CHECK(length(content_sha256)=64 AND content_sha256 NOT GLOB '*[^0-9a-f]*'),
 byte_size INTEGER NOT NULL CHECK(byte_size BETWEEN 0 AND 16777216),
 storage_encoding TEXT NOT NULL CHECK(storage_encoding IN ('raw','gzip')),
 data BLOB NOT NULL CHECK(typeof(data)='blob' AND length(data)<=16777216),
 CHECK(storage_encoding!='raw' OR length(data)=byte_size)
);

CREATE TABLE source_documents (
 uuid TEXT NOT NULL PRIMARY KEY
 CHECK(length(uuid)=36 AND uuid=lower(uuid) AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
 AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-' AND length(replace(uuid,'-',''))=32
 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*' AND uuid!='00000000-0000-0000-0000-000000000000'),
 content_sha256 TEXT NOT NULL REFERENCES source_document_contents(content_sha256),
 encoding TEXT NOT NULL CHECK(length(CAST(encoding AS BLOB))<=128),
 parser TEXT NOT NULL CHECK(length(CAST(parser AS BLOB)) BETWEEN 1 AND 128),
 parse_status TEXT NOT NULL CHECK(length(CAST(parse_status AS BLOB)) BETWEEN 1 AND 128),
 warnings TEXT NOT NULL CHECK(length(CAST(warnings AS BLOB))<=4194304 AND json_valid(warnings) AND json_type(warnings)='array'),
 parsed TEXT NOT NULL CHECK(length(CAST(parsed AS BLOB))<=4194304 AND json_valid(parsed) AND json_type(parsed)='object')
);

CREATE TABLE source_document_sources (
 uuid TEXT NOT NULL PRIMARY KEY
 CHECK(length(uuid)=36 AND uuid=lower(uuid) AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
 AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-' AND length(replace(uuid,'-',''))=32
 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*' AND uuid!='00000000-0000-0000-0000-000000000000'),
 document_uuid TEXT NOT NULL REFERENCES source_documents(uuid),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL,
 relative_path TEXT NOT NULL CHECK(length(CAST(relative_path AS BLOB)) BETWEEN 1 AND 8192 AND instr(relative_path,char(0))=0),
 post_uuid TEXT REFERENCES source_posts(uuid),
 captured_at TEXT NOT NULL CHECK(length(captured_at)<=64),
 origin TEXT NOT NULL CHECK(origin IN ('capture','migration','review')),
 details TEXT NOT NULL CHECK(length(CAST(details AS BLOB))<=65536 AND json_valid(details) AND json_type(details)='object'),
 recorded_at DATETIME NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision)
);

CREATE TABLE source_document_head_claims (
 uuid TEXT NOT NULL PRIMARY KEY
 CHECK(length(uuid)=36 AND uuid=lower(uuid) AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
 AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-' AND length(replace(uuid,'-',''))=32
 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*' AND uuid!='00000000-0000-0000-0000-000000000000'),
 source_uuid TEXT NOT NULL REFERENCES source_document_sources(uuid),
 collection_uuid TEXT NOT NULL REFERENCES source_collections(uuid),
 relative_path TEXT NOT NULL,
 observed_at TEXT NOT NULL CHECK(length(observed_at)<=64),
 origin TEXT NOT NULL CHECK(origin IN ('capture','migration','review')),
 details TEXT NOT NULL CHECK(length(CAST(details AS BLOB))<=65536 AND json_valid(details) AND json_type(details)='object'),
 recorded_at DATETIME NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE source_document_head_decisions (
 uuid TEXT NOT NULL PRIMARY KEY
 CHECK(length(uuid)=36 AND uuid=lower(uuid) AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-'
 AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-' AND length(replace(uuid,'-',''))=32
 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*' AND uuid!='00000000-0000-0000-0000-000000000000'),
 collection_uuid TEXT NOT NULL REFERENCES source_collections(uuid),
 relative_path TEXT NOT NULL CHECK(length(CAST(relative_path AS BLOB)) BETWEEN 1 AND 8192 AND instr(relative_path,char(0))=0),
 revision INTEGER NOT NULL CHECK(revision>0),
 state TEXT NOT NULL CHECK(state IN ('linked','unlinked')),
 source_uuid TEXT REFERENCES source_document_sources(uuid),
 claim_uuid TEXT REFERENCES source_document_head_claims(uuid),
 origin TEXT NOT NULL CHECK(origin IN ('capture','migration','review')),
 reason TEXT NOT NULL CHECK(length(CAST(reason AS BLOB))<=4096),
 created_at DATETIME NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 UNIQUE(collection_uuid,relative_path,revision),
 CHECK((state='linked')=(source_uuid IS NOT NULL)),
 CHECK(claim_uuid IS NULL OR source_uuid IS NOT NULL)
);

CREATE TABLE source_document_heads (
 collection_uuid TEXT NOT NULL REFERENCES source_collections(uuid),
 relative_path TEXT NOT NULL,
 decision_uuid TEXT NOT NULL UNIQUE REFERENCES source_document_head_decisions(uuid),
 PRIMARY KEY(collection_uuid,relative_path)
);

CREATE TABLE catalog_document_imports (
 snapshot_uuid TEXT PRIMARY KEY REFERENCES catalog_snapshots(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL CHECK(collection_revision=1),
 policy TEXT NOT NULL CHECK(policy='catalog-documents-v1'),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 phase TEXT NOT NULL CHECK(phase IN ('sidecar_documents','sidecar_sources','sidecars','sidecar_heads','complete')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 mapped_records INTEGER NOT NULL DEFAULT 0 CHECK(mapped_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 CHECK(mapped_records+review_records=processed_records),
 CHECK((state='running')=(phase!='complete')),
 CHECK(state='running' OR processed_records=source_records)
);

CREATE TABLE catalog_document_records (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_document_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 document_uuid TEXT REFERENCES source_documents(uuid),
 source_uuid TEXT REFERENCES source_document_sources(uuid),
 post_uuid TEXT REFERENCES source_posts(uuid),
 claim_uuid TEXT REFERENCES source_document_head_claims(uuid),
 head_uuid TEXT REFERENCES source_document_head_decisions(uuid),
 selection_basis TEXT NOT NULL CHECK(selection_basis IN ('','explicit','legacy_fallback')),
 outcome TEXT NOT NULL CHECK(outcome IN ('mapped','review')),
 reason TEXT NOT NULL CHECK(length(reason)<=128),
 PRIMARY KEY(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES catalog_snapshot_records(snapshot_uuid,ordinal),
 CHECK(source_uuid IS NULL OR document_uuid IS NOT NULL),
 CHECK(claim_uuid IS NULL OR source_uuid IS NOT NULL),
 CHECK(head_uuid IS NULL OR claim_uuid IS NOT NULL),
 CHECK(selection_basis!='' OR (claim_uuid IS NULL AND head_uuid IS NULL)),
 CHECK(outcome!='mapped' OR document_uuid IS NOT NULL),
 CHECK(outcome!='mapped' OR selection_basis='' OR (claim_uuid IS NOT NULL AND head_uuid IS NOT NULL)),
 CHECK((outcome='mapped')=(reason=''))
);

CREATE TABLE source_translations (
 uuid TEXT NOT NULL PRIMARY KEY CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 original_sha256 TEXT CHECK(original_sha256 IS NULL OR (length(original_sha256)=64 AND original_sha256 NOT GLOB '*[^0-9a-f]*')),
 original_text TEXT CHECK(original_text IS NULL OR length(CAST(original_text AS BLOB))<=4194304),
 translated_text TEXT NOT NULL CHECK(length(CAST(translated_text AS BLOB))<=4194304),
 source_language TEXT CHECK(source_language IS NULL OR length(CAST(source_language AS BLOB))<=128),
 target_language TEXT CHECK(target_language IS NULL OR length(CAST(target_language AS BLOB))<=128),
 provider TEXT CHECK(provider IS NULL OR length(CAST(provider AS BLOB))<=1024),
 CHECK((original_text IS NULL)=(original_sha256 IS NULL))
);

CREATE TABLE source_translation_evidence (
 uuid TEXT NOT NULL PRIMARY KEY CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 translation_uuid TEXT NOT NULL REFERENCES source_translations(uuid),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 collection_uuid TEXT,
 collection_revision INTEGER CHECK(collection_revision IS NULL OR collection_revision>0),
 provenance TEXT NOT NULL CHECK(length(CAST(provenance AS BLOB))<=4096),
 declared_input_hash TEXT CHECK(declared_input_hash IS NULL OR length(CAST(declared_input_hash AS BLOB))<=4096),
 input_hash_algorithm TEXT NOT NULL CHECK(length(CAST(input_hash_algorithm AS BLOB))<=128),
 captured_at TEXT NOT NULL CHECK(length(CAST(captured_at AS BLOB))<=64),
 origin TEXT NOT NULL CHECK(origin IN ('migration','capture','review','worker')),
 details TEXT NOT NULL CHECK(json_valid(details) AND json_type(details)='object' AND length(CAST(details AS BLOB))<=65536),
 recorded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 CHECK((collection_uuid IS NULL)=(collection_revision IS NULL)),
 CHECK((declared_input_hash IS NULL)=(input_hash_algorithm=''))
);

CREATE TABLE catalog_translation_imports (
 snapshot_uuid TEXT PRIMARY KEY REFERENCES catalog_snapshots(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL CHECK(collection_revision=1),
 policy TEXT NOT NULL CHECK(policy='catalog-translations-v1'),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 mapped_records INTEGER NOT NULL DEFAULT 0 CHECK(mapped_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 CHECK(mapped_records+review_records=processed_records),
 CHECK(state='running' OR processed_records=source_records)
);

CREATE TABLE catalog_translation_records (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_translation_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 post_uuid TEXT REFERENCES source_posts(uuid),
 translation_uuid TEXT REFERENCES source_translations(uuid),
 evidence_uuid TEXT REFERENCES source_translation_evidence(uuid),
 input_hash_state TEXT NOT NULL CHECK(input_hash_state IN ('','missing','verified','unverifiable','mismatch')),
 outcome TEXT NOT NULL CHECK(outcome IN ('mapped','review')),
 reason TEXT NOT NULL,
 PRIMARY KEY(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES catalog_snapshot_records(snapshot_uuid,ordinal),
 CHECK((outcome='mapped')=(reason='')),
 CHECK(outcome!='mapped' OR (evidence_uuid IS NOT NULL AND input_hash_state IN ('missing','verified','unverifiable'))),
 CHECK(evidence_uuid IS NULL OR (post_uuid IS NOT NULL AND translation_uuid IS NOT NULL))
);

CREATE TABLE translation_requests (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 original_text TEXT NOT NULL CHECK(length(CAST(original_text AS BLOB))<=4194304),
 original_sha256 TEXT NOT NULL CHECK(length(original_sha256)=64 AND original_sha256 NOT GLOB '*[^0-9a-f]*'),
 target_language TEXT NOT NULL CHECK(length(CAST(target_language AS BLOB)) BETWEEN 1 AND 128),
 policy TEXT NOT NULL CHECK(policy='translate-shell-bing-text-v1'),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE translation_cache (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 request_uuid TEXT NOT NULL UNIQUE REFERENCES translation_requests(uuid),
 status TEXT NOT NULL CHECK(status IN ('translated','unchanged','no_text')),
 translation_uuid TEXT REFERENCES source_translations(uuid),
 captured_at TEXT NOT NULL CHECK(length(CAST(captured_at AS BLOB))<=64),
 origin TEXT NOT NULL CHECK(origin IN ('worker','migration','review')),
 recorded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK((status='no_text')=(translation_uuid IS NULL))
);

CREATE TABLE translation_targets (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 request_uuid TEXT NOT NULL REFERENCES translation_requests(uuid),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 collection_uuid TEXT,
 collection_revision INTEGER CHECK(collection_revision IS NULL OR collection_revision>0),
 field TEXT NOT NULL CHECK(field IN ('title','caption')),
 origin TEXT NOT NULL CHECK(origin IN ('capture','migration','review')),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 state TEXT NOT NULL CHECK(state IN ('held','pending','completed','review')),
 priority INTEGER NOT NULL CHECK(typeof(priority)='integer' AND priority BETWEEN 0 AND 100),
 not_before DATETIME NOT NULL,
 cache_uuid TEXT REFERENCES translation_cache(uuid),
 evidence_uuid TEXT REFERENCES source_translation_evidence(uuid),
 reason TEXT NOT NULL DEFAULT '' CHECK(reason IN ('','post_forgotten')),
 created_at DATETIME NOT NULL,
 updated_at DATETIME NOT NULL,
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 CHECK((collection_uuid IS NULL)=(collection_revision IS NULL)),
 CHECK((state='review')=(reason!='')),
 CHECK(state!='completed' OR cache_uuid IS NOT NULL),
 CHECK(state='completed' OR evidence_uuid IS NULL),
 CHECK(state NOT IN ('held','pending') OR cache_uuid IS NULL)
);

CREATE TABLE translation_target_history (
 target_uuid TEXT NOT NULL REFERENCES translation_targets(uuid),
 revision INTEGER NOT NULL CHECK(revision>0),
 state TEXT NOT NULL CHECK(state IN ('held','pending','completed','review')),
 priority INTEGER NOT NULL CHECK(priority BETWEEN 0 AND 100),
 not_before DATETIME NOT NULL,
 cache_uuid TEXT REFERENCES translation_cache(uuid),
 evidence_uuid TEXT REFERENCES source_translation_evidence(uuid),
 reason TEXT NOT NULL,
 recorded_at DATETIME NOT NULL,
 PRIMARY KEY(target_uuid,revision)
);

CREATE TABLE translation_job_targets (
 job_uuid TEXT NOT NULL REFERENCES archive_jobs(uuid),
 target_uuid TEXT NOT NULL,
 target_revision INTEGER NOT NULL CHECK(typeof(target_revision)='integer' AND target_revision>0),
 PRIMARY KEY(target_uuid,target_revision),
 FOREIGN KEY(target_uuid,target_revision) REFERENCES translation_target_history(target_uuid,revision)
);

CREATE TABLE automation_snapshots (
 uuid TEXT PRIMARY KEY CHECK(length(uuid)=36),
 source_uuid TEXT NOT NULL UNIQUE CHECK(length(source_uuid)=36),
 registry_import_uuid TEXT NOT NULL REFERENCES catalog_registry_imports(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64 AND manifest_sha256 NOT GLOB '*[^0-9a-f]*'),
 source_sha256 TEXT NOT NULL CHECK(length(source_sha256)=64 AND source_sha256 NOT GLOB '*[^0-9a-f]*'),
 manifest BLOB NOT NULL CHECK(typeof(manifest)='blob' AND length(manifest) BETWEEN 1 AND 8388608),
 captured_at TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('receiving','received')),
 chunk_count INTEGER NOT NULL CHECK(chunk_count BETWEEN 0 AND 100000),
 record_count INTEGER NOT NULL CHECK(record_count BETWEEN 0 AND 10000000),
 byte_count INTEGER NOT NULL CHECK(byte_count>=0),
 next_chunk INTEGER NOT NULL DEFAULT 0 CHECK(next_chunk BETWEEN 0 AND chunk_count),
 received_records INTEGER NOT NULL DEFAULT 0 CHECK(received_records BETWEEN 0 AND record_count),
 received_bytes INTEGER NOT NULL DEFAULT 0 CHECK(received_bytes BETWEEN 0 AND byte_count),
 last_table TEXT NOT NULL DEFAULT '',
 last_key TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(last_key) AND json_type(last_key)='array' AND length(CAST(last_key AS BLOB))<=32768),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 CHECK((record_count=0)=(chunk_count=0) AND (record_count=0)=(byte_count=0)),
 CHECK((state='received')=(next_chunk=chunk_count)),
 CHECK(state!='received' OR (received_records=record_count AND received_bytes=byte_count))
);

CREATE TABLE automation_snapshot_tables (
 snapshot_uuid TEXT NOT NULL REFERENCES automation_snapshots(uuid),
 source_table TEXT NOT NULL,
 received_records INTEGER NOT NULL DEFAULT 0 CHECK(received_records>=0),
 received_bytes INTEGER NOT NULL DEFAULT 0 CHECK(received_bytes>=0),
 received_sha256 TEXT NOT NULL CHECK(length(received_sha256)=64 AND received_sha256 NOT GLOB '*[^0-9a-f]*'),
 hash_state BLOB NOT NULL CHECK(typeof(hash_state)='blob' AND length(hash_state) BETWEEN 1 AND 256),
 PRIMARY KEY(snapshot_uuid,source_table)
);

CREATE TABLE automation_snapshot_chunks (
 snapshot_uuid TEXT NOT NULL REFERENCES automation_snapshots(uuid),
 chunk_index INTEGER NOT NULL CHECK(chunk_index BETWEEN 0 AND 99999),
 sha256 TEXT NOT NULL CHECK(length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*'),
 record_count INTEGER NOT NULL CHECK(record_count BETWEEN 1 AND 1000),
 byte_count INTEGER NOT NULL CHECK(byte_count BETWEEN 1 AND 16777216),
 created_at TEXT NOT NULL,
 PRIMARY KEY(snapshot_uuid,chunk_index)
);

CREATE TABLE automation_snapshot_records (
 snapshot_uuid TEXT NOT NULL,
 ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 1 AND 10000000),
 chunk_index INTEGER NOT NULL,
 source_table TEXT NOT NULL,
 source_key TEXT NOT NULL CHECK(json_valid(source_key) AND json_type(source_key)='array' AND length(CAST(source_key AS BLOB))<=32768),
 data TEXT NOT NULL CHECK(json_valid(data) AND json_type(data)='object'),
 byte_count INTEGER NOT NULL CHECK(byte_count=length(CAST(data AS BLOB)) AND byte_count BETWEEN 1 AND 16777216),
 data_sha256 TEXT NOT NULL CHECK(length(data_sha256)=64 AND data_sha256 NOT GLOB '*[^0-9a-f]*'),
 PRIMARY KEY(snapshot_uuid,ordinal),
 UNIQUE(snapshot_uuid,source_table,source_key),
 FOREIGN KEY(snapshot_uuid,chunk_index) REFERENCES automation_snapshot_chunks(snapshot_uuid,chunk_index),
 FOREIGN KEY(snapshot_uuid,source_table) REFERENCES automation_snapshot_tables(snapshot_uuid,source_table)
);

CREATE TABLE automation_translation_imports (
 snapshot_uuid TEXT PRIMARY KEY REFERENCES automation_snapshots(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64),
 policy TEXT NOT NULL CHECK(policy='automation-translations-v1'),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 mapped_records INTEGER NOT NULL DEFAULT 0 CHECK(mapped_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 CHECK(mapped_records+review_records=processed_records),
 CHECK(state='running' OR processed_records=source_records),
 CHECK(state!='mapped' OR review_records=0),
 CHECK(state!='review' OR review_records>0)
);

CREATE TABLE automation_translation_records (
 snapshot_uuid TEXT NOT NULL REFERENCES automation_translation_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 job_ordinal INTEGER,
 request_uuid TEXT REFERENCES translation_requests(uuid),
 cache_uuid TEXT REFERENCES translation_cache(uuid),
 post_uuid TEXT REFERENCES source_posts(uuid),
 post_reference TEXT NOT NULL DEFAULT '' CHECK(length(post_reference) IN (0,69)),
 collection_uuid TEXT,
 collection_revision INTEGER CHECK(collection_revision IS NULL OR collection_revision=1),
 target_uuid TEXT REFERENCES translation_targets(uuid),
 target_revision INTEGER,
 evidence_uuid TEXT REFERENCES source_translation_evidence(uuid),
 disposition TEXT NOT NULL CHECK(disposition IN ('request','cache','english_original','held','completed','preserved','review')),
 outcome TEXT NOT NULL CHECK(outcome IN ('mapped','review')),
 reason TEXT NOT NULL,
 PRIMARY KEY(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES automation_snapshot_records(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,job_ordinal) REFERENCES automation_translation_records(snapshot_uuid,ordinal),
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 FOREIGN KEY(target_uuid,target_revision) REFERENCES translation_target_history(target_uuid,revision),
 CHECK((target_uuid IS NULL)=(target_revision IS NULL)),
 CHECK((collection_uuid IS NULL)=(collection_revision IS NULL)),
 CHECK((outcome='review')=(reason!='') AND (outcome='review')=(disposition='review')),
 CHECK(cache_uuid IS NULL OR request_uuid IS NOT NULL),
 CHECK(post_uuid IS NULL OR post_reference!=''),
 CHECK(target_uuid IS NULL OR (post_uuid IS NOT NULL AND request_uuid IS NOT NULL AND collection_uuid IS NOT NULL AND job_ordinal IS NOT NULL)),
 CHECK(evidence_uuid IS NULL OR (target_uuid IS NOT NULL AND disposition='completed')),
 CHECK(disposition NOT IN ('held','completed','preserved') OR target_uuid IS NOT NULL),
 CHECK(disposition NOT IN ('cache','english_original','completed') OR cache_uuid IS NOT NULL),
 CHECK(disposition NOT IN ('request','cache','english_original') OR (request_uuid IS NOT NULL AND job_ordinal IS NULL AND post_uuid IS NULL AND target_uuid IS NULL))
);

CREATE TABLE translation_activations (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36),
 input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64),
 plan_sha256 TEXT NOT NULL CHECK(length(plan_sha256)=64),
 snapshot_uuid TEXT REFERENCES automation_translation_imports(snapshot_uuid),
 manifest_sha256 TEXT CHECK(manifest_sha256 IS NULL OR length(manifest_sha256)=64),
 plan TEXT NOT NULL CHECK(json_valid(plan) AND json_type(plan)='object' AND length(CAST(plan AS BLOB))<=131072),
 created_at DATETIME NOT NULL,
 CHECK((snapshot_uuid IS NULL)=(manifest_sha256 IS NULL))
);

CREATE TABLE translation_activation_targets (
 activation_uuid TEXT NOT NULL REFERENCES translation_activations(uuid),
 target_uuid TEXT NOT NULL REFERENCES translation_targets(uuid),
 previous_revision INTEGER NOT NULL CHECK(previous_revision>0),
 activated_revision INTEGER NOT NULL CHECK(activated_revision=previous_revision+1),
 PRIMARY KEY(activation_uuid,target_uuid),
 UNIQUE(target_uuid,previous_revision),
 FOREIGN KEY(target_uuid,previous_revision) REFERENCES translation_target_history(target_uuid,revision),
 FOREIGN KEY(target_uuid,activated_revision) REFERENCES translation_target_history(target_uuid,revision)
);

CREATE TABLE translation_policies (
 collection_uuid TEXT PRIMARY KEY NOT NULL REFERENCES source_collections(uuid),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
 FOREIGN KEY(collection_uuid,revision) REFERENCES translation_policy_revisions(collection_uuid,revision) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE translation_policy_revisions (
 collection_uuid TEXT NOT NULL REFERENCES translation_policies(collection_uuid),
 revision INTEGER NOT NULL CHECK(revision>0),
 collection_revision INTEGER NOT NULL CHECK(collection_revision>0),
 definition TEXT NOT NULL CHECK(json_valid(definition) AND json_type(definition)='object' AND length(CAST(definition AS BLOB))<=1024),
 origin TEXT NOT NULL CHECK(origin IN ('review','migration')),
 reason TEXT NOT NULL CHECK(length(reason)<=4096),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(collection_uuid,revision),
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision)
);

CREATE TABLE capture_translation_decisions (
 collection_uuid TEXT NOT NULL,
 capture_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL,
 policy_revision INTEGER,
 status TEXT NOT NULL CHECK(status IN ('no_policy','disabled','collection_changed','recorded')),
 entry_count INTEGER NOT NULL CHECK(entry_count BETWEEN 0 AND 2),
 created_at DATETIME NOT NULL,
 PRIMARY KEY(collection_uuid,capture_uuid,collection_revision),
 FOREIGN KEY(collection_uuid,capture_uuid,collection_revision) REFERENCES source_collection_captures(collection_uuid,capture_uuid,collection_revision),
 FOREIGN KEY(collection_uuid,policy_revision) REFERENCES translation_policy_revisions(collection_uuid,revision),
 CHECK((status='no_policy')=(policy_revision IS NULL)),
 CHECK((status='recorded' AND entry_count BETWEEN 1 AND 2) OR (status!='recorded' AND entry_count=0))
);

CREATE TABLE capture_translation_entries (
 collection_uuid TEXT NOT NULL,
 capture_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL,
 field TEXT NOT NULL CHECK(field IN ('title','caption')),
 status TEXT NOT NULL CHECK(status IN ('created','retained','no_text')),
 target_uuid TEXT,
 target_revision INTEGER,
 PRIMARY KEY(collection_uuid,capture_uuid,collection_revision,field),
 FOREIGN KEY(collection_uuid,capture_uuid,collection_revision) REFERENCES capture_translation_decisions(collection_uuid,capture_uuid,collection_revision),
 FOREIGN KEY(target_uuid,target_revision) REFERENCES translation_target_history(target_uuid,revision),
 CHECK((target_uuid IS NULL)=(target_revision IS NULL)),
 CHECK((status IN ('created','retained'))=(target_uuid IS NOT NULL))
);

CREATE TABLE enrichment_targets (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 url_uuid TEXT NOT NULL REFERENCES source_post_urls(uuid),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL CHECK(typeof(collection_revision)='integer' AND collection_revision>0),
 policy TEXT NOT NULL CHECK(policy='gallery-dl-metadata-v1'),
 origin TEXT NOT NULL CHECK(origin IN ('review','migration')),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 state TEXT NOT NULL CHECK(state IN ('held','pending','review','excluded','completed')),
 priority INTEGER NOT NULL CHECK(typeof(priority)='integer' AND priority BETWEEN 0 AND 100),
 not_before DATETIME NOT NULL,
 reason TEXT NOT NULL CHECK(length(CAST(reason AS BLOB))<=64 AND reason NOT GLOB '*[^a-z0-9_]*'
  AND (reason='' OR substr(reason,1,1) GLOB '[a-z]')),
 completion_uuid TEXT REFERENCES enrichment_completions(uuid) DEFERRABLE INITIALLY DEFERRED,
 created_at DATETIME NOT NULL,
 updated_at DATETIME NOT NULL,
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 UNIQUE(post_uuid,url_uuid,collection_uuid,collection_revision,policy),
 UNIQUE(uuid,completion_uuid),
 CHECK((state='completed')=(completion_uuid IS NOT NULL)),
 CHECK(state NOT IN ('review','excluded') OR reason!=''),
 CHECK(state!='completed' OR reason='')
);

CREATE TABLE enrichment_completion_captures (
 completion_uuid TEXT NOT NULL REFERENCES enrichment_completions(uuid),
 capture_uuid TEXT NOT NULL REFERENCES source_captures(uuid),
 PRIMARY KEY(completion_uuid,capture_uuid)
);

CREATE TABLE enrichment_target_history (
 target_uuid TEXT NOT NULL REFERENCES enrichment_targets(uuid),
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>0),
 state TEXT NOT NULL CHECK(state IN ('held','pending','review','excluded','completed')),
 priority INTEGER NOT NULL CHECK(typeof(priority)='integer' AND priority BETWEEN 0 AND 100),
 not_before DATETIME NOT NULL,
 reason TEXT NOT NULL,
 completion_uuid TEXT REFERENCES enrichment_completions(uuid),
 recorded_at DATETIME NOT NULL,
 PRIMARY KEY(target_uuid,revision)
);

CREATE TABLE enrichment_job_targets (
 job_uuid TEXT PRIMARY KEY NOT NULL REFERENCES archive_jobs(uuid),
 target_uuid TEXT NOT NULL,
 target_revision INTEGER NOT NULL CHECK(typeof(target_revision)='integer' AND target_revision>0),
 UNIQUE(target_uuid,target_revision),
 FOREIGN KEY(target_uuid,target_revision) REFERENCES enrichment_target_history(target_uuid,revision)
);

CREATE TABLE enrichment_job_attempts (
 job_uuid TEXT NOT NULL REFERENCES enrichment_job_targets(job_uuid),
 fence INTEGER NOT NULL CHECK(typeof(fence)='integer' AND fence>0),
 producer_uuid TEXT NOT NULL REFERENCES ingest_producers(uuid),
 PRIMARY KEY(job_uuid,fence),
 FOREIGN KEY(job_uuid,fence) REFERENCES archive_job_attempts(job_uuid,fence)
);

CREATE TABLE enrichment_checkpoint_receipts (
 job_uuid TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision BETWEEN 1 AND 128),
 digest TEXT NOT NULL CHECK(length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*'),
 fence INTEGER NOT NULL,
 record_count INTEGER NOT NULL CHECK(typeof(record_count)='integer' AND record_count BETWEEN 1 AND 1024),
 pending_count INTEGER NOT NULL CHECK(typeof(pending_count)='integer' AND pending_count BETWEEN 0 AND 256),
 unresolved_count INTEGER NOT NULL CHECK(typeof(unresolved_count)='integer' AND unresolved_count BETWEEN 0 AND 256),
 created_at DATETIME NOT NULL,
 PRIMARY KEY(job_uuid,revision),
 UNIQUE(job_uuid,digest),
 FOREIGN KEY(job_uuid,fence) REFERENCES enrichment_job_attempts(job_uuid,fence)
);

CREATE TABLE enrichment_checkpoints (
 job_uuid TEXT PRIMARY KEY NOT NULL,
 revision INTEGER NOT NULL,
 body TEXT NOT NULL CHECK(json_valid(body) AND json_type(body)='object'),
 byte_size INTEGER NOT NULL CHECK(typeof(byte_size)='integer' AND byte_size=length(CAST(body AS BLOB)) AND byte_size BETWEEN 1 AND 33554432),
 FOREIGN KEY(job_uuid,revision) REFERENCES enrichment_checkpoint_receipts(job_uuid,revision)
);

CREATE TABLE enrichment_checkpoint_records (
 job_uuid TEXT NOT NULL,
 ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal BETWEEN 0 AND 1023),
 checkpoint_revision INTEGER NOT NULL,
 digest TEXT NOT NULL CHECK(length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*'),
 PRIMARY KEY(job_uuid,ordinal),
 FOREIGN KEY(job_uuid,checkpoint_revision) REFERENCES enrichment_checkpoint_receipts(job_uuid,revision)
);

CREATE TABLE enrichment_checkpoint_usage (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 byte_size INTEGER NOT NULL CHECK(typeof(byte_size)='integer' AND byte_size BETWEEN 0 AND 2147483648)
);

CREATE TABLE enrichment_publications (
 job_uuid TEXT PRIMARY KEY NOT NULL REFERENCES enrichment_job_targets(job_uuid),
 checkpoint_revision INTEGER NOT NULL,
 fence INTEGER NOT NULL,
 completion_uuid TEXT NOT NULL UNIQUE REFERENCES enrichment_completions(uuid),
 created_at DATETIME NOT NULL,
 FOREIGN KEY(job_uuid,checkpoint_revision) REFERENCES enrichment_checkpoint_receipts(job_uuid,revision),
 FOREIGN KEY(job_uuid,fence) REFERENCES enrichment_job_attempts(job_uuid,fence)
);

CREATE TABLE enrichment_published_records (
 job_uuid TEXT NOT NULL REFERENCES enrichment_publications(job_uuid),
 ordinal INTEGER NOT NULL,
 capture_uuid TEXT NOT NULL REFERENCES source_captures(uuid),
 PRIMARY KEY(job_uuid,ordinal),
 FOREIGN KEY(job_uuid,ordinal) REFERENCES enrichment_checkpoint_records(job_uuid,ordinal)
);

CREATE TABLE source_pacing (
  scope TEXT PRIMARY KEY NOT NULL CHECK(length(scope) BETWEEN 1 AND 300),
  available_at_ms INTEGER NOT NULL DEFAULT 0 CHECK(available_at_ms>=0),
  last_started_at_ms INTEGER NOT NULL DEFAULT 0 CHECK(last_started_at_ms>=0),
  reason TEXT NOT NULL DEFAULT '' CHECK(length(reason)<=128)
);

CREATE TABLE source_run_pacing (
  run_uuid TEXT PRIMARY KEY NOT NULL REFERENCES source_runs(uuid),
  scope TEXT NOT NULL REFERENCES source_pacing(scope)
);

CREATE TABLE enrichment_attempt_pacing (
  job_uuid TEXT NOT NULL REFERENCES enrichment_job_pacing(job_uuid),
  fence INTEGER NOT NULL,
  scope TEXT NOT NULL REFERENCES source_pacing(scope),
  PRIMARY KEY(job_uuid,fence,scope),
  FOREIGN KEY(job_uuid,fence) REFERENCES archive_job_attempts(job_uuid,fence)
);

CREATE TABLE source_run_attempt_pacing (
 run_uuid TEXT NOT NULL,
 fence INTEGER NOT NULL CHECK(typeof(fence)='integer' AND fence>0),
 scope TEXT NOT NULL REFERENCES source_pacing(scope),
 reserved INTEGER NOT NULL CHECK(reserved IN (0,1)), source_origin TEXT,
 PRIMARY KEY(run_uuid,fence,scope),
 FOREIGN KEY(run_uuid,fence) REFERENCES source_run_attempts(run_uuid,fence)
);

CREATE TABLE source_run_attempt_failures (
 run_uuid TEXT NOT NULL,
 fence INTEGER NOT NULL,
 scope TEXT NOT NULL,
 error_code TEXT NOT NULL CHECK(error_code IN ('source_busy','rate_limited','timeout','extraction_failed',
  'authentication','access_denied','challenge','not_found')),
 created_at_ms INTEGER NOT NULL CHECK(typeof(created_at_ms)='integer' AND created_at_ms>0),
 PRIMARY KEY(run_uuid,fence),
 FOREIGN KEY(run_uuid,fence,scope) REFERENCES source_run_attempt_pacing(run_uuid,fence,scope)
);

CREATE TABLE source_service_turns (
 scope TEXT PRIMARY KEY NOT NULL REFERENCES source_pacing(scope),
 download_starts INTEGER NOT NULL DEFAULT 0 CHECK(typeof(download_starts)='integer' AND download_starts BETWEEN 0 AND 4),
 enrichment_started_at_ms INTEGER NOT NULL DEFAULT 0 CHECK(typeof(enrichment_started_at_ms)='integer' AND enrichment_started_at_ms>=0)
);

CREATE TABLE source_enrichment_waiters (
 job_uuid TEXT PRIMARY KEY NOT NULL REFERENCES enrichment_job_pacing(job_uuid),
 fence INTEGER NOT NULL CHECK(typeof(fence)='integer' AND fence>=0),
 first_requested_at_ms INTEGER NOT NULL CHECK(typeof(first_requested_at_ms)='integer' AND first_requested_at_ms>0),
 refreshed_at_ms INTEGER NOT NULL CHECK(typeof(refreshed_at_ms)='integer' AND refreshed_at_ms>=first_requested_at_ms),
 expires_at_ms INTEGER NOT NULL CHECK(typeof(expires_at_ms)='integer' AND expires_at_ms=refreshed_at_ms+90000)
);

CREATE TABLE source_enrichment_waiter_scopes (
 job_uuid TEXT NOT NULL REFERENCES source_enrichment_waiters(job_uuid) ON DELETE CASCADE,
 scope TEXT NOT NULL REFERENCES source_pacing(scope),
 PRIMARY KEY(job_uuid,scope)
);

CREATE TABLE source_enrichment_receipts (
 uuid TEXT NOT NULL PRIMARY KEY CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL CHECK(collection_revision=1),
 origin TEXT NOT NULL CHECK(origin='migration'),
 policy TEXT NOT NULL CHECK(policy='catalog-enrichment-v1'),
 source_version INTEGER NOT NULL CHECK(source_version=1),
 completed_at TEXT NOT NULL CHECK(length(CAST(completed_at AS BLOB)) BETWEEN 1 AND 64),
 attachment_links_enriched INTEGER NOT NULL CHECK(attachment_links_enriched>=0),
 unresolved_children INTEGER NOT NULL CHECK(unresolved_children>=0),
 recorded_at TEXT NOT NULL,
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision)
);

CREATE TABLE catalog_enrichment_imports (
 snapshot_uuid TEXT PRIMARY KEY REFERENCES catalog_snapshots(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64 AND manifest_sha256 NOT GLOB '*[^0-9a-f]*'),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL CHECK(collection_revision=1),
 policy TEXT NOT NULL CHECK(policy='catalog-enrichment-v1'),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 mapped_records INTEGER NOT NULL DEFAULT 0 CHECK(mapped_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 CHECK(mapped_records+review_records=processed_records),
 CHECK(state='running' OR processed_records=source_records),
 CHECK(state!='mapped' OR review_records=0),
 CHECK(state!='review' OR review_records>0)
);

CREATE TABLE catalog_enrichment_records (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_enrichment_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 post_uuid TEXT REFERENCES source_posts(uuid),
 receipt_uuid TEXT REFERENCES source_enrichment_receipts(uuid),
 outcome TEXT NOT NULL CHECK(outcome IN ('mapped','review')),
 reason TEXT NOT NULL,
 PRIMARY KEY(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES catalog_snapshot_records(snapshot_uuid,ordinal),
 CHECK((outcome='mapped')=(reason='')),
 CHECK((outcome='mapped')=(receipt_uuid IS NOT NULL)),
 CHECK(receipt_uuid IS NULL OR post_uuid IS NOT NULL)
);

CREATE TABLE "enrichment_completions" (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 target_uuid TEXT NOT NULL UNIQUE REFERENCES enrichment_targets(uuid),
 expected_revision INTEGER NOT NULL CHECK(typeof(expected_revision)='integer' AND expected_revision>0),
 request_digest TEXT NOT NULL CHECK(length(request_digest)=64 AND request_digest NOT GLOB '*[^0-9a-f]*'),
 capture_count INTEGER NOT NULL CHECK(typeof(capture_count)='integer' AND capture_count BETWEEN 0 AND 1024),
 legacy_receipt_uuid TEXT REFERENCES source_enrichment_receipts(uuid),
 legacy_capture_uuid TEXT REFERENCES source_captures(uuid),
 created_at DATETIME NOT NULL,
 CHECK((legacy_receipt_uuid IS NULL AND legacy_capture_uuid IS NULL AND capture_count>=1)
  OR (legacy_receipt_uuid IS NOT NULL AND legacy_capture_uuid IS NULL AND capture_count=0)
  OR (legacy_receipt_uuid IS NULL AND legacy_capture_uuid IS NOT NULL AND capture_count=0)),
 FOREIGN KEY(target_uuid,uuid) REFERENCES enrichment_targets(uuid,completion_uuid) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE automation_enrichment_imports (
 snapshot_uuid TEXT PRIMARY KEY REFERENCES automation_snapshots(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64 AND manifest_sha256 NOT GLOB '*[^0-9a-f]*'),
 policy TEXT NOT NULL CHECK(policy='automation-enrichment-v1'),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 mapped_records INTEGER NOT NULL DEFAULT 0 CHECK(mapped_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 CHECK(mapped_records+review_records=processed_records),
 CHECK(state='running' OR processed_records=source_records),
 CHECK(state!='mapped' OR review_records=0),
 CHECK(state!='review' OR review_records>0)
);

CREATE TABLE automation_enrichment_records (
 snapshot_uuid TEXT NOT NULL REFERENCES automation_enrichment_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 post_uuid TEXT REFERENCES source_posts(uuid),
 post_reference TEXT NOT NULL DEFAULT '' CHECK(length(post_reference) IN (0,69)),
 catalog_snapshot_uuid TEXT REFERENCES catalog_snapshots(uuid),
 collection_uuid TEXT,
 collection_revision INTEGER CHECK(collection_revision IS NULL OR collection_revision=1),
 url_uuid TEXT REFERENCES source_post_urls(uuid),
 url_evidence_uuid TEXT REFERENCES source_post_url_evidence(uuid),
 target_uuid TEXT REFERENCES enrichment_targets(uuid),
 target_revision INTEGER,
 receipt_uuid TEXT REFERENCES source_enrichment_receipts(uuid),
 capture_uuid TEXT REFERENCES source_captures(uuid),
 completion_uuid TEXT REFERENCES enrichment_completions(uuid),
 alias_ordinal INTEGER,
 historical_attempts INTEGER CHECK(historical_attempts IS NULL OR (typeof(historical_attempts)='integer' AND historical_attempts>=0)),
 service_scope TEXT NOT NULL DEFAULT '',
 not_before DATETIME,
 staged_sha256 TEXT NOT NULL DEFAULT '' CHECK(staged_sha256='' OR (length(staged_sha256)=64 AND staged_sha256 NOT GLOB '*[^0-9a-f]*')),
 cooldown_kind TEXT NOT NULL DEFAULT '' CHECK(cooldown_kind IN ('','platform','account')),
 cooldown_value TEXT NOT NULL DEFAULT '',
 cooldown_until DATETIME,
 cooldown_reason TEXT NOT NULL DEFAULT '',
 seed_last_post_key TEXT,
 seed_complete INTEGER CHECK(seed_complete IS NULL OR seed_complete IN (0,1)),
 seed_counts TEXT CHECK(seed_counts IS NULL OR (json_valid(seed_counts) AND json_type(seed_counts)='object' AND length(CAST(seed_counts AS BLOB))<=65536)),
 source_platform TEXT NOT NULL DEFAULT '',
 source_last_attempt DATETIME,
 disposition TEXT NOT NULL CHECK(disposition IN ('held','historical_completion','source_present','coalesced','excluded','preserved','review','staged_review','cooldown','seed_progress','source_progress')),
 outcome TEXT NOT NULL CHECK(outcome IN ('mapped','review')),
 reason TEXT NOT NULL,
 PRIMARY KEY(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES automation_snapshot_records(snapshot_uuid,ordinal),
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 FOREIGN KEY(target_uuid,target_revision) REFERENCES enrichment_target_history(target_uuid,revision),
 FOREIGN KEY(catalog_snapshot_uuid,alias_ordinal) REFERENCES catalog_snapshot_records(snapshot_uuid,ordinal),
 CHECK((target_uuid IS NULL)=(target_revision IS NULL)),
 CHECK((collection_uuid IS NULL)=(collection_revision IS NULL)),
 CHECK((outcome='review')=(reason!='') AND (outcome='review')=(disposition IN ('review','staged_review'))),
 CHECK(post_uuid IS NULL OR post_reference!=''),
 CHECK(url_evidence_uuid IS NULL OR url_uuid IS NOT NULL),
 CHECK(target_uuid IS NULL OR (post_uuid IS NOT NULL AND collection_uuid IS NOT NULL AND url_uuid IS NOT NULL)),
 CHECK(disposition NOT IN ('held','preserved') OR target_uuid IS NOT NULL),
 CHECK(disposition!='historical_completion' OR receipt_uuid IS NOT NULL),
 CHECK(disposition!='source_present' OR capture_uuid IS NOT NULL),
 CHECK(disposition!='coalesced' OR (catalog_snapshot_uuid IS NOT NULL AND alias_ordinal IS NOT NULL)),
 CHECK(completion_uuid IS NULL OR (target_uuid IS NOT NULL AND (receipt_uuid IS NOT NULL OR capture_uuid IS NOT NULL))),
 CHECK(disposition!='cooldown' OR (cooldown_kind!='' AND cooldown_value!='' AND cooldown_until IS NOT NULL AND cooldown_reason!='')),
 CHECK(disposition!='seed_progress' OR (collection_uuid IS NOT NULL AND seed_last_post_key IS NOT NULL AND seed_complete IS NOT NULL AND seed_counts IS NOT NULL)),
 CHECK(disposition!='source_progress' OR (source_platform!='' AND source_last_attempt IS NOT NULL))
);

CREATE TABLE enrichment_activations (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36),
 input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64),
 plan_sha256 TEXT NOT NULL CHECK(length(plan_sha256)=64),
 snapshot_uuid TEXT REFERENCES automation_enrichment_imports(snapshot_uuid),
 manifest_sha256 TEXT CHECK(manifest_sha256 IS NULL OR length(manifest_sha256)=64),
 plan TEXT NOT NULL CHECK(json_valid(plan) AND json_type(plan)='object' AND length(CAST(plan AS BLOB))<=8388608),
 created_at DATETIME NOT NULL,
 CHECK((snapshot_uuid IS NULL)=(manifest_sha256 IS NULL))
);

CREATE TABLE enrichment_activation_targets (
 activation_uuid TEXT NOT NULL REFERENCES enrichment_activations(uuid),
 target_uuid TEXT NOT NULL REFERENCES enrichment_targets(uuid),
 previous_revision INTEGER NOT NULL CHECK(previous_revision>0),
 consumed_revision INTEGER NOT NULL CHECK(consumed_revision=previous_revision+1),
 released_target_uuid TEXT NOT NULL REFERENCES enrichment_targets(uuid),
 released_revision INTEGER NOT NULL CHECK(released_revision>0),
 CHECK((released_target_uuid=target_uuid AND released_revision=consumed_revision)
  OR (released_target_uuid!=target_uuid AND released_revision=1)),
 PRIMARY KEY(activation_uuid,target_uuid),
 UNIQUE(target_uuid,previous_revision),
 UNIQUE(released_target_uuid,released_revision),
 FOREIGN KEY(target_uuid,previous_revision) REFERENCES enrichment_target_history(target_uuid,revision),
 FOREIGN KEY(target_uuid,consumed_revision) REFERENCES enrichment_target_history(target_uuid,revision),
 FOREIGN KEY(released_target_uuid,released_revision) REFERENCES enrichment_target_history(target_uuid,revision)
);

CREATE TABLE automation_checkpoint_imports (
 snapshot_uuid TEXT PRIMARY KEY NOT NULL REFERENCES automation_enrichment_imports(snapshot_uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64 AND manifest_sha256 NOT GLOB '*[^0-9a-f]*'),
 policy TEXT NOT NULL CHECK(policy='legacy-enrichment-staging-v1'),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 mapped_records INTEGER NOT NULL DEFAULT 0 CHECK(mapped_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 CHECK(mapped_records+review_records=processed_records),
 CHECK(state='running' OR processed_records=source_records),
 CHECK(state!='mapped' OR review_records=0),
 CHECK(state!='review' OR review_records>0)
);

CREATE TABLE automation_checkpoint_bodies (
 hash TEXT PRIMARY KEY NOT NULL CHECK(length(hash)=64 AND hash NOT GLOB '*[^0-9a-f]*'),
 body TEXT NOT NULL CHECK(json_valid(body) AND json_type(body)='object' AND length(CAST(body AS BLOB))<=8388608)
);

CREATE TABLE automation_checkpoint_records (
 snapshot_uuid TEXT NOT NULL REFERENCES automation_checkpoint_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 source_sha256 TEXT NOT NULL CHECK(length(source_sha256)=64 AND source_sha256 NOT GLOB '*[^0-9a-f]*'),
 staged_sha256 TEXT CHECK(staged_sha256 IS NULL OR (length(staged_sha256)=64 AND staged_sha256 NOT GLOB '*[^0-9a-f]*')),
 body_sha256 TEXT REFERENCES automation_checkpoint_bodies(hash),
 record_count INTEGER NOT NULL CHECK(record_count BETWEEN 0 AND 256),
 pending_count INTEGER NOT NULL CHECK(pending_count BETWEEN 0 AND 256),
 unresolved_count INTEGER NOT NULL CHECK(unresolved_count BETWEEN 0 AND 256),
 outcome TEXT NOT NULL CHECK(outcome IN ('mapped','review')),
 reason TEXT NOT NULL,
 PRIMARY KEY(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES automation_enrichment_records(snapshot_uuid,ordinal),
 CHECK((outcome='mapped')=(reason='')),
 CHECK((outcome='mapped')=(body_sha256 IS NOT NULL)),
 CHECK(outcome!='mapped' OR (staged_sha256 IS NOT NULL AND record_count>0)),
 CHECK(outcome!='review' OR (record_count=0 AND pending_count=0 AND unresolved_count=0))
);

CREATE TABLE source_captures (
  uuid TEXT NOT NULL PRIMARY KEY
    CHECK (length(uuid) = 36 AND uuid = lower(uuid)
      AND substr(uuid, 9, 1) = '-' AND substr(uuid, 14, 1) = '-'
      AND substr(uuid, 19, 1) = '-' AND substr(uuid, 24, 1) = '-'
      AND length(replace(uuid, '-', '')) = 32
      AND replace(uuid, '-', '') NOT GLOB '*[^0-9a-f]*'
      AND uuid != '00000000-0000-0000-0000-000000000000'),
  post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
  revision_uuid TEXT NOT NULL,
  origin TEXT NOT NULL CHECK (length(origin) BETWEEN 1 AND 128),
  platform TEXT NOT NULL CHECK (length(platform) BETWEEN 1 AND 128),
  captured_at DATETIME CHECK (captured_at IS NULL OR (length(captured_at) = 30 AND substr(captured_at, 11, 1) = 'T' AND substr(captured_at, 20, 1) = '.' AND substr(captured_at, 30, 1) = 'Z' AND julianday(captured_at) IS NOT NULL)),
  extractor_version TEXT CHECK (extractor_version IS NULL OR length(extractor_version) <= 128),
  retention_policy TEXT NOT NULL CHECK (length(retention_policy) BETWEEN 1 AND 128),
  patch_digest TEXT NOT NULL REFERENCES source_payloads(digest),
  signature TEXT NOT NULL CHECK (length(signature) = 64 AND signature NOT GLOB '*[^0-9a-f]*'),
  recorded_at DATETIME CHECK (recorded_at IS NULL OR (length(recorded_at) = 30 AND substr(recorded_at, 11, 1) = 'T' AND substr(recorded_at, 20, 1) = '.' AND substr(recorded_at, 30, 1) = 'Z' AND julianday(recorded_at) IS NOT NULL)),
  CHECK ((captured_at IS NULL) != (recorded_at IS NULL)),
  FOREIGN KEY (post_uuid, revision_uuid) REFERENCES source_post_revisions(post_uuid, uuid)
);

CREATE TABLE checkpoint_evidence_acceptances (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36 AND uuid=lower(uuid)
   AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
   AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
   AND uuid!='00000000-0000-0000-0000-000000000000'),
 snapshot_uuid TEXT NOT NULL,
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 target_uuid TEXT NOT NULL,
 target_revision INTEGER NOT NULL CHECK(target_revision>0),
 input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64 AND input_sha256 NOT GLOB '*[^0-9a-f]*'),
 plan_sha256 TEXT NOT NULL CHECK(length(plan_sha256)=64 AND plan_sha256 NOT GLOB '*[^0-9a-f]*'),
 plan TEXT NOT NULL CHECK(json_valid(plan) AND json_type(plan)='object' AND length(CAST(plan AS BLOB))<=1048576),
 created_at DATETIME NOT NULL,
 UNIQUE(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES automation_checkpoint_records(snapshot_uuid,ordinal),
 FOREIGN KEY(target_uuid,target_revision) REFERENCES enrichment_target_history(target_uuid,revision)
);

CREATE TABLE checkpoint_evidence_captures (
 acceptance_uuid TEXT NOT NULL REFERENCES checkpoint_evidence_acceptances(uuid),
 body_index INTEGER NOT NULL CHECK(body_index BETWEEN 0 AND 4095),
 capture_uuid TEXT NOT NULL REFERENCES source_captures(uuid),
 payload_sha256 TEXT NOT NULL CHECK(length(payload_sha256)=64 AND payload_sha256 NOT GLOB '*[^0-9a-f]*'),
 PRIMARY KEY(acceptance_uuid,body_index)
);

CREATE TABLE source_capture_contexts (
 capture_uuid TEXT NOT NULL REFERENCES source_captures(uuid),
 path TEXT NOT NULL CHECK(path IN ('/_parent','/_reddit')),
 parent_capture_uuid TEXT NOT NULL REFERENCES source_captures(uuid),
 PRIMARY KEY(capture_uuid,path),
 CHECK(capture_uuid!=parent_capture_uuid)
);

CREATE TABLE checkpoint_handoffs (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36 AND uuid=lower(uuid)
   AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
   AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
   AND uuid!='00000000-0000-0000-0000-000000000000'),
 evidence_uuid TEXT NOT NULL REFERENCES checkpoint_evidence_acceptances(uuid),
 target_uuid TEXT NOT NULL,
 target_revision INTEGER NOT NULL CHECK(target_revision>0),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL CHECK(collection_revision>0),
 input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64 AND input_sha256 NOT GLOB '*[^0-9a-f]*'),
 plan_sha256 TEXT NOT NULL CHECK(length(plan_sha256)=64 AND plan_sha256 NOT GLOB '*[^0-9a-f]*'),
 seed_sha256 TEXT NOT NULL CHECK(length(seed_sha256)=64 AND seed_sha256 NOT GLOB '*[^0-9a-f]*'),
 plan TEXT NOT NULL CHECK(json_valid(plan) AND json_type(plan)='object' AND length(CAST(plan AS BLOB))<=1048576),
 created_at DATETIME NOT NULL,
 FOREIGN KEY(target_uuid,target_revision) REFERENCES enrichment_target_history(target_uuid,revision),
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision)
);

CREATE TABLE enrichment_checkpoint_releases (
 job_uuid TEXT PRIMARY KEY NOT NULL REFERENCES enrichment_publications(job_uuid),
 version INTEGER NOT NULL CHECK(version IN (1,2)),
 proof_sha256 TEXT NOT NULL CHECK(length(proof_sha256)=64 AND proof_sha256 NOT GLOB '*[^0-9a-f]*'),
 checkpoint_bytes INTEGER NOT NULL CHECK(typeof(checkpoint_bytes)='integer' AND checkpoint_bytes BETWEEN 1 AND 33554432),
 unresolved TEXT NOT NULL CHECK(json_valid(unresolved) AND json_type(unresolved)='array'
  AND json_array_length(unresolved)<=256 AND length(CAST(unresolved AS BLOB))<=4194304),
 created_at DATETIME NOT NULL
);

CREATE TABLE enrichment_handoff_jobs (
 handoff_uuid TEXT PRIMARY KEY NOT NULL REFERENCES checkpoint_handoffs(uuid),
 job_uuid TEXT NOT NULL UNIQUE REFERENCES enrichment_job_targets(job_uuid),
 consumed_revision INTEGER NOT NULL CHECK(consumed_revision>1),
 created_at DATETIME NOT NULL
);

CREATE TABLE enrichment_job_retained_records (
 job_uuid TEXT NOT NULL REFERENCES enrichment_handoff_jobs(job_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 1023),
 capture_uuid TEXT NOT NULL REFERENCES source_captures(uuid),
 digest TEXT NOT NULL CHECK(length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*'),
 PRIMARY KEY(job_uuid,ordinal),
 UNIQUE(job_uuid,capture_uuid)
);

CREATE TABLE enrichment_job_seed_services (
 job_uuid TEXT NOT NULL REFERENCES enrichment_handoff_jobs(job_uuid),
 scope TEXT NOT NULL CHECK(length(scope) BETWEEN 1 AND 1024),
 PRIMARY KEY(job_uuid,scope)
);

CREATE TABLE source_file_history (
 uuid TEXT PRIMARY KEY NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('metadata_edit','state_change','deduplication')),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL,
 root_uuid TEXT NOT NULL,
 root_revision INTEGER NOT NULL,
 reference_namespace TEXT NOT NULL CHECK(length(reference_namespace) BETWEEN 1 AND 128),
 reference_value TEXT NOT NULL CHECK(length(reference_value) BETWEEN 1 AND 4096),
 source_time TEXT NOT NULL CHECK(length(source_time)<=64),
 origin TEXT NOT NULL CHECK(origin IN ('migration','ingest','review','scan')),
 observed_at DATETIME NOT NULL,
 details TEXT NOT NULL CHECK(json_valid(details) AND json_type(details)='object' AND length(CAST(details AS BLOB))<=65536),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 location_count INTEGER NOT NULL CHECK(location_count BETWEEN 1 AND 1024),
 edit_count INTEGER NOT NULL CHECK(edit_count BETWEEN 0 AND 256),
 signature TEXT NOT NULL CHECK(length(signature)=64 AND signature NOT GLOB '*[^0-9a-f]*'),
 CHECK((kind='metadata_edit' AND location_count=1 AND edit_count>0)
  OR (kind='state_change' AND location_count=1 AND edit_count=0)
  OR (kind='deduplication' AND location_count>=2 AND edit_count=0)),
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 FOREIGN KEY(root_uuid,root_revision) REFERENCES media_root_revisions(root_uuid,revision)
);

CREATE TABLE source_file_history_locations (
 history_uuid TEXT NOT NULL REFERENCES source_file_history(uuid),
 position INTEGER NOT NULL CHECK(position BETWEEN 0 AND 1023),
 relative_path TEXT NOT NULL CHECK(length(relative_path) BETWEEN 1 AND 4096),
 archive_path TEXT CHECK(archive_path IS NULL OR length(archive_path) BETWEEN 1 AND 4096),
 observation_uuid TEXT REFERENCES source_file_observations(uuid),
 PRIMARY KEY(history_uuid,position)
);

CREATE TABLE source_file_history_edits (
 history_uuid TEXT NOT NULL REFERENCES source_file_history(uuid),
 field TEXT NOT NULL CHECK(length(field) BETWEEN 1 AND 128),
 target_field TEXT NOT NULL CHECK(length(target_field)<=128),
 value_type TEXT NOT NULL CHECK(value_type IN ('string','date','urls','names','extension')),
 mode TEXT NOT NULL CHECK(mode IN ('set','inherit','unmapped')),
 value_json TEXT NOT NULL CHECK(json_valid(value_json) AND length(CAST(value_json AS BLOB))<=4194304),
 PRIMARY KEY(history_uuid,field),
 CHECK((mode='unmapped' AND target_field='' AND value_type='extension') OR (mode!='unmapped' AND target_field!='' AND value_type!='extension')),
 CHECK(mode!='inherit' OR value_json='null')
);

CREATE TABLE source_file_history_states (
 history_uuid TEXT PRIMARY KEY NOT NULL REFERENCES source_file_history(uuid),
 old_state TEXT NOT NULL CHECK(old_state IN ('present','missing','pending','deduplicated')),
 new_state TEXT NOT NULL CHECK(new_state IN ('present','missing','pending','deduplicated')),
 reason TEXT NOT NULL CHECK(length(reason) BETWEEN 1 AND 4096)
);

CREATE TABLE source_file_history_deduplications (
 history_uuid TEXT PRIMARY KEY NOT NULL REFERENCES source_file_history(uuid),
 content_claim_uuid TEXT NOT NULL REFERENCES source_content_claims(uuid),
 stage TEXT NOT NULL CHECK(stage IN ('prepared','finished')),
 survivor_path TEXT CHECK(survivor_path IS NULL OR length(survivor_path) BETWEEN 1 AND 4096),
 CHECK((stage='prepared' AND survivor_path IS NULL) OR (stage='finished' AND survivor_path IS NOT NULL))
);

CREATE TABLE catalog_file_history_imports (
 snapshot_uuid TEXT PRIMARY KEY NOT NULL REFERENCES catalog_media_imports(snapshot_uuid),
 manifest_sha256 TEXT NOT NULL,
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL,
 root_uuid TEXT NOT NULL,
 root_revision INTEGER NOT NULL,
 policy TEXT NOT NULL CHECK(policy='catalog-file-history-v1'),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records>=0 AND processed_records<=source_records),
 mapped_records INTEGER NOT NULL DEFAULT 0 CHECK(mapped_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 CHECK(processed_records=mapped_records+review_records),
 CHECK(state='running' OR processed_records=source_records),
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 FOREIGN KEY(root_uuid,root_revision) REFERENCES media_root_revisions(root_uuid,revision)
);

CREATE TABLE catalog_file_history_records (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_file_history_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL,
 history_uuid TEXT REFERENCES source_file_history(uuid),
 outcome TEXT NOT NULL CHECK(outcome IN ('mapped','review')),
 reason TEXT NOT NULL,
 PRIMARY KEY(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES catalog_snapshot_records(snapshot_uuid,ordinal),
 CHECK((outcome='mapped' AND history_uuid IS NOT NULL AND reason='') OR (outcome='review' AND reason!=''))
);

CREATE TABLE metadata_file_edit_reviews (
 request_uuid TEXT PRIMARY KEY NOT NULL,
 decision_uuid TEXT NOT NULL UNIQUE REFERENCES metadata_field_decisions(uuid),
 history_uuid TEXT NOT NULL,
 source_field TEXT NOT NULL,
 match_uuid TEXT NOT NULL REFERENCES source_file_matches(uuid),
 request_json TEXT NOT NULL CHECK(json_valid(request_json) AND json_type(request_json)='object' AND length(CAST(request_json AS BLOB))<=262144),
 signature TEXT NOT NULL CHECK(length(signature)=64 AND signature NOT GLOB '*[^0-9a-f]*'),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(history_uuid,source_field) REFERENCES source_file_history_edits(history_uuid,field)
);

CREATE TABLE account_ownership_reviews (
 request_uuid TEXT PRIMARY KEY NOT NULL,
 account_uuid TEXT NOT NULL REFERENCES source_accounts(uuid),
 decision_uuid TEXT NOT NULL UNIQUE,
 request_json TEXT NOT NULL CHECK(json_valid(request_json) AND json_type(request_json)='object' AND length(CAST(request_json AS BLOB))<=16384),
 signature TEXT NOT NULL CHECK(length(signature)=64 AND signature NOT GLOB '*[^0-9a-f]*'),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(account_uuid,decision_uuid) REFERENCES account_performer_decisions(account_uuid,uuid)
);

CREATE TABLE automation_discovery_imports (
 snapshot_uuid TEXT PRIMARY KEY REFERENCES automation_snapshots(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64 AND manifest_sha256 NOT GLOB '*[^0-9a-f]*'),
 policy TEXT NOT NULL CHECK(policy='automation-discovery-v1'),
 state TEXT NOT NULL CHECK(state IN ('running','mapped','review')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 mapped_records INTEGER NOT NULL DEFAULT 0 CHECK(mapped_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 CHECK(mapped_records+review_records=processed_records),
 CHECK(state='running' OR processed_records=source_records),
 CHECK(state!='mapped' OR review_records=0),
 CHECK(state!='review' OR review_records>0)
);

CREATE TABLE automation_discovery_records (
 snapshot_uuid TEXT NOT NULL REFERENCES automation_discovery_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 account_uuid TEXT REFERENCES source_accounts(uuid),
 account_ordinal INTEGER,
 target_ordinal INTEGER,
 enrichment_ordinal INTEGER,
 post_uuid TEXT REFERENCES source_posts(uuid),
 post_reference TEXT NOT NULL DEFAULT '' CHECK(length(post_reference) IN (0,69)),
 catalog_snapshot_uuid TEXT REFERENCES catalog_snapshots(uuid),
 collection_uuid TEXT,
 collection_revision INTEGER CHECK(collection_revision IS NULL OR collection_revision=1),
 phase TEXT NOT NULL DEFAULT '' CHECK(phase IN ('','listing','matching','complete')),
 service_scope TEXT NOT NULL DEFAULT '',
 profile_url TEXT NOT NULL DEFAULT '',
 not_before DATETIME,
 historical_attempts INTEGER CHECK(historical_attempts IS NULL OR (typeof(historical_attempts)='integer' AND historical_attempts>=0)),
 historical_pages INTEGER CHECK(historical_pages IS NULL OR (typeof(historical_pages)='integer' AND historical_pages>=0)),
 cursor_sha256 TEXT NOT NULL DEFAULT '' CHECK(cursor_sha256='' OR (length(cursor_sha256)=64 AND cursor_sha256 NOT GLOB '*[^0-9a-f]*')),
 staged_sha256 TEXT NOT NULL DEFAULT '' CHECK(staged_sha256='' OR (length(staged_sha256)=64 AND staged_sha256 NOT GLOB '*[^0-9a-f]*')),
 staged_kind TEXT NOT NULL DEFAULT '' CHECK(staged_kind IN ('','page','detail')),
 evidence_sha256 TEXT NOT NULL DEFAULT '' CHECK(evidence_sha256='' OR (length(evidence_sha256)=64 AND evidence_sha256 NOT GLOB '*[^0-9a-f]*')),
 candidate_url TEXT NOT NULL DEFAULT '',
 candidate_basis TEXT NOT NULL DEFAULT '',
 payload_sha256 TEXT NOT NULL DEFAULT '' CHECK(payload_sha256='' OR (length(payload_sha256)=64 AND payload_sha256 NOT GLOB '*[^0-9a-f]*')),
 maintenance_kind TEXT NOT NULL DEFAULT '' CHECK(maintenance_kind IN ('','inventory_watermark','translation_seed','seed_summary','source_exclusions','pruning_summary')),
 maintenance_time DATETIME,
 watermark_ns TEXT NOT NULL DEFAULT '',
 disposition TEXT NOT NULL CHECK(disposition IN ('held','historical_listing','lookup','historical_completion','source_present','coalesced','candidate','maintenance_history','review')),
 outcome TEXT NOT NULL CHECK(outcome IN ('mapped','review')),
 reason TEXT NOT NULL,
 PRIMARY KEY(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES automation_snapshot_records(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,account_ordinal) REFERENCES automation_snapshot_records(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,target_ordinal) REFERENCES automation_snapshot_records(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,enrichment_ordinal) REFERENCES automation_enrichment_records(snapshot_uuid,ordinal),
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 CHECK((collection_uuid IS NULL)=(collection_revision IS NULL)),
 CHECK((outcome='review')=(reason!='') AND (outcome='review')=(disposition='review')),
 CHECK(post_uuid IS NULL OR post_reference!=''),
 CHECK((staged_sha256='')=(staged_kind='')),
 CHECK(disposition NOT IN ('lookup','historical_completion','source_present','coalesced') OR (post_uuid IS NOT NULL AND enrichment_ordinal IS NOT NULL)),
 CHECK(disposition!='candidate' OR (post_uuid IS NOT NULL AND target_ordinal IS NOT NULL AND candidate_url!='' AND candidate_basis!='' AND payload_sha256!='')),
 CHECK(disposition!='maintenance_history' OR (maintenance_kind!='' AND payload_sha256!='')),
 CHECK(disposition!='historical_listing' OR (account_uuid IS NOT NULL AND phase='complete')),
 CHECK(disposition!='held' OR account_uuid IS NOT NULL)
);

CREATE TABLE enrichment_discovery_resolutions (
 job_uuid TEXT PRIMARY KEY NOT NULL REFERENCES enrichment_job_targets(job_uuid),
 snapshot_uuid TEXT NOT NULL,
 source_ordinal INTEGER NOT NULL CHECK(source_ordinal>0),
 checkpoint_revision INTEGER NOT NULL CHECK(checkpoint_revision>0),
 record_ordinal INTEGER NOT NULL CHECK(record_ordinal>=0),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 post_revision INTEGER NOT NULL CHECK(post_revision>0),
 namespace TEXT NOT NULL CHECK(namespace IN ('native:reddit','native:twitter')),
 value TEXT NOT NULL CHECK(length(value)>0),
 policy TEXT NOT NULL CHECK(policy='retained-discovery-identity-v1'),
 basis TEXT NOT NULL CHECK(basis IN ('strict-filename-id','captured-account-and-post-id','original-text-date-and-post-id','title-date-and-post-id')),
 evidence_uuid TEXT NOT NULL UNIQUE REFERENCES source_post_identifier_evidence(uuid),
 created_at DATETIME NOT NULL,
 FOREIGN KEY(snapshot_uuid,source_ordinal) REFERENCES automation_discovery_records(snapshot_uuid,ordinal),
 FOREIGN KEY(job_uuid,checkpoint_revision) REFERENCES enrichment_checkpoint_receipts(job_uuid,revision),
 FOREIGN KEY(job_uuid,record_ordinal) REFERENCES enrichment_checkpoint_records(job_uuid,ordinal),
 FOREIGN KEY(job_uuid) REFERENCES enrichment_publications(job_uuid) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE enrichment_job_pacing (
 job_uuid TEXT PRIMARY KEY NOT NULL REFERENCES archive_jobs(uuid),
 scope TEXT NOT NULL REFERENCES source_pacing(scope)
);

CREATE TABLE discovery_listings (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36),
 account_uuid TEXT NOT NULL REFERENCES source_accounts(uuid),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL CHECK(collection_revision>0),
 root_uuid TEXT REFERENCES media_roots(uuid),
 definition TEXT NOT NULL CHECK(json_valid(definition) AND json_type(definition)='object' AND length(CAST(definition AS BLOB))<=32768),
 digest TEXT NOT NULL CHECK(length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*'),
 created_at DATETIME NOT NULL,
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 CHECK(json_extract(definition,'$.uuid') IS uuid AND json_extract(definition,'$.account_uuid') IS account_uuid
  AND json_extract(definition,'$.collection_uuid') IS collection_uuid AND json_extract(definition,'$.collection_revision') IS collection_revision
  AND json_extract(definition,'$.root_uuid') IS root_uuid)
);

CREATE TABLE discovery_listing_legacy (
 listing_uuid TEXT PRIMARY KEY NOT NULL REFERENCES discovery_listings(uuid),
 snapshot_uuid TEXT NOT NULL,
 account_ordinal INTEGER NOT NULL,
 FOREIGN KEY(snapshot_uuid,account_ordinal) REFERENCES automation_discovery_records(snapshot_uuid,ordinal)
);

CREATE TABLE discovery_listing_jobs (
 job_uuid TEXT PRIMARY KEY NOT NULL REFERENCES archive_jobs(uuid),
 listing_uuid TEXT NOT NULL REFERENCES discovery_listings(uuid),
 generation INTEGER NOT NULL CHECK(typeof(generation)='integer' AND generation>0),
 page_ordinal INTEGER NOT NULL CHECK(typeof(page_ordinal)='integer' AND page_ordinal BETWEEN 1 AND 10000),
 UNIQUE(listing_uuid,generation)
);

CREATE TABLE discovery_job_attempts (
 job_uuid TEXT NOT NULL REFERENCES discovery_listing_jobs(job_uuid),
 fence INTEGER NOT NULL CHECK(typeof(fence)='integer' AND fence>0),
 producer_uuid TEXT NOT NULL REFERENCES ingest_producers(uuid),
 PRIMARY KEY(job_uuid,fence),
 FOREIGN KEY(job_uuid,fence) REFERENCES archive_job_attempts(job_uuid,fence)
);

CREATE TABLE discovery_pages (
 listing_uuid TEXT NOT NULL REFERENCES discovery_listings(uuid),
 ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal BETWEEN 1 AND 10000),
 job_uuid TEXT NOT NULL,
 fence INTEGER NOT NULL,
 producer_uuid TEXT NOT NULL REFERENCES ingest_producers(uuid),
 digest TEXT NOT NULL CHECK(length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*'),
 byte_count INTEGER NOT NULL CHECK(byte_count=length(CAST(body AS BLOB)) AND byte_count BETWEEN 1 AND 33554432),
 record_count INTEGER NOT NULL CHECK(typeof(record_count)='integer' AND record_count BETWEEN 0 AND 4096),
 complete INTEGER NOT NULL CHECK(complete IN (0,1)),
 body TEXT NOT NULL CHECK(json_valid(body) AND json_type(body)='object'),
 created_at DATETIME NOT NULL,
 PRIMARY KEY(listing_uuid,ordinal),
 FOREIGN KEY(job_uuid,fence) REFERENCES discovery_job_attempts(job_uuid,fence),
 CHECK(json_type(body,'$.complete')=CASE WHEN complete=1 THEN 'true' ELSE 'false' END
  AND json_array_length(body,'$.records')=record_count)
);

CREATE TABLE discovery_match_targets (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36),
 listing_uuid TEXT NOT NULL REFERENCES discovery_listings(uuid),
 snapshot_uuid TEXT NOT NULL,
 source_ordinal INTEGER NOT NULL CHECK(source_ordinal>0),
 source_sha256 TEXT NOT NULL CHECK(length(source_sha256)=64 AND source_sha256 NOT GLOB '*[^0-9a-f]*'),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 post_revision INTEGER NOT NULL CHECK(post_revision>0),
 policy TEXT NOT NULL CHECK(policy='retained-discovery-listing-v1'),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
 last_page INTEGER NOT NULL DEFAULT 0 CHECK(last_page BETWEEN 0 AND 10000),
 enumeration_complete INTEGER NOT NULL DEFAULT 0 CHECK(enumeration_complete IN (0,1)),
 created_at DATETIME NOT NULL,
 updated_at DATETIME NOT NULL,
 FOREIGN KEY(snapshot_uuid,source_ordinal) REFERENCES automation_discovery_records(snapshot_uuid,ordinal),
 UNIQUE(listing_uuid,snapshot_uuid,source_ordinal),
 UNIQUE(uuid,listing_uuid),
 CHECK(revision=last_page+1 AND (last_page>0 OR enumeration_complete=0))
);

CREATE TABLE discovery_match_pages (
 target_uuid TEXT NOT NULL,
 listing_uuid TEXT NOT NULL,
 page_ordinal INTEGER NOT NULL CHECK(page_ordinal BETWEEN 1 AND 10000),
 page_sha256 TEXT NOT NULL CHECK(length(page_sha256)=64 AND page_sha256 NOT GLOB '*[^0-9a-f]*'),
 matches_sha256 TEXT NOT NULL CHECK(length(matches_sha256)=64 AND matches_sha256 NOT GLOB '*[^0-9a-f]*'),
 candidate_count INTEGER NOT NULL CHECK(candidate_count BETWEEN 0 AND 4096),
 complete INTEGER NOT NULL CHECK(complete IN (0,1)),
 created_at DATETIME NOT NULL,
 PRIMARY KEY(target_uuid,page_ordinal),
 FOREIGN KEY(target_uuid,listing_uuid) REFERENCES discovery_match_targets(uuid,listing_uuid),
 FOREIGN KEY(listing_uuid,page_ordinal) REFERENCES discovery_pages(listing_uuid,ordinal)
);

CREATE TABLE discovery_match_candidates (
 id INTEGER PRIMARY KEY,
 target_uuid TEXT NOT NULL REFERENCES discovery_match_targets(uuid),
 namespace TEXT NOT NULL CHECK(namespace IN ('native:reddit','native:twitter')),
 value TEXT NOT NULL CHECK(length(value) BETWEEN 1 AND 256),
 first_page INTEGER NOT NULL CHECK(first_page BETWEEN 1 AND 10000),
 best_page INTEGER NOT NULL CHECK(best_page BETWEEN first_page AND last_page),
 last_page INTEGER NOT NULL CHECK(last_page BETWEEN first_page AND 10000),
 page_count INTEGER NOT NULL CHECK(page_count BETWEEN 1 AND last_page-first_page+1),
 UNIQUE(target_uuid,namespace,value),
 FOREIGN KEY(target_uuid,first_page,namespace,value) REFERENCES discovery_match_evidence(target_uuid,page_ordinal,namespace,value) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(target_uuid,best_page,namespace,value) REFERENCES discovery_match_evidence(target_uuid,page_ordinal,namespace,value) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(target_uuid,last_page,namespace,value) REFERENCES discovery_match_evidence(target_uuid,page_ordinal,namespace,value) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE discovery_match_evidence (
 target_uuid TEXT NOT NULL,
 page_ordinal INTEGER NOT NULL,
 namespace TEXT NOT NULL,
 value TEXT NOT NULL,
 url TEXT NOT NULL CHECK(length(url) BETWEEN 1 AND 8192),
 basis TEXT NOT NULL CHECK(basis IN ('exact-title-and-date','exact-original-text-and-date','exact-title-and-original-text','exact-source-url-and-date','title-needs-verification')),
 needs_detail INTEGER NOT NULL CHECK(needs_detail IN (0,1) AND (needs_detail=1)=(basis='title-needs-verification')),
 record_ordinals TEXT NOT NULL CHECK(json_valid(record_ordinals) AND json_type(record_ordinals)='array'
  AND json_array_length(record_ordinals) BETWEEN 1 AND 4096 AND length(CAST(record_ordinals AS BLOB))<=32768),
 PRIMARY KEY(target_uuid,page_ordinal,namespace,value),
 FOREIGN KEY(target_uuid,page_ordinal) REFERENCES discovery_match_pages(target_uuid,page_ordinal),
 FOREIGN KEY(target_uuid,namespace,value) REFERENCES discovery_match_candidates(target_uuid,namespace,value) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE discovery_activations (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36),
 input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64 AND input_sha256 NOT GLOB '*[^0-9a-f]*'),
 plan_sha256 TEXT NOT NULL CHECK(length(plan_sha256)=64 AND plan_sha256 NOT GLOB '*[^0-9a-f]*'),
 snapshot_uuid TEXT NOT NULL REFERENCES automation_discovery_imports(snapshot_uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64 AND manifest_sha256 NOT GLOB '*[^0-9a-f]*'),
 listing_uuid TEXT NOT NULL REFERENCES discovery_listings(uuid),
 plan TEXT NOT NULL CHECK(json_valid(plan) AND json_type(plan)='object' AND length(CAST(plan AS BLOB))<=4194304),
 created_at DATETIME NOT NULL
);

CREATE TABLE discovery_activation_targets (
 activation_uuid TEXT NOT NULL REFERENCES discovery_activations(uuid),
 target_uuid TEXT NOT NULL REFERENCES discovery_match_targets(uuid),
 PRIMARY KEY(activation_uuid,target_uuid)
);

CREATE TABLE discovery_published_records (
 target_uuid TEXT NOT NULL REFERENCES discovery_match_publications(target_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 4095),
 capture_uuid TEXT NOT NULL REFERENCES source_captures(uuid),
 PRIMARY KEY(target_uuid,ordinal)
);

CREATE TABLE discovery_listing_recoveries (
 listing_uuid TEXT PRIMARY KEY NOT NULL REFERENCES discovery_listings(uuid),
 previous_listing_uuid TEXT NOT NULL UNIQUE REFERENCES discovery_listings(uuid),
 previous_sha256 TEXT NOT NULL CHECK(length(previous_sha256)=64 AND previous_sha256 NOT GLOB '*[^0-9a-f]*'),
 CHECK(listing_uuid!=previous_listing_uuid)
);

CREATE TABLE discovery_recovery_targets (
 target_uuid TEXT PRIMARY KEY NOT NULL REFERENCES discovery_match_targets(uuid),
 previous_target_uuid TEXT NOT NULL UNIQUE REFERENCES discovery_match_targets(uuid)
);

CREATE TABLE discovery_detail_jobs (
 job_uuid TEXT PRIMARY KEY NOT NULL REFERENCES archive_jobs(uuid),
 target_uuid TEXT NOT NULL REFERENCES discovery_match_targets(uuid),
 target_revision INTEGER NOT NULL CHECK(typeof(target_revision)='integer' AND target_revision>0),
 candidate_sequence INTEGER NOT NULL REFERENCES discovery_match_candidates(id),
 generation INTEGER NOT NULL CHECK(typeof(generation)='integer' AND generation>0),
 UNIQUE(target_uuid,target_revision,candidate_sequence,generation)
);

CREATE TABLE discovery_detail_attempts (
 job_uuid TEXT NOT NULL REFERENCES discovery_detail_jobs(job_uuid),
 fence INTEGER NOT NULL CHECK(typeof(fence)='integer' AND fence>0),
 producer_uuid TEXT NOT NULL REFERENCES ingest_producers(uuid),
 PRIMARY KEY(job_uuid,fence),
 FOREIGN KEY(job_uuid,fence) REFERENCES archive_job_attempts(job_uuid,fence)
);

CREATE TABLE discovery_detail_checkpoint_receipts (
 job_uuid TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision BETWEEN 1 AND 128),
 digest TEXT NOT NULL CHECK(length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*'),
 fence INTEGER NOT NULL,
 record_count INTEGER NOT NULL CHECK(typeof(record_count)='integer' AND record_count BETWEEN 0 AND 1024),
 pending_count INTEGER NOT NULL CHECK(typeof(pending_count)='integer' AND pending_count BETWEEN 0 AND 256),
 unresolved_count INTEGER NOT NULL CHECK(typeof(unresolved_count)='integer' AND unresolved_count BETWEEN 0 AND 256),
 created_at DATETIME NOT NULL,
 PRIMARY KEY(job_uuid,revision),
 UNIQUE(job_uuid,digest),
 FOREIGN KEY(job_uuid,fence) REFERENCES discovery_detail_attempts(job_uuid,fence)
);

CREATE TABLE discovery_detail_checkpoints (
 job_uuid TEXT PRIMARY KEY NOT NULL,
 revision INTEGER NOT NULL,
 body TEXT NOT NULL CHECK(json_valid(body) AND json_type(body)='object'),
 byte_size INTEGER NOT NULL CHECK(typeof(byte_size)='integer' AND byte_size=length(CAST(body AS BLOB)) AND byte_size BETWEEN 1 AND 33554432),
 FOREIGN KEY(job_uuid,revision) REFERENCES discovery_detail_checkpoint_receipts(job_uuid,revision)
);

CREATE TABLE discovery_detail_checkpoint_records (
 job_uuid TEXT NOT NULL,
 ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal BETWEEN 0 AND 1023),
 checkpoint_revision INTEGER NOT NULL,
 digest TEXT NOT NULL CHECK(length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*'),
 PRIMARY KEY(job_uuid,ordinal),
 FOREIGN KEY(job_uuid,checkpoint_revision) REFERENCES discovery_detail_checkpoint_receipts(job_uuid,revision)
);

CREATE TABLE discovery_detail_checkpoint_usage (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 byte_size INTEGER NOT NULL CHECK(typeof(byte_size)='integer' AND byte_size BETWEEN 0 AND 2147483648)
);

CREATE TABLE discovery_detail_results (
 job_uuid TEXT PRIMARY KEY NOT NULL,
 checkpoint_revision INTEGER NOT NULL,
 fence INTEGER NOT NULL,
 evidence TEXT NOT NULL CHECK(json_valid(evidence) AND json_type(evidence)='object' AND length(CAST(evidence AS BLOB))<=16384),
 created_at DATETIME NOT NULL,
 FOREIGN KEY(job_uuid,checkpoint_revision) REFERENCES discovery_detail_checkpoint_receipts(job_uuid,revision),
 FOREIGN KEY(job_uuid,fence) REFERENCES discovery_detail_attempts(job_uuid,fence),
 CHECK(json_extract(evidence,'$.status') IN ('corroborated','uncorroborated') AND json_extract(evidence,'$.pending_count')=0)
);

CREATE TABLE discovery_match_publications (
 target_uuid TEXT PRIMARY KEY NOT NULL REFERENCES discovery_match_targets(uuid),
 target_revision INTEGER NOT NULL CHECK(target_revision>1),
 listing_uuid TEXT NOT NULL,
 page_ordinal INTEGER NOT NULL CHECK(page_ordinal BETWEEN 1 AND 10000),
 page_sha256 TEXT NOT NULL CHECK(length(page_sha256)=64 AND page_sha256 NOT GLOB '*[^0-9a-f]*'),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 post_revision INTEGER NOT NULL CHECK(post_revision>0),
 namespace TEXT NOT NULL CHECK(namespace IN ('native:reddit','native:twitter')),
 value TEXT NOT NULL CHECK(length(value) BETWEEN 1 AND 256),
 policy TEXT NOT NULL,
 basis TEXT NOT NULL CHECK(basis IN ('exact-title-and-date','exact-original-text-and-date','exact-title-and-original-text','exact-source-url-and-date')),
 witness_ordinal INTEGER NOT NULL CHECK(witness_ordinal BETWEEN 0 AND 4095),
 evidence_uuid TEXT NOT NULL UNIQUE REFERENCES source_post_identifier_evidence(uuid),
 url_evidence_uuid TEXT NOT NULL UNIQUE REFERENCES source_post_url_evidence(uuid),
 record_count INTEGER NOT NULL CHECK(record_count BETWEEN 1 AND 4096),
 capture_count INTEGER NOT NULL CHECK(capture_count BETWEEN 1 AND record_count),
 created_at DATETIME NOT NULL,
 detail_job_uuid TEXT REFERENCES discovery_detail_results(job_uuid),
 CHECK((policy='retained-discovery-publication-v1' AND detail_job_uuid IS NULL)
    OR (policy='retained-discovery-detail-publication-v1' AND detail_job_uuid IS NOT NULL)),
 FOREIGN KEY(target_uuid,listing_uuid) REFERENCES discovery_match_targets(uuid,listing_uuid),
 FOREIGN KEY(target_uuid,page_ordinal,namespace,value) REFERENCES discovery_match_evidence(target_uuid,page_ordinal,namespace,value),
 FOREIGN KEY(listing_uuid,page_ordinal) REFERENCES discovery_pages(listing_uuid,ordinal)
);

CREATE TABLE metadata_policy_imports (
  uuid TEXT NOT NULL PRIMARY KEY,
  input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64),
  plan_sha256 TEXT NOT NULL CHECK(length(plan_sha256)=64),
  collection_uuid TEXT NOT NULL,
  collection_revision INTEGER NOT NULL CHECK(collection_revision>0),
  policy_revision INTEGER NOT NULL CHECK(policy_revision>0),
  binding TEXT NOT NULL CHECK(json_valid(binding) AND json_type(binding)='object' AND length(CAST(binding AS BLOB))<=1048576),
  plan TEXT NOT NULL CHECK(json_valid(plan) AND json_type(plan)='object' AND length(CAST(plan AS BLOB))<=524288),
  created_at TEXT NOT NULL,
  FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
  FOREIGN KEY(collection_uuid,policy_revision) REFERENCES metadata_policy_revisions(collection_uuid,revision)
);

CREATE TABLE metadata_policy_import_documents (
  import_uuid TEXT NOT NULL REFERENCES metadata_policy_imports(uuid),
  source_uuid TEXT NOT NULL REFERENCES source_document_sources(uuid),
  head_uuid TEXT NOT NULL REFERENCES source_document_head_decisions(uuid),
  PRIMARY KEY(import_uuid,source_uuid)
);

CREATE TABLE source_cleanup_intents (
 uuid TEXT PRIMARY KEY NOT NULL,
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL CHECK(collection_revision=1),
 kind TEXT NOT NULL CHECK(kind='background_targets'),
 state TEXT NOT NULL CHECK(state='held'),
 reference_namespace TEXT NOT NULL CHECK(length(CAST(reference_namespace AS BLOB)) BETWEEN 1 AND 256),
 reference_value TEXT NOT NULL CHECK(length(CAST(reference_value AS BLOB)) BETWEEN 1 AND 4096),
 requested_at TEXT NOT NULL CHECK(length(CAST(requested_at AS BLOB)) BETWEEN 1 AND 64),
 origin TEXT NOT NULL CHECK(origin='migration'),
 recorded_at TEXT NOT NULL,
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision)
);

CREATE TABLE catalog_cleanup_imports (
 snapshot_uuid TEXT PRIMARY KEY NOT NULL REFERENCES catalog_snapshots(uuid),
 manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64 AND manifest_sha256 NOT GLOB '*[^0-9a-f]*'),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL CHECK(collection_revision=1),
 policy TEXT NOT NULL CHECK(policy='catalog-cleanup-v1'),
 state TEXT NOT NULL CHECK(state IN ('running','retained','review')),
 last_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(last_ordinal>=0),
 source_records INTEGER NOT NULL CHECK(source_records>=0),
 processed_records INTEGER NOT NULL DEFAULT 0 CHECK(processed_records BETWEEN 0 AND source_records),
 held_records INTEGER NOT NULL DEFAULT 0 CHECK(held_records>=0),
 review_records INTEGER NOT NULL DEFAULT 0 CHECK(review_records>=0),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 CHECK(held_records+review_records=processed_records),
 CHECK(state='running' OR processed_records=source_records),
 CHECK(state!='retained' OR review_records=0),
 CHECK(state!='review' OR review_records>0)
);

CREATE TABLE catalog_cleanup_records (
 snapshot_uuid TEXT NOT NULL REFERENCES catalog_cleanup_imports(snapshot_uuid),
 ordinal INTEGER NOT NULL CHECK(ordinal>0),
 intent_uuid TEXT REFERENCES source_cleanup_intents(uuid),
 outcome TEXT NOT NULL CHECK(outcome IN ('held','review')),
 reason TEXT NOT NULL,
 PRIMARY KEY(snapshot_uuid,ordinal),
 FOREIGN KEY(snapshot_uuid,ordinal) REFERENCES catalog_snapshot_records(snapshot_uuid,ordinal),
 CHECK((outcome='held')=(reason='')),
 CHECK((outcome='held')=(intent_uuid IS NOT NULL))
);

CREATE TABLE post_media_decisions (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36 AND uuid=lower(uuid)
 AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
 AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
 AND uuid!='00000000-0000-0000-0000-000000000000'),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 media_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
 post_revision INTEGER NOT NULL CHECK(post_revision>1),
 media_revision INTEGER NOT NULL CHECK(media_revision>0),
 state TEXT NOT NULL CHECK(state IN ('linked','unlinked','undecided')),
 origin TEXT NOT NULL CHECK(origin IN ('review','migration')),
 reason TEXT NOT NULL CHECK(length(CAST(reason AS BLOB))<=4096),
 request_digest TEXT NOT NULL CHECK(length(request_digest)=64 AND request_digest NOT GLOB '*[^0-9a-f]*'),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(post_uuid,post_revision),
 UNIQUE(post_uuid,media_uuid,uuid)
);

CREATE TABLE post_media_links (
 post_uuid TEXT NOT NULL,
 media_uuid TEXT NOT NULL,
 decision_uuid TEXT NOT NULL UNIQUE,
 PRIMARY KEY(post_uuid,media_uuid),
 FOREIGN KEY(post_uuid,media_uuid,decision_uuid) REFERENCES post_media_decisions(post_uuid,media_uuid,uuid) ON UPDATE CASCADE
) WITHOUT ROWID;

CREATE TABLE post_media_supersessions (
 previous_uuid TEXT PRIMARY KEY NOT NULL REFERENCES post_media_decisions(uuid),
 decision_uuid TEXT NOT NULL REFERENCES post_media_decisions(uuid)
) WITHOUT ROWID;

CREATE TABLE metadata_decision_post_media (
 decision_uuid TEXT PRIMARY KEY NOT NULL REFERENCES metadata_field_decisions(uuid),
 post_media_decision_uuid TEXT NOT NULL REFERENCES post_media_decisions(uuid)
) WITHOUT ROWID;

CREATE TABLE post_media_backfills (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36 AND uuid=lower(uuid)
 AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
 AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
 AND uuid!='00000000-0000-0000-0000-000000000000'),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 post_revision INTEGER NOT NULL CHECK(typeof(post_revision)='integer' AND post_revision>0),
 policy TEXT NOT NULL CHECK(policy='catalog-files-v1'),
 signature TEXT NOT NULL CHECK(length(signature)=64 AND signature NOT GLOB '*[^0-9a-f]*'),
 request_digest TEXT NOT NULL CHECK(length(request_digest)=64 AND request_digest NOT GLOB '*[^0-9a-f]*'),
 selected INTEGER NOT NULL CHECK(typeof(selected)='integer' AND selected BETWEEN 0 AND 8192),
 preserved INTEGER NOT NULL CHECK(typeof(preserved)='integer' AND preserved BETWEEN 0 AND 8192),
 review INTEGER NOT NULL CHECK(typeof(review)='integer' AND review BETWEEN 0 AND 8192),
 unavailable INTEGER NOT NULL CHECK(typeof(unavailable)='integer' AND unavailable BETWEEN 0 AND 8192),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK(selected+preserved+review+unavailable<=8192)
);

CREATE TABLE post_media_backfill_decisions (
 backfill_uuid TEXT NOT NULL REFERENCES post_media_backfills(uuid),
 decision_uuid TEXT NOT NULL UNIQUE REFERENCES post_media_decisions(uuid),
 PRIMARY KEY(backfill_uuid,decision_uuid)
) WITHOUT ROWID;

CREATE TABLE post_media_decision_evidence (
 decision_uuid TEXT NOT NULL REFERENCES post_media_decisions(uuid),
 evidence_uuid TEXT NOT NULL REFERENCES source_media_evidence(uuid),
 post_file_uuid TEXT NOT NULL REFERENCES source_post_file_evidence(uuid),
 match_uuid TEXT NOT NULL REFERENCES source_file_matches(uuid),
 PRIMARY KEY(decision_uuid,evidence_uuid)
) WITHOUT ROWID;

CREATE TABLE enrichment_rebindings (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36),
 input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64),
 plan_sha256 TEXT NOT NULL CHECK(length(plan_sha256)=64),
 activation_uuid TEXT NOT NULL UNIQUE REFERENCES enrichment_activations(uuid),
 plan TEXT NOT NULL CHECK(json_valid(plan) AND json_type(plan)='object' AND length(CAST(plan AS BLOB))<=8388608),
 created_at DATETIME NOT NULL,
 UNIQUE(uuid,activation_uuid)
);

CREATE TABLE enrichment_rebinding_targets (
 rebinding_uuid TEXT NOT NULL,
 activation_uuid TEXT NOT NULL,
 target_uuid TEXT NOT NULL,
 previous_revision INTEGER NOT NULL CHECK(previous_revision>0),
 held_revision INTEGER NOT NULL CHECK(held_revision=previous_revision+1),
 PRIMARY KEY(rebinding_uuid,target_uuid),
 UNIQUE(target_uuid,previous_revision),
 FOREIGN KEY(rebinding_uuid,activation_uuid) REFERENCES enrichment_rebindings(uuid,activation_uuid),
 FOREIGN KEY(activation_uuid,target_uuid) REFERENCES enrichment_activation_targets(activation_uuid,target_uuid),
 FOREIGN KEY(target_uuid,previous_revision) REFERENCES enrichment_target_history(target_uuid,revision),
 FOREIGN KEY(target_uuid,held_revision) REFERENCES enrichment_target_history(target_uuid,revision)
);

CREATE TABLE discovery_scope_reviews (
 id INTEGER PRIMARY KEY,
 uuid TEXT NOT NULL UNIQUE CHECK(length(uuid)=36),
 listing_uuid TEXT NOT NULL REFERENCES discovery_listings(uuid),
 previous_uuid TEXT UNIQUE REFERENCES discovery_scope_reviews(uuid),
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL CHECK(collection_revision>0),
 root_uuid TEXT REFERENCES media_roots(uuid),
 input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64),
 plan_sha256 TEXT NOT NULL CHECK(length(plan_sha256)=64),
 plan TEXT NOT NULL CHECK(json_valid(plan) AND json_type(plan)='object' AND length(CAST(plan AS BLOB))<=131072),
 definition TEXT NOT NULL CHECK(json_valid(definition) AND json_type(definition)='object' AND length(CAST(definition AS BLOB))<=32768),
 digest TEXT NOT NULL CHECK(length(digest)=64),
 created_at DATETIME NOT NULL,
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 CHECK(json_extract(definition,'$.uuid') IS listing_uuid AND json_extract(definition,'$.collection_uuid') IS collection_uuid
  AND json_extract(definition,'$.collection_revision') IS collection_revision AND json_extract(definition,'$.root_uuid') IS root_uuid)
);

CREATE TABLE attachment_selection_reviews (
 request_uuid TEXT PRIMARY KEY NOT NULL,
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 decision_uuid TEXT NOT NULL UNIQUE,
 request_json TEXT NOT NULL CHECK(json_valid(request_json) AND json_type(request_json)='object' AND length(CAST(request_json AS BLOB))<=16384),
 signature TEXT NOT NULL CHECK(length(signature)=64 AND signature NOT GLOB '*[^0-9a-f]*'),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(post_uuid,decision_uuid) REFERENCES post_attachment_decisions(post_uuid,uuid)
);

CREATE TABLE gallery_association_reviews (
 request_uuid TEXT PRIMARY KEY NOT NULL,
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 decision_uuid TEXT NOT NULL UNIQUE,
 request_json TEXT NOT NULL CHECK(json_valid(request_json) AND json_type(request_json)='object' AND length(CAST(request_json AS BLOB))<=16384),
 signature TEXT NOT NULL CHECK(length(signature)=64 AND signature NOT GLOB '*[^0-9a-f]*'),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(post_uuid,decision_uuid) REFERENCES post_gallery_decisions(post_uuid,uuid)
);

CREATE TABLE attachment_media_reviews (
 request_uuid TEXT PRIMARY KEY NOT NULL,
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 attachment_uuid TEXT NOT NULL REFERENCES source_attachments(uuid),
 decision_uuid TEXT NOT NULL UNIQUE,
 request_json TEXT NOT NULL CHECK(json_valid(request_json) AND json_type(request_json)='object' AND length(CAST(request_json AS BLOB))<=16384),
 signature TEXT NOT NULL CHECK(length(signature)=64 AND signature NOT GLOB '*[^0-9a-f]*'),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(attachment_uuid,decision_uuid) REFERENCES attachment_media_decisions(attachment_uuid,uuid)
);

CREATE TABLE "ingest_receipts" (
 producer_uuid TEXT NOT NULL REFERENCES ingest_producers(uuid),
 event_uuid TEXT NOT NULL CHECK(length(event_uuid)=36 AND event_uuid=lower(event_uuid)
  AND substr(event_uuid,9,1)='-' AND substr(event_uuid,14,1)='-' AND substr(event_uuid,19,1)='-' AND substr(event_uuid,24,1)='-'
  AND length(replace(event_uuid,'-',''))=32 AND replace(event_uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND event_uuid!='00000000-0000-0000-0000-000000000000'),
 digest TEXT NOT NULL CHECK(length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*'),
 credential_uuid TEXT NOT NULL,
 collection_uuid TEXT NOT NULL,
 collection_revision INTEGER NOT NULL,
 root_uuid TEXT REFERENCES media_roots(uuid),
 run_uuid TEXT NOT NULL CHECK(length(run_uuid)=36 AND run_uuid=lower(run_uuid)
  AND substr(run_uuid,9,1)='-' AND substr(run_uuid,14,1)='-' AND substr(run_uuid,19,1)='-' AND substr(run_uuid,24,1)='-'
  AND length(replace(run_uuid,'-',''))=32 AND replace(run_uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND run_uuid!='00000000-0000-0000-0000-000000000000'),
 kind TEXT NOT NULL CHECK(kind IN ('source.capture','file.completed','attachment.download')),
 post_uuid TEXT REFERENCES source_posts(uuid),
 capture_uuid TEXT REFERENCES source_captures(uuid),
 job_uuid TEXT REFERENCES archive_jobs(uuid),
 result TEXT NOT NULL CHECK(json_valid(result) AND json_type(result)='object' AND length(result)<=16384),
 committed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(producer_uuid,event_uuid),
 FOREIGN KEY(producer_uuid,credential_uuid) REFERENCES ingest_credentials(producer_uuid,uuid),
 FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
 FOREIGN KEY(post_uuid,capture_uuid) REFERENCES source_captures(post_uuid,uuid),
 CHECK((post_uuid IS NULL)=(capture_uuid IS NULL)),
 CHECK((kind='source.capture' AND capture_uuid IS NOT NULL AND job_uuid IS NULL) OR
       (kind='file.completed' AND job_uuid IS NOT NULL AND root_uuid IS NOT NULL) OR
       (kind='attachment.download' AND capture_uuid IS NOT NULL AND job_uuid IS NULL AND root_uuid IS NOT NULL))
);

CREATE TABLE source_attachment_downloads (
 id INTEGER PRIMARY KEY,
 producer_uuid TEXT NOT NULL,
 event_uuid TEXT NOT NULL,
 run_uuid TEXT NOT NULL,
 fence INTEGER NOT NULL CHECK(fence BETWEEN 1 AND 9007199254740991),
 owner_uuid TEXT NOT NULL,
 transfer_sequence INTEGER NOT NULL CHECK(transfer_sequence BETWEEN 1 AND 9007199254740991),
 capture_event_uuid TEXT NOT NULL,
 attachment_uuid TEXT NOT NULL REFERENCES source_attachments(uuid),
 state TEXT NOT NULL CHECK(state IN ('started','downloaded','failed','excluded','skipped')),
 phase INTEGER NOT NULL CHECK(phase=CASE WHEN state='started' THEN 0 ELSE 1 END),
 file_event_uuid TEXT,
 reason_code TEXT NOT NULL DEFAULT '',
 observed_at DATETIME NOT NULL CHECK(length(observed_at) BETWEEN 20 AND 35 AND julianday(observed_at) IS NOT NULL),
 recorded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(producer_uuid,event_uuid),
 FOREIGN KEY(producer_uuid,event_uuid) REFERENCES ingest_receipts(producer_uuid,event_uuid) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(producer_uuid,capture_event_uuid) REFERENCES ingest_receipts(producer_uuid,event_uuid),
 FOREIGN KEY(producer_uuid,file_event_uuid) REFERENCES ingest_receipts(producer_uuid,event_uuid),
 FOREIGN KEY(run_uuid,fence) REFERENCES source_run_attempts(run_uuid,fence),
 CHECK((state='started' AND file_event_uuid IS NULL AND reason_code='') OR
       (state='downloaded' AND file_event_uuid IS NOT NULL AND reason_code='') OR
       (state='failed' AND file_event_uuid IS NULL AND reason_code IN ('download_failed','postprocess_failed','source_failure')) OR
       (state='excluded' AND file_event_uuid IS NULL AND reason_code IN ('unsupported_media','filter')) OR
       (state='skipped' AND file_event_uuid IS NULL AND reason_code IN ('archive_entry_without_file','existing_without_file')))
);

CREATE TABLE source_post_identities (
 post_uuid TEXT PRIMARY KEY NOT NULL REFERENCES source_posts(uuid),
 canonical_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 UNIQUE(post_uuid,canonical_uuid)
) WITHOUT ROWID;

CREATE TABLE source_post_consolidations (
 sequence INTEGER PRIMARY KEY AUTOINCREMENT,
 uuid TEXT NOT NULL UNIQUE CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 source_uuid TEXT NOT NULL UNIQUE REFERENCES source_posts(uuid),
 destination_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 source_revision INTEGER NOT NULL CHECK(source_revision>0),
 destination_revision INTEGER NOT NULL CHECK(destination_revision>0),
 member_count INTEGER NOT NULL CHECK(member_count BETWEEN 2 AND 256),
 identity_signature TEXT NOT NULL CHECK(length(identity_signature)=64 AND identity_signature NOT GLOB '*[^0-9a-f]*'),
 review_signature TEXT NOT NULL CHECK(length(review_signature)=64 AND review_signature NOT GLOB '*[^0-9a-f]*'),
 request_digest TEXT NOT NULL CHECK(length(request_digest)=64 AND request_digest NOT GLOB '*[^0-9a-f]*'),
 origin TEXT NOT NULL CHECK(origin IN ('review','migration')),
 reason TEXT NOT NULL CHECK(length(CAST(reason AS BLOB))<=4096),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK(source_uuid!=destination_uuid)
);

CREATE TABLE source_post_consolidation_context (
 request_uuid TEXT PRIMARY KEY NOT NULL,
 source_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 destination_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 CHECK(source_uuid!=destination_uuid)
);

CREATE TABLE post_attachment_decisions (
  uuid TEXT NOT NULL PRIMARY KEY
    CHECK (length(uuid) = 36 AND uuid = lower(uuid)
      AND substr(uuid, 9, 1) = '-' AND substr(uuid, 14, 1) = '-'
      AND substr(uuid, 19, 1) = '-' AND substr(uuid, 24, 1) = '-'
      AND length(replace(uuid, '-', '')) = 32
      AND replace(uuid, '-', '') NOT GLOB '*[^0-9a-f]*'
      AND uuid != '00000000-0000-0000-0000-000000000000'),
  post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
  revision INTEGER NOT NULL CHECK (revision > 0),
  mode TEXT NOT NULL CHECK (mode IN ('automatic', 'pinned', 'disabled')),
  origin TEXT NOT NULL CHECK (origin IN ('ingest', 'review', 'migration')),
  reason TEXT NOT NULL DEFAULT '' CHECK (length(reason) <= 4096),
  capture_uuid TEXT,
  manifest_count INTEGER NOT NULL CHECK (manifest_count BETWEEN 0 AND 4099),
  signature TEXT NOT NULL CHECK (length(signature) = 64 AND signature NOT GLOB '*[^0-9a-f]*'),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (post_uuid, revision),
  UNIQUE (post_uuid, uuid),
  FOREIGN KEY (capture_uuid) REFERENCES source_captures(uuid),
  CHECK ((mode = 'disabled' AND capture_uuid IS NULL AND manifest_count = 0)
      OR (mode = 'pinned' AND capture_uuid IS NOT NULL AND manifest_count = 1)
      OR (mode = 'automatic' AND capture_uuid IS NOT NULL AND manifest_count > 0)),
  CHECK (origin != 'ingest' OR mode = 'automatic')
);

CREATE TABLE post_attachment_decision_manifests (
  post_uuid TEXT NOT NULL,
  decision_uuid TEXT NOT NULL,
  manifest_uuid TEXT NOT NULL,
  PRIMARY KEY (decision_uuid, manifest_uuid),
  FOREIGN KEY (post_uuid, decision_uuid) REFERENCES post_attachment_decisions(post_uuid, uuid),
  FOREIGN KEY (manifest_uuid) REFERENCES source_attachment_manifests(uuid)
) WITHOUT ROWID;

CREATE TABLE post_media_consolidation_edges (
 previous_uuid TEXT PRIMARY KEY NOT NULL REFERENCES post_media_decisions(uuid),
 decision_uuid TEXT NOT NULL REFERENCES post_media_decisions(uuid),
 consolidation_uuid TEXT NOT NULL REFERENCES source_post_consolidations(uuid),
 FOREIGN KEY(previous_uuid,decision_uuid) REFERENCES post_media_supersessions(previous_uuid,decision_uuid) DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID;

CREATE TABLE post_consolidation_reviews (
 request_uuid TEXT PRIMARY KEY NOT NULL REFERENCES source_post_consolidations(uuid),
 request_json TEXT NOT NULL CHECK(json_valid(request_json) AND json_type(request_json)='object' AND length(CAST(request_json AS BLOB))<=4194304),
 result_json TEXT NOT NULL CHECK(json_valid(result_json) AND json_type(result_json)='object' AND length(CAST(result_json AS BLOB))<=4194304),
 signature TEXT NOT NULL CHECK(length(signature)=64 AND signature NOT GLOB '*[^0-9a-f]*'),
 selection_uuid TEXT UNIQUE REFERENCES post_attachment_decisions(uuid),
 gallery_decision_uuid TEXT UNIQUE REFERENCES post_gallery_decisions(uuid),
 notification_job_uuid TEXT UNIQUE REFERENCES archive_jobs(uuid)
) WITHOUT ROWID;

CREATE TABLE post_consolidation_review_members (
 request_uuid TEXT NOT NULL REFERENCES post_consolidation_reviews(request_uuid),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 previous_canonical_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 previous_revision INTEGER NOT NULL CHECK(typeof(previous_revision)='integer' AND previous_revision>0),
 PRIMARY KEY(request_uuid,post_uuid)
) WITHOUT ROWID;

CREATE TABLE post_consolidation_review_media (
 request_uuid TEXT NOT NULL REFERENCES post_consolidation_reviews(request_uuid),
 ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal>=0 AND ordinal<8192),
 decision_uuid TEXT NOT NULL UNIQUE REFERENCES post_media_decisions(uuid),
 PRIMARY KEY(request_uuid,ordinal)
) WITHOUT ROWID;

CREATE TABLE post_consolidation_review_attachments (
 request_uuid TEXT NOT NULL REFERENCES post_consolidation_reviews(request_uuid),
 ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal>=0 AND ordinal<8192),
 decision_uuid TEXT NOT NULL UNIQUE REFERENCES attachment_media_decisions(uuid),
 PRIMARY KEY(request_uuid,ordinal)
) WITHOUT ROWID;

CREATE TABLE metadata_file_edit_keeps (
 request_uuid TEXT PRIMARY KEY NOT NULL,
 entity_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
 entity_revision INTEGER NOT NULL CHECK(entity_revision>0),
 history_uuid TEXT NOT NULL,
 source_field TEXT NOT NULL,
 match_uuid TEXT NOT NULL REFERENCES source_file_matches(uuid),
 selected_decision_uuid TEXT REFERENCES metadata_field_decisions(uuid),
 request_json TEXT NOT NULL CHECK(json_valid(request_json) AND json_type(request_json)='object' AND length(CAST(request_json AS BLOB))<=262144),
 signature TEXT NOT NULL CHECK(length(signature)=64 AND signature NOT GLOB '*[^0-9a-f]*'),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(history_uuid,source_field) REFERENCES source_file_history_edits(history_uuid,field)
);

CREATE TABLE file_deduplications (
 uuid TEXT PRIMARY KEY NOT NULL CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 signature TEXT NOT NULL CHECK(length(signature)=64 AND signature NOT GLOB '*[^0-9a-f]*'),
 root_uuid TEXT NOT NULL REFERENCES media_roots(uuid),
 keep_path TEXT NOT NULL CHECK(length(keep_path) BETWEEN 1 AND 4096),
 remove_path TEXT NOT NULL CHECK(length(remove_path) BETWEEN 1 AND 4096),
 kept_file_uuid TEXT NOT NULL,
 kept_generation INTEGER NOT NULL,
 removed_file_uuid TEXT NOT NULL,
 removed_generation INTEGER NOT NULL,
 media_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
 sha256 TEXT NOT NULL REFERENCES media_contents(sha256),
 proof TEXT NOT NULL CHECK(json_valid(proof) AND json_type(proof)='object' AND length(CAST(proof AS BLOB))<=2097152),
 committed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(kept_file_uuid,kept_generation) REFERENCES file_content_versions(file_uuid,generation) ON UPDATE CASCADE,
 FOREIGN KEY(removed_file_uuid,removed_generation) REFERENCES file_content_versions(file_uuid,generation) ON UPDATE CASCADE,
 UNIQUE(removed_file_uuid,removed_generation),
 CHECK(kept_file_uuid!=removed_file_uuid AND keep_path!=remove_path)
);

CREATE TABLE provider_metadata_imports (
 sequence INTEGER PRIMARY KEY AUTOINCREMENT,
 uuid TEXT NOT NULL UNIQUE CHECK(length(uuid)=36 AND uuid=lower(uuid)
  AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
  AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
  AND uuid!='00000000-0000-0000-0000-000000000000'),
 entity_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
 original_entity_uuid TEXT NOT NULL CHECK(length(original_entity_uuid)=36),
 entity_kind TEXT NOT NULL CHECK(entity_kind IN ('scene','performer','studio','tag')),
 entity_revision INTEGER NOT NULL CHECK(entity_revision>0),
 endpoint TEXT NOT NULL CHECK(length(endpoint) BETWEEN 1 AND 4096),
 remote_id TEXT NOT NULL CHECK(length(remote_id) BETWEEN 1 AND 1024),
 operation TEXT NOT NULL CHECK(operation IN ('review','identify','batch')),
 values_json TEXT NOT NULL CHECK(json_valid(values_json) AND json_type(values_json)='object'
  AND length(CAST(values_json AS BLOB)) BETWEEN 3 AND 4194304),
 signature TEXT NOT NULL CHECK(length(signature)=64 AND signature NOT GLOB '*[^0-9a-f]*'),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE account_profile_urls (
 account_uuid TEXT NOT NULL REFERENCES source_accounts(uuid) ON UPDATE CASCADE,
 url_key TEXT NOT NULL CHECK(length(url_key) BETWEEN 1 AND 8192),
 url TEXT NOT NULL CHECK(length(url) BETWEEN 1 AND 4096),
 capture_uuid TEXT NOT NULL REFERENCES source_captures(uuid) ON UPDATE CASCADE,
 PRIMARY KEY(account_uuid,url_key)
);

CREATE TABLE performer_profile_url_suppressions (
 performer_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
 url_key TEXT NOT NULL CHECK(length(url_key) BETWEEN 1 AND 8192),
 url TEXT NOT NULL CHECK(length(url) BETWEEN 1 AND 4096),
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(performer_uuid,url_key)
);

CREATE TABLE source_capture_content (
 capture_uuid TEXT NOT NULL PRIMARY KEY,
 post_uuid TEXT NOT NULL,
 digest TEXT NOT NULL CHECK(length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*'),
 FOREIGN KEY(post_uuid,capture_uuid) REFERENCES source_captures(post_uuid,uuid)
) WITHOUT ROWID;

CREATE TABLE source_capture_sightings (
 capture_uuid TEXT NOT NULL PRIMARY KEY REFERENCES source_captures(uuid),
 count INTEGER NOT NULL CHECK(count>0),
 first_seen DATETIME NOT NULL CHECK(length(first_seen)=30 AND julianday(first_seen) IS NOT NULL),
 last_seen DATETIME NOT NULL CHECK(length(last_seen)=30 AND julianday(last_seen) IS NOT NULL),
 CHECK(first_seen<=last_seen)
) WITHOUT ROWID;

CREATE TABLE source_run_policy_upgrades (
  request_uuid TEXT PRIMARY KEY CHECK(length(request_uuid)=36),
  run_uuid TEXT NOT NULL REFERENCES source_runs(uuid),
  expected_revision INTEGER NOT NULL CHECK(expected_revision>0),
  effective_after_fence INTEGER NOT NULL CHECK(effective_after_fence>=0),
  expected_policy_sha256 TEXT NOT NULL CHECK(length(expected_policy_sha256)=64 AND expected_policy_sha256 NOT GLOB '*[^0-9a-f]*'),
  policy_sha256 TEXT NOT NULL CHECK(length(policy_sha256)=64 AND policy_sha256 NOT GLOB '*[^0-9a-f]*' AND policy_sha256!=expected_policy_sha256),
  reason TEXT NOT NULL CHECK(length(reason) BETWEEN 1 AND 1024),
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0),
  UNIQUE(run_uuid,expected_revision)
);

CREATE TABLE metadata_worker_policy_upgrades (
  id INTEGER PRIMARY KEY,
  request_uuid TEXT NOT NULL UNIQUE CHECK(length(request_uuid)=36),
  kind TEXT NOT NULL CHECK(kind IN ('post.enrich','account.list_page','post.verify_candidate')),
  original_policy_sha256 TEXT NOT NULL CHECK(length(original_policy_sha256)=64 AND original_policy_sha256 NOT GLOB '*[^0-9a-f]*'),
  expected_policy_sha256 TEXT NOT NULL CHECK(length(expected_policy_sha256)=64 AND expected_policy_sha256 NOT GLOB '*[^0-9a-f]*'),
  policy_sha256 TEXT NOT NULL CHECK(length(policy_sha256)=64 AND policy_sha256 NOT GLOB '*[^0-9a-f]*' AND policy_sha256!=expected_policy_sha256),
  reason TEXT NOT NULL CHECK(length(reason) BETWEEN 1 AND 1024),
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0)
);

CREATE TABLE metadata_worker_attempt_policies (
  job_uuid TEXT NOT NULL,
  fence INTEGER NOT NULL CHECK(fence>0),
  original_policy_sha256 TEXT NOT NULL CHECK(length(original_policy_sha256)=64 AND original_policy_sha256 NOT GLOB '*[^0-9a-f]*'),
  policy_sha256 TEXT NOT NULL CHECK(length(policy_sha256)=64 AND policy_sha256 NOT GLOB '*[^0-9a-f]*'),
  approval_uuid TEXT REFERENCES metadata_worker_policy_upgrades(request_uuid),
  PRIMARY KEY(job_uuid,fence),
  FOREIGN KEY(job_uuid,fence) REFERENCES archive_job_attempts(job_uuid,fence)
);

CREATE TABLE source_post_threads (
  post_uuid TEXT PRIMARY KEY NOT NULL REFERENCES source_posts(uuid),
  capture_uuid TEXT NOT NULL REFERENCES source_captures(uuid),
  namespace TEXT NOT NULL CHECK(namespace='native:twitter'),
  post_id TEXT NOT NULL CHECK(length(post_id) BETWEEN 1 AND 20 AND post_id NOT GLOB '*[^0-9]*'),
  conversation_id TEXT NOT NULL,
  author_id TEXT NOT NULL,
  reply_id TEXT NOT NULL DEFAULT '',
  reply_author_id TEXT NOT NULL DEFAULT '',
  conflict_capture_uuid TEXT REFERENCES source_captures(uuid),
  UNIQUE(namespace,post_id)
) WITHOUT ROWID;

CREATE TABLE source_collection_aliases (
 alias_uuid TEXT PRIMARY KEY NOT NULL REFERENCES source_collections(uuid),
 source_uuid TEXT NOT NULL REFERENCES source_collections(uuid),
 CHECK(alias_uuid!=source_uuid)
);

CREATE TABLE source_run_retrievals (
 run_uuid TEXT PRIMARY KEY NOT NULL REFERENCES source_runs(uuid),
 url TEXT NOT NULL CHECK(length(url) BETWEEN 1 AND 8192)
);

CREATE TABLE archive_jobs (
 id INTEGER PRIMARY KEY,
 uuid TEXT NOT NULL UNIQUE CHECK(length(uuid)=36 AND uuid=lower(uuid)
   AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
   AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
   AND uuid!='00000000-0000-0000-0000-000000000000'),
 kind TEXT NOT NULL CHECK(kind IN ('media.verify','album.backfill','text.translate','post.enrich','account.list_page','post.verify_candidate','post.merge_notify')),
 work_key TEXT NOT NULL CHECK(length(work_key)=64 AND work_key NOT GLOB '*[^0-9a-f]*'),
 resource_key TEXT NOT NULL CHECK(length(resource_key)=64 AND resource_key NOT GLOB '*[^0-9a-f]*'),
 arguments TEXT NOT NULL CHECK(json_valid(arguments) AND json_type(arguments)='object' AND length(CAST(arguments AS BLOB))<=262144),
 state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','succeeded','failed','cancelled')),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 priority INTEGER NOT NULL CHECK(typeof(priority)='integer' AND priority BETWEEN 0 AND 100),
 fence INTEGER NOT NULL DEFAULT 0 CHECK(typeof(fence)='integer' AND fence>=0),
 max_attempts INTEGER NOT NULL CHECK(typeof(max_attempts)='integer' AND max_attempts BETWEEN 1 AND 100),
 failures INTEGER NOT NULL DEFAULT 0 CHECK(typeof(failures)='integer' AND failures>=0),
 available_at_ms INTEGER NOT NULL CHECK(typeof(available_at_ms)='integer' AND available_at_ms>0),
 owner_uuid TEXT,
 lease_until_ms INTEGER,
 progress TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(progress) AND json_type(progress)='object' AND length(CAST(progress AS BLOB))<=16384),
 result TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(result) AND json_type(result)='object' AND length(CAST(result AS BLOB))<=16384),
 error_code TEXT NOT NULL DEFAULT '' CHECK(length(error_code)<=128),
 created_at_ms INTEGER NOT NULL CHECK(typeof(created_at_ms)='integer' AND created_at_ms>0),
 updated_at_ms INTEGER NOT NULL CHECK(typeof(updated_at_ms)='integer' AND updated_at_ms>=created_at_ms),
 CHECK(failures<=fence AND failures<=max_attempts AND (state NOT IN ('queued','running') OR failures<max_attempts)),
 CHECK((state='running' AND owner_uuid IS NOT NULL AND length(owner_uuid)=36
   AND typeof(lease_until_ms)='integer' AND lease_until_ms>0 AND fence>0)
   OR (state!='running' AND owner_uuid IS NULL AND lease_until_ms IS NULL))
);

CREATE TABLE gallery_covers (
  gallery_id INTEGER PRIMARY KEY REFERENCES galleries(id) ON DELETE CASCADE,
  media_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE
);

CREATE TABLE media_conversions (
  uuid TEXT PRIMARY KEY,
  image_uuid TEXT NOT NULL UNIQUE REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  scene_uuid TEXT NOT NULL UNIQUE REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  original_file_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  original_generation INTEGER NOT NULL CHECK(original_generation>0),
  file_uuid TEXT NOT NULL REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  generation INTEGER NOT NULL CHECK(generation>0),
  photographer TEXT NOT NULL,
  undated_o_count INTEGER NOT NULL CHECK(undated_o_count>=0),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK(image_uuid!=scene_uuid AND original_file_uuid!=file_uuid),
  FOREIGN KEY(file_uuid,generation) REFERENCES file_content_versions(file_uuid,generation)
) WITHOUT ROWID;

CREATE TABLE "scenes_o_dates" (
  scene_id INTEGER NOT NULL REFERENCES scenes(id) ON DELETE CASCADE,
  o_date DATETIME
);

CREATE TABLE source_request_budgets (
 scope TEXT PRIMARY KEY NOT NULL REFERENCES source_pacing(scope),
 next_at_ms INTEGER NOT NULL DEFAULT 0 CHECK(next_at_ms>=0),
 maintained_hour INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE source_request_permits (
 run_uuid TEXT PRIMARY KEY NOT NULL REFERENCES source_runs(uuid),
 fence INTEGER NOT NULL CHECK(fence>0),
 request_uuid TEXT NOT NULL CHECK(length(request_uuid)=36),
 scope TEXT NOT NULL REFERENCES source_request_budgets(scope),
 class TEXT NOT NULL CHECK(class IN ('routine','initial','recovery')),
 operation TEXT NOT NULL CHECK(operation IN ('listing','profile','media-resolution','other')),
 requested_at_ms INTEGER NOT NULL,
 touched_at_ms INTEGER NOT NULL,
 granted_at_ms INTEGER,
 reported INTEGER NOT NULL DEFAULT 0 CHECK(reported IN (0,1))
);

CREATE TABLE source_request_metrics (
 hour INTEGER NOT NULL,
 scope TEXT NOT NULL,
 class TEXT NOT NULL,
 operation TEXT NOT NULL,
 requests INTEGER NOT NULL DEFAULT 0,
 responses INTEGER NOT NULL DEFAULT 0,
 rate_limited INTEGER NOT NULL DEFAULT 0,
 errors INTEGER NOT NULL DEFAULT 0,
 new_posts INTEGER NOT NULL DEFAULT 0,
 repeated_posts INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(hour,scope,class,operation)
);

CREATE TABLE source_request_posts (
 run_uuid TEXT NOT NULL REFERENCES source_runs(uuid),
 post_uuid TEXT NOT NULL REFERENCES source_posts(uuid),
 hour INTEGER NOT NULL,
 PRIMARY KEY(run_uuid,post_uuid)
);

CREATE TABLE source_check_health (
 collection_uuid TEXT PRIMARY KEY NOT NULL REFERENCES source_collections(uuid),
 last_success_ms INTEGER NOT NULL CHECK(last_success_ms>=0)
);

CREATE TABLE metadata_request_permits (
 job_uuid TEXT PRIMARY KEY NOT NULL REFERENCES archive_jobs(uuid),
 fence INTEGER NOT NULL CHECK(fence>0),
 request_uuid TEXT NOT NULL CHECK(length(request_uuid)=36),
 scope TEXT NOT NULL REFERENCES source_request_budgets(scope),
 operation TEXT NOT NULL CHECK(operation IN ('listing','profile','media-resolution','other')),
 granted_at_ms INTEGER NOT NULL,
 reported INTEGER NOT NULL DEFAULT 0 CHECK(reported IN (0,1))
);

CREATE TABLE source_subscriptions (
  collection_uuid TEXT PRIMARY KEY REFERENCES source_collections(uuid),
  revision INTEGER NOT NULL CHECK(revision>0),
  enabled INTEGER NOT NULL CHECK(enabled IN (0,1))
);

CREATE TABLE source_run_subscriptions (
  run_uuid TEXT PRIMARY KEY REFERENCES source_runs(uuid),
  collection_uuid TEXT NOT NULL REFERENCES source_collections(uuid),
  revision INTEGER NOT NULL CHECK(revision>0)
);

CREATE TABLE archive_entities (
  uuid TEXT NOT NULL PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', (random() & 3) + 1, 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6))))
    CHECK (length(uuid) = 36 AND uuid = lower(uuid)
      AND substr(uuid, 9, 1) = '-' AND substr(uuid, 14, 1) = '-'
      AND substr(uuid, 19, 1) = '-' AND substr(uuid, 24, 1) = '-'
      AND length(replace(uuid, '-', '')) = 32
      AND replace(uuid, '-', '') NOT GLOB '*[^0-9a-f]*'
      AND uuid != '00000000-0000-0000-0000-000000000000'),
  kind TEXT NOT NULL CHECK (kind IN ('performer', 'scene', 'image', 'file', 'gallery', 'tag', 'studio', 'group', 'folder', 'scene_marker', 'gallery_chapter', 'saved_filter')),
  state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('active', 'redirected', 'deleted')),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),
  performer_id INTEGER REFERENCES performers(id) ON UPDATE CASCADE,
  scene_id INTEGER REFERENCES scenes(id) ON UPDATE CASCADE,
  image_id INTEGER REFERENCES images(id) ON UPDATE CASCADE,
  file_id INTEGER REFERENCES files(id) ON UPDATE CASCADE,
  gallery_id INTEGER REFERENCES galleries(id) ON UPDATE CASCADE,
  tag_id INTEGER REFERENCES tags(id) ON UPDATE CASCADE,
  studio_id INTEGER REFERENCES studios(id) ON UPDATE CASCADE,
  group_id INTEGER REFERENCES groups(id) ON UPDATE CASCADE,
  folder_id INTEGER REFERENCES folders(id) ON UPDATE CASCADE,
  scene_marker_id INTEGER REFERENCES scene_markers(id) ON UPDATE CASCADE,
  gallery_chapter_id INTEGER REFERENCES galleries_chapters(id) ON UPDATE CASCADE,
  saved_filter_id INTEGER REFERENCES saved_filters(id) ON UPDATE CASCADE,
  original_id INTEGER CHECK (original_id > 0),
  redirect_to TEXT REFERENCES archive_entities(uuid) ON UPDATE CASCADE,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  retired_at DATETIME,
  CHECK (redirect_to IS NULL OR redirect_to != uuid),
  CHECK (
    (state = 'active' AND redirect_to IS NULL AND retired_at IS NULL AND (
      (kind = 'performer' AND performer_id IS NOT NULL AND scene_id IS NULL AND image_id IS NULL AND file_id IS NULL AND gallery_id IS NULL AND tag_id IS NULL AND studio_id IS NULL AND group_id IS NULL AND folder_id IS NULL AND scene_marker_id IS NULL AND gallery_chapter_id IS NULL AND saved_filter_id IS NULL) OR
      (kind = 'scene' AND performer_id IS NULL AND scene_id IS NOT NULL AND image_id IS NULL AND file_id IS NULL AND gallery_id IS NULL AND tag_id IS NULL AND studio_id IS NULL AND group_id IS NULL AND folder_id IS NULL AND scene_marker_id IS NULL AND gallery_chapter_id IS NULL AND saved_filter_id IS NULL) OR
      (kind = 'image' AND performer_id IS NULL AND scene_id IS NULL AND image_id IS NOT NULL AND file_id IS NULL AND gallery_id IS NULL AND tag_id IS NULL AND studio_id IS NULL AND group_id IS NULL AND folder_id IS NULL AND scene_marker_id IS NULL AND gallery_chapter_id IS NULL AND saved_filter_id IS NULL) OR
      (kind = 'file' AND performer_id IS NULL AND scene_id IS NULL AND image_id IS NULL AND file_id IS NOT NULL AND gallery_id IS NULL AND tag_id IS NULL AND studio_id IS NULL AND group_id IS NULL AND folder_id IS NULL AND scene_marker_id IS NULL AND gallery_chapter_id IS NULL AND saved_filter_id IS NULL) OR
      (kind = 'gallery' AND performer_id IS NULL AND scene_id IS NULL AND image_id IS NULL AND file_id IS NULL AND gallery_id IS NOT NULL AND tag_id IS NULL AND studio_id IS NULL AND group_id IS NULL AND folder_id IS NULL AND scene_marker_id IS NULL AND gallery_chapter_id IS NULL AND saved_filter_id IS NULL) OR
      (kind = 'tag' AND performer_id IS NULL AND scene_id IS NULL AND image_id IS NULL AND file_id IS NULL AND gallery_id IS NULL AND tag_id IS NOT NULL AND studio_id IS NULL AND group_id IS NULL AND folder_id IS NULL AND scene_marker_id IS NULL AND gallery_chapter_id IS NULL AND saved_filter_id IS NULL) OR
      (kind = 'studio' AND performer_id IS NULL AND scene_id IS NULL AND image_id IS NULL AND file_id IS NULL AND gallery_id IS NULL AND tag_id IS NULL AND studio_id IS NOT NULL AND group_id IS NULL AND folder_id IS NULL AND scene_marker_id IS NULL AND gallery_chapter_id IS NULL AND saved_filter_id IS NULL) OR
      (kind = 'group' AND performer_id IS NULL AND scene_id IS NULL AND image_id IS NULL AND file_id IS NULL AND gallery_id IS NULL AND tag_id IS NULL AND studio_id IS NULL AND group_id IS NOT NULL AND folder_id IS NULL AND scene_marker_id IS NULL AND gallery_chapter_id IS NULL AND saved_filter_id IS NULL) OR
      (kind = 'folder' AND performer_id IS NULL AND scene_id IS NULL AND image_id IS NULL AND file_id IS NULL AND gallery_id IS NULL AND tag_id IS NULL AND studio_id IS NULL AND group_id IS NULL AND folder_id IS NOT NULL AND scene_marker_id IS NULL AND gallery_chapter_id IS NULL AND saved_filter_id IS NULL) OR
      (kind = 'scene_marker' AND performer_id IS NULL AND scene_id IS NULL AND image_id IS NULL AND file_id IS NULL AND gallery_id IS NULL AND tag_id IS NULL AND studio_id IS NULL AND group_id IS NULL AND folder_id IS NULL AND scene_marker_id IS NOT NULL AND gallery_chapter_id IS NULL AND saved_filter_id IS NULL) OR
      (kind = 'gallery_chapter' AND performer_id IS NULL AND scene_id IS NULL AND image_id IS NULL AND file_id IS NULL AND gallery_id IS NULL AND tag_id IS NULL AND studio_id IS NULL AND group_id IS NULL AND folder_id IS NULL AND scene_marker_id IS NULL AND gallery_chapter_id IS NOT NULL AND saved_filter_id IS NULL) OR
      (kind = 'saved_filter' AND performer_id IS NULL AND scene_id IS NULL AND image_id IS NULL AND file_id IS NULL AND gallery_id IS NULL AND tag_id IS NULL AND studio_id IS NULL AND group_id IS NULL AND folder_id IS NULL AND scene_marker_id IS NULL AND gallery_chapter_id IS NULL AND saved_filter_id IS NOT NULL)
    )) OR
    (state IN ('redirected', 'deleted') AND retired_at IS NOT NULL
      AND performer_id IS NULL AND scene_id IS NULL AND image_id IS NULL AND file_id IS NULL AND gallery_id IS NULL AND tag_id IS NULL AND studio_id IS NULL AND group_id IS NULL AND folder_id IS NULL AND scene_marker_id IS NULL AND gallery_chapter_id IS NULL AND saved_filter_id IS NULL
      AND ((state = 'redirected' AND redirect_to IS NOT NULL) OR (state = 'deleted' AND redirect_to IS NULL)))
  )
);

CREATE TABLE source_runs (
  id INTEGER PRIMARY KEY,
  uuid TEXT NOT NULL UNIQUE CHECK(length(uuid)=36 AND uuid=lower(uuid)
    AND substr(uuid,9,1)='-' AND substr(uuid,14,1)='-' AND substr(uuid,19,1)='-' AND substr(uuid,24,1)='-'
    AND length(replace(uuid,'-',''))=32 AND replace(uuid,'-','') NOT GLOB '*[^0-9a-f]*'
    AND uuid!='00000000-0000-0000-0000-000000000000'),
  collection_uuid TEXT NOT NULL,
  collection_revision INTEGER NOT NULL,
  root_uuid TEXT,
  root_revision INTEGER,
  operation TEXT NOT NULL CHECK(operation IN ('download','enrich')),
  policy_sha256 TEXT NOT NULL CHECK(length(policy_sha256)=64 AND policy_sha256 NOT GLOB '*[^0-9a-f]*'),
  cooldown_seconds INTEGER NOT NULL CHECK(cooldown_seconds BETWEEN 0 AND 86400),
  work_key TEXT NOT NULL CHECK(length(work_key)=64 AND work_key NOT GLOB '*[^0-9a-f]*'),
  target_key TEXT NOT NULL CHECK(length(target_key)=64 AND target_key NOT GLOB '*[^0-9a-f]*'),
  destination TEXT NOT NULL DEFAULT '' CHECK(length(destination)<=8192),
  root_identity TEXT NOT NULL DEFAULT '' CHECK(length(root_identity)<=128),
  destination_prefix TEXT NOT NULL DEFAULT '' CHECK(length(destination_prefix)<=4096),
  state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','succeeded','deferred','cancelled')),
  revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
  fence INTEGER NOT NULL DEFAULT 0 CHECK(fence>=0),
  failures INTEGER NOT NULL DEFAULT 0 CHECK(typeof(failures)='integer' AND failures>=0),
  pending TEXT NOT NULL CHECK(json_valid(pending) AND json_type(pending)='array' AND json_array_length(pending)<=64 AND length(pending)<=32768),
  completed TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(completed) AND json_type(completed)='array' AND json_array_length(completed)<=64 AND length(completed)<=32768),
  window TEXT CHECK(window IS NULL OR (json_valid(window) AND json_type(window)='object' AND length(window)<=512)),
  producer_uuid TEXT REFERENCES ingest_producers(uuid),
  owner_uuid TEXT CHECK(owner_uuid IS NULL OR (length(owner_uuid)=36 AND owner_uuid=lower(owner_uuid)
    AND substr(owner_uuid,9,1)='-' AND substr(owner_uuid,14,1)='-' AND substr(owner_uuid,19,1)='-' AND substr(owner_uuid,24,1)='-'
    AND length(replace(owner_uuid,'-',''))=32 AND replace(owner_uuid,'-','') NOT GLOB '*[^0-9a-f]*'
    AND owner_uuid!='00000000-0000-0000-0000-000000000000')),
  lease_until_ms INTEGER,
  available_at_ms INTEGER NOT NULL CHECK(available_at_ms>0),
  progress TEXT NOT NULL DEFAULT '{"items_seen":0,"files_completed":0,"cursor":""}' CHECK(json_valid(progress) AND json_type(progress)='object' AND length(progress)<=4096),
  error_code TEXT NOT NULL DEFAULT '' CHECK(length(error_code)<=128),
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms>0),
  updated_at_ms INTEGER NOT NULL CHECK(updated_at_ms>=created_at_ms),
  FOREIGN KEY(collection_uuid,collection_revision) REFERENCES source_collection_revisions(collection_uuid,revision),
  FOREIGN KEY(root_uuid,root_revision) REFERENCES media_root_revisions(root_uuid,revision),
  CHECK((root_uuid IS NULL AND root_revision IS NULL) OR (root_uuid IS NOT NULL AND root_revision IS NOT NULL)),
  CHECK(operation!='download' OR root_uuid IS NOT NULL),
  CHECK((state='running' AND producer_uuid IS NOT NULL AND owner_uuid IS NOT NULL AND lease_until_ms IS NOT NULL AND window IS NOT NULL AND fence>0)
    OR (state!='running' AND producer_uuid IS NULL AND owner_uuid IS NULL AND lease_until_ms IS NULL AND window IS NULL)),
  CHECK(state NOT IN ('queued','deferred') OR json_array_length(pending)>0),
  CHECK(state!='succeeded' OR json_array_length(pending)=0)
);

CREATE TABLE gallery_alternate_titles (
  gallery_id INTEGER NOT NULL REFERENCES galleries(id) ON DELETE CASCADE,
  title TEXT NOT NULL CHECK (length(trim(title)) > 0),
  PRIMARY KEY (gallery_id, title)
) WITHOUT ROWID;

CREATE TABLE source_gallery_merge_context (
