CREATE TABLE source_gallery_performer_pending (
  gallery_id INTEGER PRIMARY KEY REFERENCES galleries(id) ON DELETE CASCADE
);

CREATE TABLE source_collection_studios (
 collection_uuid TEXT PRIMARY KEY REFERENCES source_collections(uuid),
 studio_id INTEGER REFERENCES studios(id) ON DELETE SET NULL,
 revision INTEGER NOT NULL CHECK(revision>0)
);

CREATE TABLE source_gallery_studio_pending (
 gallery_id INTEGER PRIMARY KEY REFERENCES galleries(id) ON DELETE CASCADE
);

CREATE TABLE source_post_translation_display (
  post_uuid TEXT PRIMARY KEY REFERENCES source_posts(uuid),
  target_language TEXT NOT NULL,
  pending BOOLEAN NOT NULL DEFAULT 1 CHECK(pending IN (0,1)),
  after_entity TEXT NOT NULL DEFAULT '',
  adopt_before DATETIME
);

CREATE TABLE translation_policy_defaults (
