    AND (EXISTS(SELECT 1 FROM metadata_field_baselines b WHERE b.entity_uuid=a.uuid) OR json_quote(coalesce(OLD.code, ''))!='""');
  INSERT INTO metadata_field_decisions(entity_uuid, field, mode, origin, value_json)
