CREATE TRIGGER source_account_consolidation_scope BEFORE INSERT ON source_account_consolidations
BEGIN
  SELECT RAISE(ABORT,'account consolidation requires its write context') WHERE NOT EXISTS(
    SELECT 1 FROM source_account_consolidation_context WHERE source_uuid=NEW.source_uuid AND destination_uuid=NEW.destination_uuid
  );
  SELECT RAISE(ABORT,'account consolidation requires current roots in one namespace') WHERE NOT EXISTS(
    SELECT 1 FROM source_accounts s JOIN source_accounts d ON s.namespace=d.namespace
    WHERE s.uuid=NEW.source_uuid AND d.uuid=NEW.destination_uuid
    AND s.revision=NEW.source_revision AND d.revision=NEW.destination_revision
    AND s.canonical_uuid=s.uuid AND d.canonical_uuid=d.uuid
  ) OR EXISTS(SELECT 1 FROM source_account_consolidations WHERE source_uuid IN (NEW.source_uuid,NEW.destination_uuid));
  SELECT RAISE(ABORT,'account consolidation requires its selected ownership') WHERE NOT EXISTS(
    SELECT 1 FROM account_performer_links l JOIN account_performer_decisions d ON d.uuid=l.decision_uuid AND d.account_uuid=l.account_uuid
    WHERE l.account_uuid=NEW.destination_uuid AND l.decision_uuid=NEW.ownership_decision_uuid AND d.revision=NEW.destination_revision
  );
END;

CREATE TRIGGER source_account_consolidation_publish AFTER INSERT ON source_account_consolidations
BEGIN
  UPDATE source_accounts SET canonical_uuid=NEW.destination_uuid WHERE canonical_uuid=NEW.source_uuid;
END;

CREATE TRIGGER source_account_root_initial BEFORE INSERT ON source_accounts
WHEN NEW.canonical_uuid IS NOT NULL AND NEW.canonical_uuid!=NEW.uuid
BEGIN SELECT RAISE(ABORT,'new source accounts must begin as independent identities'); END;

CREATE TRIGGER source_account_root_created AFTER INSERT ON source_accounts
WHEN NEW.canonical_uuid IS NULL
BEGIN UPDATE source_accounts SET canonical_uuid=NEW.uuid WHERE uuid=NEW.uuid; END;

CREATE TRIGGER source_account_root_update BEFORE UPDATE OF canonical_uuid ON source_accounts
WHEN NOT (OLD.canonical_uuid IS NULL AND NEW.canonical_uuid=OLD.uuid)
BEGIN
  SELECT RAISE(ABORT,'canonical accounts change only through consolidation') WHERE NEW.canonical_uuid IS NULL OR NOT EXISTS(
    SELECT 1 FROM source_account_consolidation_context w
    JOIN source_account_consolidations c ON c.source_uuid=w.source_uuid AND c.destination_uuid=w.destination_uuid
    JOIN source_accounts d ON d.uuid=w.destination_uuid AND d.canonical_uuid=d.uuid AND d.namespace=OLD.namespace
    WHERE w.source_uuid=OLD.canonical_uuid AND w.destination_uuid=NEW.canonical_uuid
  );
END;

CREATE TRIGGER source_account_consolidation_immutable BEFORE UPDATE ON source_account_consolidations
BEGIN SELECT RAISE(ABORT,'account consolidations are immutable'); END;

CREATE TRIGGER source_account_namespace_immutable BEFORE UPDATE OF uuid,namespace ON source_accounts
WHEN NEW.uuid!=OLD.uuid OR NEW.namespace!=OLD.namespace
BEGIN SELECT RAISE(ABORT,'source account identity is immutable'); END;

CREATE TRIGGER source_account_identifier_immutable BEFORE UPDATE ON source_account_identifiers
WHEN NEW.uuid!=OLD.uuid OR NEW.account_uuid!=OLD.account_uuid OR NEW.namespace!=OLD.namespace OR NEW.kind!=OLD.kind OR NEW.value!=OLD.value
  OR (NEW.canonical_uuid!=OLD.canonical_uuid AND EXISTS(SELECT 1 FROM source_accounts WHERE uuid=OLD.account_uuid AND canonical_uuid=OLD.canonical_uuid))
BEGIN SELECT RAISE(ABORT,'source account identifiers are immutable'); END;

CREATE TRIGGER source_account_evidence_immutable BEFORE UPDATE ON source_account_identifier_evidence
WHEN NEW.identifier_uuid!=OLD.identifier_uuid OR NEW.evidence_key!=OLD.evidence_key OR NEW.basis!=OLD.basis
  OR NEW.origin!=OLD.origin OR NEW.details!=OLD.details
  OR NEW.first_observed>OLD.first_observed OR NEW.last_observed<OLD.last_observed
BEGIN SELECT RAISE(ABORT,'source account evidence can only extend its observation interval'); END;

CREATE TRIGGER account_performer_active_root BEFORE INSERT ON account_performer_decisions
WHEN EXISTS(SELECT 1 FROM source_account_consolidations WHERE source_uuid=NEW.account_uuid)
BEGIN SELECT RAISE(ABORT,'ownership edits require the canonical source account'); END;

CREATE TRIGGER media_root_revision_publish AFTER INSERT ON media_root_revisions
BEGIN UPDATE media_roots SET revision=NEW.revision WHERE uuid=NEW.root_uuid; END;

CREATE TRIGGER media_root_revision_immutable BEFORE UPDATE ON media_root_revisions
BEGIN SELECT RAISE(ABORT,'root revisions are immutable'); END;

CREATE TRIGGER media_root_identity_immutable BEFORE UPDATE ON media_roots
WHEN NEW.uuid!=OLD.uuid OR NEW.created_at!=OLD.created_at OR NEW.revision NOT IN (OLD.revision,OLD.revision+1)
  OR NOT EXISTS(SELECT 1 FROM media_root_revisions WHERE root_uuid=NEW.uuid AND revision=NEW.revision)
BEGIN SELECT RAISE(ABORT,'root identity advances only to a recorded revision'); END;

CREATE TRIGGER source_collection_revision_publish AFTER INSERT ON source_collection_revisions
BEGIN UPDATE source_collections SET revision=NEW.revision WHERE uuid=NEW.collection_uuid; END;

CREATE TRIGGER source_collection_revision_immutable BEFORE UPDATE ON source_collection_revisions
BEGIN SELECT RAISE(ABORT,'collection revisions are immutable'); END;

CREATE TRIGGER source_collection_identity_immutable BEFORE UPDATE ON source_collections
WHEN NEW.uuid!=OLD.uuid OR NEW.created_at!=OLD.created_at OR NEW.revision NOT IN (OLD.revision,OLD.revision+1)
  OR NOT EXISTS(SELECT 1 FROM source_collection_revisions WHERE collection_uuid=NEW.uuid AND revision=NEW.revision)
BEGIN SELECT RAISE(ABORT,'collection identity advances only to a recorded revision'); END;

CREATE TRIGGER source_collection_capture_immutable BEFORE UPDATE ON source_collection_captures
BEGIN SELECT RAISE(ABORT,'collection capture provenance is immutable'); END;

CREATE TRIGGER source_collection_intake_kind BEFORE INSERT ON source_collection_media_intake
WHEN NEW.submitted_media_uuid!=NEW.media_uuid OR NOT EXISTS(SELECT 1 FROM archive_entities WHERE uuid=NEW.media_uuid AND kind IN ('scene','image'))
BEGIN SELECT RAISE(ABORT,'collection intake requires a scene or image identity'); END;

CREATE TRIGGER source_collection_intake_immutable BEFORE UPDATE ON source_collection_media_intake
WHEN NEW.uuid!=OLD.uuid OR NEW.collection_uuid!=OLD.collection_uuid OR NEW.collection_revision!=OLD.collection_revision
  OR NEW.origin!=OLD.origin OR NEW.reason!=OLD.reason OR NEW.created_at!=OLD.created_at OR NEW.submitted_media_uuid!=OLD.submitted_media_uuid
  OR (NEW.media_uuid!=OLD.media_uuid AND EXISTS(SELECT 1 FROM archive_entities WHERE uuid=OLD.media_uuid))
BEGIN SELECT RAISE(ABORT,'collection intake provenance is immutable'); END;

CREATE TRIGGER capture_publisher_decision_scope BEFORE INSERT ON capture_publisher_decisions
BEGIN
  SELECT RAISE(ABORT,'publisher revision is stale') WHERE NEW.revision!=coalesce(
    (SELECT d.revision+1 FROM capture_publisher_heads h JOIN capture_publisher_decisions d ON d.uuid=h.decision_uuid WHERE h.capture_uuid=NEW.capture_uuid),1);
  SELECT RAISE(ABORT,'forgotten post cannot receive publisher decisions') WHERE EXISTS(
    SELECT 1 FROM source_captures c JOIN source_posts p ON p.uuid=c.post_uuid WHERE c.uuid=NEW.capture_uuid AND p.state!='active');
  SELECT RAISE(ABORT,'publisher choice requires a canonical account') WHERE EXISTS(
    SELECT 1 FROM source_accounts a WHERE a.uuid=NEW.account_uuid AND a.uuid!=a.canonical_uuid);
END;

CREATE TRIGGER capture_publisher_decision_publish AFTER INSERT ON capture_publisher_decisions
BEGIN
  INSERT INTO capture_publisher_heads(capture_uuid,decision_uuid) VALUES(NEW.capture_uuid,NEW.uuid)
    ON CONFLICT(capture_uuid) DO UPDATE SET decision_uuid=excluded.decision_uuid;
  UPDATE source_posts SET revision=revision+1 WHERE uuid=(SELECT post_uuid FROM source_captures WHERE uuid=NEW.capture_uuid);
END;

CREATE TRIGGER capture_publisher_decision_immutable BEFORE UPDATE ON capture_publisher_decisions
BEGIN SELECT RAISE(ABORT,'publisher decisions are immutable'); END;

CREATE TRIGGER capture_publisher_head_scope BEFORE INSERT ON capture_publisher_heads
WHEN (SELECT revision FROM capture_publisher_decisions WHERE uuid=NEW.decision_uuid)!=(SELECT max(revision) FROM capture_publisher_decisions WHERE capture_uuid=NEW.capture_uuid)
BEGIN SELECT RAISE(ABORT,'publisher head requires the latest decision'); END;

CREATE TRIGGER capture_publisher_head_forward BEFORE UPDATE ON capture_publisher_heads
WHEN NEW.capture_uuid!=OLD.capture_uuid OR (NEW.decision_uuid!=OLD.decision_uuid AND
  (SELECT revision FROM capture_publisher_decisions WHERE uuid=NEW.decision_uuid)<=(SELECT revision FROM capture_publisher_decisions WHERE uuid=OLD.decision_uuid))
BEGIN SELECT RAISE(ABORT,'publisher head cannot move backwards'); END;

CREATE TRIGGER capture_publisher_claim_scope BEFORE INSERT ON capture_publisher_claims
WHEN NOT EXISTS(SELECT 1 FROM capture_publisher_decisions d JOIN source_account_identifiers i ON i.account_uuid=d.account_uuid
WHERE d.uuid=NEW.decision_uuid AND d.state='linked' AND i.uuid=NEW.identifier_uuid)
BEGIN SELECT RAISE(ABORT,'publisher claim belongs to a different account'); END;

CREATE TRIGGER capture_publisher_claim_immutable BEFORE UPDATE ON capture_publisher_claims
BEGIN SELECT RAISE(ABORT,'publisher claims are immutable'); END;

CREATE TRIGGER ingest_producer_immutable BEFORE UPDATE ON ingest_producers
BEGIN SELECT RAISE(ABORT,'ingestion producer identity is immutable'); END;

CREATE TRIGGER ingest_credential_immutable BEFORE UPDATE ON ingest_credentials
WHEN NEW.uuid!=OLD.uuid OR NEW.producer_uuid!=OLD.producer_uuid OR NEW.secret_hash!=OLD.secret_hash
  OR NEW.expires_at IS NOT OLD.expires_at OR NEW.created_at!=OLD.created_at OR NEW.revoked<OLD.revoked
BEGIN SELECT RAISE(ABORT,'ingestion credentials may only be revoked'); END;

CREATE TRIGGER ingest_scope_immutable BEFORE UPDATE ON ingest_credential_scopes
BEGIN SELECT RAISE(ABORT,'ingestion scopes are immutable; issue a new credential'); END;

CREATE TRIGGER file_generation_forward BEFORE UPDATE OF generation ON files
WHEN NEW.generation != OLD.generation + 1
BEGIN SELECT RAISE(ABORT, 'file generation must advance'); END;

CREATE TRIGGER file_generation_location AFTER UPDATE OF basename,parent_folder_id,zip_file_id,size,mod_time ON files
WHEN NEW.basename IS NOT OLD.basename OR NEW.parent_folder_id IS NOT OLD.parent_folder_id
 OR NEW.zip_file_id IS NOT OLD.zip_file_id OR NEW.size IS NOT OLD.size OR NEW.mod_time IS NOT OLD.mod_time
BEGIN UPDATE files SET generation = generation + 1 WHERE id=NEW.id; END;

CREATE TRIGGER file_generation_folder AFTER UPDATE OF path ON folders
WHEN NEW.path IS NOT OLD.path
BEGIN UPDATE files SET generation = generation + 1 WHERE parent_folder_id=NEW.id; END;

CREATE TRIGGER file_generation_fingerprint_insert AFTER INSERT ON files_fingerprints
WHEN NEW.type IN ('md5','oshash')
BEGIN UPDATE files SET generation = generation + 1 WHERE id=NEW.file_id; END;

CREATE TRIGGER file_generation_fingerprint_delete AFTER DELETE ON files_fingerprints
WHEN OLD.type IN ('md5','oshash')
BEGIN UPDATE files SET generation = generation + 1 WHERE id=OLD.file_id; END;

CREATE TRIGGER file_generation_fingerprint_update AFTER UPDATE ON files_fingerprints
WHEN (OLD.type IN ('md5','oshash') OR NEW.type IN ('md5','oshash'))
 AND (NEW.file_id IS NOT OLD.file_id OR NEW.type IS NOT OLD.type OR NEW.fingerprint IS NOT OLD.fingerprint)
BEGIN UPDATE files SET generation = generation + 1 WHERE id IN (OLD.file_id,NEW.file_id); END;

CREATE TRIGGER media_content_immutable BEFORE UPDATE ON media_contents
BEGIN SELECT RAISE(ABORT, 'verified content is immutable'); END;

CREATE TRIGGER file_content_version_valid BEFORE INSERT ON file_content_versions
BEGIN
 SELECT RAISE(ABORT, 'file generation is not active') WHERE NOT EXISTS (
   SELECT 1 FROM archive_entities e JOIN files f ON f.id=e.file_id
   JOIN media_contents c ON c.uuid=NEW.content_uuid
   WHERE e.uuid=NEW.file_uuid AND e.kind='file' AND e.state='active'
     AND f.generation=NEW.generation AND f.size=c.size AND f.zip_file_id IS NULL
 );
 SELECT RAISE(ABORT, 'verified file root is inactive') WHERE NOT EXISTS (
   SELECT 1 FROM media_roots r JOIN media_root_revisions d ON d.root_uuid=r.uuid AND d.revision=r.revision
   WHERE r.uuid=NEW.root_uuid AND r.revision=NEW.root_revision AND d.state='active' AND d.server_path IS NOT NULL
 );
END;

CREATE TRIGGER file_content_version_immutable BEFORE UPDATE OF generation,content_uuid,root_uuid,root_revision,relative_path,filesystem_identity,mod_time_text,change_token,verified_at ON file_content_versions
BEGIN SELECT RAISE(ABORT, 'file content verification is immutable'); END;

CREATE TRIGGER file_content_version_identity BEFORE UPDATE OF file_uuid ON file_content_versions
WHEN NEW.file_uuid!=OLD.file_uuid AND EXISTS(SELECT 1 FROM archive_entities WHERE uuid=OLD.file_uuid)
BEGIN SELECT RAISE(ABORT, 'file content identity is immutable'); END;

CREATE TRIGGER archive_job_submission_immutable BEFORE UPDATE ON archive_job_submissions
BEGIN SELECT RAISE(ABORT,'archive job submission is immutable'); END;

CREATE TRIGGER archive_job_attempt_valid BEFORE INSERT ON archive_job_attempts
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs WHERE uuid=NEW.job_uuid AND fence=NEW.fence
 AND state='running' AND owner_uuid=NEW.owner_uuid)
BEGIN SELECT RAISE(ABORT,'archive job attempt requires owned running work'); END;

CREATE TRIGGER archive_job_attempt_immutable BEFORE UPDATE ON archive_job_attempts
WHEN OLD.outcome!='running' OR NEW.job_uuid!=OLD.job_uuid OR NEW.fence!=OLD.fence
 OR NEW.owner_uuid!=OLD.owner_uuid OR NEW.started_at_ms!=OLD.started_at_ms OR NEW.outcome='running'
BEGIN SELECT RAISE(ABORT,'archive job attempt is immutable after completion'); END;

CREATE TRIGGER file_path_fence_forward BEFORE UPDATE ON file_path_fences
WHEN NEW.folder_path!=OLD.folder_path OR NEW.basename!=OLD.basename OR NEW.revision!=OLD.revision+1
BEGIN SELECT RAISE(ABORT,'file path removal fence must advance'); END;

CREATE TRIGGER file_path_removed BEFORE DELETE ON files
WHEN OLD.zip_file_id IS NULL
BEGIN
 INSERT INTO file_path_fences(folder_path,basename,revision)
 SELECT path,OLD.basename,1 FROM folders WHERE id=OLD.parent_folder_id
 ON CONFLICT(folder_path,basename) DO UPDATE SET revision=revision+1;
END;

CREATE TRIGGER file_path_moved BEFORE UPDATE OF basename,parent_folder_id,zip_file_id ON files
WHEN OLD.zip_file_id IS NULL AND
 (NEW.basename IS NOT OLD.basename OR NEW.parent_folder_id IS NOT OLD.parent_folder_id OR NEW.zip_file_id IS NOT OLD.zip_file_id)
BEGIN
 INSERT INTO file_path_fences(folder_path,basename,revision)
 SELECT path,OLD.basename,1 FROM folders WHERE id=OLD.parent_folder_id
 ON CONFLICT(folder_path,basename) DO UPDATE SET revision=revision+1;
END;

CREATE TRIGGER file_path_folder_moved BEFORE UPDATE OF path ON folders
WHEN NEW.path IS NOT OLD.path
BEGIN
 INSERT INTO file_path_fences(folder_path,basename,revision)
 SELECT OLD.path,basename,1 FROM files WHERE parent_folder_id=OLD.id AND zip_file_id IS NULL
 ON CONFLICT(folder_path,basename) DO UPDATE SET revision=revision+1;
END;

CREATE TRIGGER metadata_policy_revision_scope BEFORE INSERT ON metadata_policy_revisions
BEGIN
  SELECT RAISE(ABORT,'policy revision is stale') WHERE NOT EXISTS(
    SELECT 1 FROM metadata_policies p LEFT JOIN metadata_policy_revisions d ON d.collection_uuid=p.collection_uuid AND d.revision=p.revision
    JOIN source_collections c ON c.uuid=p.collection_uuid
    JOIN source_collection_revisions s ON s.collection_uuid=c.uuid AND s.revision=c.revision
    WHERE p.collection_uuid=NEW.collection_uuid AND c.revision=NEW.collection_revision AND s.state!='retired'
      AND ((d.collection_uuid IS NULL AND NEW.revision=1 AND p.revision=1) OR NEW.revision=p.revision+1)
  );
END;

CREATE TRIGGER metadata_policy_revision_publish AFTER INSERT ON metadata_policy_revisions
BEGIN UPDATE metadata_policies SET revision=NEW.revision WHERE collection_uuid=NEW.collection_uuid; END;

CREATE TRIGGER metadata_policy_revision_immutable BEFORE UPDATE ON metadata_policy_revisions
BEGIN SELECT RAISE(ABORT,'policy revisions are immutable'); END;

CREATE TRIGGER metadata_policy_identity_immutable BEFORE UPDATE ON metadata_policies
WHEN NEW.collection_uuid!=OLD.collection_uuid OR NEW.revision NOT IN (OLD.revision,OLD.revision+1)
  OR NOT EXISTS(SELECT 1 FROM metadata_policy_revisions WHERE collection_uuid=NEW.collection_uuid AND revision=NEW.revision)
BEGIN SELECT RAISE(ABORT,'policy advances only to a recorded revision'); END;

CREATE TRIGGER metadata_decision_policy_immutable BEFORE UPDATE ON metadata_decision_policies
BEGIN SELECT RAISE(ABORT,'decision policy provenance is immutable'); END;

CREATE TRIGGER metadata_decision_policy_origin BEFORE INSERT ON metadata_decision_policies
WHEN NOT EXISTS(SELECT 1 FROM metadata_field_decisions WHERE uuid=NEW.decision_uuid AND mode='inherit' AND origin IN ('source','policy','filename'))
BEGIN SELECT RAISE(ABORT,'policy provenance requires an inherited decision'); END;

CREATE TRIGGER source_run_request_immutable BEFORE UPDATE ON source_run_requests
BEGIN SELECT RAISE(ABORT,'source run requests are immutable'); END;

CREATE TRIGGER source_run_attempt_valid BEFORE INSERT ON source_run_attempts
WHEN NOT EXISTS(SELECT 1 FROM source_runs WHERE uuid=NEW.run_uuid AND state='running' AND fence=NEW.fence
  AND producer_uuid=NEW.producer_uuid AND owner_uuid=NEW.owner_uuid AND window=NEW.window AND progress=NEW.progress)
BEGIN SELECT RAISE(ABORT,'source attempt requires the current lease'); END;

CREATE TRIGGER source_run_attempt_immutable BEFORE UPDATE ON source_run_attempts
WHEN OLD.outcome!='running' OR NEW.run_uuid!=OLD.run_uuid OR NEW.fence!=OLD.fence OR NEW.producer_uuid!=OLD.producer_uuid
  OR NEW.owner_uuid!=OLD.owner_uuid OR NEW.window!=OLD.window OR NEW.started_at_ms!=OLD.started_at_ms
BEGIN SELECT RAISE(ABORT,'finished source attempts are immutable'); END;

CREATE TRIGGER source_run_review_immutable BEFORE UPDATE ON source_run_reviews
BEGIN SELECT RAISE(ABORT,'source run reviews are immutable'); END;

CREATE TRIGGER ingest_root_immutable BEFORE UPDATE ON ingest_credential_roots
BEGIN SELECT RAISE(ABORT,'ingestion root grants are immutable; issue a new credential'); END;

