WHEN EXISTS(SELECT 1 FROM source_posts WHERE uuid=NEW.post_uuid AND state!='active')
BEGIN SELECT RAISE(ABORT,'forgotten source post cannot receive translations'); END;

CREATE TRIGGER source_translation_evidence_revision AFTER INSERT ON source_translation_evidence
BEGIN UPDATE source_posts SET revision=revision+1 WHERE uuid=NEW.post_uuid; END;

CREATE TRIGGER catalog_translation_import_guard BEFORE UPDATE ON catalog_translation_imports
WHEN NEW.snapshot_uuid!=OLD.snapshot_uuid OR NEW.manifest_sha256!=OLD.manifest_sha256 OR NEW.policy!=OLD.policy
 OR NEW.collection_uuid!=OLD.collection_uuid OR NEW.collection_revision!=OLD.collection_revision
 OR NEW.source_records!=OLD.source_records OR NEW.created_at!=OLD.created_at
 OR OLD.state!='running' OR NEW.last_ordinal<OLD.last_ordinal
 OR NEW.processed_records<OLD.processed_records OR NEW.mapped_records<OLD.mapped_records OR NEW.review_records<OLD.review_records
BEGIN SELECT RAISE(ABORT,'catalog translation import identity and completed progress are immutable'); END;

CREATE TRIGGER catalog_translation_record_immutable BEFORE UPDATE ON catalog_translation_records
BEGIN SELECT RAISE(ABORT,'catalog translation import receipts are immutable'); END;

CREATE TRIGGER translation_request_immutable BEFORE UPDATE ON translation_requests
BEGIN SELECT RAISE(ABORT,'translation request identity is immutable'); END;

CREATE TRIGGER translation_cache_immutable BEFORE UPDATE ON translation_cache
BEGIN SELECT RAISE(ABORT,'translation cache outcomes are immutable'); END;

CREATE TRIGGER translation_cache_scope BEFORE INSERT ON translation_cache
WHEN NEW.translation_uuid IS NOT NULL AND NOT EXISTS(
 SELECT 1 FROM source_translations s JOIN translation_requests r ON r.uuid=NEW.request_uuid
 WHERE s.uuid=NEW.translation_uuid AND s.original_text IS r.original_text
 AND s.original_sha256 IS r.original_sha256 AND s.target_language IS r.target_language
 AND (NEW.status!='unchanged' OR s.translated_text=r.original_text))
BEGIN SELECT RAISE(ABORT,'translation cache input or output scope does not match'); END;

CREATE TRIGGER translation_target_initial BEFORE INSERT ON translation_targets
WHEN NEW.revision!=1 OR NEW.state NOT IN ('held','pending') OR NEW.cache_uuid IS NOT NULL OR NEW.evidence_uuid IS NOT NULL OR NEW.reason!=''
BEGIN SELECT RAISE(ABORT,'translation targets require initial pending or held work'); END;

CREATE TRIGGER translation_target_active BEFORE INSERT ON translation_targets
WHEN EXISTS(SELECT 1 FROM source_posts WHERE uuid=NEW.post_uuid AND state!='active')
BEGIN SELECT RAISE(ABORT,'forgotten post cannot receive translation work'); END;

CREATE TRIGGER translation_target_identity BEFORE UPDATE ON translation_targets
WHEN NEW.uuid!=OLD.uuid OR NEW.request_uuid!=OLD.request_uuid OR NEW.post_uuid!=OLD.post_uuid
 OR NEW.collection_uuid IS NOT OLD.collection_uuid OR NEW.collection_revision IS NOT OLD.collection_revision
 OR NEW.field!=OLD.field OR NEW.origin!=OLD.origin OR NEW.created_at!=OLD.created_at
 OR NEW.revision!=OLD.revision+1 OR OLD.state IN ('completed','review') OR NEW.updated_at<OLD.updated_at
BEGIN SELECT RAISE(ABORT,'translation target identity or transition changed'); END;

CREATE TRIGGER translation_target_scope BEFORE UPDATE ON translation_targets
WHEN (NEW.cache_uuid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM translation_cache c WHERE c.uuid=NEW.cache_uuid AND c.request_uuid=NEW.request_uuid))
 OR (NEW.state='completed' AND NOT EXISTS(SELECT 1 FROM translation_cache c WHERE c.uuid=NEW.cache_uuid
  AND ((c.status='no_text' AND NEW.evidence_uuid IS NULL) OR EXISTS(SELECT 1 FROM source_translation_evidence e
   WHERE e.uuid=NEW.evidence_uuid AND e.post_uuid=NEW.post_uuid AND e.translation_uuid=c.translation_uuid
   AND e.collection_uuid IS NEW.collection_uuid AND e.collection_revision IS NEW.collection_revision))))
BEGIN SELECT RAISE(ABORT,'translation target completion scope does not match'); END;

CREATE TRIGGER translation_target_history_immutable BEFORE UPDATE ON translation_target_history
BEGIN SELECT RAISE(ABORT,'translation target history is immutable'); END;

CREATE TRIGGER translation_target_history_insert AFTER INSERT ON translation_targets
BEGIN
 INSERT INTO translation_target_history VALUES(NEW.uuid,NEW.revision,NEW.state,NEW.priority,NEW.not_before,NEW.cache_uuid,NEW.evidence_uuid,NEW.reason,NEW.updated_at);
END;

CREATE TRIGGER translation_target_history_update AFTER UPDATE ON translation_targets
BEGIN
 INSERT INTO translation_target_history VALUES(NEW.uuid,NEW.revision,NEW.state,NEW.priority,NEW.not_before,NEW.cache_uuid,NEW.evidence_uuid,NEW.reason,NEW.updated_at);
END;

CREATE TRIGGER translation_job_target_immutable BEFORE UPDATE ON translation_job_targets
BEGIN SELECT RAISE(ABORT,'translation job target revisions are immutable'); END;

CREATE TRIGGER translation_job_target_scope BEFORE INSERT ON translation_job_targets
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs j JOIN translation_targets t ON t.uuid=NEW.target_uuid
 WHERE j.uuid=NEW.job_uuid AND j.kind='text.translate' AND j.state='queued' AND j.fence=0
 AND t.revision=NEW.target_revision AND t.state='pending'
 AND json_extract(j.arguments,'$.version')=1 AND json_extract(j.arguments,'$.request_uuid')=t.request_uuid
 AND json_array_length(j.arguments,'$.targets') BETWEEN 1 AND 50
 AND EXISTS(SELECT 1 FROM json_each(j.arguments,'$.targets') x
  WHERE json_extract(x.value,'$.target_uuid')=t.uuid AND json_extract(x.value,'$.revision')=t.revision))
BEGIN SELECT RAISE(ABORT,'translation job target scope does not match'); END;

CREATE TRIGGER automation_snapshot_identity_immutable BEFORE UPDATE ON automation_snapshots
WHEN NEW.uuid!=OLD.uuid OR NEW.source_uuid!=OLD.source_uuid OR NEW.registry_import_uuid!=OLD.registry_import_uuid
 OR NEW.manifest_sha256!=OLD.manifest_sha256 OR NEW.source_sha256!=OLD.source_sha256 OR NEW.manifest!=OLD.manifest
 OR NEW.captured_at!=OLD.captured_at OR NEW.chunk_count!=OLD.chunk_count OR NEW.record_count!=OLD.record_count
 OR NEW.byte_count!=OLD.byte_count OR NEW.created_at!=OLD.created_at
 OR NEW.next_chunk<OLD.next_chunk OR NEW.received_records<OLD.received_records OR NEW.received_bytes<OLD.received_bytes
BEGIN SELECT RAISE(ABORT,'automation snapshot identity is immutable'); END;

CREATE TRIGGER automation_snapshot_chunk_immutable BEFORE UPDATE ON automation_snapshot_chunks
BEGIN SELECT RAISE(ABORT,'automation snapshot chunk receipts are immutable'); END;

CREATE TRIGGER automation_snapshot_record_immutable BEFORE UPDATE ON automation_snapshot_records
BEGIN SELECT RAISE(ABORT,'staged automation records are immutable'); END;

CREATE TRIGGER automation_translation_import_guard BEFORE UPDATE ON automation_translation_imports
WHEN NEW.snapshot_uuid!=OLD.snapshot_uuid OR NEW.manifest_sha256!=OLD.manifest_sha256 OR NEW.policy!=OLD.policy
 OR NEW.source_records!=OLD.source_records OR NEW.created_at!=OLD.created_at OR OLD.state!='running'
 OR NEW.last_ordinal<OLD.last_ordinal OR NEW.processed_records<OLD.processed_records
 OR NEW.mapped_records<OLD.mapped_records OR NEW.review_records<OLD.review_records
BEGIN SELECT RAISE(ABORT,'automation translation input and completed progress are immutable'); END;

CREATE TRIGGER automation_translation_record_immutable BEFORE UPDATE ON automation_translation_records
BEGIN SELECT RAISE(ABORT,'automation translation receipts are immutable'); END;

CREATE TRIGGER translation_activation_immutable BEFORE UPDATE ON translation_activations
BEGIN SELECT RAISE(ABORT,'translation activation receipts are immutable'); END;

CREATE TRIGGER translation_activation_target_immutable BEFORE UPDATE ON translation_activation_targets
BEGIN SELECT RAISE(ABORT,'translation activation target receipts are immutable'); END;

CREATE TRIGGER translation_policy_revision_scope BEFORE INSERT ON translation_policy_revisions
BEGIN
 SELECT RAISE(ABORT,'translation policy revision is stale') WHERE NOT EXISTS(
  SELECT 1 FROM translation_policies p LEFT JOIN translation_policy_revisions r ON r.collection_uuid=p.collection_uuid AND r.revision=p.revision
  JOIN source_collections c ON c.uuid=p.collection_uuid
  JOIN source_collection_revisions s ON s.collection_uuid=c.uuid AND s.revision=c.revision
  WHERE p.collection_uuid=NEW.collection_uuid AND c.revision=NEW.collection_revision AND s.state!='retired'
   AND ((r.collection_uuid IS NULL AND NEW.revision=1 AND p.revision=1) OR NEW.revision=p.revision+1)
 );
END;

CREATE TRIGGER translation_policy_revision_publish AFTER INSERT ON translation_policy_revisions
BEGIN UPDATE translation_policies SET revision=NEW.revision WHERE collection_uuid=NEW.collection_uuid; END;

CREATE TRIGGER translation_policy_revision_immutable BEFORE UPDATE ON translation_policy_revisions
BEGIN SELECT RAISE(ABORT,'translation policy revisions are immutable'); END;

CREATE TRIGGER translation_policy_identity_immutable BEFORE UPDATE ON translation_policies
WHEN NEW.collection_uuid!=OLD.collection_uuid OR NEW.revision NOT IN (OLD.revision,OLD.revision+1)
 OR NOT EXISTS(SELECT 1 FROM translation_policy_revisions WHERE collection_uuid=NEW.collection_uuid AND revision=NEW.revision)
BEGIN SELECT RAISE(ABORT,'translation policy advances only to a recorded revision'); END;

CREATE TRIGGER capture_translation_decision_immutable BEFORE UPDATE ON capture_translation_decisions
BEGIN SELECT RAISE(ABORT,'capture translation decisions are immutable'); END;

CREATE TRIGGER capture_translation_entry_immutable BEFORE UPDATE ON capture_translation_entries
BEGIN SELECT RAISE(ABORT,'capture translation entries are immutable'); END;

CREATE TRIGGER enrichment_target_initial BEFORE INSERT ON enrichment_targets
WHEN NEW.revision!=1 OR NEW.state='completed' OR NEW.created_at!=NEW.updated_at
 OR NOT EXISTS(SELECT 1 FROM source_post_urls u JOIN source_posts p ON p.uuid=u.post_uuid
  WHERE u.uuid=NEW.url_uuid AND p.uuid=NEW.post_uuid AND p.state='active')
 OR (NEW.state='pending' AND NOT EXISTS(SELECT 1 FROM source_collections c
  JOIN source_collection_revisions r ON r.collection_uuid=c.uuid AND r.revision=c.revision
  WHERE c.uuid=NEW.collection_uuid AND c.revision=NEW.collection_revision AND r.state='active'))
BEGIN SELECT RAISE(ABORT,'enrichment target requires retained post evidence and an eligible initial state'); END;

CREATE TRIGGER enrichment_target_identity BEFORE UPDATE ON enrichment_targets
WHEN NEW.uuid!=OLD.uuid OR NEW.post_uuid!=OLD.post_uuid OR NEW.url_uuid!=OLD.url_uuid
 OR NEW.collection_uuid!=OLD.collection_uuid OR NEW.collection_revision!=OLD.collection_revision
 OR NEW.policy!=OLD.policy OR NEW.origin!=OLD.origin OR NEW.created_at!=OLD.created_at
 OR NEW.revision!=OLD.revision+1 OR OLD.state='completed' OR NEW.updated_at<OLD.updated_at
BEGIN SELECT RAISE(ABORT,'enrichment target identity or transition changed'); END;

CREATE TRIGGER enrichment_completion_capture_immutable BEFORE UPDATE ON enrichment_completion_captures
BEGIN SELECT RAISE(ABORT,'enrichment completion capture evidence is immutable'); END;

CREATE TRIGGER enrichment_target_history_immutable BEFORE UPDATE ON enrichment_target_history
BEGIN SELECT RAISE(ABORT,'enrichment target history is immutable'); END;

CREATE TRIGGER enrichment_target_history_insert AFTER INSERT ON enrichment_targets
BEGIN
 INSERT INTO enrichment_target_history VALUES(NEW.uuid,NEW.revision,NEW.state,NEW.priority,NEW.not_before,NEW.reason,NEW.completion_uuid,NEW.updated_at);
END;

CREATE TRIGGER enrichment_target_history_update AFTER UPDATE ON enrichment_targets
BEGIN
 INSERT INTO enrichment_target_history VALUES(NEW.uuid,NEW.revision,NEW.state,NEW.priority,NEW.not_before,NEW.reason,NEW.completion_uuid,NEW.updated_at);
END;

CREATE TRIGGER enrichment_job_target_immutable BEFORE UPDATE ON enrichment_job_targets
BEGIN SELECT RAISE(ABORT,'enrichment job target revisions are immutable'); END;

CREATE TRIGGER enrichment_job_attempt_immutable BEFORE UPDATE ON enrichment_job_attempts
BEGIN SELECT RAISE(ABORT,'enrichment attempt producers are immutable'); END;

CREATE TRIGGER enrichment_job_attempt_scope BEFORE INSERT ON enrichment_job_attempts
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs j JOIN archive_job_attempts a ON a.job_uuid=j.uuid AND a.fence=j.fence
 WHERE j.uuid=NEW.job_uuid AND j.fence=NEW.fence AND j.kind='post.enrich' AND j.state='running'
 AND a.outcome='running' AND a.owner_uuid=j.owner_uuid)
BEGIN SELECT RAISE(ABORT,'enrichment producer requires the current running attempt'); END;

CREATE TRIGGER enrichment_checkpoint_receipt_immutable BEFORE UPDATE ON enrichment_checkpoint_receipts
BEGIN SELECT RAISE(ABORT,'enrichment checkpoint receipts are immutable'); END;

CREATE TRIGGER enrichment_checkpoint_receipt_scope BEFORE INSERT ON enrichment_checkpoint_receipts
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs j WHERE j.uuid=NEW.job_uuid AND j.state='running' AND j.fence=NEW.fence)
 OR NEW.revision!=coalesce((SELECT revision+1 FROM enrichment_checkpoints WHERE job_uuid=NEW.job_uuid),1)
 OR NEW.record_count<coalesce((SELECT r.record_count FROM enrichment_checkpoints h
  JOIN enrichment_checkpoint_receipts r ON r.job_uuid=h.job_uuid AND r.revision=h.revision WHERE h.job_uuid=NEW.job_uuid),0)
BEGIN SELECT RAISE(ABORT,'enrichment checkpoint requires a continuing owned attempt'); END;

CREATE TRIGGER enrichment_checkpoint_initial BEFORE INSERT ON enrichment_checkpoints
WHEN NEW.revision!=1
BEGIN SELECT RAISE(ABORT,'enrichment checkpoint must begin at revision one'); END;

CREATE TRIGGER enrichment_checkpoint_transition BEFORE UPDATE ON enrichment_checkpoints
WHEN NEW.job_uuid!=OLD.job_uuid OR NEW.revision!=OLD.revision+1
BEGIN SELECT RAISE(ABORT,'enrichment checkpoint revision must advance'); END;

CREATE TRIGGER enrichment_checkpoint_record_immutable BEFORE UPDATE ON enrichment_checkpoint_records
BEGIN SELECT RAISE(ABORT,'enrichment observation provenance is immutable'); END;

CREATE TRIGGER enrichment_checkpoint_record_scope BEFORE INSERT ON enrichment_checkpoint_records
WHEN NOT EXISTS(SELECT 1 FROM enrichment_checkpoint_receipts r
 WHERE r.job_uuid=NEW.job_uuid AND r.revision=NEW.checkpoint_revision AND NEW.ordinal<r.record_count
 AND NEW.ordinal>=coalesce((SELECT p.record_count FROM enrichment_checkpoint_receipts p
  WHERE p.job_uuid=r.job_uuid AND p.revision=r.revision-1),0))
BEGIN SELECT RAISE(ABORT,'enrichment observation is outside its first checkpoint'); END;

CREATE TRIGGER enrichment_checkpoint_usage_insert AFTER INSERT ON enrichment_checkpoints
BEGIN UPDATE enrichment_checkpoint_usage SET byte_size=byte_size+NEW.byte_size WHERE singleton=1; END;

CREATE TRIGGER enrichment_checkpoint_usage_update AFTER UPDATE ON enrichment_checkpoints
BEGIN UPDATE enrichment_checkpoint_usage SET byte_size=byte_size-OLD.byte_size+NEW.byte_size WHERE singleton=1; END;

CREATE TRIGGER enrichment_checkpoint_usage_delete AFTER DELETE ON enrichment_checkpoints
BEGIN UPDATE enrichment_checkpoint_usage SET byte_size=byte_size-OLD.byte_size WHERE singleton=1; END;

CREATE TRIGGER enrichment_publication_immutable BEFORE UPDATE ON enrichment_publications
BEGIN SELECT RAISE(ABORT,'enrichment publication is immutable'); END;

CREATE TRIGGER enrichment_published_record_immutable BEFORE UPDATE ON enrichment_published_records
BEGIN SELECT RAISE(ABORT,'enrichment published capture association is immutable'); END;

CREATE TRIGGER enrichment_job_pacing_bind AFTER INSERT ON enrichment_job_targets
BEGIN
 INSERT OR IGNORE INTO source_pacing(scope)
  SELECT source_scope_v1(u.url) FROM enrichment_targets t JOIN source_post_urls u ON u.uuid=t.url_uuid WHERE t.uuid=NEW.target_uuid;
 INSERT INTO enrichment_job_pacing(job_uuid,scope)
  SELECT NEW.job_uuid,source_scope_v1(u.url) FROM enrichment_targets t JOIN source_post_urls u ON u.uuid=t.url_uuid WHERE t.uuid=NEW.target_uuid;
END;

CREATE TRIGGER source_run_pacing_immutable BEFORE UPDATE ON source_run_pacing
BEGIN SELECT RAISE(ABORT,'source pacing binding is immutable'); END;

CREATE TRIGGER enrichment_attempt_pacing_bind AFTER INSERT ON archive_job_attempts
WHEN EXISTS(SELECT 1 FROM enrichment_job_pacing WHERE job_uuid=NEW.job_uuid)
BEGIN
 INSERT INTO enrichment_attempt_pacing(job_uuid,fence,scope)
  SELECT NEW.job_uuid,NEW.fence,scope FROM enrichment_job_pacing WHERE job_uuid=NEW.job_uuid;
 INSERT OR IGNORE INTO source_pacing(scope)
  SELECT source_scope_v1(json_extract(p.value,'$.url')) FROM enrichment_checkpoints h,json_each(h.body,'$.pending') p WHERE h.job_uuid=NEW.job_uuid;
 INSERT OR IGNORE INTO enrichment_attempt_pacing(job_uuid,fence,scope)
  SELECT NEW.job_uuid,NEW.fence,source_scope_v1(json_extract(p.value,'$.url'))
  FROM enrichment_checkpoints h,json_each(h.body,'$.pending') p WHERE h.job_uuid=NEW.job_uuid;
END;

CREATE TRIGGER enrichment_attempt_pacing_immutable BEFORE UPDATE ON enrichment_attempt_pacing
BEGIN SELECT RAISE(ABORT,'source attempt reservation is immutable'); END;

CREATE TRIGGER source_run_attempt_pacing_current BEFORE INSERT ON source_run_attempt_pacing
WHEN NOT EXISTS(SELECT 1 FROM source_runs r WHERE r.uuid=NEW.run_uuid AND r.fence=NEW.fence AND r.state='running')
BEGIN SELECT RAISE(ABORT,'source service requires the current attempt'); END;

CREATE TRIGGER source_run_attempt_pacing_transition BEFORE UPDATE ON source_run_attempt_pacing
WHEN NEW.run_uuid!=OLD.run_uuid OR NEW.fence!=OLD.fence OR NEW.scope!=OLD.scope OR OLD.reserved!=0 OR NEW.reserved!=1
 OR NOT EXISTS(SELECT 1 FROM source_runs r WHERE r.uuid=NEW.run_uuid AND r.fence=NEW.fence AND r.state='running')
BEGIN SELECT RAISE(ABORT,'source service reservation cannot be replaced'); END;

CREATE TRIGGER source_run_attempt_failure_current BEFORE INSERT ON source_run_attempt_failures
WHEN NOT EXISTS(SELECT 1 FROM source_run_attempts a
 JOIN source_run_attempt_pacing p ON p.run_uuid=a.run_uuid AND p.fence=a.fence AND p.scope=NEW.scope
 WHERE a.run_uuid=NEW.run_uuid AND a.fence=NEW.fence AND a.outcome IN ('retry','deferred')
  AND a.error_code=NEW.error_code AND a.ended_at_ms=NEW.created_at_ms
  AND (p.reserved=1 OR NEW.error_code='source_busy'))
BEGIN SELECT RAISE(ABORT,'source failure requires the matching completed attempt and service'); END;

CREATE TRIGGER source_run_attempt_failure_immutable BEFORE UPDATE ON source_run_attempt_failures
BEGIN SELECT RAISE(ABORT,'source service failures are immutable'); END;

CREATE TRIGGER source_service_turns_bind AFTER INSERT ON source_pacing
BEGIN INSERT INTO source_service_turns(scope) VALUES(NEW.scope); END;

CREATE TRIGGER source_enrichment_waiter_identity BEFORE UPDATE ON source_enrichment_waiters
WHEN NEW.job_uuid!=OLD.job_uuid OR NEW.fence!=OLD.fence OR NEW.refreshed_at_ms<OLD.refreshed_at_ms
BEGIN SELECT RAISE(ABORT,'source waiter identity cannot change'); END;

CREATE TRIGGER source_enrichment_receipt_immutable BEFORE UPDATE ON source_enrichment_receipts
BEGIN SELECT RAISE(ABORT,'historical enrichment receipts are immutable'); END;

CREATE TRIGGER source_enrichment_receipt_scope BEFORE INSERT ON source_enrichment_receipts
WHEN NOT EXISTS(SELECT 1 FROM source_posts WHERE uuid=NEW.post_uuid AND state='active')
 OR NOT EXISTS(SELECT 1 FROM source_collection_revisions WHERE collection_uuid=NEW.collection_uuid AND revision=NEW.collection_revision AND origin='migration')
BEGIN SELECT RAISE(ABORT,'historical enrichment receipt requires an active post and migrated collection'); END;

CREATE TRIGGER catalog_enrichment_import_guard BEFORE UPDATE ON catalog_enrichment_imports
WHEN NEW.snapshot_uuid!=OLD.snapshot_uuid OR NEW.manifest_sha256!=OLD.manifest_sha256 OR NEW.policy!=OLD.policy
 OR NEW.collection_uuid!=OLD.collection_uuid OR NEW.collection_revision!=OLD.collection_revision
 OR NEW.source_records!=OLD.source_records OR NEW.created_at!=OLD.created_at
 OR OLD.state!='running' OR NEW.last_ordinal<OLD.last_ordinal
 OR NEW.processed_records<OLD.processed_records OR NEW.mapped_records<OLD.mapped_records OR NEW.review_records<OLD.review_records
BEGIN SELECT RAISE(ABORT,'catalog enrichment import identity and completed progress are immutable'); END;

CREATE TRIGGER catalog_enrichment_record_immutable BEFORE UPDATE ON catalog_enrichment_records
BEGIN SELECT RAISE(ABORT,'catalog enrichment import records are immutable'); END;

CREATE TRIGGER enrichment_publication_scope BEFORE INSERT ON enrichment_publications
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs j
 JOIN enrichment_job_targets b ON b.job_uuid=j.uuid
 JOIN enrichment_checkpoints h ON h.job_uuid=j.uuid AND h.revision=NEW.checkpoint_revision
 JOIN enrichment_checkpoint_receipts r ON r.job_uuid=h.job_uuid AND r.revision=h.revision AND r.pending_count=0
 JOIN enrichment_completions e ON e.uuid=NEW.completion_uuid AND e.target_uuid=b.target_uuid AND e.expected_revision=b.target_revision
 JOIN enrichment_targets t ON t.uuid=e.target_uuid AND t.state='completed' AND t.completion_uuid=e.uuid
 WHERE j.uuid=NEW.job_uuid AND j.kind='post.enrich' AND j.state='running' AND j.fence=NEW.fence
 AND r.fence<=NEW.fence AND e.created_at=NEW.created_at AND r.created_at<=NEW.created_at)
BEGIN SELECT RAISE(ABORT,'enrichment publication requires the owned checkpoint and exact target completion'); END;

CREATE TRIGGER enrichment_published_record_scope BEFORE INSERT ON enrichment_published_records
WHEN NOT EXISTS(SELECT 1 FROM enrichment_publications p
 JOIN archive_jobs j ON j.uuid=p.job_uuid AND j.state='running' AND j.fence=p.fence
 JOIN enrichment_completions e ON e.uuid=p.completion_uuid
 JOIN enrichment_completion_captures c ON c.completion_uuid=e.uuid AND c.capture_uuid=NEW.capture_uuid
 WHERE p.job_uuid=NEW.job_uuid)
BEGIN SELECT RAISE(ABORT,'enrichment published record must belong to its completion'); END;

CREATE TRIGGER enrichment_completion_immutable BEFORE UPDATE ON enrichment_completions
BEGIN SELECT RAISE(ABORT,'enrichment completion evidence is immutable'); END;

CREATE TRIGGER enrichment_completion_scope BEFORE INSERT ON enrichment_completions
WHEN NOT EXISTS(SELECT 1 FROM enrichment_targets t WHERE t.uuid=NEW.target_uuid AND t.revision=NEW.expected_revision AND t.updated_at<=NEW.created_at
 AND ((NEW.legacy_receipt_uuid IS NULL AND NEW.legacy_capture_uuid IS NULL AND t.state='pending' AND t.not_before<=NEW.created_at)
  OR ((NEW.legacy_receipt_uuid IS NOT NULL OR NEW.legacy_capture_uuid IS NOT NULL)
   AND t.origin='migration' AND t.state='held' AND t.collection_revision=1
   AND EXISTS(SELECT 1 FROM source_collection_revisions c WHERE c.collection_uuid=t.collection_uuid AND c.revision=1 AND c.origin='migration')
   AND ((NEW.legacy_receipt_uuid IS NOT NULL AND EXISTS(SELECT 1 FROM source_enrichment_receipts r WHERE r.uuid=NEW.legacy_receipt_uuid
     AND r.post_uuid=t.post_uuid AND r.collection_uuid=t.collection_uuid AND r.collection_revision=t.collection_revision))
    OR (NEW.legacy_capture_uuid IS NOT NULL AND EXISTS(SELECT 1 FROM source_captures c JOIN source_collection_captures b ON b.capture_uuid=c.uuid
     WHERE c.uuid=NEW.legacy_capture_uuid AND c.post_uuid=t.post_uuid AND c.origin='gallery-dl'
     AND b.collection_uuid=t.collection_uuid AND b.collection_revision=t.collection_revision))))))
BEGIN SELECT RAISE(ABORT,'enrichment completion requires its exact target revision and proof scope'); END;

CREATE TRIGGER enrichment_target_scope BEFORE UPDATE ON enrichment_targets
WHEN (NEW.state IN ('pending','completed') AND NOT EXISTS(SELECT 1 FROM source_posts WHERE uuid=NEW.post_uuid AND state='active'))
 OR ((NEW.state='pending' OR (NEW.state='completed' AND EXISTS(SELECT 1 FROM enrichment_completions e WHERE e.uuid=NEW.completion_uuid
   AND e.legacy_receipt_uuid IS NULL AND e.legacy_capture_uuid IS NULL)))
  AND NOT EXISTS(SELECT 1 FROM source_collections c JOIN source_collection_revisions r ON r.collection_uuid=c.uuid AND r.revision=c.revision
   WHERE c.uuid=NEW.collection_uuid AND c.revision=NEW.collection_revision AND r.state='active'))
 OR (NEW.state='completed' AND NOT EXISTS(SELECT 1 FROM enrichment_completions e
  WHERE e.uuid=NEW.completion_uuid AND e.target_uuid=NEW.uuid AND e.expected_revision=OLD.revision AND e.created_at=NEW.updated_at
  AND e.capture_count=(SELECT count(*) FROM enrichment_completion_captures WHERE completion_uuid=e.uuid)
  AND ((e.legacy_receipt_uuid IS NULL AND e.legacy_capture_uuid IS NULL AND OLD.state='pending' AND NEW.not_before<=NEW.updated_at)
   OR ((e.legacy_receipt_uuid IS NOT NULL OR e.legacy_capture_uuid IS NOT NULL) AND OLD.state='held' AND NEW.origin='migration'))))
BEGIN SELECT RAISE(ABORT,'enrichment completion or active source scope does not match'); END;

CREATE TRIGGER automation_enrichment_import_guard BEFORE UPDATE ON automation_enrichment_imports
WHEN NEW.snapshot_uuid!=OLD.snapshot_uuid OR NEW.manifest_sha256!=OLD.manifest_sha256 OR NEW.policy!=OLD.policy
 OR NEW.source_records!=OLD.source_records OR NEW.created_at!=OLD.created_at OR OLD.state!='running'
 OR NEW.last_ordinal<OLD.last_ordinal OR NEW.processed_records<OLD.processed_records
 OR NEW.mapped_records<OLD.mapped_records OR NEW.review_records<OLD.review_records
BEGIN SELECT RAISE(ABORT,'automation enrichment input and completed progress are immutable'); END;

CREATE TRIGGER automation_enrichment_record_immutable BEFORE UPDATE ON automation_enrichment_records
BEGIN SELECT RAISE(ABORT,'automation enrichment import records are immutable'); END;

CREATE TRIGGER enrichment_activation_immutable BEFORE UPDATE ON enrichment_activations
BEGIN SELECT RAISE(ABORT,'enrichment activation receipts are immutable'); END;

CREATE TRIGGER enrichment_activation_target_immutable BEFORE UPDATE ON enrichment_activation_targets
BEGIN SELECT RAISE(ABORT,'enrichment activation target receipts are immutable'); END;

CREATE TRIGGER automation_checkpoint_import_guard BEFORE UPDATE ON automation_checkpoint_imports
WHEN NEW.snapshot_uuid!=OLD.snapshot_uuid OR NEW.manifest_sha256!=OLD.manifest_sha256 OR NEW.policy!=OLD.policy
 OR NEW.source_records!=OLD.source_records OR NEW.created_at!=OLD.created_at OR OLD.state!='running'
 OR NEW.last_ordinal<OLD.last_ordinal OR NEW.processed_records<OLD.processed_records
 OR NEW.mapped_records<OLD.mapped_records OR NEW.review_records<OLD.review_records
BEGIN SELECT RAISE(ABORT,'checkpoint import identity and completed progress are immutable'); END;

CREATE TRIGGER automation_checkpoint_body_immutable BEFORE UPDATE ON automation_checkpoint_bodies
BEGIN SELECT RAISE(ABORT,'converted legacy checkpoint bodies are immutable'); END;

CREATE TRIGGER automation_checkpoint_record_immutable BEFORE UPDATE ON automation_checkpoint_records
BEGIN SELECT RAISE(ABORT,'legacy checkpoint mappings are immutable'); END;

CREATE TRIGGER source_capture_immutable BEFORE UPDATE ON source_captures
BEGIN SELECT RAISE(ABORT, 'source captures are immutable'); END;

CREATE TRIGGER source_capture_active_post BEFORE INSERT ON source_captures
WHEN EXISTS (SELECT 1 FROM source_posts WHERE uuid = NEW.post_uuid AND state != 'active')
BEGIN SELECT RAISE(ABORT, 'forgotten source post cannot receive captures'); END;

CREATE TRIGGER checkpoint_evidence_acceptance_immutable BEFORE UPDATE ON checkpoint_evidence_acceptances
BEGIN SELECT RAISE(ABORT,'accepted legacy evidence is immutable'); END;

CREATE TRIGGER checkpoint_evidence_acceptance_scope BEFORE INSERT ON checkpoint_evidence_acceptances
WHEN NOT EXISTS(SELECT 1 FROM automation_enrichment_records r JOIN automation_checkpoint_records c
 ON c.snapshot_uuid=r.snapshot_uuid AND c.ordinal=r.ordinal
 JOIN enrichment_targets t ON t.uuid=r.target_uuid
 WHERE r.snapshot_uuid=NEW.snapshot_uuid AND r.ordinal=NEW.ordinal
 AND r.target_uuid=NEW.target_uuid AND r.target_revision=NEW.target_revision
 AND r.disposition='staged_review' AND c.outcome='mapped'
 AND t.revision=NEW.target_revision AND t.state='review' AND t.reason='legacy_checkpoint_conversion')
BEGIN SELECT RAISE(ABORT,'legacy evidence requires its original staged review target'); END;

CREATE TRIGGER checkpoint_evidence_capture_immutable BEFORE UPDATE ON checkpoint_evidence_captures
BEGIN SELECT RAISE(ABORT,'legacy checkpoint capture bindings are immutable'); END;

CREATE TRIGGER checkpoint_evidence_capture_scope BEFORE INSERT ON checkpoint_evidence_captures
WHEN NOT EXISTS(SELECT 1 FROM checkpoint_evidence_acceptances a
 JOIN enrichment_targets t ON t.uuid=a.target_uuid
 JOIN source_captures c ON c.post_uuid=t.post_uuid AND c.uuid=NEW.capture_uuid
 WHERE a.uuid=NEW.acceptance_uuid AND c.captured_at IS NULL
 AND c.origin='legacy-enrichment' AND c.retention_policy='legacy-retained-v1')
BEGIN SELECT RAISE(ABORT,'legacy checkpoint capture scope does not match'); END;

CREATE TRIGGER source_capture_context_immutable BEFORE UPDATE ON source_capture_contexts
BEGIN SELECT RAISE(ABORT,'source capture context is immutable'); END;

CREATE TRIGGER source_capture_context_scope BEFORE INSERT ON source_capture_contexts
WHEN NOT EXISTS(SELECT 1 FROM source_captures c JOIN source_captures p ON p.post_uuid=c.post_uuid
 JOIN source_posts s ON s.uuid=c.post_uuid
 WHERE c.uuid=NEW.capture_uuid AND p.uuid=NEW.parent_capture_uuid AND s.state='active'
 AND c.retention_policy='source-retention-v1+capture-context-v1'
 AND (p.captured_at IS NULL OR (c.captured_at IS NOT NULL AND julianday(p.captured_at)<=julianday(c.captured_at))))
 OR EXISTS(SELECT 1 FROM capture_publisher_decisions WHERE capture_uuid=NEW.capture_uuid)
 OR EXISTS(SELECT 1 FROM enrichment_published_records WHERE capture_uuid=NEW.capture_uuid)
BEGIN SELECT RAISE(ABORT,'source context must precede publisher assessment and publication'); END;

CREATE TRIGGER checkpoint_handoff_immutable BEFORE UPDATE ON checkpoint_handoffs
BEGIN SELECT RAISE(ABORT,'checkpoint handoff review is immutable'); END;

CREATE TRIGGER checkpoint_handoff_scope BEFORE INSERT ON checkpoint_handoffs
WHEN NOT EXISTS(SELECT 1 FROM checkpoint_evidence_acceptances a
 JOIN enrichment_targets t ON t.uuid=a.target_uuid
 JOIN source_posts p ON p.uuid=t.post_uuid
 JOIN source_collections c ON c.uuid=t.collection_uuid
 JOIN source_collection_revisions d ON d.collection_uuid=c.uuid AND d.revision=c.revision
 WHERE a.uuid=NEW.evidence_uuid AND t.uuid=NEW.target_uuid AND a.target_revision=NEW.target_revision
 AND t.revision=NEW.target_revision AND t.state='review' AND t.reason='legacy_checkpoint_conversion'
 AND p.state='active' AND c.uuid=NEW.collection_uuid AND c.revision=NEW.collection_revision AND d.state='active')
BEGIN SELECT RAISE(ABORT,'checkpoint handoff requires original review and active destination'); END;

CREATE TRIGGER enrichment_checkpoint_release_immutable BEFORE UPDATE ON enrichment_checkpoint_releases
BEGIN SELECT RAISE(ABORT,'enrichment checkpoint release is immutable'); END;

CREATE TRIGGER enrichment_checkpoint_release_scope BEFORE INSERT ON enrichment_checkpoint_releases
WHEN NOT EXISTS(SELECT 1 FROM enrichment_publications p
 JOIN archive_jobs j ON j.uuid=p.job_uuid AND j.state='succeeded' AND j.fence=p.fence
 JOIN enrichment_checkpoints h ON h.job_uuid=p.job_uuid AND h.revision=p.checkpoint_revision
 JOIN enrichment_checkpoint_receipts r ON r.job_uuid=h.job_uuid AND r.revision=h.revision
 WHERE p.job_uuid=NEW.job_uuid AND NEW.version=json_extract(j.arguments,'$.version') AND NEW.created_at>=p.created_at AND h.byte_size=NEW.checkpoint_bytes
 AND r.pending_count=0 AND r.unresolved_count=json_array_length(NEW.unresolved))
BEGIN SELECT RAISE(ABORT,'enrichment staging release requires its completed publication'); END;

CREATE TRIGGER enrichment_checkpoint_published_delete BEFORE DELETE ON enrichment_checkpoints
WHEN EXISTS(SELECT 1 FROM enrichment_publications p WHERE p.job_uuid=OLD.job_uuid)
 AND NOT EXISTS(SELECT 1 FROM enrichment_checkpoint_releases r WHERE r.job_uuid=OLD.job_uuid)
BEGIN SELECT RAISE(ABORT,'published enrichment checkpoint requires a release receipt'); END;

CREATE TRIGGER enrichment_job_target_scope BEFORE INSERT ON enrichment_job_targets
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs j JOIN enrichment_targets t ON t.uuid=NEW.target_uuid
 JOIN source_posts p ON p.uuid=t.post_uuid AND p.state='active'
 JOIN source_collections c ON c.uuid=t.collection_uuid AND c.revision=t.collection_revision
 JOIN source_collection_revisions r ON r.collection_uuid=c.uuid AND r.revision=c.revision AND r.state='active'
 WHERE j.uuid=NEW.job_uuid AND j.kind='post.enrich' AND j.state='queued' AND j.fence=0
 AND t.revision=NEW.target_revision AND t.state='pending'
 AND json_extract(j.arguments,'$.version') IN (1,2)
 AND ((json_extract(j.arguments,'$.version')=1 AND json_type(j.arguments,'$.capture_policy') IS NULL AND json_type(j.arguments,'$.handoff') IS NULL)
 OR (json_extract(j.arguments,'$.version')=2 AND json_extract(j.arguments,'$.capture_policy')='source-retention-v1+capture-context-v1'))
 AND json_extract(j.arguments,'$.target_uuid')=t.uuid AND json_extract(j.arguments,'$.target_revision')=t.revision
 AND json_extract(j.arguments,'$.post_uuid')=t.post_uuid
 AND json_extract(j.arguments,'$.collection_uuid')=t.collection_uuid
 AND json_extract(j.arguments,'$.collection_revision')=t.collection_revision
 AND json_extract(j.arguments,'$.root_uuid') IS r.root_uuid)
BEGIN SELECT RAISE(ABORT,'enrichment job target scope does not match'); END;

CREATE TRIGGER enrichment_handoff_job_immutable BEFORE UPDATE ON enrichment_handoff_jobs
BEGIN SELECT RAISE(ABORT,'checkpoint handoff consumption is immutable'); END;

CREATE TRIGGER enrichment_handoff_job_scope BEFORE INSERT ON enrichment_handoff_jobs
WHEN NOT EXISTS(SELECT 1 FROM checkpoint_handoffs a JOIN archive_jobs j ON j.uuid=NEW.job_uuid
 JOIN enrichment_job_targets b ON b.job_uuid=j.uuid
 JOIN enrichment_target_history h ON h.target_uuid=a.target_uuid AND h.revision=NEW.consumed_revision
 JOIN enrichment_target_history r ON r.target_uuid=b.target_uuid AND r.revision=b.target_revision
 WHERE a.uuid=NEW.handoff_uuid AND NEW.consumed_revision=a.target_revision+1
 AND j.kind='post.enrich' AND j.state='queued' AND j.fence=0 AND json_extract(j.arguments,'$.version')=2
 AND json_extract(j.arguments,'$.handoff.uuid')=a.uuid AND json_extract(j.arguments,'$.handoff.plan_sha256')=a.plan_sha256
 AND json_extract(j.arguments,'$.handoff.seed_sha256')=a.seed_sha256
 AND json_extract(j.arguments,'$.capture_policy')=json_extract(a.plan,'$.capture_policy')
 AND b.target_uuid=json_extract(a.plan,'$.released_target_uuid') AND b.target_revision=json_extract(a.plan,'$.released_revision')
 AND h.recorded_at=NEW.created_at AND r.recorded_at=NEW.created_at AND r.state='pending' AND r.reason=''
 AND ((b.target_uuid=a.target_uuid AND h.state='pending' AND h.reason='')
 OR (b.target_uuid!=a.target_uuid AND h.state='excluded' AND h.reason='checkpoint_handoff')))
BEGIN SELECT RAISE(ABORT,'checkpoint handoff requires its atomic reviewed release and job'); END;

CREATE TRIGGER enrichment_job_retained_immutable BEFORE UPDATE ON enrichment_job_retained_records
BEGIN SELECT RAISE(ABORT,'retained observation bindings are immutable'); END;

CREATE TRIGGER enrichment_job_retained_scope BEFORE INSERT ON enrichment_job_retained_records
WHEN NOT EXISTS(SELECT 1 FROM enrichment_handoff_jobs x JOIN checkpoint_handoffs h ON h.uuid=x.handoff_uuid
 JOIN checkpoint_evidence_captures c ON c.acceptance_uuid=h.evidence_uuid AND c.capture_uuid=NEW.capture_uuid
 JOIN archive_jobs j ON j.uuid=x.job_uuid AND j.state='queued' AND j.fence=0
 WHERE x.job_uuid=NEW.job_uuid)
BEGIN SELECT RAISE(ABORT,'retained records require accepted evidence before execution'); END;

CREATE TRIGGER enrichment_job_seed_service_immutable BEFORE UPDATE ON enrichment_job_seed_services
BEGIN SELECT RAISE(ABORT,'seed service bindings are immutable'); END;

CREATE TRIGGER enrichment_job_seed_service_scope BEFORE INSERT ON enrichment_job_seed_services
WHEN NOT EXISTS(SELECT 1 FROM enrichment_handoff_jobs x JOIN archive_jobs j ON j.uuid=x.job_uuid
 WHERE x.job_uuid=NEW.job_uuid AND j.state='queued' AND j.fence=0)
BEGIN SELECT RAISE(ABORT,'seed services must be bound before execution'); END;

CREATE TRIGGER enrichment_completion_capture_scope BEFORE INSERT ON enrichment_completion_captures
WHEN NOT EXISTS(SELECT 1 FROM enrichment_completions e JOIN enrichment_targets t ON t.uuid=e.target_uuid
 JOIN source_captures c ON c.uuid=NEW.capture_uuid AND c.post_uuid=t.post_uuid
 JOIN source_collection_captures b ON b.capture_uuid=c.uuid AND b.collection_uuid=t.collection_uuid AND b.collection_revision=t.collection_revision
 WHERE e.uuid=NEW.completion_uuid AND (c.origin IN ('gallery-dl','gallery-dl-enrichment') OR (c.origin='legacy-enrichment'
 AND EXISTS(SELECT 1 FROM enrichment_job_retained_records x JOIN enrichment_job_targets j ON j.job_uuid=x.job_uuid
 JOIN archive_jobs a ON a.uuid=j.job_uuid AND a.state='running'
 WHERE x.capture_uuid=c.uuid AND j.target_uuid=t.uuid AND j.target_revision=e.expected_revision)))
 AND e.legacy_receipt_uuid IS NULL AND e.legacy_capture_uuid IS NULL AND t.state='pending' AND t.revision=e.expected_revision
 AND e.capture_count>(SELECT count(*) FROM enrichment_completion_captures WHERE completion_uuid=e.uuid))
BEGIN SELECT RAISE(ABORT,'enrichment completion capture is outside its post or collection scope'); END;

CREATE TRIGGER source_file_history_immutable BEFORE UPDATE ON source_file_history
BEGIN SELECT RAISE(ABORT,'source file history is immutable'); END;

CREATE TRIGGER source_file_history_location_immutable BEFORE UPDATE ON source_file_history_locations
BEGIN SELECT RAISE(ABORT,'source file history locations are immutable'); END;

CREATE TRIGGER source_file_history_location_scope BEFORE INSERT ON source_file_history_locations
WHEN NOT EXISTS(SELECT 1 FROM source_file_history h WHERE h.uuid=NEW.history_uuid AND NEW.position<h.location_count
 AND (NEW.observation_uuid IS NOT NULL OR h.kind='deduplication')
 AND (NEW.observation_uuid IS NULL OR EXISTS(SELECT 1 FROM source_file_observations o WHERE o.uuid=NEW.observation_uuid
 AND o.collection_uuid=h.collection_uuid AND o.collection_revision=h.collection_revision
 AND o.root_uuid=h.root_uuid AND o.root_revision=h.root_revision
 AND o.relative_path=NEW.relative_path AND o.archive_path IS NEW.archive_path)))
BEGIN SELECT RAISE(ABORT,'source file history location is outside its scope'); END;

CREATE TRIGGER source_file_history_edit_immutable BEFORE UPDATE ON source_file_history_edits
BEGIN SELECT RAISE(ABORT,'source file edit history is immutable'); END;

CREATE TRIGGER source_file_history_edit_scope BEFORE INSERT ON source_file_history_edits
WHEN NOT EXISTS(SELECT 1 FROM source_file_history h WHERE h.uuid=NEW.history_uuid AND h.kind='metadata_edit'
 AND h.edit_count>(SELECT count(*) FROM source_file_history_edits e WHERE e.history_uuid=h.uuid))
BEGIN SELECT RAISE(ABORT,'source metadata choice requires its history event'); END;

CREATE TRIGGER source_file_history_state_immutable BEFORE UPDATE ON source_file_history_states
BEGIN SELECT RAISE(ABORT,'source file state history is immutable'); END;

CREATE TRIGGER source_file_history_state_scope BEFORE INSERT ON source_file_history_states
WHEN NOT EXISTS(SELECT 1 FROM source_file_history WHERE uuid=NEW.history_uuid AND kind='state_change')
BEGIN SELECT RAISE(ABORT,'source state change requires its history event'); END;

CREATE TRIGGER source_file_history_deduplication_immutable BEFORE UPDATE ON source_file_history_deduplications
BEGIN SELECT RAISE(ABORT,'source deduplication history is immutable'); END;

CREATE TRIGGER source_file_history_deduplication_scope BEFORE INSERT ON source_file_history_deduplications
WHEN NOT EXISTS(SELECT 1 FROM source_file_history h JOIN source_content_claims c
 ON c.collection_uuid=h.collection_uuid AND c.collection_revision=h.collection_revision
 WHERE h.uuid=NEW.history_uuid AND h.kind='deduplication' AND c.uuid=NEW.content_claim_uuid)
BEGIN SELECT RAISE(ABORT,'source deduplication claim is outside its history scope'); END;

CREATE TRIGGER catalog_file_history_import_guard BEFORE UPDATE ON catalog_file_history_imports
WHEN OLD.state!='running' OR NEW.snapshot_uuid!=OLD.snapshot_uuid OR NEW.manifest_sha256!=OLD.manifest_sha256
 OR NEW.collection_uuid!=OLD.collection_uuid OR NEW.collection_revision!=OLD.collection_revision
 OR NEW.root_uuid!=OLD.root_uuid OR NEW.root_revision!=OLD.root_revision OR NEW.policy!=OLD.policy
 OR NEW.created_at!=OLD.created_at OR NEW.source_records!=OLD.source_records
 OR NEW.last_ordinal<OLD.last_ordinal OR NEW.processed_records<OLD.processed_records
 OR NEW.mapped_records<OLD.mapped_records OR NEW.review_records<OLD.review_records
BEGIN SELECT RAISE(ABORT,'catalog file history progress cannot regress or change scope'); END;

CREATE TRIGGER catalog_file_history_record_immutable BEFORE UPDATE ON catalog_file_history_records
BEGIN SELECT RAISE(ABORT,'catalog file history receipts are immutable'); END;

CREATE TRIGGER metadata_file_edit_review_immutable BEFORE UPDATE ON metadata_file_edit_reviews
BEGIN SELECT RAISE(ABORT,'historical metadata review receipts are immutable'); END;

CREATE TRIGGER metadata_file_edit_review_scope BEFORE INSERT ON metadata_file_edit_reviews
WHEN NOT EXISTS(SELECT 1 FROM source_file_history_edits e
 JOIN source_file_history_locations l ON l.history_uuid=e.history_uuid
 JOIN source_file_matches m ON m.observation_uuid=l.observation_uuid
 JOIN metadata_field_decisions d ON d.uuid=NEW.decision_uuid
 JOIN archive_entities owner ON owner.uuid=d.entity_uuid AND owner.state='active'
 JOIN archive_entities f ON f.uuid=m.file_uuid AND f.kind='file' AND f.state='active'
 JOIN files current_file ON current_file.id=f.file_id AND current_file.generation=m.generation
 WHERE e.history_uuid=NEW.history_uuid AND e.field=NEW.source_field AND m.uuid=NEW.match_uuid
 AND e.mode!='unmapped' AND d.field=e.target_field AND d.mode=e.mode
 AND d.origin='review' AND d.capture_uuid IS NULL AND d.sealed=1
 AND (EXISTS(SELECT 1 FROM scenes_files sf WHERE sf.scene_id=owner.scene_id AND sf.file_id=f.file_id)
 OR EXISTS(SELECT 1 FROM images_files imf WHERE imf.image_id=owner.image_id AND imf.file_id=f.file_id)))
BEGIN SELECT RAISE(ABORT,'historical metadata review is outside its source scope'); END;

CREATE TRIGGER account_ownership_review_immutable BEFORE UPDATE ON account_ownership_reviews
BEGIN SELECT RAISE(ABORT,'account ownership review receipts are immutable'); END;

CREATE TRIGGER account_ownership_review_scope BEFORE INSERT ON account_ownership_reviews
WHEN NOT EXISTS(SELECT 1 FROM account_performer_decisions d
 JOIN account_performer_links h ON h.account_uuid=d.account_uuid AND h.decision_uuid=d.uuid
 JOIN source_accounts a ON a.uuid=d.account_uuid AND a.canonical_uuid=a.uuid
 WHERE d.uuid=NEW.decision_uuid AND d.account_uuid=NEW.account_uuid AND d.origin='review'
 AND a.revision=d.revision
 AND json_extract(NEW.request_json,'$.request_uuid') IS NEW.request_uuid
 AND json_extract(NEW.request_json,'$.account_uuid') IS d.account_uuid
 AND json_extract(NEW.request_json,'$.account_revision') IS d.revision-1
 AND json_extract(NEW.request_json,'$.state') IS d.state
 AND coalesce(json_extract(NEW.request_json,'$.reason'),'') IS d.reason
 AND json_extract(NEW.request_json,'$.performer_uuid') IS d.performer_uuid)
BEGIN SELECT RAISE(ABORT,'account ownership review is outside its decision scope'); END;

CREATE TRIGGER automation_discovery_import_guard BEFORE UPDATE ON automation_discovery_imports
WHEN NEW.snapshot_uuid!=OLD.snapshot_uuid OR NEW.manifest_sha256!=OLD.manifest_sha256 OR NEW.policy!=OLD.policy
 OR NEW.source_records!=OLD.source_records OR NEW.created_at!=OLD.created_at OR OLD.state!='running'
 OR NEW.last_ordinal<OLD.last_ordinal OR NEW.processed_records<OLD.processed_records
 OR NEW.mapped_records<OLD.mapped_records OR NEW.review_records<OLD.review_records
BEGIN SELECT RAISE(ABORT,'automation discovery input and completed progress are immutable'); END;

CREATE TRIGGER automation_discovery_record_immutable BEFORE UPDATE ON automation_discovery_records
BEGIN SELECT RAISE(ABORT,'automation discovery records are immutable'); END;

CREATE TRIGGER automation_discovery_record_scope BEFORE INSERT ON automation_discovery_records
WHEN NOT EXISTS(SELECT 1 FROM automation_snapshot_records e JOIN automation_discovery_imports i ON i.snapshot_uuid=e.snapshot_uuid
 WHERE e.snapshot_uuid=NEW.snapshot_uuid AND e.ordinal=NEW.ordinal AND i.state='running'
 AND e.source_table IN ('discovery_accounts','discovery_targets','discovery_candidates','maintenance'))
 OR (NEW.account_ordinal IS NOT NULL AND NOT EXISTS(SELECT 1 FROM automation_snapshot_records e
  WHERE e.snapshot_uuid=NEW.snapshot_uuid AND e.ordinal=NEW.account_ordinal AND e.source_table='discovery_accounts'))
 OR (NEW.target_ordinal IS NOT NULL AND NOT EXISTS(SELECT 1 FROM automation_snapshot_records e
  WHERE e.snapshot_uuid=NEW.snapshot_uuid AND e.ordinal=NEW.target_ordinal AND e.source_table='discovery_targets'))
BEGIN SELECT RAISE(ABORT,'automation discovery references must retain their original family'); END;

CREATE TRIGGER enrichment_discovery_resolution_immutable BEFORE UPDATE ON enrichment_discovery_resolutions
BEGIN SELECT RAISE(ABORT,'discovery identity resolutions are immutable'); END;

CREATE TRIGGER enrichment_job_pacing_immutable BEFORE UPDATE ON enrichment_job_pacing
BEGIN SELECT RAISE(ABORT,'source pacing binding is immutable'); END;

CREATE TRIGGER discovery_listing_immutable BEFORE UPDATE ON discovery_listings
BEGIN SELECT RAISE(ABORT,'discovery definition is immutable'); END;

CREATE TRIGGER discovery_listing_legacy_immutable BEFORE UPDATE ON discovery_listing_legacy
BEGIN SELECT RAISE(ABORT,'discovery resume evidence is immutable'); END;

CREATE TRIGGER discovery_listing_job_immutable BEFORE UPDATE ON discovery_listing_jobs
BEGIN SELECT RAISE(ABORT,'discovery job binding is immutable'); END;

CREATE TRIGGER discovery_listing_pacing_bind AFTER INSERT ON discovery_listing_jobs
BEGIN
 INSERT OR IGNORE INTO source_pacing(scope)
 SELECT source_scope_v1(json_extract(definition,'$.profile_url')) FROM discovery_listings WHERE uuid=NEW.listing_uuid;
 INSERT INTO enrichment_job_pacing(job_uuid,scope)
 SELECT NEW.job_uuid,source_scope_v1(json_extract(definition,'$.profile_url')) FROM discovery_listings WHERE uuid=NEW.listing_uuid;
END;

CREATE TRIGGER discovery_job_attempt_immutable BEFORE UPDATE ON discovery_job_attempts
BEGIN SELECT RAISE(ABORT,'discovery attempt producer is immutable'); END;

CREATE TRIGGER discovery_page_immutable BEFORE UPDATE ON discovery_pages
BEGIN SELECT RAISE(ABORT,'discovery pages are immutable'); END;

CREATE TRIGGER discovery_page_sequence BEFORE INSERT ON discovery_pages
WHEN NEW.ordinal!=coalesce((SELECT max(ordinal)+1 FROM discovery_pages WHERE listing_uuid=NEW.listing_uuid),1)
 OR EXISTS(SELECT 1 FROM discovery_pages WHERE listing_uuid=NEW.listing_uuid AND complete=1)
 OR NOT EXISTS(SELECT 1 FROM archive_jobs j JOIN discovery_listing_jobs b ON b.job_uuid=j.uuid
 JOIN discovery_job_attempts a ON a.job_uuid=j.uuid AND a.fence=j.fence
 WHERE j.uuid=NEW.job_uuid AND b.listing_uuid=NEW.listing_uuid AND b.page_ordinal=NEW.ordinal AND j.state='running' AND j.fence=NEW.fence AND a.producer_uuid=NEW.producer_uuid)
BEGIN SELECT RAISE(ABORT,'discovery page does not continue its owned listing'); END;

CREATE TRIGGER discovery_match_target_scope BEFORE INSERT ON discovery_match_targets
WHEN NOT EXISTS(SELECT 1 FROM discovery_listing_legacy l JOIN discovery_listings d ON d.uuid=l.listing_uuid
 JOIN automation_discovery_records r ON r.snapshot_uuid=l.snapshot_uuid AND r.account_ordinal=l.account_ordinal
 JOIN automation_snapshot_records e ON e.snapshot_uuid=r.snapshot_uuid AND e.ordinal=r.ordinal
 JOIN source_posts p ON p.uuid=r.post_uuid
 WHERE d.uuid=NEW.listing_uuid AND r.ordinal=NEW.source_ordinal AND r.snapshot_uuid=NEW.snapshot_uuid
 AND e.source_table='discovery_targets' AND e.data_sha256=NEW.source_sha256
 AND r.outcome='mapped' AND r.disposition='held' AND r.account_uuid=d.account_uuid AND r.collection_uuid=d.collection_uuid
 AND p.uuid=NEW.post_uuid AND p.revision=NEW.post_revision AND p.state='active')
BEGIN SELECT RAISE(ABORT,'discovery target must bind its original reviewed source'); END;

CREATE TRIGGER discovery_match_page_immutable BEFORE UPDATE ON discovery_match_pages
BEGIN SELECT RAISE(ABORT,'discovery comparison receipt is immutable'); END;

CREATE TRIGGER discovery_match_page_scope BEFORE INSERT ON discovery_match_pages
WHEN NOT EXISTS(SELECT 1 FROM discovery_match_targets t JOIN discovery_pages p ON p.listing_uuid=t.listing_uuid
 WHERE t.uuid=NEW.target_uuid AND t.listing_uuid=NEW.listing_uuid AND t.last_page+1=NEW.page_ordinal AND t.enumeration_complete=0
 AND p.ordinal=NEW.page_ordinal AND p.digest=NEW.page_sha256 AND p.complete=NEW.complete)
BEGIN SELECT RAISE(ABORT,'discovery comparison must continue its original pages'); END;

CREATE TRIGGER discovery_match_candidate_transition BEFORE UPDATE ON discovery_match_candidates
WHEN NEW.id!=OLD.id OR NEW.target_uuid!=OLD.target_uuid OR NEW.namespace!=OLD.namespace OR NEW.value!=OLD.value
 OR NEW.first_page!=OLD.first_page OR NEW.last_page<=OLD.last_page OR NEW.page_count!=OLD.page_count+1
 OR NEW.best_page NOT IN (OLD.best_page,NEW.last_page)
BEGIN SELECT RAISE(ABORT,'invalid discovery candidate progression'); END;

CREATE TRIGGER discovery_match_evidence_immutable BEFORE UPDATE ON discovery_match_evidence
BEGIN SELECT RAISE(ABORT,'discovery candidate evidence is immutable'); END;

CREATE TRIGGER discovery_match_target_transition BEFORE UPDATE ON discovery_match_targets
WHEN NEW.uuid!=OLD.uuid OR NEW.listing_uuid!=OLD.listing_uuid OR NEW.snapshot_uuid!=OLD.snapshot_uuid
 OR NEW.source_ordinal!=OLD.source_ordinal OR NEW.source_sha256!=OLD.source_sha256 OR NEW.post_uuid!=OLD.post_uuid
 OR NEW.post_revision!=OLD.post_revision OR NEW.policy!=OLD.policy OR NEW.created_at!=OLD.created_at
 OR OLD.enumeration_complete=1 OR NEW.last_page!=OLD.last_page+1 OR NEW.revision!=OLD.revision+1
 OR NOT EXISTS(SELECT 1 FROM discovery_match_pages p WHERE p.target_uuid=NEW.uuid AND p.page_ordinal=NEW.last_page
  AND p.complete=NEW.enumeration_complete AND p.created_at=NEW.updated_at
  AND p.candidate_count=(SELECT count(*) FROM discovery_match_evidence e WHERE e.target_uuid=p.target_uuid AND e.page_ordinal=p.page_ordinal))
BEGIN SELECT RAISE(ABORT,'discovery comparison progress requires its complete receipt'); END;

CREATE TRIGGER discovery_activation_immutable BEFORE UPDATE ON discovery_activations
BEGIN SELECT RAISE(ABORT,'discovery activation receipts are immutable'); END;

CREATE TRIGGER discovery_activation_source BEFORE INSERT ON discovery_activations
WHEN NOT EXISTS(SELECT 1 FROM automation_discovery_imports i JOIN discovery_listing_legacy l ON l.snapshot_uuid=i.snapshot_uuid
 JOIN discovery_listings d ON d.uuid=l.listing_uuid
 JOIN automation_snapshot_records a ON a.snapshot_uuid=l.snapshot_uuid AND a.ordinal=l.account_ordinal
 WHERE i.snapshot_uuid=NEW.snapshot_uuid AND i.state!='running' AND i.manifest_sha256=NEW.manifest_sha256
 AND d.uuid=NEW.listing_uuid AND d.digest=json_extract(NEW.plan,'$.listing_sha256')
 AND a.data_sha256=json_extract(NEW.plan,'$.account_sha256'))
BEGIN SELECT RAISE(ABORT,'discovery activation requires its reviewed source'); END;

CREATE TRIGGER discovery_activation_target_immutable BEFORE UPDATE ON discovery_activation_targets
BEGIN SELECT RAISE(ABORT,'discovery activation target receipts are immutable'); END;

CREATE TRIGGER discovery_activation_target_scope BEFORE INSERT ON discovery_activation_targets
WHEN NOT EXISTS(SELECT 1 FROM discovery_activations a JOIN discovery_match_targets t ON t.listing_uuid=a.listing_uuid
 JOIN json_each(a.plan,'$.entries') e ON json_extract(e.value,'$.target_uuid')=t.uuid
 WHERE a.uuid=NEW.activation_uuid AND t.uuid=NEW.target_uuid
 AND t.source_ordinal=json_extract(e.value,'$.source_ordinal') AND t.source_sha256=json_extract(e.value,'$.source_sha256')
 AND t.post_uuid=json_extract(e.value,'$.post_uuid') AND t.post_revision=json_extract(e.value,'$.post_revision'))
BEGIN SELECT RAISE(ABORT,'discovery activation target differs from its review'); END;

CREATE TRIGGER discovery_published_record_immutable BEFORE UPDATE ON discovery_published_records
BEGIN SELECT RAISE(ABORT,'discovery published records are immutable'); END;

CREATE TRIGGER discovery_listing_recovery_immutable BEFORE UPDATE ON discovery_listing_recoveries
BEGIN SELECT RAISE(ABORT,'discovery recovery references are immutable'); END;

CREATE TRIGGER discovery_recovery_job_scope BEFORE INSERT ON discovery_listing_jobs
WHEN EXISTS(SELECT 1 FROM discovery_listing_recoveries WHERE previous_listing_uuid=NEW.listing_uuid)
BEGIN SELECT RAISE(ABORT,'recovered discovery searches cannot admit more jobs'); END;

CREATE TRIGGER discovery_recovery_page_scope BEFORE INSERT ON discovery_pages
WHEN EXISTS(SELECT 1 FROM discovery_listing_recoveries WHERE previous_listing_uuid=NEW.listing_uuid)
BEGIN SELECT RAISE(ABORT,'recovered discovery searches retain their original final evidence'); END;

CREATE TRIGGER discovery_recovery_target_immutable BEFORE UPDATE ON discovery_recovery_targets
BEGIN SELECT RAISE(ABORT,'discovery recovery target references are immutable'); END;

CREATE TRIGGER discovery_recovery_target_scope BEFORE INSERT ON discovery_recovery_targets
WHEN NOT EXISTS(SELECT 1 FROM discovery_match_targets n JOIN discovery_match_targets p ON p.uuid=NEW.previous_target_uuid
 JOIN discovery_listing_recoveries r ON r.listing_uuid=n.listing_uuid AND r.previous_listing_uuid=p.listing_uuid
 WHERE n.uuid=NEW.target_uuid AND n.snapshot_uuid=p.snapshot_uuid AND n.source_ordinal=p.source_ordinal
 AND n.source_sha256=p.source_sha256 AND n.post_uuid=p.post_uuid)
BEGIN SELECT RAISE(ABORT,'discovery recovery target must preserve its original evidence'); END;

CREATE TRIGGER enrichment_attempt_pacing_current BEFORE INSERT ON enrichment_attempt_pacing
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs j WHERE j.uuid=NEW.job_uuid AND j.kind IN ('post.enrich','account.list_page','post.verify_candidate') AND j.state='running' AND j.fence=NEW.fence)
BEGIN SELECT RAISE(ABORT,'source reservation requires the current metadata attempt'); END;

CREATE TRIGGER source_enrichment_waiter_current BEFORE INSERT ON source_enrichment_waiters
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs j WHERE j.uuid=NEW.job_uuid AND j.kind IN ('post.enrich','account.list_page','post.verify_candidate') AND j.state='queued' AND j.fence=NEW.fence)
BEGIN SELECT RAISE(ABORT,'source waiter requires the current queued metadata job'); END;

CREATE TRIGGER discovery_detail_job_immutable BEFORE UPDATE ON discovery_detail_jobs
BEGIN SELECT RAISE(ABORT,'discovery detail selection is immutable'); END;

CREATE TRIGGER discovery_detail_pacing_bind AFTER INSERT ON discovery_detail_jobs
BEGIN
 INSERT OR IGNORE INTO source_pacing(scope)
 SELECT source_scope_v1(json_extract(arguments,'$.url')) FROM archive_jobs WHERE uuid=NEW.job_uuid;
 INSERT INTO enrichment_job_pacing(job_uuid,scope)
 SELECT NEW.job_uuid,source_scope_v1(json_extract(arguments,'$.url')) FROM archive_jobs WHERE uuid=NEW.job_uuid;
END;

CREATE TRIGGER discovery_detail_attempt_immutable BEFORE UPDATE ON discovery_detail_attempts
BEGIN SELECT RAISE(ABORT,'discovery detail attempt producer is immutable'); END;

CREATE TRIGGER discovery_detail_attempt_scope BEFORE INSERT ON discovery_detail_attempts
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs j JOIN archive_job_attempts a ON a.job_uuid=j.uuid AND a.fence=j.fence
 WHERE j.uuid=NEW.job_uuid AND j.fence=NEW.fence AND j.kind='post.verify_candidate' AND j.state='running'
 AND a.outcome='running' AND a.owner_uuid=j.owner_uuid)
BEGIN SELECT RAISE(ABORT,'discovery detail producer requires the current running attempt'); END;

CREATE TRIGGER discovery_detail_checkpoint_receipt_immutable BEFORE UPDATE ON discovery_detail_checkpoint_receipts
BEGIN SELECT RAISE(ABORT,'enrichment checkpoint receipts are immutable'); END;

CREATE TRIGGER discovery_detail_checkpoint_receipt_scope BEFORE INSERT ON discovery_detail_checkpoint_receipts
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs j WHERE j.uuid=NEW.job_uuid AND j.state='running' AND j.fence=NEW.fence)
 OR NEW.revision!=coalesce((SELECT revision+1 FROM discovery_detail_checkpoints WHERE job_uuid=NEW.job_uuid),1)
 OR NEW.record_count<coalesce((SELECT r.record_count FROM discovery_detail_checkpoints h
  JOIN discovery_detail_checkpoint_receipts r ON r.job_uuid=h.job_uuid AND r.revision=h.revision WHERE h.job_uuid=NEW.job_uuid),0)
BEGIN SELECT RAISE(ABORT,'enrichment checkpoint requires a continuing owned attempt'); END;

CREATE TRIGGER discovery_detail_checkpoint_initial BEFORE INSERT ON discovery_detail_checkpoints
WHEN NEW.revision!=1
BEGIN SELECT RAISE(ABORT,'enrichment checkpoint must begin at revision one'); END;

CREATE TRIGGER discovery_detail_checkpoint_transition BEFORE UPDATE ON discovery_detail_checkpoints
WHEN NEW.job_uuid!=OLD.job_uuid OR NEW.revision!=OLD.revision+1
BEGIN SELECT RAISE(ABORT,'enrichment checkpoint revision must advance'); END;

CREATE TRIGGER discovery_detail_checkpoint_record_immutable BEFORE UPDATE ON discovery_detail_checkpoint_records
BEGIN SELECT RAISE(ABORT,'enrichment observation provenance is immutable'); END;

CREATE TRIGGER discovery_detail_checkpoint_record_scope BEFORE INSERT ON discovery_detail_checkpoint_records
WHEN NOT EXISTS(SELECT 1 FROM discovery_detail_checkpoint_receipts r
 WHERE r.job_uuid=NEW.job_uuid AND r.revision=NEW.checkpoint_revision AND NEW.ordinal<r.record_count
 AND NEW.ordinal>=coalesce((SELECT p.record_count FROM discovery_detail_checkpoint_receipts p
  WHERE p.job_uuid=r.job_uuid AND p.revision=r.revision-1),0))
BEGIN SELECT RAISE(ABORT,'enrichment observation is outside its first checkpoint'); END;

CREATE TRIGGER discovery_detail_checkpoint_usage_insert AFTER INSERT ON discovery_detail_checkpoints
BEGIN UPDATE discovery_detail_checkpoint_usage SET byte_size=byte_size+NEW.byte_size WHERE singleton=1; END;

CREATE TRIGGER discovery_detail_checkpoint_usage_update AFTER UPDATE ON discovery_detail_checkpoints
BEGIN UPDATE discovery_detail_checkpoint_usage SET byte_size=byte_size-OLD.byte_size+NEW.byte_size WHERE singleton=1; END;

CREATE TRIGGER discovery_detail_checkpoint_usage_delete AFTER DELETE ON discovery_detail_checkpoints
BEGIN UPDATE discovery_detail_checkpoint_usage SET byte_size=byte_size-OLD.byte_size WHERE singleton=1; END;

CREATE TRIGGER discovery_detail_result_immutable BEFORE UPDATE ON discovery_detail_results
BEGIN SELECT RAISE(ABORT,'discovery detail result is immutable'); END;

CREATE TRIGGER discovery_detail_result_scope BEFORE INSERT ON discovery_detail_results
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs j JOIN discovery_detail_checkpoints h ON h.job_uuid=j.uuid
 JOIN discovery_detail_checkpoint_receipts r ON r.job_uuid=h.job_uuid AND r.revision=h.revision
 WHERE j.uuid=NEW.job_uuid AND j.state='running' AND j.fence=NEW.fence AND r.revision=NEW.checkpoint_revision
 AND r.pending_count=0 AND r.digest=json_extract(NEW.evidence,'$.transcript_sha256'))
BEGIN SELECT RAISE(ABORT,'discovery detail result requires its current completed checkpoint'); END;

CREATE TRIGGER discovery_match_publication_immutable BEFORE UPDATE ON discovery_match_publications
BEGIN SELECT RAISE(ABORT,'discovery publication is immutable'); END;

CREATE TRIGGER discovery_match_publication_scope BEFORE INSERT ON discovery_match_publications
WHEN NOT EXISTS(SELECT 1 FROM discovery_match_targets t
 JOIN discovery_listings l ON l.uuid=t.listing_uuid
 JOIN discovery_match_candidates c ON c.target_uuid=t.uuid
 JOIN discovery_match_evidence e ON e.target_uuid=t.uuid AND e.page_ordinal=NEW.page_ordinal AND e.namespace=c.namespace AND e.value=c.value
 JOIN discovery_pages p ON p.listing_uuid=l.uuid AND p.ordinal=e.page_ordinal
 WHERE t.uuid=NEW.target_uuid AND t.revision=NEW.target_revision AND t.enumeration_complete=1
 AND t.post_uuid=NEW.post_uuid AND t.post_revision=NEW.post_revision
 AND json_extract(l.definition,'$.historical_pages')=0 AND json_type(l.definition,'$.initial_cursor')='null'
 AND c.namespace=NEW.namespace AND c.value=NEW.value AND p.digest=NEW.page_sha256
 AND (SELECT count(*) FROM discovery_match_candidates WHERE target_uuid=t.uuid)=1
 AND ((NEW.detail_job_uuid IS NULL AND c.best_page=e.page_ordinal AND e.needs_detail=0 AND e.basis=NEW.basis)
   OR (e.needs_detail=1 AND EXISTS(SELECT 1 FROM discovery_detail_jobs d
     JOIN archive_jobs j ON j.uuid=d.job_uuid AND j.state='succeeded'
     JOIN discovery_detail_results r ON r.job_uuid=j.uuid AND r.fence=j.fence
     JOIN discovery_detail_checkpoint_receipts h ON h.job_uuid=r.job_uuid AND h.revision=r.checkpoint_revision
     WHERE d.job_uuid=NEW.detail_job_uuid AND d.target_uuid=t.uuid AND d.target_revision<=t.revision AND d.candidate_sequence=c.id
     AND json_extract(j.arguments,'$.page_ordinal')=e.page_ordinal
     AND json_extract(j.arguments,'$.page_sha256')=p.digest
     AND json_extract(r.evidence,'$.status')='corroborated'
     AND json_extract(r.evidence,'$.basis')=NEW.basis
     AND json_extract(r.evidence,'$.witness_ordinal')=NEW.witness_ordinal
     AND h.pending_count=0 AND h.record_count=NEW.record_count))))
BEGIN SELECT RAISE(ABORT,'discovery publication requires a complete unique verified match'); END;

CREATE TRIGGER discovery_published_record_scope BEFORE INSERT ON discovery_published_records
WHEN NOT EXISTS(SELECT 1 FROM discovery_match_publications p JOIN source_captures c ON c.post_uuid=p.post_uuid
 JOIN discovery_pages page ON page.listing_uuid=p.listing_uuid AND page.ordinal=p.page_ordinal
 WHERE p.target_uuid=NEW.target_uuid AND c.uuid=NEW.capture_uuid
 AND ((p.detail_job_uuid IS NULL AND NEW.ordinal<page.record_count)
 OR (p.detail_job_uuid IS NOT NULL AND EXISTS(SELECT 1 FROM discovery_detail_checkpoint_records r
     WHERE r.job_uuid=p.detail_job_uuid AND r.ordinal=NEW.ordinal))))
BEGIN SELECT RAISE(ABORT,'discovery record must publish its original post observation'); END;

CREATE TRIGGER metadata_policy_import_immutable BEFORE UPDATE ON metadata_policy_imports
BEGIN SELECT RAISE(ABORT,'metadata policy migration receipts are immutable'); END;

CREATE TRIGGER metadata_policy_import_document_immutable BEFORE UPDATE ON metadata_policy_import_documents
BEGIN SELECT RAISE(ABORT,'metadata policy migration document references are immutable'); END;

CREATE TRIGGER metadata_policy_import_document_source BEFORE INSERT ON metadata_policy_import_documents
WHEN NOT EXISTS(SELECT 1 FROM source_document_head_decisions h WHERE h.uuid=NEW.head_uuid AND h.source_uuid=NEW.source_uuid AND h.state='linked')
BEGIN SELECT RAISE(ABORT,'metadata policy migration requires a selected document source'); END;

CREATE TRIGGER source_cleanup_intent_immutable BEFORE UPDATE ON source_cleanup_intents
BEGIN SELECT RAISE(ABORT,'source cleanup intent is immutable'); END;

CREATE TRIGGER source_cleanup_intent_scope BEFORE INSERT ON source_cleanup_intents
WHEN NOT EXISTS(SELECT 1 FROM source_collection_revisions WHERE collection_uuid=NEW.collection_uuid AND revision=NEW.collection_revision AND origin='migration')
BEGIN SELECT RAISE(ABORT,'historical cleanup requires its original migrated collection'); END;

CREATE TRIGGER catalog_cleanup_import_guard BEFORE UPDATE ON catalog_cleanup_imports
WHEN NEW.snapshot_uuid!=OLD.snapshot_uuid OR NEW.manifest_sha256!=OLD.manifest_sha256 OR NEW.policy!=OLD.policy
 OR NEW.collection_uuid!=OLD.collection_uuid OR NEW.collection_revision!=OLD.collection_revision
 OR NEW.source_records!=OLD.source_records OR NEW.created_at!=OLD.created_at
 OR OLD.state!='running' OR NEW.last_ordinal<OLD.last_ordinal
 OR NEW.processed_records<OLD.processed_records OR NEW.held_records<OLD.held_records OR NEW.review_records<OLD.review_records
BEGIN SELECT RAISE(ABORT,'catalog cleanup import identity and completed progress are immutable'); END;

CREATE TRIGGER catalog_cleanup_record_immutable BEFORE UPDATE ON catalog_cleanup_records
BEGIN SELECT RAISE(ABORT,'catalog cleanup import records are immutable'); END;

CREATE TRIGGER post_media_supersession_immutable BEFORE UPDATE ON post_media_supersessions
BEGIN SELECT RAISE(ABORT,'post media replacements are immutable'); END;

CREATE TRIGGER post_media_decision_immutable BEFORE UPDATE ON post_media_decisions
WHEN NEW.uuid!=OLD.uuid OR NEW.post_uuid!=OLD.post_uuid OR NEW.post_revision!=OLD.post_revision
 OR NEW.media_revision!=OLD.media_revision OR NEW.state!=OLD.state OR NEW.origin!=OLD.origin
 OR NEW.reason!=OLD.reason OR NEW.request_digest!=OLD.request_digest OR NEW.created_at!=OLD.created_at
 OR (NEW.media_uuid!=OLD.media_uuid AND EXISTS(SELECT 1 FROM archive_entities WHERE uuid=OLD.media_uuid))
BEGIN SELECT RAISE(ABORT,'post media decisions are immutable'); END;

CREATE TRIGGER post_media_head_forward BEFORE UPDATE OF decision_uuid ON post_media_links
WHEN NEW.decision_uuid!=OLD.decision_uuid AND (SELECT post_revision FROM post_media_decisions WHERE uuid=NEW.decision_uuid)
 <= (SELECT post_revision FROM post_media_decisions WHERE uuid=OLD.decision_uuid)
BEGIN SELECT RAISE(ABORT,'post media head cannot move backwards'); END;

CREATE TRIGGER metadata_decision_post_media_immutable BEFORE UPDATE ON metadata_decision_post_media
BEGIN SELECT RAISE(ABORT,'metadata post association provenance is immutable'); END;

CREATE TRIGGER post_media_backfill_immutable BEFORE UPDATE ON post_media_backfills
BEGIN SELECT RAISE(ABORT,'post media backfill receipts are immutable'); END;

CREATE TRIGGER post_media_backfill_scope BEFORE INSERT ON post_media_backfills
WHEN NOT EXISTS(SELECT 1 FROM source_posts WHERE uuid=NEW.post_uuid AND revision=NEW.post_revision
 AND (state='active' OR NEW.selected=0))
BEGIN SELECT RAISE(ABORT,'post media backfill requires the reviewed post revision'); END;

CREATE TRIGGER post_media_backfill_decision_immutable BEFORE UPDATE ON post_media_backfill_decisions
BEGIN SELECT RAISE(ABORT,'post media backfill choices are immutable'); END;

CREATE TRIGGER post_media_backfill_decision_scope BEFORE INSERT ON post_media_backfill_decisions
WHEN NOT EXISTS(SELECT 1 FROM post_media_backfills b JOIN post_media_decisions d ON d.uuid=NEW.decision_uuid
 WHERE b.uuid=NEW.backfill_uuid AND d.post_uuid=b.post_uuid AND d.origin='migration' AND d.state='linked'
 AND d.post_revision>b.post_revision AND d.post_revision<=b.post_revision+b.selected)
BEGIN SELECT RAISE(ABORT,'post media backfill choice requires its matching migration decision'); END;

CREATE TRIGGER post_media_decision_evidence_immutable BEFORE UPDATE ON post_media_decision_evidence
BEGIN SELECT RAISE(ABORT,'post media matching evidence is immutable'); END;

CREATE TRIGGER enrichment_rebinding_immutable BEFORE UPDATE ON enrichment_rebindings
BEGIN SELECT RAISE(ABORT,'enrichment collection review receipts are immutable'); END;

CREATE TRIGGER enrichment_rebinding_target_immutable BEFORE UPDATE ON enrichment_rebinding_targets
BEGIN SELECT RAISE(ABORT,'enrichment collection review targets are immutable'); END;

CREATE TRIGGER enrichment_rebinding_target_scope BEFORE INSERT ON enrichment_rebinding_targets
WHEN NOT EXISTS (
 SELECT 1 FROM enrichment_rebindings r
 JOIN enrichment_activation_targets a ON a.activation_uuid=r.activation_uuid AND a.target_uuid=NEW.target_uuid
 JOIN enrichment_target_history old ON old.target_uuid=NEW.target_uuid AND old.revision=NEW.previous_revision
 JOIN enrichment_target_history held ON held.target_uuid=NEW.target_uuid AND held.revision=NEW.held_revision
 WHERE r.uuid=NEW.rebinding_uuid AND r.activation_uuid=NEW.activation_uuid
 AND a.previous_revision=NEW.held_revision AND a.released_target_uuid!=a.target_uuid
 AND old.state='pending' AND old.completion_uuid IS NULL AND held.state='held' AND held.completion_uuid IS NULL
 AND held.reason='collection_rebind' AND held.priority=old.priority AND held.not_before=old.not_before
 AND held.recorded_at=r.created_at
 AND NOT EXISTS(SELECT 1 FROM enrichment_job_targets j WHERE j.target_uuid=NEW.target_uuid AND j.target_revision<=NEW.previous_revision)
)
BEGIN SELECT RAISE(ABORT,'invalid enrichment collection review history'); END;

CREATE TRIGGER discovery_scope_review_immutable BEFORE UPDATE ON discovery_scope_reviews
BEGIN SELECT RAISE(ABORT,'discovery collection reviews are immutable'); END;

CREATE TRIGGER discovery_scope_review_scope BEFORE INSERT ON discovery_scope_reviews
WHEN NOT EXISTS(SELECT 1 FROM discovery_effective_listings d
 JOIN source_collections c ON c.uuid=d.collection_uuid AND c.revision=NEW.collection_revision
 JOIN source_collection_revisions r ON r.collection_uuid=c.uuid AND r.revision=c.revision
 WHERE d.uuid=NEW.listing_uuid AND d.collection_uuid=NEW.collection_uuid AND r.state='active'
 AND r.root_uuid IS NEW.root_uuid AND d.collection_revision<NEW.collection_revision
 AND d.digest=json_extract(NEW.plan,'$.input.expected_definition_sha256')
 AND NEW.previous_uuid IS (SELECT p.uuid FROM discovery_scope_reviews p WHERE p.listing_uuid=d.uuid ORDER BY p.id DESC LIMIT 1)
 AND NOT EXISTS(SELECT 1 FROM discovery_listing_jobs j WHERE j.listing_uuid=d.uuid)
 AND NOT EXISTS(SELECT 1 FROM discovery_detail_jobs j JOIN discovery_match_targets t ON t.uuid=j.target_uuid WHERE t.listing_uuid=d.uuid)
 AND NOT EXISTS(SELECT 1 FROM discovery_listing_recoveries x WHERE x.previous_listing_uuid=d.uuid))
BEGIN SELECT RAISE(ABORT,'discovery collection review requires an unstarted current search'); END;

CREATE TRIGGER discovery_listing_job_scope BEFORE INSERT ON discovery_listing_jobs
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs j JOIN discovery_effective_listings d ON d.uuid=NEW.listing_uuid
 WHERE j.uuid=NEW.job_uuid AND j.kind='account.list_page' AND j.state='queued' AND j.fence=0
 AND json_extract(j.arguments,'$.version')=1 AND json_extract(j.arguments,'$.listing_uuid')=d.uuid
 AND json_extract(j.arguments,'$.generation')=NEW.generation
 AND json_extract(j.arguments,'$.page_ordinal')=NEW.page_ordinal
 AND json_extract(j.arguments,'$.definition_sha256')=d.digest AND json_extract(j.arguments,'$.collection_uuid')=d.collection_uuid)
BEGIN SELECT RAISE(ABORT,'discovery job does not match its listing'); END;

CREATE TRIGGER discovery_detail_job_scope BEFORE INSERT ON discovery_detail_jobs
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs j JOIN discovery_match_targets t ON t.uuid=NEW.target_uuid
 JOIN discovery_match_candidates c ON c.id=NEW.candidate_sequence AND c.target_uuid=t.uuid
 JOIN discovery_match_evidence e ON e.target_uuid=t.uuid AND e.page_ordinal=c.best_page AND e.namespace=c.namespace AND e.value=c.value
 JOIN discovery_pages p ON p.listing_uuid=t.listing_uuid AND p.ordinal=c.best_page
 JOIN discovery_effective_listings d ON d.uuid=t.listing_uuid
 WHERE j.uuid=NEW.job_uuid AND j.kind='post.verify_candidate' AND j.state='queued' AND j.fence=0
 AND t.revision=NEW.target_revision AND e.needs_detail=1
 AND json_extract(j.arguments,'$.version')=1 AND json_extract(j.arguments,'$.generation')=NEW.generation
 AND json_extract(j.arguments,'$.target_uuid')=t.uuid AND json_extract(j.arguments,'$.target_revision')=t.revision
 AND json_extract(j.arguments,'$.source_sha256')=t.source_sha256 AND json_extract(j.arguments,'$.post_uuid')=t.post_uuid
 AND json_extract(j.arguments,'$.post_revision')=t.post_revision AND json_extract(j.arguments,'$.candidate_sequence')=c.id
 AND json_extract(j.arguments,'$.post_namespace')=c.namespace AND json_extract(j.arguments,'$.post_value')=c.value
 AND json_extract(j.arguments,'$.url')=e.url AND json_extract(j.arguments,'$.listing_uuid')=t.listing_uuid
 AND json_extract(j.arguments,'$.definition_sha256')=d.digest AND json_extract(j.arguments,'$.page_ordinal')=p.ordinal
 AND json_extract(j.arguments,'$.page_sha256')=p.digest AND json_extract(j.arguments,'$.collection_uuid')=d.collection_uuid
 AND json_extract(j.arguments,'$.collection_revision')=d.collection_revision AND json_extract(j.arguments,'$.root_uuid') IS d.root_uuid)
BEGIN SELECT RAISE(ABORT,'discovery detail job does not match its candidate'); END;

CREATE TRIGGER discovery_listing_recovery_scope BEFORE INSERT ON discovery_listing_recoveries
WHEN NOT EXISTS(SELECT 1 FROM discovery_listings n JOIN discovery_effective_listings p ON p.uuid=NEW.previous_listing_uuid
 JOIN discovery_listing_legacy nl ON nl.listing_uuid=n.uuid
 JOIN discovery_listing_legacy pl ON pl.listing_uuid=p.uuid
 WHERE n.uuid=NEW.listing_uuid AND p.digest=NEW.previous_sha256
 AND n.account_uuid=p.account_uuid AND n.collection_uuid=p.collection_uuid
 AND nl.snapshot_uuid=pl.snapshot_uuid AND nl.account_ordinal=pl.account_ordinal
 AND json_extract(n.definition,'$.recovery_of.listing_uuid')=p.uuid
 AND json_extract(n.definition,'$.recovery_of.sha256')=p.digest
 AND json_type(p.definition,'$.recovery_of') IS NULL
 AND (json_extract(p.definition,'$.historical_pages')>0 OR json_type(p.definition,'$.initial_cursor')='object')
 AND json_extract(n.definition,'$.historical_pages')=0 AND json_type(n.definition,'$.initial_cursor')='null'
 AND NOT EXISTS(SELECT 1 FROM discovery_listing_jobs b JOIN archive_jobs j ON j.uuid=b.job_uuid
  WHERE b.listing_uuid=p.uuid AND j.state IN ('queued','running')))
BEGIN SELECT RAISE(ABORT,'discovery recovery requires its original quiescent search'); END;

CREATE TRIGGER attachment_selection_review_immutable BEFORE UPDATE ON attachment_selection_reviews
BEGIN SELECT RAISE(ABORT,'source-list review receipts are immutable'); END;

CREATE TRIGGER attachment_selection_review_scope BEFORE INSERT ON attachment_selection_reviews
WHEN NOT EXISTS(SELECT 1 FROM post_attachment_decisions d
 JOIN post_attachment_selections h ON h.post_uuid=d.post_uuid AND h.decision_uuid=d.uuid
 JOIN source_posts p ON p.uuid=d.post_uuid AND p.state='active'
 WHERE d.uuid=NEW.decision_uuid AND d.post_uuid=NEW.post_uuid AND d.origin='review'
 AND p.revision=d.revision
 AND json_extract(NEW.request_json,'$.request_uuid') IS NEW.request_uuid
 AND json_extract(NEW.request_json,'$.post_uuid') IS d.post_uuid
 AND json_extract(NEW.request_json,'$.post_revision') IS d.revision-1
 AND json_extract(NEW.request_json,'$.mode') IS d.mode
 AND coalesce(json_extract(NEW.request_json,'$.reason'),'') IS d.reason
 AND json_extract(NEW.request_json,'$.capture_uuid') IS d.capture_uuid)
BEGIN SELECT RAISE(ABORT,'source-list review is outside its decision scope'); END;

CREATE TRIGGER gallery_association_review_immutable BEFORE UPDATE ON gallery_association_reviews
BEGIN SELECT RAISE(ABORT,'gallery association review receipts are immutable'); END;

CREATE TRIGGER gallery_association_review_scope BEFORE INSERT ON gallery_association_reviews
WHEN NOT EXISTS(SELECT 1 FROM post_gallery_decisions d
 JOIN post_gallery_links h ON h.post_uuid=d.post_uuid AND h.decision_uuid=d.uuid
 JOIN source_posts p ON p.uuid=d.post_uuid AND p.state='active'
 WHERE d.uuid=NEW.decision_uuid AND d.post_uuid=NEW.post_uuid AND d.origin='review'
 AND d.selection_uuid IS NULL AND p.revision=d.revision
 AND json_extract(NEW.request_json,'$.request_uuid') IS NEW.request_uuid
 AND json_extract(NEW.request_json,'$.post_uuid') IS d.post_uuid
 AND json_extract(NEW.request_json,'$.post_revision') IS d.revision-1
 AND json_extract(NEW.request_json,'$.state') IS d.state
 AND coalesce(json_extract(NEW.request_json,'$.reason'),'') IS d.reason
 AND json_extract(NEW.request_json,'$.gallery_uuid') IS d.gallery_uuid
 AND ((d.state='disabled' AND json_extract(NEW.request_json,'$.gallery_revision') IS NULL)
 OR EXISTS(SELECT 1 FROM archive_entities a WHERE a.uuid=d.gallery_uuid AND a.kind='gallery'
 AND a.state='active' AND a.revision=json_extract(NEW.request_json,'$.gallery_revision'))))
BEGIN SELECT RAISE(ABORT,'gallery association review is outside its decision scope'); END;

CREATE TRIGGER attachment_media_review_immutable BEFORE UPDATE ON attachment_media_reviews
BEGIN SELECT RAISE(ABORT,'attachment media review receipts are immutable'); END;

CREATE TRIGGER attachment_media_review_scope BEFORE INSERT ON attachment_media_reviews
WHEN NOT EXISTS(SELECT 1 FROM attachment_media_decisions d
 JOIN attachment_media_links h ON h.attachment_uuid=d.attachment_uuid AND h.decision_uuid=d.uuid
 JOIN source_attachments a ON a.uuid=d.attachment_uuid AND a.post_uuid=NEW.post_uuid
 JOIN source_posts p ON p.uuid=a.post_uuid AND p.state='active'
 WHERE d.uuid=NEW.decision_uuid AND d.attachment_uuid=NEW.attachment_uuid AND d.origin='review'
 AND a.revision=d.revision
 AND json_extract(NEW.request_json,'$.request_uuid') IS NEW.request_uuid
 AND json_extract(NEW.request_json,'$.post_uuid') IS p.uuid
 AND json_extract(NEW.request_json,'$.post_revision') IS p.revision-1
 AND json_extract(NEW.request_json,'$.attachment_uuid') IS d.attachment_uuid
 AND json_extract(NEW.request_json,'$.attachment_revision') IS d.revision-1
 AND json_extract(NEW.request_json,'$.state') IS d.state
 AND coalesce(json_extract(NEW.request_json,'$.reason'),'') IS d.reason
 AND json_extract(NEW.request_json,'$.media_uuid') IS d.media_uuid
 AND ((d.state!='linked' AND json_extract(NEW.request_json,'$.media_revision') IS NULL)
 OR EXISTS(SELECT 1 FROM archive_entities m WHERE m.uuid=d.media_uuid AND m.kind IN ('scene','image')
 AND m.state='active' AND m.revision=json_extract(NEW.request_json,'$.media_revision'))))
BEGIN SELECT RAISE(ABORT,'attachment media review is outside its decision scope'); END;

CREATE TRIGGER ingest_receipt_scope BEFORE INSERT ON ingest_receipts
BEGIN
 SELECT RAISE(ABORT,'ingestion receipt root is outside its credential scope') WHERE NOT EXISTS
  (SELECT 1 FROM ingest_credential_scopes WHERE credential_uuid=NEW.credential_uuid
   AND collection_uuid=NEW.collection_uuid AND root_uuid IS NEW.root_uuid)
  AND NOT EXISTS(SELECT 1 FROM ingest_credential_roots WHERE credential_uuid=NEW.credential_uuid AND root_uuid=NEW.root_uuid);
 SELECT RAISE(ABORT,'ingestion receipt root differs from its collection revision') WHERE NEW.root_uuid IS NOT
  (SELECT root_uuid FROM source_collection_revisions WHERE collection_uuid=NEW.collection_uuid AND revision=NEW.collection_revision);
 SELECT RAISE(ABORT,'ingestion receipt requires capture provenance') WHERE NEW.capture_uuid IS NOT NULL AND NOT EXISTS
  (SELECT 1 FROM source_collection_captures WHERE capture_uuid=NEW.capture_uuid AND collection_uuid=NEW.collection_uuid AND collection_revision=NEW.collection_revision);
 SELECT RAISE(ABORT,'file ingestion receipt requires media verification work') WHERE NEW.job_uuid IS NOT NULL AND NOT EXISTS
  (SELECT 1 FROM archive_jobs WHERE uuid=NEW.job_uuid AND kind='media.verify');
END;

CREATE TRIGGER ingest_receipt_immutable BEFORE UPDATE ON ingest_receipts
BEGIN SELECT RAISE(ABORT,'ingestion receipts are immutable'); END;

CREATE TRIGGER ingest_scope_receipts BEFORE DELETE ON ingest_credential_scopes
WHEN EXISTS(SELECT 1 FROM ingest_receipts WHERE credential_uuid=OLD.credential_uuid
 AND collection_uuid=OLD.collection_uuid AND root_uuid IS OLD.root_uuid)
BEGIN SELECT RAISE(ABORT,'ingestion scope has retained receipts'); END;

CREATE TRIGGER ingest_root_receipts BEFORE DELETE ON ingest_credential_roots
WHEN EXISTS(SELECT 1 FROM ingest_receipts WHERE credential_uuid=OLD.credential_uuid AND root_uuid=OLD.root_uuid)
BEGIN SELECT RAISE(ABORT,'ingestion root grant has retained receipts'); END;

CREATE TRIGGER attachment_download_immutable BEFORE UPDATE ON source_attachment_downloads
BEGIN SELECT RAISE(ABORT,'attachment download reports are immutable'); END;

CREATE TRIGGER attachment_download_scope BEFORE INSERT ON source_attachment_downloads
BEGIN
 SELECT RAISE(ABORT,'attachment download requires its original capture and owned run attempt') WHERE NOT EXISTS(
  SELECT 1 FROM ingest_receipts c JOIN source_runs r ON r.uuid=NEW.run_uuid AND r.operation='download'
  JOIN source_run_attempts a ON a.run_uuid=r.uuid AND a.fence=NEW.fence
  JOIN source_capture_attachment_manifests m ON m.capture_uuid=c.capture_uuid
  JOIN source_attachment_entries e ON e.manifest_uuid=m.manifest_uuid AND e.attachment_uuid=NEW.attachment_uuid
  WHERE c.producer_uuid=NEW.producer_uuid AND c.event_uuid=NEW.capture_event_uuid AND c.kind='source.capture'
  AND c.run_uuid=r.uuid AND c.collection_uuid=r.collection_uuid AND c.collection_revision=r.collection_revision
  AND c.root_uuid=r.root_uuid AND a.producer_uuid=NEW.producer_uuid AND a.owner_uuid=NEW.owner_uuid);
 SELECT RAISE(ABORT,'attachment download transfer identity is immutable') WHERE EXISTS(
  SELECT 1 FROM source_attachment_downloads d WHERE d.producer_uuid=NEW.producer_uuid
  AND d.capture_event_uuid=NEW.capture_event_uuid AND d.attachment_uuid=NEW.attachment_uuid
  AND (d.run_uuid!=NEW.run_uuid OR d.fence!=NEW.fence OR d.owner_uuid!=NEW.owner_uuid OR d.transfer_sequence!=NEW.transfer_sequence));
 SELECT RAISE(ABORT,'attachment download sequence belongs to another transfer') WHERE EXISTS(
  SELECT 1 FROM source_attachment_downloads d WHERE d.producer_uuid=NEW.producer_uuid
  AND d.run_uuid=NEW.run_uuid AND d.fence=NEW.fence AND d.transfer_sequence=NEW.transfer_sequence
  AND (d.capture_event_uuid!=NEW.capture_event_uuid OR d.attachment_uuid!=NEW.attachment_uuid));
 SELECT RAISE(ABORT,'attachment download event belongs to another receipt kind') WHERE EXISTS(
  SELECT 1 FROM ingest_receipts r WHERE r.producer_uuid=NEW.producer_uuid AND r.event_uuid=NEW.event_uuid AND r.kind!='attachment.download');
 SELECT RAISE(ABORT,'downloaded report requires the exact file verification receipt') WHERE NEW.file_event_uuid IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM ingest_receipts f JOIN ingest_receipts c ON c.producer_uuid=NEW.producer_uuid AND c.event_uuid=NEW.capture_event_uuid
  JOIN archive_jobs j ON j.uuid=f.job_uuid AND j.kind='media.verify'
  WHERE f.producer_uuid=NEW.producer_uuid AND f.event_uuid=NEW.file_event_uuid AND f.kind='file.completed'
  AND f.run_uuid=NEW.run_uuid AND f.collection_uuid=c.collection_uuid AND f.collection_revision=c.collection_revision
  AND f.root_uuid=c.root_uuid AND f.capture_uuid=c.capture_uuid AND f.post_uuid=c.post_uuid
  AND json_extract(j.arguments,'$.publication.source.capture_uuid')=c.capture_uuid
  AND json_extract(j.arguments,'$.publication.source.attachment_uuid')=NEW.attachment_uuid);
END;

CREATE TRIGGER attachment_download_receipt BEFORE INSERT ON ingest_receipts
WHEN NEW.kind='attachment.download'
BEGIN
 SELECT RAISE(ABORT,'attachment download receipt requires its atomic report') WHERE NOT EXISTS(
  SELECT 1 FROM source_attachment_downloads d JOIN ingest_receipts c ON c.producer_uuid=d.producer_uuid AND c.event_uuid=d.capture_event_uuid
  WHERE d.producer_uuid=NEW.producer_uuid AND d.event_uuid=NEW.event_uuid AND d.run_uuid=NEW.run_uuid
  AND c.collection_uuid=NEW.collection_uuid AND c.collection_revision=NEW.collection_revision
  AND c.root_uuid=NEW.root_uuid AND c.post_uuid=NEW.post_uuid AND c.capture_uuid=NEW.capture_uuid);
END;

CREATE TRIGGER source_post_consolidation_scope BEFORE INSERT ON source_post_consolidations
BEGIN
 SELECT RAISE(ABORT,'post consolidation requires its managed write context') WHERE NOT EXISTS(
  SELECT 1 FROM source_post_consolidation_context w WHERE w.request_uuid=NEW.uuid
  AND w.source_uuid=NEW.source_uuid AND w.destination_uuid=NEW.destination_uuid);
 SELECT RAISE(ABORT,'post consolidation requires current active roots') WHERE NOT EXISTS(
  SELECT 1 FROM source_posts s JOIN source_post_identities si ON si.post_uuid=s.uuid
  JOIN source_posts d JOIN source_post_identities di ON di.post_uuid=d.uuid
  WHERE s.uuid=NEW.source_uuid AND d.uuid=NEW.destination_uuid
  AND si.canonical_uuid=s.uuid AND di.canonical_uuid=d.uuid AND s.state='active' AND d.state='active'
  AND s.revision=NEW.source_revision AND d.revision=NEW.destination_revision);
 SELECT RAISE(ABORT,'post consolidation member scope changed') WHERE NEW.member_count != (
  SELECT count(*) FROM (SELECT 1 FROM source_post_identities WHERE canonical_uuid IN (NEW.source_uuid,NEW.destination_uuid) LIMIT 257))
  OR EXISTS(SELECT 1 FROM source_post_identities i JOIN source_posts p ON p.uuid=i.post_uuid
   WHERE i.canonical_uuid IN (NEW.source_uuid,NEW.destination_uuid) AND p.state!='active');
 -- A shared URL, caption or media item cannot override different qualified
 -- upstream identities. Legacy catalog keys remain original aliases.
 SELECT RAISE(ABORT,'post consolidation has conflicting upstream identifiers') WHERE 1 < (
  SELECT count(*) FROM (SELECT DISTINCT i.namespace,i.value FROM source_post_identities p
  JOIN source_post_identifiers i ON i.post_uuid=p.post_uuid
  WHERE p.canonical_uuid IN (NEW.source_uuid,NEW.destination_uuid) AND substr(i.namespace,1,7)!='legacy:' LIMIT 2));
END;

CREATE TRIGGER source_post_consolidation_publish AFTER INSERT ON source_post_consolidations
BEGIN
 UPDATE source_posts SET revision=revision+1 WHERE uuid IN (
  SELECT post_uuid FROM source_post_identities WHERE canonical_uuid IN (NEW.source_uuid,NEW.destination_uuid));
 UPDATE source_post_identities SET canonical_uuid=NEW.destination_uuid WHERE canonical_uuid=NEW.source_uuid;
END;

CREATE TRIGGER source_post_consolidation_immutable BEFORE UPDATE ON source_post_consolidations
BEGIN SELECT RAISE(ABORT,'post consolidation history is immutable'); END;

CREATE TRIGGER source_post_root_initial BEFORE INSERT ON source_post_identities
WHEN NEW.canonical_uuid!=NEW.post_uuid
BEGIN SELECT RAISE(ABORT,'new posts must begin as independent identities'); END;

CREATE TRIGGER source_post_root_created AFTER INSERT ON source_posts
BEGIN INSERT INTO source_post_identities(post_uuid,canonical_uuid) VALUES(NEW.uuid,NEW.uuid); END;

CREATE TRIGGER source_post_root_update BEFORE UPDATE ON source_post_identities
BEGIN
 SELECT RAISE(ABORT,'source post identity owners are immutable') WHERE NEW.post_uuid!=OLD.post_uuid;
 SELECT RAISE(ABORT,'canonical posts change only through reviewed consolidation') WHERE NEW.canonical_uuid!=OLD.canonical_uuid AND NOT EXISTS(
  SELECT 1 FROM source_post_consolidation_context w
  JOIN source_post_consolidations c ON c.uuid=w.request_uuid AND c.source_uuid=w.source_uuid AND c.destination_uuid=w.destination_uuid
  JOIN source_posts s ON s.uuid=w.source_uuid AND s.state='active' AND s.revision=c.source_revision+1
  JOIN source_posts d ON d.uuid=w.destination_uuid AND d.state='active' AND d.revision=c.destination_revision+1
  JOIN source_post_identities di ON di.post_uuid=d.uuid AND di.canonical_uuid=d.uuid
  WHERE w.source_uuid=OLD.canonical_uuid AND w.destination_uuid=NEW.canonical_uuid);
END;

CREATE TRIGGER source_post_uuid_immutable BEFORE UPDATE OF uuid ON source_posts
WHEN OLD.uuid!=NEW.uuid
BEGIN SELECT RAISE(ABORT,'source post UUIDs are immutable'); END;

CREATE TRIGGER source_post_group_identifier BEFORE INSERT ON source_post_identifiers
WHEN substr(NEW.namespace,1,7)!='legacy:'
 AND EXISTS(SELECT 1 FROM source_post_identities p JOIN source_post_identities m ON m.canonical_uuid=p.canonical_uuid
  WHERE p.post_uuid=NEW.post_uuid AND m.post_uuid!=p.post_uuid)
 AND EXISTS(SELECT 1 FROM source_post_identities p JOIN source_post_identities m ON m.canonical_uuid=p.canonical_uuid
  JOIN source_post_identifiers i ON i.post_uuid=m.post_uuid WHERE p.post_uuid=NEW.post_uuid
  AND substr(i.namespace,1,7)!='legacy:' AND (i.namespace!=NEW.namespace OR i.value!=NEW.value))
BEGIN SELECT RAISE(ABORT,'consolidated post cannot acquire a contradictory upstream identity'); END;

CREATE TRIGGER source_post_group_forgotten AFTER UPDATE OF state ON source_posts
WHEN NEW.state='forgotten' AND OLD.state!='forgotten'
BEGIN
 UPDATE source_posts SET state='forgotten',revision=revision+1
 WHERE uuid IN (SELECT m.post_uuid FROM source_post_identities p
  JOIN source_post_identities m ON m.canonical_uuid=p.canonical_uuid WHERE p.post_uuid=NEW.uuid)
 AND state!='forgotten';
END;

CREATE TRIGGER post_attachment_decision_immutable BEFORE UPDATE ON post_attachment_decisions
BEGIN SELECT RAISE(ABORT, 'attachment selection decisions are immutable'); END;

CREATE TRIGGER post_attachment_decision_manifest_immutable BEFORE UPDATE ON post_attachment_decision_manifests
BEGIN SELECT RAISE(ABORT, 'attachment selection evidence is immutable'); END;

CREATE TRIGGER post_attachment_decision_active_post BEFORE INSERT ON post_attachment_decisions
WHEN EXISTS (SELECT 1 FROM source_posts WHERE uuid = NEW.post_uuid AND state != 'active')
BEGIN SELECT RAISE(ABORT, 'forgotten source post cannot select attachments'); END;

CREATE TRIGGER post_attachment_decision_capture_scope BEFORE INSERT ON post_attachment_decisions
WHEN NEW.capture_uuid IS NOT NULL AND NOT EXISTS (
 SELECT 1 FROM source_captures c JOIN source_post_identities owner ON owner.post_uuid=c.post_uuid
 JOIN source_post_identities selected ON selected.post_uuid=NEW.post_uuid AND selected.canonical_uuid=owner.canonical_uuid
 WHERE c.uuid=NEW.capture_uuid)
BEGIN SELECT RAISE(ABORT,'attachment selection capture belongs to another post identity'); END;

CREATE TRIGGER post_attachment_decision_manifest_scope BEFORE INSERT ON post_attachment_decision_manifests
WHEN NOT EXISTS (
 SELECT 1 FROM source_attachment_manifests m JOIN source_post_identities owner ON owner.post_uuid=m.post_uuid
 JOIN source_post_identities selected ON selected.post_uuid=NEW.post_uuid AND selected.canonical_uuid=owner.canonical_uuid
 WHERE m.uuid=NEW.manifest_uuid)
BEGIN SELECT RAISE(ABORT,'attachment selection evidence belongs to another post identity'); END;

CREATE TRIGGER post_media_consolidation_edge_scope BEFORE INSERT ON post_media_consolidation_edges
WHEN NOT EXISTS (
 SELECT 1 FROM post_media_decisions old
 JOIN post_media_links head ON head.decision_uuid=old.uuid
 JOIN post_media_decisions current ON current.uuid=NEW.decision_uuid
 JOIN source_posts root ON root.uuid=current.post_uuid AND root.state='active' AND root.revision=current.post_revision
 JOIN source_post_identities identity ON identity.post_uuid=root.uuid AND identity.canonical_uuid=root.uuid
 JOIN source_post_consolidations c ON c.uuid=NEW.consolidation_uuid AND c.destination_uuid=root.uuid
 WHERE old.uuid=NEW.previous_uuid AND old.post_uuid!=current.post_uuid
 AND c.sequence=(SELECT max(sequence) FROM source_post_consolidations WHERE destination_uuid=root.uuid)
 AND current.post_revision>c.destination_revision
 AND current.post_uuid IN (WITH RECURSIVE ancestors(uuid,depth) AS (
  SELECT old.post_uuid,0 UNION ALL
  SELECT h.destination_uuid,a.depth+1 FROM ancestors a JOIN source_post_consolidations h ON h.source_uuid=a.uuid
  WHERE h.sequence<=c.sequence AND a.depth<256
 ) SELECT uuid FROM ancestors)
 AND current.media_uuid IN (WITH RECURSIVE targets(uuid,depth) AS (
  SELECT old.media_uuid,0 UNION ALL
  SELECT e.redirect_to,t.depth+1 FROM targets t JOIN archive_entities e ON e.uuid=t.uuid
  WHERE e.state='redirected' AND t.depth<127
 ) SELECT uuid FROM targets))
BEGIN SELECT RAISE(ABORT,'post media consolidation requires current related choices and its reviewed identity'); END;

CREATE TRIGGER post_media_consolidation_edge_immutable BEFORE UPDATE ON post_media_consolidation_edges
BEGIN SELECT RAISE(ABORT,'post media consolidation evidence is immutable'); END;

CREATE TRIGGER post_media_supersession_scope BEFORE INSERT ON post_media_supersessions
WHEN NOT EXISTS(SELECT 1 FROM post_media_decisions old JOIN post_media_decisions current ON current.uuid=NEW.decision_uuid
 WHERE old.uuid=NEW.previous_uuid AND (
  (old.post_uuid=current.post_uuid AND old.post_revision<current.post_revision)
  OR (old.post_uuid!=current.post_uuid AND EXISTS(SELECT 1 FROM post_media_consolidation_edges e
   WHERE e.previous_uuid=NEW.previous_uuid AND e.decision_uuid=NEW.decision_uuid))))
BEGIN SELECT RAISE(ABORT,'post media replacement requires a later decision or reviewed post consolidation'); END;

CREATE TRIGGER post_media_decision_scope BEFORE INSERT ON post_media_decisions
BEGIN
 SELECT RAISE(ABORT,'post media requires an active post and its current revision')
 WHERE NOT EXISTS(SELECT 1 FROM source_posts WHERE uuid=NEW.post_uuid AND state='active' AND revision=NEW.post_revision);
 SELECT RAISE(ABORT,'post media requires a current scene or image')
 WHERE NOT EXISTS(SELECT 1 FROM archive_entities media WHERE media.uuid=NEW.media_uuid
  AND media.kind IN ('scene','image') AND media.revision=NEW.media_revision
  AND (media.state='active' OR (media.state='deleted'
   AND EXISTS(SELECT 1 FROM source_post_identities root WHERE root.post_uuid=NEW.post_uuid AND root.canonical_uuid=root.post_uuid)
   AND EXISTS(SELECT 1 FROM source_post_consolidations WHERE destination_uuid=NEW.post_uuid AND destination_revision<NEW.post_revision)
   AND EXISTS(WITH RECURSIVE aliases(uuid,depth) AS (
    SELECT NEW.media_uuid,0 UNION ALL SELECT a.uuid,r.depth+1 FROM aliases r JOIN archive_entities a ON a.redirect_to=r.uuid WHERE r.depth<127
   ) SELECT 1 FROM source_post_identities owner JOIN post_media_links h ON h.post_uuid=owner.post_uuid
   WHERE owner.canonical_uuid=NEW.post_uuid AND h.media_uuid IN (SELECT uuid FROM aliases)))));
END;

CREATE TRIGGER metadata_decision_post_media_scope BEFORE INSERT ON metadata_decision_post_media
WHEN NOT EXISTS(SELECT 1 FROM metadata_field_decisions d
 JOIN source_captures c ON c.uuid=d.capture_uuid
 JOIN source_post_identities captured ON captured.post_uuid=c.post_uuid
 JOIN post_media_decisions p ON p.uuid=NEW.post_media_decision_uuid AND p.state='linked'
 JOIN source_post_identities selected ON selected.post_uuid=p.post_uuid AND selected.canonical_uuid=captured.canonical_uuid
 WHERE d.uuid=NEW.decision_uuid AND d.origin='source'
 AND d.entity_uuid IN (WITH RECURSIVE targets(uuid,depth) AS (
 SELECT p.media_uuid,0 UNION ALL SELECT a.redirect_to,t.depth+1 FROM targets t JOIN archive_entities a ON a.uuid=t.uuid
 WHERE a.state='redirected' AND t.depth<127
 ) SELECT uuid FROM targets))
BEGIN SELECT RAISE(ABORT,'metadata post association requires matching source provenance'); END;

CREATE TRIGGER post_media_decision_evidence_scope BEFORE INSERT ON post_media_decision_evidence
WHEN NOT EXISTS(SELECT 1 FROM post_media_decisions d
 JOIN post_media_backfill_decisions b ON b.decision_uuid=d.uuid
 JOIN source_post_identities chosen ON chosen.post_uuid=d.post_uuid
 JOIN source_media_evidence e ON e.uuid=NEW.evidence_uuid
 JOIN source_post_identities original ON original.post_uuid=e.post_uuid AND original.canonical_uuid=chosen.canonical_uuid
 JOIN source_post_file_evidence p ON p.uuid=NEW.post_file_uuid AND p.post_uuid=e.post_uuid
 JOIN source_file_matches f ON f.uuid=NEW.match_uuid AND f.observation_uuid=p.observation_uuid
 WHERE d.uuid=NEW.decision_uuid AND d.origin='migration' AND d.state='linked'
 AND e.attachment_uuid IS NULL AND e.basis='legacy' AND p.origin='migration' AND p.basis='catalog-appearance'
 AND p.uuid=json_extract(e.details,'$.source_post_file_evidence_uuid')
 AND f.uuid=json_extract(e.details,'$.source_file_match_uuid') AND f.file_uuid=e.file_uuid)
BEGIN SELECT RAISE(ABORT,'post media matching requires its original file chain and current post identity'); END;

CREATE TRIGGER post_consolidation_review_immutable BEFORE UPDATE ON post_consolidation_reviews
BEGIN SELECT RAISE(ABORT,'post merge review receipts are immutable'); END;

CREATE TRIGGER post_consolidation_review_member_immutable BEFORE UPDATE ON post_consolidation_review_members
BEGIN SELECT RAISE(ABORT,'post merge review members are immutable'); END;

CREATE TRIGGER post_consolidation_review_media_immutable BEFORE UPDATE ON post_consolidation_review_media
BEGIN SELECT RAISE(ABORT,'post merge review media decisions are immutable'); END;

CREATE TRIGGER post_consolidation_review_attachment_immutable BEFORE UPDATE ON post_consolidation_review_attachments
BEGIN SELECT RAISE(ABORT,'post merge review attachment decisions are immutable'); END;

CREATE TRIGGER post_consolidation_review_scope BEFORE INSERT ON post_consolidation_reviews
WHEN NOT EXISTS(SELECT 1 FROM source_post_consolidations c
 WHERE c.uuid=NEW.request_uuid AND c.origin='review'
 AND json_extract(NEW.request_json,'$.request_uuid') IS c.uuid
 AND json_extract(NEW.request_json,'$.source_uuid') IS c.source_uuid
 AND json_extract(NEW.request_json,'$.destination_uuid') IS c.destination_uuid
 AND json_extract(NEW.request_json,'$.digest') IS c.review_signature
 AND json_extract(NEW.request_json,'$.reason') IS c.reason
 AND json_extract(NEW.result_json,'$.consolidation.uuid') IS c.uuid
 AND json_extract(NEW.result_json,'$.selection_uuid') IS NEW.selection_uuid
 AND json_extract(NEW.result_json,'$.gallery_decision_uuid') IS NEW.gallery_decision_uuid
 AND json_extract(NEW.result_json,'$.notification_job_uuid') IS NEW.notification_job_uuid
 AND (NEW.selection_uuid IS NULL OR EXISTS(SELECT 1 FROM post_attachment_decisions d
   JOIN post_attachment_selections h ON h.decision_uuid=d.uuid AND h.post_uuid=d.post_uuid
   WHERE d.uuid=NEW.selection_uuid AND d.post_uuid=c.destination_uuid AND d.origin='review' AND d.reason=c.reason))
 AND (NEW.gallery_decision_uuid IS NULL OR EXISTS(SELECT 1 FROM post_gallery_decisions d
   JOIN post_gallery_links h ON h.decision_uuid=d.uuid AND h.post_uuid=d.post_uuid
   WHERE d.uuid=NEW.gallery_decision_uuid AND d.post_uuid=c.destination_uuid
   AND d.gallery_uuid IS json_extract(NEW.result_json,'$.gallery.gallery_uuid')
   AND ((d.origin='review' AND d.reason=c.reason) OR
     (d.origin='source' AND json_extract(NEW.result_json,'$.gallery.created')=1 AND d.selection_uuid=NEW.selection_uuid))))
 AND (NEW.notification_job_uuid IS NULL OR EXISTS(SELECT 1 FROM archive_jobs j
   WHERE j.uuid=NEW.notification_job_uuid AND j.kind='post.merge_notify'
   AND json_extract(j.arguments,'$.review_uuid')=c.uuid AND json_extract(j.arguments,'$.version')=1
   AND json_extract(j.arguments,'$.resume_from_job_uuid') IS NULL)))
BEGIN SELECT RAISE(ABORT,'post merge review is outside its consolidation scope'); END;

CREATE TRIGGER post_consolidation_review_member_scope BEFORE INSERT ON post_consolidation_review_members
WHEN NOT EXISTS(SELECT 1 FROM source_post_consolidations c
 JOIN source_post_identities i ON i.post_uuid=NEW.post_uuid AND i.canonical_uuid=c.destination_uuid
 WHERE c.uuid=NEW.request_uuid AND NEW.previous_canonical_uuid IN (c.source_uuid,c.destination_uuid))
BEGIN SELECT RAISE(ABORT,'post merge member is outside the reviewed identity'); END;

CREATE TRIGGER post_consolidation_review_media_scope BEFORE INSERT ON post_consolidation_review_media
WHEN NOT EXISTS(SELECT 1 FROM source_post_consolidations c
 JOIN post_media_decisions d ON d.post_uuid=c.destination_uuid AND d.uuid=NEW.decision_uuid
 JOIN post_media_links h ON h.post_uuid=d.post_uuid AND h.decision_uuid=d.uuid
 WHERE c.uuid=NEW.request_uuid AND d.origin='review' AND d.reason=c.reason)
BEGIN SELECT RAISE(ABORT,'post merge media decision is outside its review'); END;

CREATE TRIGGER post_consolidation_review_attachment_scope BEFORE INSERT ON post_consolidation_review_attachments
WHEN NOT EXISTS(SELECT 1 FROM source_post_consolidations c
 JOIN post_consolidation_review_members m ON m.request_uuid=c.uuid
 JOIN source_attachments a ON a.post_uuid=m.post_uuid
 JOIN attachment_media_decisions d ON d.attachment_uuid=a.uuid AND d.uuid=NEW.decision_uuid
 JOIN attachment_media_links h ON h.attachment_uuid=d.attachment_uuid AND h.decision_uuid=d.uuid
 WHERE c.uuid=NEW.request_uuid AND d.origin='review' AND d.reason=c.reason)
BEGIN SELECT RAISE(ABORT,'post merge attachment decision is outside its review'); END;

CREATE TRIGGER metadata_file_edit_keep_immutable BEFORE UPDATE ON metadata_file_edit_keeps
WHEN NEW.request_uuid!=OLD.request_uuid OR NEW.entity_revision!=OLD.entity_revision
 OR NEW.history_uuid!=OLD.history_uuid OR NEW.source_field!=OLD.source_field OR NEW.match_uuid!=OLD.match_uuid
 OR NEW.selected_decision_uuid IS NOT OLD.selected_decision_uuid OR NEW.request_json!=OLD.request_json
 OR NEW.signature!=OLD.signature OR NEW.created_at!=OLD.created_at
 OR (NEW.entity_uuid!=OLD.entity_uuid AND EXISTS(SELECT 1 FROM archive_entities WHERE uuid=OLD.entity_uuid))
BEGIN SELECT RAISE(ABORT,'historical metadata keep receipts are immutable'); END;

CREATE TRIGGER metadata_file_edit_keep_request_distinct BEFORE INSERT ON metadata_file_edit_keeps
WHEN EXISTS(SELECT 1 FROM metadata_file_edit_reviews WHERE request_uuid=NEW.request_uuid)
BEGIN SELECT RAISE(ABORT,'historical metadata request already has an apply receipt'); END;

CREATE TRIGGER metadata_file_edit_apply_request_distinct BEFORE INSERT ON metadata_file_edit_reviews
WHEN EXISTS(SELECT 1 FROM metadata_file_edit_keeps WHERE request_uuid=NEW.request_uuid)
BEGIN SELECT RAISE(ABORT,'historical metadata request already has a keep receipt'); END;

CREATE TRIGGER metadata_file_edit_keep_scope BEFORE INSERT ON metadata_file_edit_keeps
WHEN NOT EXISTS(SELECT 1 FROM source_file_history_edits e
 JOIN source_file_history_locations l ON l.history_uuid=e.history_uuid
 JOIN source_file_matches m ON m.observation_uuid=l.observation_uuid
 JOIN archive_entities owner ON owner.uuid=NEW.entity_uuid AND owner.state='active' AND owner.revision=NEW.entity_revision
 JOIN archive_entities f ON f.uuid=m.file_uuid AND f.kind='file' AND f.state='active'
 JOIN files current_file ON current_file.id=f.file_id AND current_file.generation=m.generation
 WHERE e.history_uuid=NEW.history_uuid AND e.field=NEW.source_field AND m.uuid=NEW.match_uuid
 AND (SELECT decision_uuid FROM metadata_field_heads WHERE entity_uuid=owner.uuid AND field=e.target_field) IS NEW.selected_decision_uuid
 AND (EXISTS(SELECT 1 FROM scenes_files sf WHERE sf.scene_id=owner.scene_id AND sf.file_id=f.file_id)
 OR EXISTS(SELECT 1 FROM images_files imf WHERE imf.image_id=owner.image_id AND imf.file_id=f.file_id)))
BEGIN SELECT RAISE(ABORT,'historical metadata keep is outside its reviewed scope'); END;

CREATE TRIGGER file_deduplication_verified BEFORE INSERT ON file_deduplications
BEGIN
 SELECT RAISE(ABORT,'deduplication requires equal verified content') WHERE NOT EXISTS (
  SELECT 1 FROM file_content_versions k JOIN file_content_versions d ON d.content_uuid=k.content_uuid
  JOIN media_contents c ON c.uuid=k.content_uuid AND c.sha256=NEW.sha256
  WHERE k.file_uuid=NEW.kept_file_uuid AND k.generation=NEW.kept_generation
   AND d.file_uuid=NEW.removed_file_uuid AND d.generation=NEW.removed_generation);
END;

CREATE TRIGGER file_deduplication_immutable BEFORE UPDATE ON file_deduplications
WHEN NEW.uuid!=OLD.uuid OR NEW.signature!=OLD.signature OR NEW.root_uuid!=OLD.root_uuid
 OR NEW.keep_path!=OLD.keep_path OR NEW.remove_path!=OLD.remove_path
 OR NEW.kept_generation!=OLD.kept_generation OR NEW.removed_generation!=OLD.removed_generation
 OR NEW.sha256!=OLD.sha256 OR NEW.proof!=OLD.proof OR NEW.committed_at!=OLD.committed_at
 OR (NEW.kept_file_uuid!=OLD.kept_file_uuid AND EXISTS(SELECT 1 FROM archive_entities WHERE uuid=OLD.kept_file_uuid))
 OR (NEW.removed_file_uuid!=OLD.removed_file_uuid AND EXISTS(SELECT 1 FROM archive_entities WHERE uuid=OLD.removed_file_uuid))
 OR (NEW.media_uuid!=OLD.media_uuid AND EXISTS(SELECT 1 FROM archive_entities WHERE uuid=OLD.media_uuid))
BEGIN SELECT RAISE(ABORT,'file deduplication receipts are immutable'); END;

CREATE TRIGGER provider_metadata_import_scope BEFORE INSERT ON provider_metadata_imports
BEGIN
 SELECT RAISE(ABORT,'provider metadata import requires the current entity revision') WHERE NOT EXISTS (
  SELECT 1 FROM archive_entities WHERE uuid=NEW.entity_uuid AND uuid=NEW.original_entity_uuid
   AND state='active' AND kind=NEW.entity_kind AND revision=NEW.entity_revision);
END;

CREATE TRIGGER provider_metadata_import_immutable BEFORE UPDATE ON provider_metadata_imports
WHEN NEW.sequence!=OLD.sequence OR NEW.uuid!=OLD.uuid OR NEW.original_entity_uuid!=OLD.original_entity_uuid
 OR NEW.entity_kind!=OLD.entity_kind OR NEW.entity_revision!=OLD.entity_revision OR NEW.endpoint!=OLD.endpoint
 OR NEW.remote_id!=OLD.remote_id OR NEW.operation!=OLD.operation OR NEW.values_json!=OLD.values_json
 OR NEW.signature!=OLD.signature OR NEW.created_at!=OLD.created_at
 OR (NEW.entity_uuid!=OLD.entity_uuid AND EXISTS(SELECT 1 FROM archive_entities WHERE uuid=OLD.entity_uuid))
BEGIN SELECT RAISE(ABORT,'provider metadata imports are immutable'); END;

CREATE TRIGGER performer_profile_url_suppression_scope BEFORE INSERT ON performer_profile_url_suppressions
BEGIN
 SELECT RAISE(ABORT,'profile URL suppression requires a performer') WHERE NOT EXISTS (
  SELECT 1 FROM archive_entities WHERE uuid=NEW.performer_uuid AND kind='performer');
END;

CREATE TRIGGER performer_profile_url_suppression_update BEFORE UPDATE ON performer_profile_url_suppressions
BEGIN
 SELECT RAISE(ABORT,'profile URL suppressions retain their removal evidence')
 WHERE NEW.url_key!=OLD.url_key OR NEW.url!=OLD.url OR NEW.created_at!=OLD.created_at
  OR NOT EXISTS(SELECT 1 FROM archive_entities WHERE uuid=NEW.performer_uuid AND kind='performer');
END;

CREATE TRIGGER source_run_attempt_basis BEFORE INSERT ON source_run_attempts
BEGIN
 SELECT RAISE(ABORT,'invalid source attempt coverage basis')
 WHERE COALESCE(json_extract(NEW.window,'$.basis'),'') NOT IN ('','traversal')
  OR (json_extract(NEW.window,'$.basis')='traversal' AND
      (json_extract(NEW.window,'$.since') IS NOT NULL OR
       (SELECT operation FROM source_runs WHERE uuid=NEW.run_uuid)!='download'));
END;

CREATE TRIGGER source_run_attempt_pacing_origin BEFORE INSERT ON source_run_attempt_pacing
WHEN (NEW.source_origin IS NULL
 AND NEW.scope NOT IN ('service:redgifs','service:imgur')
 AND NOT EXISTS(SELECT 1 FROM source_run_pacing WHERE run_uuid=NEW.run_uuid AND scope=NEW.scope))
 OR (NEW.source_origin IS NOT NULL
 AND (typeof(NEW.source_origin)!='text' OR source_origin_v1(NEW.source_origin)!=NEW.source_origin
  OR source_scope_v1(NEW.source_origin)!=NEW.scope))
BEGIN SELECT RAISE(ABORT,'source dependency requires its canonical HTTP origin'); END;

CREATE TRIGGER source_run_attempt_pacing_origin_immutable BEFORE UPDATE OF source_origin ON source_run_attempt_pacing
WHEN NEW.source_origin IS NOT OLD.source_origin
BEGIN SELECT RAISE(ABORT,'source dependency origin is immutable'); END;

CREATE TRIGGER source_run_attempt_pacing_bind AFTER INSERT ON source_run_attempts
BEGIN
 INSERT INTO source_run_attempt_pacing(run_uuid,fence,scope,reserved)
  SELECT NEW.run_uuid,NEW.fence,scope,1 FROM source_run_pacing WHERE run_uuid=NEW.run_uuid;
 INSERT OR IGNORE INTO source_run_attempt_pacing(run_uuid,fence,scope,reserved,source_origin)
  SELECT NEW.run_uuid,NEW.fence,p.scope,1,p.source_origin FROM source_run_attempt_pacing p
  JOIN source_run_attempts a ON a.run_uuid=p.run_uuid AND a.fence=p.fence
  WHERE a.run_uuid=NEW.run_uuid AND a.fence=NEW.fence-1 AND a.window=NEW.window
   AND a.outcome IN ('retry','expired','deferred');
END;

CREATE TRIGGER catalog_nfo_compaction_guard BEFORE UPDATE OF nfo_compacted ON catalog_snapshots
WHEN NEW.nfo_compacted<OLD.nfo_compacted
 OR (NEW.nfo_compacted=1 AND (NEW.state!='received'
  OR NOT EXISTS(SELECT 1 FROM catalog_document_imports i WHERE i.snapshot_uuid=NEW.uuid AND i.state='mapped' AND i.phase='complete')
  OR EXISTS(SELECT 1 FROM catalog_document_records r WHERE r.snapshot_uuid=NEW.uuid)
  OR EXISTS(SELECT 1 FROM catalog_snapshot_records r WHERE r.snapshot_uuid=NEW.uuid AND r.source_table IN ('sidecars','sidecar_documents','sidecar_sources','sidecar_heads'))))
BEGIN SELECT RAISE(ABORT,'NFO inputs can only be discarded after a completed import'); END;

CREATE TRIGGER media_root_revision_scope BEFORE INSERT ON media_root_revisions
BEGIN
  SELECT RAISE(ABORT,'root revision is stale') WHERE NOT EXISTS(
    SELECT 1 FROM media_roots r LEFT JOIN media_root_revisions d ON d.root_uuid=r.uuid AND d.revision=r.revision
    WHERE r.uuid=NEW.root_uuid AND ((d.root_uuid IS NULL AND NEW.revision=1 AND r.revision=1)
      OR (d.root_uuid IS NOT NULL AND NEW.revision=r.revision+1))
  );
END;

CREATE TRIGGER source_collection_revision_scope BEFORE INSERT ON source_collection_revisions
BEGIN
  SELECT RAISE(ABORT,'collection revision is stale') WHERE NOT EXISTS(
    SELECT 1 FROM source_collections c LEFT JOIN source_collection_revisions d ON d.collection_uuid=c.uuid AND d.revision=c.revision
    WHERE c.uuid=NEW.collection_uuid AND ((d.collection_uuid IS NULL AND NEW.revision=1 AND c.revision=1)
      OR (d.collection_uuid IS NOT NULL AND NEW.revision=c.revision+1))
  );
END;

CREATE TRIGGER source_run_policy_upgrade_valid BEFORE INSERT ON source_run_policy_upgrades
WHEN NOT EXISTS(SELECT 1 FROM source_runs r WHERE r.uuid=NEW.run_uuid AND r.state IN ('queued','deferred')
  AND r.revision=NEW.expected_revision AND r.fence=NEW.effective_after_fence
  AND NEW.created_at_ms>=r.updated_at_ms
  AND NEW.expected_policy_sha256=coalesce((SELECT p.policy_sha256 FROM source_run_policy_upgrades p
    WHERE p.run_uuid=r.uuid ORDER BY p.expected_revision DESC LIMIT 1),r.policy_sha256))
BEGIN SELECT RAISE(ABORT,'source policy upgrade requires current inactive work'); END;

CREATE TRIGGER source_run_policy_upgrade_revision AFTER INSERT ON source_run_policy_upgrades
BEGIN
  UPDATE source_runs SET revision=revision+1,updated_at_ms=NEW.created_at_ms WHERE uuid=NEW.run_uuid;
END;

CREATE TRIGGER source_run_policy_upgrade_immutable BEFORE UPDATE ON source_run_policy_upgrades
BEGIN SELECT RAISE(ABORT,'source policy upgrades are immutable'); END;

CREATE TRIGGER source_run_policy_upgrade_retained BEFORE DELETE ON source_run_policy_upgrades
BEGIN SELECT RAISE(ABORT,'source policy upgrades are retained'); END;

CREATE TRIGGER metadata_worker_policy_valid BEFORE INSERT ON metadata_worker_policy_upgrades
WHEN NEW.expected_policy_sha256!=coalesce((SELECT policy_sha256 FROM metadata_worker_policy_upgrades
  WHERE kind=NEW.kind AND original_policy_sha256=NEW.original_policy_sha256 ORDER BY id DESC LIMIT 1),NEW.original_policy_sha256)
 OR NEW.created_at_ms<coalesce((SELECT created_at_ms FROM metadata_worker_policy_upgrades
  WHERE kind=NEW.kind AND original_policy_sha256=NEW.original_policy_sha256 ORDER BY id DESC LIMIT 1),0)
BEGIN SELECT RAISE(ABORT,'metadata worker policy changed'); END;

CREATE TRIGGER metadata_worker_policy_immutable BEFORE UPDATE ON metadata_worker_policy_upgrades
BEGIN SELECT RAISE(ABORT,'metadata worker policy approvals are immutable'); END;

CREATE TRIGGER metadata_worker_policy_retained BEFORE DELETE ON metadata_worker_policy_upgrades
BEGIN SELECT RAISE(ABORT,'metadata worker policy approvals are retained'); END;

CREATE TRIGGER metadata_worker_attempt_policy_valid BEFORE INSERT ON metadata_worker_attempt_policies
WHEN NOT EXISTS(SELECT 1 FROM archive_jobs j JOIN archive_job_attempts a ON a.job_uuid=j.uuid AND a.fence=j.fence
  WHERE j.uuid=NEW.job_uuid AND j.fence=NEW.fence AND j.state='running' AND a.outcome='running'
  AND j.kind IN ('post.enrich','account.list_page','post.verify_candidate')
  AND NEW.original_policy_sha256=CASE WHEN j.kind='account.list_page'
    THEN (SELECT json_extract(d.definition,'$.policy_sha256') FROM discovery_listings d WHERE d.uuid=json_extract(j.arguments,'$.listing_uuid'))
    ELSE json_extract(j.arguments,'$.policy_sha256') END
  AND NEW.approval_uuid IS (SELECT p.request_uuid FROM metadata_worker_policy_upgrades p
    WHERE p.kind=j.kind AND p.original_policy_sha256=NEW.original_policy_sha256 ORDER BY p.id DESC LIMIT 1)
  AND ((NEW.approval_uuid IS NULL AND NEW.policy_sha256=NEW.original_policy_sha256)
    OR EXISTS(SELECT 1 FROM metadata_worker_policy_upgrades p WHERE p.request_uuid=NEW.approval_uuid
       AND p.kind=j.kind AND p.original_policy_sha256=NEW.original_policy_sha256 AND p.policy_sha256=NEW.policy_sha256
       AND p.created_at_ms<=a.started_at_ms)))
BEGIN SELECT RAISE(ABORT,'invalid metadata worker attempt policy'); END;

CREATE TRIGGER metadata_worker_attempt_policy_immutable BEFORE UPDATE ON metadata_worker_attempt_policies
BEGIN SELECT RAISE(ABORT,'metadata worker attempts are immutable'); END;

CREATE TRIGGER metadata_worker_attempt_policy_retained BEFORE DELETE ON metadata_worker_attempt_policies
BEGIN SELECT RAISE(ABORT,'metadata worker attempts are retained'); END;

CREATE TRIGGER source_post_thread_scope BEFORE INSERT ON source_post_threads
BEGIN
  SELECT RAISE(ABORT,'thread evidence must belong to its post') WHERE
    (SELECT post_uuid FROM source_captures WHERE uuid=NEW.capture_uuid) IS NOT NEW.post_uuid OR
    (SELECT post_uuid FROM source_post_identifiers WHERE namespace=NEW.namespace AND value=NEW.post_id) IS NOT NEW.post_uuid;
END;

CREATE TRIGGER source_post_thread_immutable BEFORE UPDATE ON source_post_threads
WHEN NEW.post_uuid!=OLD.post_uuid OR NEW.namespace!=OLD.namespace OR NEW.post_id!=OLD.post_id
 OR NEW.conversation_id!=OLD.conversation_id OR NEW.reply_id!=OLD.reply_id OR NEW.author_id!=OLD.author_id
 OR (NEW.reply_author_id!=OLD.reply_author_id AND OLD.reply_author_id!='')
 OR (NEW.conflict_capture_uuid IS NOT OLD.conflict_capture_uuid AND OLD.conflict_capture_uuid IS NOT NULL)
BEGIN SELECT RAISE(ABORT,'thread identity is immutable'); END;

CREATE TRIGGER source_collection_alias_immutable BEFORE UPDATE ON source_collection_aliases
BEGIN SELECT RAISE(ABORT,'source collection aliases are immutable'); END;

CREATE TRIGGER source_collection_alias_retained BEFORE DELETE ON source_collection_aliases
BEGIN SELECT RAISE(ABORT,'source collection aliases retain historical receipts'); END;

CREATE TRIGGER source_collection_alias_frozen BEFORE INSERT ON source_collection_revisions
WHEN EXISTS(SELECT 1 FROM source_collection_aliases WHERE alias_uuid=NEW.collection_uuid)
BEGIN SELECT RAISE(ABORT,'edit the canonical profile source'); END;

CREATE TRIGGER source_run_retrieval_immutable BEFORE UPDATE ON source_run_retrievals
BEGIN SELECT RAISE(ABORT,'source run retrieval is immutable'); END;

CREATE TRIGGER source_run_retrieval_retained BEFORE DELETE ON source_run_retrievals
BEGIN SELECT RAISE(ABORT,'source run retrieval retains historical execution identity'); END;

CREATE TRIGGER archive_job_identity BEFORE UPDATE ON archive_jobs
WHEN NEW.id!=OLD.id OR NEW.uuid!=OLD.uuid OR NEW.kind!=OLD.kind OR NEW.work_key!=OLD.work_key
 OR NEW.resource_key!=OLD.resource_key OR NEW.arguments!=OLD.arguments OR NEW.max_attempts!=OLD.max_attempts
 OR NEW.created_at_ms!=OLD.created_at_ms
BEGIN SELECT RAISE(ABORT,'archive job identity is immutable'); END;

CREATE TRIGGER discovery_detail_success BEFORE UPDATE ON archive_jobs
WHEN NEW.kind='post.verify_candidate' AND NEW.state='succeeded' AND NOT EXISTS(
 SELECT 1 FROM discovery_detail_results r WHERE r.job_uuid=NEW.uuid AND r.fence=NEW.fence
 AND json_extract(NEW.result,'$.checkpoint_revision')=r.checkpoint_revision
 AND json_extract(NEW.result,'$.checkpoint_sha256')=json_extract(r.evidence,'$.transcript_sha256'))
BEGIN SELECT RAISE(ABORT,'detail success requires its retained comparison'); END;

CREATE TRIGGER discovery_listing_success BEFORE UPDATE ON archive_jobs
WHEN NEW.kind='account.list_page' AND NEW.state='succeeded' AND NOT EXISTS(
 SELECT 1 FROM discovery_listing_jobs b JOIN discovery_pages p ON p.listing_uuid=b.listing_uuid
 WHERE b.job_uuid=NEW.uuid AND b.page_ordinal=p.ordinal AND p.job_uuid=NEW.uuid AND p.fence=NEW.fence
 AND json_extract(NEW.result,'$.listing_uuid')=b.listing_uuid
 AND json_extract(NEW.result,'$.page_ordinal')=p.ordinal AND json_extract(NEW.result,'$.page_sha256')=p.digest)
BEGIN SELECT RAISE(ABORT,'listing job success requires its retained page'); END;

CREATE TRIGGER enrichment_job_success BEFORE UPDATE ON archive_jobs
WHEN NEW.kind='post.enrich' AND NEW.state='succeeded' AND NOT EXISTS(
 SELECT 1 FROM enrichment_publications p
 JOIN enrichment_checkpoint_receipts r ON r.job_uuid=p.job_uuid AND r.revision=p.checkpoint_revision
 JOIN enrichment_completions e ON e.uuid=p.completion_uuid
 WHERE p.job_uuid=NEW.uuid AND p.fence=NEW.fence
 AND r.record_count=(SELECT count(*) FROM enrichment_published_records c WHERE c.job_uuid=p.job_uuid)
 AND e.capture_count=(SELECT count(DISTINCT capture_uuid) FROM enrichment_published_records c WHERE c.job_uuid=p.job_uuid))
BEGIN SELECT RAISE(ABORT,'enrichment success requires complete native capture publication'); END;

CREATE TRIGGER source_enrichment_waiter_end AFTER UPDATE ON archive_jobs
WHEN NEW.kind IN ('post.enrich','account.list_page','post.verify_candidate') AND NEW.revision!=OLD.revision
BEGIN DELETE FROM source_enrichment_waiters WHERE job_uuid=NEW.uuid; END;

CREATE TRIGGER gallery_cover_scope_insert BEFORE INSERT ON gallery_covers
WHEN NOT EXISTS (
  SELECT 1 FROM archive_entities a WHERE a.uuid = NEW.media_uuid AND a.state = 'active'
  AND ((a.kind = 'image' AND EXISTS (SELECT 1 FROM galleries_images gi WHERE gi.gallery_id = NEW.gallery_id AND gi.image_id = a.image_id))
    OR (a.kind = 'scene' AND EXISTS (SELECT 1 FROM scenes_galleries gs WHERE gs.gallery_id = NEW.gallery_id AND gs.scene_id = a.scene_id)))
)
BEGIN SELECT RAISE(ABORT, 'gallery cover must be an active gallery member'); END;

CREATE TRIGGER gallery_cover_scope_update BEFORE UPDATE ON gallery_covers
WHEN NOT EXISTS (
  SELECT 1 FROM archive_entities a WHERE a.uuid = NEW.media_uuid AND a.state = 'active'
  AND ((a.kind = 'image' AND EXISTS (SELECT 1 FROM galleries_images gi WHERE gi.gallery_id = NEW.gallery_id AND gi.image_id = a.image_id))
    OR (a.kind = 'scene' AND EXISTS (SELECT 1 FROM scenes_galleries gs WHERE gs.gallery_id = NEW.gallery_id AND gs.scene_id = a.scene_id)))
)
BEGIN SELECT RAISE(ABORT, 'gallery cover must be an active gallery member'); END;

CREATE TRIGGER gallery_cover_image_removed AFTER DELETE ON galleries_images
BEGIN
  DELETE FROM gallery_covers WHERE gallery_id = OLD.gallery_id
    AND media_uuid IN (SELECT uuid FROM archive_entities WHERE image_id = OLD.image_id);
END;

CREATE TRIGGER gallery_cover_scene_removed AFTER DELETE ON scenes_galleries
BEGIN
  DELETE FROM gallery_covers WHERE gallery_id = OLD.gallery_id
    AND media_uuid IN (SELECT uuid FROM archive_entities WHERE scene_id = OLD.scene_id);
END;

CREATE TRIGGER gallery_cover_image_replaced AFTER UPDATE OF gallery_id, image_id ON galleries_images
WHEN OLD.gallery_id != NEW.gallery_id OR OLD.image_id != NEW.image_id
BEGIN
  DELETE FROM gallery_covers WHERE gallery_id = OLD.gallery_id
    AND media_uuid IN (SELECT uuid FROM archive_entities WHERE image_id = OLD.image_id);
END;

CREATE TRIGGER gallery_cover_scene_replaced AFTER UPDATE OF gallery_id, scene_id ON scenes_galleries
WHEN OLD.gallery_id != NEW.gallery_id OR OLD.scene_id != NEW.scene_id
BEGIN
  DELETE FROM gallery_covers WHERE gallery_id = OLD.gallery_id
    AND media_uuid IN (SELECT uuid FROM archive_entities WHERE scene_id = OLD.scene_id);
END;

CREATE TRIGGER gallery_cover_changed_insert AFTER INSERT ON gallery_covers
BEGIN UPDATE galleries SET updated_at = CURRENT_TIMESTAMP WHERE id = NEW.gallery_id; END;

CREATE TRIGGER gallery_cover_changed_update AFTER UPDATE ON gallery_covers
BEGIN UPDATE galleries SET updated_at = CURRENT_TIMESTAMP WHERE id IN (OLD.gallery_id, NEW.gallery_id); END;

CREATE TRIGGER gallery_cover_changed_delete AFTER DELETE ON gallery_covers
BEGIN UPDATE galleries SET updated_at = CURRENT_TIMESTAMP WHERE id = OLD.gallery_id; END;

CREATE TRIGGER media_conversion_scope BEFORE INSERT ON media_conversions
BEGIN
  SELECT RAISE(ABORT,'conversion requires current image and scene identities') WHERE NOT EXISTS (
    SELECT 1 FROM archive_entities i JOIN archive_entities s
    WHERE i.uuid=NEW.image_uuid AND i.kind='image' AND i.state='active'
      AND s.uuid=NEW.scene_uuid AND s.kind='scene' AND s.state='active'
  );
  SELECT RAISE(ABORT,'conversion requires current original and verified final files') WHERE NOT EXISTS (
    SELECT 1 FROM archive_entities a JOIN files f ON f.id=a.file_id
    JOIN archive_entities b JOIN files v ON v.id=b.file_id
    JOIN images_files old ON old.file_id=f.id JOIN archive_entities i ON i.image_id=old.image_id
    JOIN scenes_files new ON new.file_id=v.id JOIN archive_entities s ON s.scene_id=new.scene_id
    WHERE a.uuid=NEW.original_file_uuid AND a.kind='file' AND a.state='active' AND f.generation=NEW.original_generation
      AND b.uuid=NEW.file_uuid AND b.kind='file' AND b.state='active' AND v.generation=NEW.generation
      AND i.uuid=NEW.image_uuid AND s.uuid=NEW.scene_uuid
  );
END;

CREATE TRIGGER media_conversion_immutable BEFORE UPDATE ON media_conversions
WHEN NEW.uuid!=OLD.uuid
  OR (NEW.image_uuid!=OLD.image_uuid AND EXISTS(SELECT 1 FROM archive_entities WHERE uuid=OLD.image_uuid))
  OR (NEW.scene_uuid!=OLD.scene_uuid AND EXISTS(SELECT 1 FROM archive_entities WHERE uuid=OLD.scene_uuid))
  OR (NEW.original_file_uuid!=OLD.original_file_uuid AND EXISTS(SELECT 1 FROM archive_entities WHERE uuid=OLD.original_file_uuid))
  OR NEW.original_generation!=OLD.original_generation
  OR (NEW.file_uuid!=OLD.file_uuid AND EXISTS(SELECT 1 FROM archive_entities WHERE uuid=OLD.file_uuid))
  OR NEW.generation!=OLD.generation OR NEW.photographer!=OLD.photographer
  OR NEW.undated_o_count!=OLD.undated_o_count OR NEW.created_at!=OLD.created_at
BEGIN SELECT RAISE(ABORT,'media conversion is immutable'); END;

CREATE TRIGGER media_conversion_retained BEFORE DELETE ON media_conversions
BEGIN SELECT RAISE(ABORT,'media conversion is retained'); END;

CREATE TRIGGER source_gallery_scenes_galleries_insert BEFORE INSERT ON scenes_galleries
WHEN NOT EXISTS (
  SELECT 1 FROM media_conversions c
  JOIN archive_entities i ON i.uuid=c.image_uuid AND i.state='active'
  JOIN archive_entities s ON s.uuid=c.scene_uuid
  JOIN galleries_images gi ON gi.image_id=i.image_id
  WHERE s.scene_id=NEW.scene_id AND gi.gallery_id=NEW.gallery_id
)
BEGIN
  INSERT INTO gallery_membership_events(uuid,gallery_uuid,media_uuid,state,origin,post_uuid,selection_uuid)
  SELECT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)),2) || '-' || substr('89ab',(random() & 3)+1,1) || substr(hex(randomblob(2)),2) || '-' || hex(randomblob(6)))),g.uuid,m.uuid,'included',
    CASE WHEN w.post_uuid IS NULL THEN 'library' ELSE 'source' END,w.post_uuid,w.selection_uuid
  FROM archive_entities g JOIN galleries ga ON ga.id=g.gallery_id
  JOIN archive_entities m ON m.scene_id=NEW.scene_id
  LEFT JOIN source_gallery_write_context w ON w.gallery_uuid=g.uuid
  WHERE g.gallery_id=NEW.gallery_id AND
    (ga.origin='source' OR EXISTS(SELECT 1 FROM post_gallery_decisions WHERE gallery_uuid=g.uuid));
END;

CREATE TRIGGER archive_job_transition BEFORE UPDATE ON archive_jobs
WHEN OLD.state IN ('succeeded','failed','cancelled') OR NEW.revision!=OLD.revision+1
 OR NEW.updated_at_ms<OLD.updated_at_ms
 OR (OLD.state='queued' AND NEW.state NOT IN ('queued','running','failed','cancelled'))
 OR (NEW.state='running' AND OLD.state='queued' AND NEW.fence!=OLD.fence+1)
 OR (NOT (NEW.state='running' AND OLD.state='queued') AND NEW.fence!=OLD.fence)
 OR (OLD.state='running' AND NEW.state='running' AND NEW.owner_uuid!=OLD.owner_uuid)
 OR NEW.failures!=OLD.failures+CASE WHEN OLD.state='running' AND NEW.state IN ('queued','failed')
   AND EXISTS(SELECT 1 FROM archive_job_attempts a WHERE a.job_uuid=OLD.uuid AND a.fence=OLD.fence
     AND a.outcome IN ('retry','failed') AND NOT (OLD.kind='post.enrich' AND a.error_code='budget_yield')) THEN 1 ELSE 0 END
BEGIN SELECT RAISE(ABORT,'invalid archive job transition'); END;

CREATE TRIGGER media_root_scan_revision BEFORE UPDATE OF scan_revision,scan_enabled,exclude_video,exclude_image ON media_roots
WHEN NEW.scan_revision!=OLD.scan_revision+1
BEGIN SELECT RAISE(ABORT,'library scan settings require the next revision'); END;

CREATE TRIGGER source_subscription_revision BEFORE UPDATE ON source_subscriptions
WHEN NEW.collection_uuid!=OLD.collection_uuid OR NEW.revision!=OLD.revision+1
BEGIN SELECT RAISE(ABORT,'subscription changes require the next revision'); END;

CREATE TRIGGER source_run_subscription_immutable BEFORE UPDATE ON source_run_subscriptions
BEGIN SELECT RAISE(ABORT,'run subscription bindings are immutable'); END;

CREATE TRIGGER archive_folder_created AFTER INSERT ON folders
BEGIN
  INSERT INTO archive_entities(kind,folder_id,original_id,created_at)
  VALUES ('folder',NEW.id,NEW.id,NEW.created_at);
END;

CREATE TRIGGER archive_folder_changed AFTER UPDATE ON folders
BEGIN UPDATE archive_entities SET revision=revision+1 WHERE folder_id=NEW.id; END;

CREATE TRIGGER archive_folder_deleted BEFORE DELETE ON folders
BEGIN
  UPDATE archive_entities SET state='deleted',revision=revision+1,
    folder_id=NULL,retired_at=CURRENT_TIMESTAMP WHERE folder_id=OLD.id;
END;

CREATE TRIGGER archive_scene_marker_created AFTER INSERT ON scene_markers
BEGIN
  INSERT INTO archive_entities(kind,scene_marker_id,original_id,created_at)
  VALUES ('scene_marker',NEW.id,NEW.id,NEW.created_at);
END;

CREATE TRIGGER archive_scene_marker_changed AFTER UPDATE ON scene_markers
BEGIN UPDATE archive_entities SET revision=revision+1 WHERE scene_marker_id=NEW.id; END;

CREATE TRIGGER archive_scene_marker_deleted BEFORE DELETE ON scene_markers
BEGIN
  UPDATE archive_entities SET state='deleted',revision=revision+1,
    scene_marker_id=NULL,retired_at=CURRENT_TIMESTAMP WHERE scene_marker_id=OLD.id;
END;

CREATE TRIGGER archive_gallery_chapter_created AFTER INSERT ON galleries_chapters
BEGIN
  INSERT INTO archive_entities(kind,gallery_chapter_id,original_id,created_at)
  VALUES ('gallery_chapter',NEW.id,NEW.id,NEW.created_at);
END;

CREATE TRIGGER archive_gallery_chapter_changed AFTER UPDATE ON galleries_chapters
BEGIN UPDATE archive_entities SET revision=revision+1 WHERE gallery_chapter_id=NEW.id; END;

CREATE TRIGGER archive_gallery_chapter_deleted BEFORE DELETE ON galleries_chapters
BEGIN
  UPDATE archive_entities SET state='deleted',revision=revision+1,
    gallery_chapter_id=NULL,retired_at=CURRENT_TIMESTAMP WHERE gallery_chapter_id=OLD.id;
END;

CREATE TRIGGER archive_saved_filter_created AFTER INSERT ON saved_filters
BEGIN
  INSERT INTO archive_entities(kind,saved_filter_id,original_id,created_at)
  VALUES ('saved_filter',NEW.id,NEW.id,CURRENT_TIMESTAMP);
END;

CREATE TRIGGER archive_saved_filter_changed AFTER UPDATE ON saved_filters
BEGIN UPDATE archive_entities SET revision=revision+1 WHERE saved_filter_id=NEW.id; END;

CREATE TRIGGER archive_saved_filter_deleted BEFORE DELETE ON saved_filters
BEGIN
  UPDATE archive_entities SET state='deleted',revision=revision+1,
    saved_filter_id=NULL,retired_at=CURRENT_TIMESTAMP WHERE saved_filter_id=OLD.id;
END;

CREATE TRIGGER archive_entity_redirect_insert BEFORE INSERT ON archive_entities
WHEN NEW.redirect_to IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'archive identity redirect kinds differ')
    WHERE EXISTS (SELECT 1 FROM archive_entities WHERE uuid = NEW.redirect_to AND kind != NEW.kind);
  SELECT RAISE(ABORT, 'archive identity redirect cycle') WHERE EXISTS (
    WITH RECURSIVE chain(uuid, redirect_to) AS (
      SELECT uuid, redirect_to FROM archive_entities WHERE uuid = NEW.redirect_to
      UNION
      SELECT e.uuid, e.redirect_to FROM archive_entities e JOIN chain c ON e.uuid = c.redirect_to
    ) SELECT 1 FROM chain WHERE uuid = NEW.uuid
  );
END;

CREATE TRIGGER archive_entity_kind_immutable BEFORE UPDATE OF kind ON archive_entities
WHEN NEW.kind != OLD.kind
BEGIN SELECT RAISE(ABORT, 'archive identity kind is immutable'); END;

CREATE TRIGGER archive_entity_no_resurrection BEFORE UPDATE OF state ON archive_entities
WHEN OLD.state != 'active' AND NEW.state != OLD.state
BEGIN SELECT RAISE(ABORT, 'retired archive identity state is immutable'); END;

CREATE TRIGGER metadata_reference_retiring BEFORE UPDATE OF state ON archive_entities
WHEN OLD.state='active' AND NEW.state!='active' AND OLD.kind IN ('performer','tag','studio','group')
BEGIN
  INSERT INTO metadata_field_pending(entity_uuid,field,previous_json)
  SELECT a.uuid,'studio',v.value_json FROM archive_entities a
  JOIN metadata_collection_values v ON v.entity_uuid=a.uuid AND v.field='studio'
  WHERE (OLD.kind='studio' AND a.scene_id IN (SELECT id FROM scenes WHERE studio_id=OLD.studio_id)) AND NOT EXISTS(SELECT 1 FROM metadata_field_write_context w WHERE w.entity_uuid=a.uuid AND w.field='studio')
    AND NOT EXISTS(SELECT 1 FROM metadata_field_pending p WHERE p.entity_uuid=a.uuid AND p.field='studio');
  INSERT INTO metadata_field_pending(entity_uuid,field,previous_json)
  SELECT a.uuid,'performers',v.value_json FROM archive_entities a
  JOIN metadata_collection_values v ON v.entity_uuid=a.uuid AND v.field='performers'
  WHERE (OLD.kind='performer' AND a.scene_id IN (SELECT scene_id FROM performers_scenes WHERE performer_id=OLD.performer_id)) AND NOT EXISTS(SELECT 1 FROM metadata_field_write_context w WHERE w.entity_uuid=a.uuid AND w.field='performers')
    AND NOT EXISTS(SELECT 1 FROM metadata_field_pending p WHERE p.entity_uuid=a.uuid AND p.field='performers');
  INSERT INTO metadata_field_pending(entity_uuid,field,previous_json)
  SELECT a.uuid,'tags',v.value_json FROM archive_entities a
  JOIN metadata_collection_values v ON v.entity_uuid=a.uuid AND v.field='tags'
  WHERE (OLD.kind='tag' AND a.scene_id IN (SELECT scene_id FROM scenes_tags WHERE tag_id=OLD.tag_id)) AND NOT EXISTS(SELECT 1 FROM metadata_field_write_context w WHERE w.entity_uuid=a.uuid AND w.field='tags')
    AND NOT EXISTS(SELECT 1 FROM metadata_field_pending p WHERE p.entity_uuid=a.uuid AND p.field='tags');
  INSERT INTO metadata_field_pending(entity_uuid,field,previous_json)
  SELECT a.uuid,'groups',v.value_json FROM archive_entities a
  JOIN metadata_collection_values v ON v.entity_uuid=a.uuid AND v.field='groups'
  WHERE (OLD.kind='group' AND a.scene_id IN (SELECT scene_id FROM groups_scenes WHERE group_id=OLD.group_id)) AND NOT EXISTS(SELECT 1 FROM metadata_field_write_context w WHERE w.entity_uuid=a.uuid AND w.field='groups')
    AND NOT EXISTS(SELECT 1 FROM metadata_field_pending p WHERE p.entity_uuid=a.uuid AND p.field='groups');
  INSERT INTO metadata_field_pending(entity_uuid,field,previous_json)
  SELECT a.uuid,'studio',v.value_json FROM archive_entities a
  JOIN metadata_collection_values v ON v.entity_uuid=a.uuid AND v.field='studio'
  WHERE (OLD.kind='studio' AND a.image_id IN (SELECT id FROM images WHERE studio_id=OLD.studio_id)) AND NOT EXISTS(SELECT 1 FROM metadata_field_write_context w WHERE w.entity_uuid=a.uuid AND w.field='studio')
    AND NOT EXISTS(SELECT 1 FROM metadata_field_pending p WHERE p.entity_uuid=a.uuid AND p.field='studio');
  INSERT INTO metadata_field_pending(entity_uuid,field,previous_json)
  SELECT a.uuid,'performers',v.value_json FROM archive_entities a
  JOIN metadata_collection_values v ON v.entity_uuid=a.uuid AND v.field='performers'
  WHERE (OLD.kind='performer' AND a.image_id IN (SELECT image_id FROM performers_images WHERE performer_id=OLD.performer_id)) AND NOT EXISTS(SELECT 1 FROM metadata_field_write_context w WHERE w.entity_uuid=a.uuid AND w.field='performers')
    AND NOT EXISTS(SELECT 1 FROM metadata_field_pending p WHERE p.entity_uuid=a.uuid AND p.field='performers');
  INSERT INTO metadata_field_pending(entity_uuid,field,previous_json)
  SELECT a.uuid,'tags',v.value_json FROM archive_entities a
  JOIN metadata_collection_values v ON v.entity_uuid=a.uuid AND v.field='tags'
  WHERE (OLD.kind='tag' AND a.image_id IN (SELECT image_id FROM images_tags WHERE tag_id=OLD.tag_id)) AND NOT EXISTS(SELECT 1 FROM metadata_field_write_context w WHERE w.entity_uuid=a.uuid AND w.field='tags')
    AND NOT EXISTS(SELECT 1 FROM metadata_field_pending p WHERE p.entity_uuid=a.uuid AND p.field='tags');
  INSERT INTO metadata_field_pending(entity_uuid,field,previous_json)
  SELECT a.uuid,'studio',v.value_json FROM archive_entities a
  JOIN metadata_collection_values v ON v.entity_uuid=a.uuid AND v.field='studio'
  WHERE (OLD.kind='studio' AND a.gallery_id IN (SELECT id FROM galleries WHERE studio_id=OLD.studio_id)) AND NOT EXISTS(SELECT 1 FROM metadata_field_write_context w WHERE w.entity_uuid=a.uuid AND w.field='studio')
    AND NOT EXISTS(SELECT 1 FROM metadata_field_pending p WHERE p.entity_uuid=a.uuid AND p.field='studio');
  INSERT INTO metadata_field_pending(entity_uuid,field,previous_json)
  SELECT a.uuid,'performers',v.value_json FROM archive_entities a
  JOIN metadata_collection_values v ON v.entity_uuid=a.uuid AND v.field='performers'
  WHERE (OLD.kind='performer' AND a.gallery_id IN (SELECT gallery_id FROM performers_galleries WHERE performer_id=OLD.performer_id)) AND NOT EXISTS(SELECT 1 FROM metadata_field_write_context w WHERE w.entity_uuid=a.uuid AND w.field='performers')
    AND NOT EXISTS(SELECT 1 FROM metadata_field_pending p WHERE p.entity_uuid=a.uuid AND p.field='performers');
  INSERT INTO metadata_field_pending(entity_uuid,field,previous_json)
  SELECT a.uuid,'tags',v.value_json FROM archive_entities a
  JOIN metadata_collection_values v ON v.entity_uuid=a.uuid AND v.field='tags'
  WHERE (OLD.kind='tag' AND a.gallery_id IN (SELECT gallery_id FROM galleries_tags WHERE tag_id=OLD.tag_id)) AND NOT EXISTS(SELECT 1 FROM metadata_field_write_context w WHERE w.entity_uuid=a.uuid AND w.field='tags')
    AND NOT EXISTS(SELECT 1 FROM metadata_field_pending p WHERE p.entity_uuid=a.uuid AND p.field='tags');
END;

CREATE TRIGGER gallery_cover_media_retired AFTER UPDATE OF state ON archive_entities
WHEN NEW.state != 'active'
BEGIN
  -- A same-kind merge can retain the selected cover when its destination is
  -- also a member. An explicit membership removal must still clear it.
  UPDATE gallery_covers SET media_uuid = NEW.redirect_to
  WHERE media_uuid = NEW.uuid AND NEW.state = 'redirected' AND EXISTS (
    SELECT 1 FROM archive_entities a WHERE a.uuid = NEW.redirect_to AND a.state = 'active'
      AND ((a.kind = 'image' AND EXISTS (SELECT 1 FROM galleries_images gi WHERE gi.gallery_id = gallery_covers.gallery_id AND gi.image_id = a.image_id))
        OR (a.kind = 'scene' AND EXISTS (SELECT 1 FROM scenes_galleries gs WHERE gs.gallery_id = gallery_covers.gallery_id AND gs.scene_id = a.scene_id)))
  );
  DELETE FROM gallery_covers WHERE media_uuid = NEW.uuid;
END;

CREATE TRIGGER archive_entity_redirect_update BEFORE UPDATE OF redirect_to, kind ON archive_entities
WHEN NEW.redirect_to IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'archive identity redirect kinds differ')
    WHERE EXISTS (SELECT 1 FROM archive_entities WHERE uuid=NEW.redirect_to AND kind!=NEW.kind)
      AND NOT EXISTS (SELECT 1 FROM media_conversions WHERE image_uuid=NEW.uuid AND NEW.kind='image'
        AND (scene_uuid=NEW.redirect_to OR (scene_uuid=OLD.redirect_to AND NOT EXISTS(SELECT 1 FROM archive_entities WHERE uuid=OLD.redirect_to))));
  SELECT RAISE(ABORT, 'archive identity redirect cycle') WHERE EXISTS (
    WITH RECURSIVE chain(uuid,redirect_to) AS (
      SELECT uuid,redirect_to FROM archive_entities WHERE uuid=NEW.redirect_to
      UNION SELECT e.uuid,e.redirect_to FROM archive_entities e JOIN chain c ON e.uuid=c.redirect_to
    ) SELECT 1 FROM chain WHERE uuid=NEW.uuid
  );
END;

CREATE TRIGGER source_run_scope BEFORE INSERT ON source_runs
WHEN NEW.root_uuid IS NOT (SELECT root_uuid FROM source_collection_revisions WHERE collection_uuid=NEW.collection_uuid AND revision=NEW.collection_revision)
BEGIN SELECT RAISE(ABORT,'source run root differs from collection'); END;

CREATE TRIGGER source_run_identity BEFORE UPDATE ON source_runs
WHEN NEW.id!=OLD.id OR NEW.uuid!=OLD.uuid OR NEW.collection_uuid!=OLD.collection_uuid OR NEW.collection_revision!=OLD.collection_revision
  OR NEW.root_uuid IS NOT OLD.root_uuid OR NEW.root_revision IS NOT OLD.root_revision OR NEW.operation!=OLD.operation
  OR NEW.policy_sha256!=OLD.policy_sha256 OR NEW.cooldown_seconds!=OLD.cooldown_seconds OR NEW.work_key!=OLD.work_key
  OR NEW.target_key!=OLD.target_key OR NEW.created_at_ms!=OLD.created_at_ms
BEGIN SELECT RAISE(ABORT,'source run definition is immutable'); END;

CREATE TRIGGER source_run_transition BEFORE UPDATE ON source_runs
WHEN OLD.state IN ('succeeded','cancelled') OR NEW.revision!=OLD.revision+1 OR NEW.updated_at_ms<OLD.updated_at_ms
  OR (NEW.state='succeeded' AND OLD.state!='running')
  OR (NEW.state='running' AND OLD.state!='running' AND (OLD.state!='queued' OR NEW.fence!=OLD.fence+1))
  OR ((NEW.state!='running' OR OLD.state='running') AND NEW.fence!=OLD.fence)
  OR (OLD.state='running' AND NEW.state='running' AND (NEW.owner_uuid!=OLD.owner_uuid OR NEW.producer_uuid!=OLD.producer_uuid OR NEW.window!=OLD.window
    OR NEW.destination!=OLD.destination OR NEW.root_identity!=OLD.root_identity OR NEW.destination_prefix!=OLD.destination_prefix))
BEGIN SELECT RAISE(ABORT,'invalid source run transition'); END;

CREATE TRIGGER source_run_pacing_bind AFTER INSERT ON source_runs
BEGIN
 INSERT OR IGNORE INTO source_pacing(scope)
  SELECT source_scope_v1(target_url) FROM source_collection_revisions WHERE collection_uuid=NEW.collection_uuid AND revision=NEW.collection_revision;
 INSERT INTO source_run_pacing(run_uuid,scope)
  SELECT NEW.uuid,source_scope_v1(target_url) FROM source_collection_revisions WHERE collection_uuid=NEW.collection_uuid AND revision=NEW.collection_revision;
END;

CREATE TRIGGER source_run_basis_insert BEFORE INSERT ON source_runs
BEGIN
 SELECT RAISE(ABORT,'invalid source run coverage basis') WHERE EXISTS (
  SELECT 1 FROM (
   SELECT value FROM json_each(NEW.pending)
   UNION ALL SELECT value FROM json_each(NEW.completed)
   UNION ALL SELECT NEW.window WHERE NEW.window IS NOT NULL
  ) WHERE COALESCE(json_extract(value,'$.basis'),'') NOT IN ('','traversal')
   OR (json_extract(value,'$.basis')='traversal'
       AND (NEW.operation!='download' OR json_extract(value,'$.since') IS NOT NULL))
 );
 SELECT RAISE(ABORT,'source run cannot mix coverage bases') WHERE (
  SELECT count(DISTINCT COALESCE(json_extract(value,'$.basis'),'')) FROM (
   SELECT value FROM json_each(NEW.pending)
   UNION ALL SELECT value FROM json_each(NEW.completed)
   UNION ALL SELECT NEW.window WHERE NEW.window IS NOT NULL
  )
 ) > 1;
END;

CREATE TRIGGER source_run_basis_update BEFORE UPDATE ON source_runs
BEGIN
 SELECT RAISE(ABORT,'invalid source run coverage basis') WHERE EXISTS (
  SELECT 1 FROM (
   SELECT value FROM json_each(NEW.pending)
   UNION ALL SELECT value FROM json_each(NEW.completed)
   UNION ALL SELECT NEW.window WHERE NEW.window IS NOT NULL
  ) WHERE COALESCE(json_extract(value,'$.basis'),'') NOT IN ('','traversal')
   OR (json_extract(value,'$.basis')='traversal'
       AND (NEW.operation!='download' OR json_extract(value,'$.since') IS NOT NULL))
 );
 SELECT RAISE(ABORT,'source run cannot mix coverage bases') WHERE (
  SELECT count(DISTINCT COALESCE(json_extract(value,'$.basis'),'')) FROM (
   SELECT value FROM json_each(NEW.pending)
   UNION ALL SELECT value FROM json_each(NEW.completed)
   UNION ALL SELECT NEW.window WHERE NEW.window IS NOT NULL
  )
 ) > 1;
END;

CREATE TRIGGER post_gallery_thread_share_insert BEFORE INSERT ON post_gallery_links
WHEN NEW.gallery_uuid IS NOT NULL
BEGIN
  SELECT RAISE(ABORT,'only evidenced self-replies may share a source gallery')
  WHERE EXISTS (SELECT 1 FROM post_gallery_links WHERE gallery_uuid=NEW.gallery_uuid AND post_uuid!=NEW.post_uuid)
  AND NOT EXISTS (SELECT 1 FROM post_gallery_links l JOIN source_post_threads a ON a.post_uuid=NEW.post_uuid
    JOIN source_post_threads b ON b.post_uuid=l.post_uuid
    AND b.namespace=a.namespace AND b.conversation_id=a.conversation_id AND b.author_id=a.author_id
    WHERE l.gallery_uuid=NEW.gallery_uuid AND l.post_uuid!=NEW.post_uuid
    AND a.conflict_capture_uuid IS NULL AND b.conflict_capture_uuid IS NULL
    AND (a.reply_id='' OR a.reply_author_id=a.author_id) AND (b.reply_id='' OR b.reply_author_id=b.author_id));
END;

CREATE TRIGGER post_gallery_thread_share_update BEFORE UPDATE OF gallery_uuid ON post_gallery_links
WHEN NEW.gallery_uuid IS NOT NULL AND NEW.gallery_uuid IS NOT OLD.gallery_uuid
AND NOT EXISTS (SELECT 1 FROM source_gallery_merge_context
  WHERE source_uuid=OLD.gallery_uuid AND target_uuid=NEW.gallery_uuid)
BEGIN
  SELECT RAISE(ABORT,'only evidenced self-replies may share a source gallery')
  WHERE EXISTS (SELECT 1 FROM post_gallery_links WHERE gallery_uuid=NEW.gallery_uuid AND post_uuid!=NEW.post_uuid)
  AND NOT EXISTS (SELECT 1 FROM post_gallery_links l JOIN source_post_threads a ON a.post_uuid=NEW.post_uuid
    JOIN source_post_threads b ON b.post_uuid=l.post_uuid
    AND b.namespace=a.namespace AND b.conversation_id=a.conversation_id AND b.author_id=a.author_id
    WHERE l.gallery_uuid=NEW.gallery_uuid AND l.post_uuid!=NEW.post_uuid
    AND a.conflict_capture_uuid IS NULL AND b.conflict_capture_uuid IS NULL
    AND (a.reply_id='' OR a.reply_author_id=a.author_id) AND (b.reply_id='' OR b.reply_author_id=b.author_id));
END;

